// Generated by scripts/build.py; edit JSON sources only.
window.UKPPPG_BANK = {"schemaVersion":1,"codes":{"P.1":"Merancang dan memfasilitasi pengalaman belajar Murid yang mendorong pemahaman konseptual, penerapan kontekstual, dan refleksi bermakna terhadap proses pembelajaran","P.2":"Melaksanakan pembelajaran yang responsif terhadap keragaman latar belakang, kebutuhan, dan potensi Murid melalui berbagai model pembelajaran","P.3":"Menciptakan proses pembelajaran yang berkesadaran, bermakna, dan menggembirakan","P.4":"Mengintegrasikan teknologi informasi dan komunikasi secara kritis dan kreatif dalam pembelajaran untuk memperluas akses, memperdalam pemahaman, dan mendukung literasi digital Murid","P.5":"Menerapkan strategi pembelajaran atau pembimbingan yang sesuai karakteristik Murid dengan memanfaatkan sumber belajar dan mempertimbangkan potensi lingkungan dan kearifan lokal","P.6":"Melaksanakan asesmen untuk mengetahui kebutuhan belajar, memberikan umpan balik, dan mengukur hasil belajar Murid secara berkesinambungan dan reflektif","K.1":"Menampilkan perilaku etis dan keteladanan yang mencerminkan kematangan spiritual, moral, dan emosional berdasarkan Ketuhanan Yang Maha Esa dan nilai-nilai keberagaman","K.2":"Melakukan refleksi diri secara berkesinambungan, mengembangkan pola pikir bertumbuh, serta belajar sepanjang hayat untuk peningkatan kualitas diri","K.3":"Mengambil keputusan dan bertindak secara konsisten dalam mengembangkan potensi dan budaya belajar Murid","S.1":"Berkomunikasi secara inklusif, empatik, dan efektif secara lisan, tulisan, dan/atau isyarat dengan memperhatikan keragaman dan kebutuhan Murid","S.2":"Berkolaborasi dengan Murid, sesama Pendidik, Tenaga Kependidikan selain Pendidik, orang tua/wali Murid, dan masyarakat untuk meningkatkan kualitas pembelajaran","S.3":"Berpartisipasi aktif dalam organisasi profesi dan komunitas pembelajaran untuk pengembangan keprofesian berkelanjutan","PF.1":"Menguasai tujuan pendidikan terutama pada Satuan Pendidikan yang diampu","PF.2":"Menguasai disiplin ilmu sesuai dengan materi/muatan pembelajaran atau pembimbingan","PF.3":"Memahami potensi dan kebutuhan belajar Murid berdasarkan karakteristik materi pembelajaran atau pembimbingan dan konteks lokal","PF.4":"Memahami, menerapkan, dan mengembangkan kurikulum secara adaptif dan kontekstual sesuai perkembangan zaman","PF.5":"Mengembangkan praktik profesional pendidikan secara konseptual, empiris, kreatif, dan inovatif"},"packages":[{"id":1,"title":"Paket 1","version":"2026-11-18.6","file":"bank_soal_80.json","reviewFile":"references/Bank_Soal_80_dan_Pembahasan.md","questions":[{"id":1,"code":"P.1","type":"PG","stem":"Dalam rancangan ERD perpustakaan kelas, beberapa murid menjadikan nama siswa sebagai primary key karena setiap murid punya nama. Guru menemukan dua murid bernama Nisa. Tindakan pembelajaran yang paling tepat adalah ...","options":["Menjelaskan definisi PK, lalu meminta murid menerapkannya tanpa menguji dua nama yang sama.","Menguji dua rekaman bernama Nisa, lalu membimbing revisi ke ID unik yang tidak kosong.","Menambahkan indeks biasa pada nama_siswa agar pencarian cepat sekaligus dianggap menjamin keunikan.","Memakai gabungan nama dan kelas, lalu menyimpulkan keunikan tanpa menguji murid bernama sama di satu kelas."],"key":"B","why":"Pertentangan data nyata mengungkap miskonsepsi: nama tidak menjamin keunikan, sedangkan ID siswa dapat menjadi PK. Guru membantu murid menemukan alasan sebelum memperbaiki ERD.","section":"PCK","package":1,"uid":"p1-001","explanations":["Definisi tanpa uji nama kembar belum membongkar alasan murid memilih nama.","ID unik dan tidak kosong memenuhi identitas baris; uji dua Nisa membuat kebutuhan itu terlihat.","Indeks biasa mempercepat pencarian tetapi tidak mewajibkan keunikan.","Nama dan kelas juga dapat sama; gabungan atribut harus dibuktikan memenuhi keunikan."]},{"id":2,"code":"P.1","type":"MCMA","stem":"Kelompok merancang basis data peminjaman alat lab. Guru ingin menghubungkan konsep relasi satu-ke-banyak dengan implementasi SQL. Aktivitas mana yang paling mendukung? Pilih semua jawaban yang tepat.","options":["Mengabaikan tabel referensi agar latihan lebih singkat.","Menempatkan id_siswa pada tabel peminjaman dan menguji data yang terhubung.","Meminta murid menjelaskan dampak jika id_siswa pada peminjaman tidak merujuk siswa yang ada.","Meminta murid menyalin definisi foreign key berulang kali.","Membuat contoh satu siswa yang memiliki beberapa peminjaman."],"key":["B","C","E"],"why":"Contoh kardinalitas, implementasi FK, dan pengujian referensi menghubungkan model relasi dengan perilaku basis data.","section":"PCK","package":1,"uid":"p1-002","explanations":["Tanpa tabel yang dirujuk, integritas FK tidak dapat dipelajari dengan benar.","FK di sisi banyak menghubungkan setiap pinjaman dengan siswa yang sesuai.","Kasus ID tak dikenal menguji fungsi constraint untuk mencegah referensi yatim.","Menyalin definisi tidak menunjukkan hubungan antara satu siswa dan banyak pinjaman.","Contoh beberapa pinjaman satu siswa memperlihatkan kardinalitas 1:N."]},{"id":3,"code":"P.1","type":"PG","stem":"Setelah menambahkan atribut required pada formulir Laravel, murid menganggap validasi di server tidak diperlukan. Cara paling tepat meluruskan pemahaman itu adalah ...","options":["Mengandalkan required browser untuk semua request.","Menambahkan pemeriksaan JavaScript yang menampilkan pesan sebelum submit tanpa pemeriksaan di server.","Menguji permintaan langsung ke server yang tidak melalui validasi browser, lalu membimbing validasi required dan format email di server.","Memberi peringatan visual ketika email kosong sambil tetap menerima request yang dikirim ke server."],"key":"C","why":"Validasi browser membantu pengalaman pengguna, tetapi pemeriksaan data tetap diperlukan di server. Demonstrasi request memperlihatkan alasan teknisnya.","section":"PCK","package":1,"uid":"p1-003","explanations":["Validasi browser dapat dilewati sehingga tidak menjamin penerimaan di server.","JavaScript juga berjalan di klien dan tidak melindungi request yang dikirim langsung.","Request langsung menunjukkan batas validasi klien; pemeriksaan server menolak data kosong atau format salah.","Warna peringatan membantu antarmuka tetapi tidak menolak data tidak valid di server."]},{"id":4,"code":"P.1","type":"Kategori","stem":"Guru memakai dua tabel kecil, siswa dan peminjaman, untuk membangun pemahaman JOIN. Nilai tiap tindakan sebagai Tepat atau Tidak tepat.","options":["Murid menjelaskan mengapa baris tertentu muncul atau tidak muncul dalam hasil INNER JOIN.","Murid memprediksi hasil JOIN sebelum menjalankan query, lalu membandingkan prediksi dengan keluaran.","Guru langsung memberikan query jadi tanpa membahas relasi tabel."],"key":["T","T","F"],"why":"Prediksi, uji, dan penjelasan hasil membangun model mental. Query yang hanya disalin dapat menghasilkan keluaran tanpa pemahaman relasi.","section":"PCK","package":1,"uid":"p1-004","explanations":["Alasan kemunculan baris menunjukkan pemahaman pasangan yang cocok pada INNER JOIN.","Prediksi sebelum eksekusi mengungkap model mental murid tentang hasil JOIN.","Query jadi tanpa relasi dapat disalin tanpa memahami kondisi penggabungan."]},{"id":5,"code":"P.1","type":"PG","stem":"Saat mengenalkan objek dalam pemrograman berorientasi objek, murid menyamakan class dan object. Representasi awal mana yang paling membantu?","options":["Menelusuri dua instans dari satu class dan membandingkan perubahan atributnya.","Menghafalkan deklarasi class tanpa membuat instans.","Menggambarkan dua objek sebagai satu keadaan global yang selalu sama.","Mengenalkan hierarki pewarisan lebih dahulu sebelum menguji apakah murid membedakan rancangan dan instans."],"key":"A","why":"Contoh dua objek dari satu class membedakan cetak biru dan instans sambil mempertahankan keterkaitan konsep dengan kode.","section":"PCK","package":1,"uid":"p1-005","explanations":["Dua instans memperlihatkan rancangan bersama dan keadaan objek yang berbeda.","Hafalan deklarasi belum membedakan class dari hasil instansiasinya.","Keadaan global tunggal justru menyesatkan tentang keadaan tiap objek.","Pewarisan menambah konsep baru sebelum miskonsepsi dasar diselesaikan."]},{"id":6,"code":"P.6","type":"MCMA","stem":"Kelompok belajar kolaborasi Git pada proyek website kelas. Bukti pemahaman alur kerja yang layak diminta guru adalah ... Pilih semua yang tepat.","options":["Memperlihatkan commit dengan pesan yang menjelaskan perubahan.","Menjelaskan kapan sebuah branch perlu digabung dan bagaimana menangani konflik.","Memastikan semua murid memakai satu akun agar mudah.","Menjelaskan perubahan lewat perbandingan diff pada dua versi kode.","Mengumpulkan satu file ZIP terakhir tanpa riwayat perubahan."],"key":["A","B","D"],"why":"Commit, penjelasan merge, dan diff memberi bukti proses serta pemahaman kolaborasi Git. ZIP akhir hanya menunjukkan produk; akun bersama mengaburkan kontribusi individu.","section":"PCK","package":1,"uid":"p1-006","explanations":["Commit bermakna memperlihatkan unit perubahan dan alasan pengerjaannya.","Penjelasan merge dan konflik menunjukkan pemahaman penggabungan pekerjaan.","Akun bersama mengaburkan identitas kontribusi dan tanggung jawab.","Diff memperlihatkan perubahan konkret antarversi yang dapat dijelaskan murid.","ZIP akhir tidak menunjukkan urutan perubahan atau keputusan integrasi."]},{"id":7,"code":"P.1","type":"PG","stem":"Pada kasus transaksi koperasi sekolah, setiap transaksi bisa berisi banyak jenis barang. Murid membuat satu kolom barang1, barang2, barang3 pada tabel transaksi. Langkah pemantik pembelajaran yang paling tepat adalah ...","options":["Menambah kolom barang hingga jumlah terbesar saat ini.","Menyatukan daftar barang dan jumlah menjadi satu teks.","Menguji transaksi enam barang dengan jumlah berbeda, lalu membimbing rancangan tabel detail yang berelasi.","Membuat tabel transaksi terpisah untuk setiap barang."],"key":"C","why":"Kasus enam barang menonjolkan keterbatasan kolom berulang dan kebutuhan tabel detail yang terhubung dengan transaksi serta barang.","section":"PCK","package":1,"uid":"p1-007","explanations":["Penambahan kolom tetap membatasi jumlah barang dan mengulang struktur.","Teks gabungan menyulitkan pengujian jumlah, pencarian, dan relasi tiap barang.","Baris detail dapat menampung jumlah barang bervariasi dan kuantitas masing-masing.","Tabel per jenis barang memecah proses transaksi yang sama dan menyulitkan query lintas barang."]},{"id":8,"code":"P.1","type":"Kategori","stem":"Guru mengajar perulangan dengan tabel pelacakan nilai variabel. Nilai tindakan sebagai Tepat atau Tidak tepat.","options":["Memulai tabel pelacakan dari iterasi kedua dan mengabaikan nilai awal karena tidak memengaruhi penelusuran.","Membandingkan pelacakan manual dengan keluaran program lalu membahas selisihnya.","Menilai jawaban benar dari keluaran akhir saja tanpa memeriksa alasan murid."],"key":["F","T","F"],"why":"Trace table membantu menjelaskan keadaan program, bukan hanya hasil akhir. Membandingkan hasil merupakan kesempatan refleksi.","section":"PCK","package":1,"uid":"p1-008","explanations":["Nilai awal diperlukan untuk menelusuri program secara lengkap; mengabaikannya dapat menyebabkan langkah pertama dan hasil pelacakan keliru.","Selisih pelacakan dan eksekusi menjadi bukti untuk meninjau langkah yang salah.","Keluaran saja dapat kebetulan benar dan menyembunyikan penalaran yang keliru."]},{"id":9,"code":"P.2","type":"PG","stem":"Asesmen awal menunjukkan sebagian murid sudah lancar SELECT-WHERE, sebagian belum mengenal kondisi WHERE. Strategi paling responsif adalah ...","options":["Mengulang semua SELECT dengan kegiatan dan tempo identik agar semua murid memperoleh perlakuan yang sama.","Membedakan bantuan dan tantangan secara fleksibel, lalu mengecek tujuan inti yang sama.","Menetapkan kelompok mahir dan belum mampu untuk satu semester berdasarkan hasil asesmen awal tersebut.","Meminta murid mahir menyelesaikan query teman yang kesulitan agar keluaran setiap kelompok memenuhi target."],"key":"B","why":"Diferensiasi menyesuaikan jalan menuju tujuan yang sama berdasarkan kebutuhan nyata; bukan pelabelan kelompok tetap.","section":"PCK","package":1,"uid":"p1-009","explanations":["Pengulangan seragam mengabaikan kebutuhan dukungan dan pengayaan yang terungkap.","Dukungan fleksibel mengikuti bukti kesiapan dan dapat diubah setelah cek ulang.","Satu asesmen tidak membenarkan pelabelan kemampuan yang permanen.","Produk yang dikerjakan teman tidak membuktikan pemahaman murid yang dibantu."]},{"id":10,"code":"P.2","type":"Kategori","stem":"Guru ingin semua murid dapat menguji query SQL. Empat murid belum mendapat komputer. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Menetapkan nilai akhir keterampilan hanya dari murid yang mendapat komputer, tanpa memberi kesempatan asesmen setara kepada murid lain.","Menyiapkan tugas prediksi query atau rancangan ERD saat menunggu giliran praktik.","Menyusun giliran operator, penguji, dan pencatat sehingga semua berperan dan berganti peran."],"key":["F","T","T"],"why":"Rotasi dan tugas tanpa perangkat menjaga partisipasi serta kesempatan menunjukkan capaian. Penilaian harus adil terhadap akses.","section":"PCK","package":1,"uid":"p1-010","explanations":["Nilai akhir itu mengecualikan murid yang belum mendapat kesempatan menunjukkan keterampilan; ini berbeda dari asesmen bergiliran.","Prediksi query dan ERD menjaga aktivitas berpikir saat menunggu praktik.","Rotasi memastikan akses ke praktik dan tanggung jawab dibagi."]},{"id":11,"code":"P.2","type":"MCMA","stem":"Murid diminta menelusuri percabangan untuk masukan tertentu. Seorang murid kesulitan membaca tangkapan layar kode yang kecil karena hambatan penglihatan. Pilih semua penyesuaian yang tepat.","options":["Memperbesar judul slide sementara kode tetap disajikan sebagai tangkapan layar kecil.","Memastikan kontras dan keterbacaan bahan praktik.","Mengizinkan murid menjelaskan jalur percabangan secara lisan atau tertulis untuk masukan yang sama.","Mengecualikan murid dari asesmen agar tidak kesulitan.","Menyediakan teks kode yang dapat diperbesar atau dibaca pembaca layar."],"key":["B","C","E"],"why":"Penyesuaian akses dan cara respons dapat menjaga target kompetensi. Menghapus kesempatan praktik atau asesmen bukan pilihan inklusif.","section":"PCK","package":1,"uid":"p1-011","explanations":["Perubahan judul tidak mengatasi hambatan membaca kode yang diperlukan untuk menelusuri percabangan.","Kontras dan keterbacaan mengurangi hambatan visual pada bahan.","Cara menyampaikan jawaban dapat disesuaikan sambil tetap meminta penalaran jalur percabangan untuk masukan yang sama.","Pengecualian asesmen menghilangkan bukti capaian alih-alih memperbaiki aksesnya.","Kode berbentuk teks memungkinkan pembesaran dan teknologi bantu."]},{"id":12,"code":"P.2","type":"PG","stem":"Murid yang cepat selesai CRUD mulai tidak tertantang, sementara teman lain masih membuat tabel. Tindakan terbaik adalah ...","options":["Memberi tantangan uji batas bagi yang siap dan contoh bertahap bagi yang masih membuat tabel.","Meminta murid cepat menyelesaikan kode kelompok lain.","Menghentikan semua kegiatan sampai rancangan tabel tiap murid selesai, termasuk bagi murid yang siap melanjutkan.","Memberi tambahan salinan CRUD yang sama kepada murid cepat tanpa menentukan tujuan atau tantangan baru."],"key":"A","why":"Tantangan pengayaan dan scaffolding disesuaikan kesiapan. Tutor sebaya boleh membantu, tetapi tidak menggantikan tanggung jawab guru.","section":"PCK","package":1,"uid":"p1-012","explanations":["Pengayaan dan bantuan bertahap memberi tantangan sesuai kesiapan masing-masing.","Mengerjakan kode teman mengambil kesempatan belajar dan mengaburkan bukti individu.","Menunggu produk identik tidak memberi kegiatan yang sesuai kebutuhan berbeda.","Salinan tambahan menambah beban tanpa memperluas pemahaman."]},{"id":13,"code":"P.2","type":"PG","stem":"Dalam diskusi ERD ada murid yang sulit mengikuti penjelasan lisan di ruang bising. Respons guru yang paling tepat adalah ...","options":["Menegur kurang fokus sebelum memeriksa hambatan akses.","Memperkeras suara tanpa mengecek pemahaman.","Memberi instruksi tertulis dan ERD berlabel, lalu mengecek secara pribadi apakah murid dapat menjelaskan relasinya.","Membebaskan murid dari penjelasan hubungan entitas dan hanya meminta salinan gambar agar tugasnya lebih ringan."],"key":"C","why":"Akses multimodal dan pengecekan pemahaman membuat murid dapat ikut tanpa distigma.","section":"PCK","package":1,"uid":"p1-013","explanations":["Teguran sebelum memeriksa hambatan akses tidak mengatasi kesulitan mengikuti penjelasan di ruang bising.","Volume saja tidak menjamin instruksi terbaca atau dipahami.","Instruksi tertulis dan label membantu akses penjelasan; murid tetap diminta menjelaskan hubungan entitas.","Pembebasan tujuan menghilangkan kesempatan belajar padahal akses dapat diperbaiki."]},{"id":14,"code":"P.3","type":"PG","stem":"Saat latihan debugging banyak murid malu karena error. Guru ingin kelas aman untuk mencoba. Respons terbaik adalah ...","options":["Memperbaiki seluruh error tanpa penelusuran oleh murid.","Memodelkan diagnosis, menyepakati komentar yang aman, lalu memberi kesempatan mencoba dan merevisi.","Mengganti debugging dengan menyalin kode jadi.","Melombakan jumlah error sebelum mengajarkan diagnosis."],"key":"B","why":"Menormalisasi kesalahan sebagai bukti proses belajar dan mengajarkan strategi diagnosis mendukung keberanian bereksperimen.","section":"PCK","package":1,"uid":"p1-014","explanations":["Perbaikan oleh guru saja tidak membangun keberanian dan strategi diagnosis murid.","Pemodelan dan kesepakatan komentar aman membuat error dapat dipakai sebagai bukti belajar.","Menyalin kode menghilangkan kesempatan berlatih diagnosis.","Lomba tanpa dukungan dapat memperkuat ketakutan membuat kesalahan."]},{"id":15,"code":"P.3","type":"Kategori","stem":"Dalam proyek penjadwalan piket lab, murid dapat menyusun urutan tugas tetapi belum melihat manfaat algoritma bagi pengguna. Nilai rancangan pembelajaran sebagai Tepat atau Tidak tepat.","options":["Menilai kebermaknaan proyek dari banyaknya animasi presentasi tanpa menguji apakah jadwal dapat dilaksanakan.","Membuka dengan kendala jadwal yang benar-benar dihadapi kelas dan mengajak murid menetapkan tujuan solusi.","Mengajak murid merefleksikan bagaimana aturan penjadwalan membantu pembagian tugas yang adil."],"key":["F","T","T"],"why":"Masalah penjadwalan nyata, tujuan yang disadari, dan refleksi dampak menghubungkan algoritma dengan pengalaman kelas.","section":"PCK","package":1,"uid":"p1-015","explanations":["Animasi presentasi tidak membuktikan jadwal memenuhi kendala pengguna.","Kendala nyata dan tujuan bersama membantu murid menyadari manfaat algoritma.","Refleksi dampak pembagian tugas menghubungkan konsep dengan pengalaman kelas."]},{"id":16,"code":"P.3","type":"MCMA","stem":"Dua kelompok memakai cara pencarian berbeda yang sama-sama lolos uji. Sebagian murid enggan menjelaskan caranya karena takut diejek. Pilih praktik guru yang mendukung diskusi aman dan menantang.","options":["Menutup pembahasan alternatif setelah satu kode berhasil dijalankan.","Memberi kriteria keberhasilan yang jelas dan kesempatan memperbaiki produk.","Memuji proses pengujian dan argumentasi, bukan hanya jawaban tercepat.","Mewajibkan semua murid meniru satu cara tanpa berdiskusi.","Mengizinkan kelompok menjelaskan alternatif solusi tanpa diejek."],"key":["B","C","E"],"why":"Keamanan psikologis, kesempatan revisi, dan penghargaan atas alasan membangun keterlibatan tanpa menurunkan standar.","section":"PCK","package":1,"uid":"p1-016","explanations":["Keberhasilan satu kode tidak menghilangkan manfaat membandingkan alasan dan hasil pengujian solusi lain.","Kriteria dan kesempatan revisi menjaga tantangan sekaligus memberi arah perbaikan.","Pengujian dan argumentasi merupakan proses belajar yang layak dihargai.","Satu cara wajib tanpa diskusi menutup kesempatan menalar alternatif yang sah.","Alternatif dapat dibahas jika suasana melindungi murid dari ejekan."]},{"id":17,"code":"P.3","type":"PG","stem":"Menjelang akhir sesi array, beberapa murid mengatakan pencarian selalu berhenti di elemen pertama meski data belum ditemukan. Guru memiliki delapan menit untuk menjaga keterlibatan sekaligus menguji pemahaman. Kegiatan terbaik adalah ...","options":["Menayangkan video motivasi agar murid kembali bersemangat tanpa menghubungkannya dengan kondisi berhenti pencarian.","Meminta murid menyalin istilah array sampai bel selesai agar semua tetap terlihat bekerja.","Meminta murid tercepat menyebut hasil pencarian sementara murid lain menyalin hasil tanpa menelusuri langkahnya.","Menguji target yang tidak ada lewat kartu array, lalu meminta revisi pemahaman kondisi berhenti."],"key":"D","why":"Tantangan singkat yang relevan, terdukung, dan diakhiri refleksi menjaga keterlibatan sambil mengungkap miskonsepsi kondisi berhenti.","section":"PCK","package":1,"uid":"p1-017","explanations":["Motivasi umum tidak menguji miskonsepsi berhenti di elemen pertama.","Menyalin istilah tidak menguji langkah pencarian.","Jawaban satu murid tidak memberi bukti atau keterlibatan murid lain.","Target yang tidak ada mengharuskan menelusuri array dan merefleksikan kondisi berhenti."]},{"id":18,"code":"P.4","type":"PG","stem":"Murid menggunakan AI untuk membuat kode autentikasi dan menganggap hasilnya pasti aman. Guru sebaiknya ...","options":["Melarang pembahasan AI tanpa memeriksa kode murid.","Menguji kode bersama murid, memeriksa penyimpanan kata sandi dan validasi masukan, lalu membahas keterbatasan AI.","Memberi nilai penuh setelah kode berjalan dan menunda pemeriksaan keamanan karena autentikasi sudah tampak berhasil.","Mengunggah kredensial server sekolah ke layanan AI agar perbaikan dapat disesuaikan langsung dengan sistem sebenarnya."],"key":"B","why":"Literasi AI mencakup verifikasi fungsi, keamanan, sumber data, dan tanggung jawab penggunaan.","section":"PCK","package":1,"uid":"p1-018","explanations":["Larangan pembicaraan tidak mengajarkan verifikasi keluaran AI.","Uji dan penjelasan keamanan melatih penggunaan AI secara kritis.","Program berjalan belum membuktikan keamanan autentikasi.","Kredensial asli tidak diperlukan untuk belajar dan membukanya menambah risiko akses."]},{"id":19,"code":"P.4","type":"Kategori","stem":"Guru memakai platform daring agar murid membandingkan validasi formulir di browser dan server. Sebagian murid hanya dapat belajar luring. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Memilih platform dari banyaknya fitur dan mengubah tujuan agar seluruh fitur dipakai.","Mengunggah data identitas siswa asli ke layanan publik agar contoh terlihat realistis.","Menyediakan contoh formulir dan server lokal yang dapat diuji saat akses daring terbatas."],"key":["F","F","T"],"why":"Pemilihan platform harus mendukung pengujian validasi, menjaga privasi, dan menyediakan akses yang sesuai kondisi murid. Banyak fitur atau data identitas asli tidak menjamin tujuan itu tercapai.","section":"PCK","package":1,"uid":"p1-019","explanations":["Jumlah fitur tidak menunjukkan apakah platform membantu murid memahami perbedaan validasi browser dan server.","Identitas asli di layanan publik tidak diperlukan dan melanggar prinsip privasi.","Contoh lokal mempertahankan kesempatan membandingkan validasi browser dan server tanpa bergantung pada jaringan luar."]},{"id":20,"code":"P.4","type":"MCMA","stem":"Internet lab terputus. Guru ingin murid memahami alur request-response API, bukan sekadar menghafal istilah. Pilih semua adaptasi yang tepat.","options":["Memakai kartu berisi method, path, dan respons untuk menelusuri pertukaran pesan sebelum uji lokal.","Mengganti tujuan menjadi menghafal nama layanan API publik karena layanan tidak dapat diakses.","Memakai server simulasi lokal yang sudah disiapkan agar murid mengamati request dan respons tanpa internet.","Meminta prediksi respons untuk beberapa request lalu membandingkannya dengan simulasi lokal.","Menampilkan tangkapan layar respons saja dan menganggap murid sudah membuktikan hubungan request-response."],"key":["A","C","D"],"why":"Representasi pesan, simulasi lokal, dan prediksi-uji mempertahankan tujuan API ketika internet terputus; sekadar istilah atau gambar hasil tidak cukup.","section":"PCK","package":1,"uid":"p1-020","explanations":["Kartu pesan mengonkretkan alur sebelum murid menguji pertukaran data.","Nama layanan tidak menggantikan pemahaman alur pesan.","Server lokal memungkinkan pengamatan teknis tanpa koneksi luar.","Perbandingan prediksi dan respons lokal menguji model mental murid.","Gambar respons tanpa hubungan dengan request belum membuktikan pemahaman alur."]},{"id":21,"code":"P.4","type":"PG","stem":"Guru hendak memilih aplikasi gambar ERD daring. Murid mampu menggambar ERD di kertas. Prinsip pilihan paling tepat adalah ...","options":["Memilih alat populer sebagai bukti manfaat belajar.","Mewajibkan semua tahap digital meski waktu tersita.","Memakai alat bila membantu uji, revisi, atau kolaborasi; tetap memakai kertas bila tujuan tercapai.","Mengutamakan hasil digital dalam nilai meskipun ERD kertas memiliki hubungan dan alasan yang lebih tepat."],"key":"C","why":"Alat dipilih jika membantu murid menguji dan merevisi relasi pada ERD; kertas tetap dapat dipakai bila tujuan itu tercapai.","section":"PCK","package":1,"uid":"p1-021","explanations":["Popularitas tidak membuktikan manfaat atau akses yang sesuai kelas.","Registrasi yang menyita waktu tanpa manfaat dapat menghambat tujuan.","Pengujian relasi dan revisi adalah nilai tambah; media dipilih sesuai manfaatnya.","Format digital saja tidak membuktikan kualitas ERD lebih baik dari kertas."]},{"id":22,"code":"P.4","type":"PG","stem":"Sebuah generator kode AI menghasilkan query yang menampilkan informasi pribadi siswa tanpa pembatasan. Tugas belajar yang paling tepat adalah ...","options":["Membandingkan query dengan kebutuhan akses, membatasi data keluaran, dan menguji hasilnya.","Memercayai query karena dapat dijalankan.","Mempublikasikan hasil berisi data pribadi untuk dinilai.","Mengganti topik keamanan dengan hafalan sintaks."],"key":"A","why":"Kritik terhadap keluaran otomatis menuntut pemahaman kebutuhan, minimisasi data, dan pengujian hasil.","section":"PCK","package":1,"uid":"p1-022","explanations":["Membandingkan kebutuhan dan keluaran melatih minimisasi serta pemeriksaan akses data.","Query yang dapat dijalankan belum tentu sesuai kebutuhan atau aman.","Publikasi memperluas paparan data yang justru perlu dibatasi.","Menghapus topik membuat murid kehilangan kesempatan belajar mengatasi masalahnya."]},{"id":23,"code":"P.5","type":"PG","stem":"Guru ingin memberi tugas rancangan basis data yang dekat dengan kehidupan murid. Masalah peminjaman alat olahraga sekolah tersedia dan datanya bisa disimulasikan. Kegiatan terbaik adalah ...","options":["Memberikan skema industri lengkap sebelum murid mengamati proses setempat agar rancangan terlihat profesional.","Meminta salinan skema dari internet sebagai hasil akhir tanpa membandingkannya dengan kebutuhan peminjaman.","Menilai rancangan dari banyaknya tabel yang dibuat, dengan asumsi jumlah tabel menunjukkan kelengkapan kebutuhan.","Mengobservasi alur peminjaman, memodelkan relasi, lalu menguji dengan transaksi contoh."],"key":"D","why":"Kebutuhan lokal yang konkret dapat menghubungkan konsep ERD, relasi, dan validasi rancangan.","section":"PCK","package":1,"uid":"p1-023","explanations":["Skema industri tanpa hubungan dengan konteks dapat menambah beban sebelum konsep terbentuk.","Salinan skema tidak menunjukkan pemahaman kebutuhan pengguna.","Jumlah tabel bukan ukuran kecocokan rancangan.","Observasi dan transaksi uji menghubungkan kebutuhan lokal dengan keputusan model data."]},{"id":24,"code":"P.5","type":"Kategori","stem":"Guru memilih kasus koperasi setempat untuk pembelajaran entitas dan relasi di SMK. Pengalaman murid tentang koperasi beragam. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Menggunakan transaksi tiruan untuk mengenali entitas dan relasi sambil menjelaskan proses koperasi yang belum dikenal murid.","Memilih konteks hanya karena tren walaupun tidak mendukung kompetensi yang dinilai.","Meminta murid yang belum mengenal koperasi menunggu tanpa aktivitas sampai teman lain selesai."],"key":["T","F","F"],"why":"Konteks lokal membantu jika relevan dan membuka beragam pengalaman; guru tidak boleh berasumsi semua murid sama.","section":"PCK","package":1,"uid":"p1-024","explanations":["Transaksi setempat menjadi sumber belajar pemodelan data; penjelasan proses membantu murid dengan pengalaman awal berbeda.","Tren tanpa hubungan dengan kompetensi tidak memberi alasan pedagogis pemilihan kasus.","Perbedaan pengalaman perlu dukungan atau konteks setara, bukan penghentian kesempatan belajar."]},{"id":25,"code":"P.5","type":"MCMA","stem":"Guru memilih kasus antrean layanan perpustakaan sekolah untuk mengajarkan algoritma FIFO. Komputer dipakai bergiliran. Pilih tindakan yang menjaga tujuan algoritma dan memanfaatkan sumber lokal.","options":["Murid bergiliran menjadi pemohon, petugas antrean, dan penelusur perubahan queue dengan kartu sebelum menguji kode.","Menilai pemahaman FIFO terutama dari kecepatan mengetik program yang dicontohkan guru.","Memakai catatan kedatangan tiruan untuk memeriksa urutan masuk dan keluar antrean.","Murid menjelaskan hasil simulasi kartu, lalu membandingkan urutannya dengan program saat mendapat perangkat.","Menyamakan FIFO dengan selalu melayani permintaan yang paling singkat tanpa membahas urutan kedatangan."],"key":["A","C","D"],"why":"Simulasi antrean lokal, data kedatangan, dan pembandingan dengan program menjaga konsep FIFO meskipun perangkat terbatas.","section":"PCK","package":1,"uid":"p1-025","explanations":["Peran kartu dan penelusuran queue memberi pengalaman konsep meskipun belum memakai komputer.","Kecepatan mengetik tidak menunjukkan urutan pengeluaran data.","Catatan kedatangan memungkinkan murid menguji aturan masuk lebih dahulu keluar lebih dahulu.","Pembandingan kartu dan program menghubungkan representasi lokal dengan implementasi.","Permintaan tersingkat adalah aturan lain; bukan definisi FIFO."]},{"id":26,"code":"P.5","type":"PG","stem":"Guru ingin murid memodelkan data produk dan transaksi dari usaha keluarga yang mereka kenal. Kelompok hendak memakai data pelanggan asli. Respons paling tepat adalah ...","options":["Menghapus nama tetapi tetap membagikan nomor telepon.","Membuat dataset sintetis yang mempertahankan kebutuhan usaha lokal serta membahas perlindungan data.","Menaruh data asli di akun bersama agar seluruh kelompok dan guru dapat memeriksa hasil praktik dengan mudah.","Meminta murid menyalin tabel contoh umum sebagai rancangan akhir untuk usaha tersebut."],"key":"B","why":"Kasus lokal tetap dapat dipakai tanpa membuka data pribadi; tujuan pembelajaran terletak pada model dan logika data.","section":"PCK","package":1,"uid":"p1-026","explanations":["Nomor telepon tetap dapat mengidentifikasi pelanggan; menghapus nama saja belum menghilangkan paparan.","Dataset sintetis mempertahankan proses usaha sebagai sumber belajar tanpa mengekspos pelanggan.","Akun bersama memperluas akses ke data yang tidak diperlukan untuk tujuan model basis data.","Tabel contoh dapat menjadi bantuan awal, tetapi salinannya belum membuktikan rancangan sesuai kebutuhan usaha yang sedang dipelajari."]},{"id":27,"code":"P.6","type":"PG","stem":"Sebelum mengajar PK dan FK, guru bertanya apakah dua orang boleh memiliki nama sama dan apakah dua peminjaman bisa dilakukan satu siswa. Fungsi utama pertanyaan itu ialah ...","options":["Memetakan gagasan awal tentang identitas unik dan relasi untuk memilih dukungan belajar.","Menetapkan nilai akhir dari dua jawaban awal.","Menguji hafalan sintaks JOIN lanjutan.","Menyaring murid yang boleh memakai komputer berdasarkan benar-salahnya dua jawaban awal tersebut."],"key":"A","why":"Pertanyaan sebelum pembelajaran memunculkan konsepsi awal dan membantu memilih dukungan belajar.","section":"PCK","package":1,"uid":"p1-027","explanations":["Pertanyaan memunculkan gagasan awal identitas unik dan relasi untuk merencanakan dukungan.","Sebelum pembelajaran, jawaban awal tidak cukup menjadi penilaian akhir capaian.","Pertanyaan tidak meminta sintaks SQL lanjutan.","Diagnosis bertujuan memberi dukungan, bukan melarang murid praktik."]},{"id":28,"code":"P.6","type":"MCMA","stem":"Murid menghasilkan query JOIN tetapi sebagian rekaman hilang. Bukti asesmen formatif apa yang membantu guru menemukan sumber masalah? Pilih semua.","options":["Memeriksa apakah kondisi JOIN dan data kunci cocok.","Memberikan nilai nol sebelum mengetahui alasan kesalahan.","Meminta murid menjelaskan tabel mana yang menjadi asal setiap kolom.","Mencatat hanya waktu tercepat menjalankan query.","Meminta prediksi baris yang seharusnya muncul dan membandingkannya dengan hasil."],"key":["A","C","E"],"why":"Penelusuran asal kolom, prediksi data, dan pemeriksaan kondisi JOIN menunjukkan miskonsepsi secara spesifik.","section":"PCK","package":1,"uid":"p1-028","explanations":["Kondisi dan nilai kunci membantu membedakan kesalahan query dari data tanpa pasangan.","Nilai nol tanpa diagnosis tidak memberi informasi sumber masalah.","Asal kolom membantu menemukan kekeliruan memahami relasi dan alias.","Kecepatan tidak menerangkan mengapa rekaman hilang.","Prediksi baris mengungkap hasil yang dipahami murid dan letak selisihnya."]},{"id":29,"code":"P.6","type":"Kategori","stem":"Guru membuat rubrik tugas ERD. Nilai pernyataan berikut sebagai Tepat atau Tidak tepat.","options":["Guru menjelaskan rubrik sebelum bekerja sehingga murid dapat menggunakannya untuk revisi.","Kriteria mencakup kecocokan entitas, PK, kardinalitas, dan alasan hubungan dengan kasus.","Penilaian hanya berdasarkan warna dan kerapian gambar, tanpa memeriksa kebenaran model."],"key":["T","T","F"],"why":"Rubrik selaras dengan tujuan belajar dan transparan sejak awal. Tampilan boleh dipertimbangkan, tetapi bukan inti kompetensi ERD.","section":"PCK","package":1,"uid":"p1-029","explanations":["Rubrik di awal memberi standar yang dapat dipakai murid meninjau rancangan.","Entitas, PK, kardinalitas, dan alasan mengukur substansi ERD.","Warna dapat membantu komunikasi tetapi tidak menggantikan ketepatan model."]},{"id":30,"code":"P.6","type":"PG","stem":"Murid menggambar relasi siswa–peminjaman sebagai 1:1 padahal satu siswa dapat meminjam berkali-kali. Umpan balik yang paling berguna adalah ...","options":["Mengganti simbol 1:1 menjadi 1:N tanpa meminta alasan.","Merapikan gambar sambil menganggap relasinya benar.","Meminta uji satu siswa dengan tiga transaksi, lalu membimbing penjelasan revisi kardinalitas.","Menyalin gambar kunci tanpa menjelaskan kardinalitas."],"key":"C","why":"Umpan balik spesifik memicu pengujian model terhadap kasus sehingga siswa memahami alasan perbaikan.","section":"PCK","package":1,"uid":"p1-030","explanations":["Perubahan simbol tanpa alasan tidak membantu murid menguji modelnya.","Kerapian tidak menyelesaikan ketidaksesuaian kardinalitas dengan transaksi.","Kasus tiga transaksi memberi bukti langsung untuk memperbaiki kardinalitas.","Menyalin gambar kunci tidak menjelaskan hubungan model dengan kebutuhan."]},{"id":31,"code":"P.6","type":"PG","stem":"Setelah kuis JOIN, 70% murid salah membedakan INNER dan LEFT JOIN. Langkah selanjutnya paling tepat adalah ...","options":["Memberikan contoh INNER JOIN dan LEFT JOIN yang seluruh barisnya memiliki pasangan.","Menganalisis kesalahan, mengajar ulang memakai baris tanpa pasangan, lalu mengecek penalaran.","Mengulang kuis sampai nilai naik tanpa membahas alasan salah, dengan asumsi pengulangan otomatis membentuk konsep.","Mengajarkan rumus LEFT JOIN selalu sama banyak dengan tabel kiri tanpa memeriksa kemungkinan beberapa pasangan."],"key":"B","why":"Hasil asesmen harus dipakai untuk mengubah pengajaran. Data tanpa pasangan memberi bukti konkret perbedaan jenis JOIN.","section":"PCK","package":1,"uid":"p1-031","explanations":["Data dengan semua baris berpasangan belum memperlihatkan perbedaan yang menjadi kesulitan kelas; B menargetkan baris tanpa pasangan dan mengecek ulang penalaran.","Baris tanpa pasangan memperlihatkan perbedaan INNER dan LEFT JOIN secara konkret.","Kuis berulang tanpa umpan balik tidak menargetkan penyebab salah.","LEFT JOIN dapat menghasilkan lebih banyak baris kiri jika ada banyak pasangan; rumus itu keliru."]},{"id":32,"code":"P.6","type":"MCMA","stem":"Tujuan praktik ialah merancang uji fungsi hitungDiskon(total) dengan batas diskon pada total >= 100000. Bukti asesmen apa yang relevan untuk mengetahui penalaran murid? Pilih semua.","options":["Catatan perbandingan hasil aktual dan hasil yang diharapkan untuk menemukan kegagalan.","Penjelasan alasan memilih kasus batas dan dampaknya jika operator >= diganti >.","Jumlah baris kode uji tanpa memeriksa perilaku apa yang diuji.","Daftar input di bawah, tepat pada, dan di atas batas beserta hasil yang diharapkan.","Tangkapan layar editor tanpa input dan hasil eksekusi."],"key":["A","B","D"],"why":"Input batas, perbandingan expected-actual, dan alasan pemilihan kasus menunjukkan penalaran pengujian; penampilan atau jumlah kode tidak cukup.","section":"PCK","package":1,"uid":"p1-032","explanations":["Expected-actual memperlihatkan perilaku yang menyimpang dari aturan.","Perubahan operator tepat di batas menunjukkan alasan pemilihan kasus.","Jumlah kode tidak menjamin kasus penting atau hasilnya diperiksa.","Input sekitar batas memperlihatkan transisi aturan diskon.","Editor tanpa eksekusi tidak menunjukkan fungsi diuji."]},{"id":33,"code":"P.6","type":"PG","stem":"Tujuan belajar ialah murid mampu memecah program kasir menjadi fungsi dengan tanggung jawab jelas dan menjelaskan aliran datanya. Asesmen paling selaras adalah ...","options":["Meminta murid menandai deklarasi dan pemanggilan fungsi pada program yang sudah dipecah.","Memberi skor semakin tinggi untuk semakin banyak fungsi tanpa memeriksa tanggung jawab serta aliran datanya.","Meminta murid menyalin hasil refaktor guru tanpa menjelaskan pemilihan parameter dan hasil setiap fungsi.","Meminta refaktor, penjelasan masukan-keluaran tiap fungsi, dan uji kesetaraan perilaku program."],"key":"D","why":"Refaktor beralasan disertai pengujian mengukur pembagian tanggung jawab dan aliran data, bukan jumlah fungsi atau hafalan definisi.","section":"PCK","package":1,"uid":"p1-033","explanations":["Menandai fungsi mengukur pengenalan struktur, belum kemampuan membagi tanggung jawab dan menjelaskan aliran data.","Banyak fungsi belum menjamin tanggung jawab jelas atau data mengalir benar.","Menyalin hasil refaktor tidak mengungkap alasan pemisahan.","Refaktor, penjelasan masukan-keluaran tiap fungsi, dan pengujian perilaku mengukur pembagian tanggung jawab serta aliran data secara langsung."]},{"id":34,"code":"P.6","type":"Kategori","stem":"Query murid untuk menampilkan semua siswa tidak memunculkan siswa tanpa peminjaman. Guru ingin murid memahami penyebabnya dan merevisi query. Nilai umpan balik berikut sebagai Tepat atau Tidak tepat.","options":["Memberi query benar untuk disalin sebagai perbaikan akhir.","Guru meminta murid memperbaiki hasilnya lalu menjelaskan perubahan dan alasan revisi.","Menunjukkan bagian query yang sudah benar, lalu meminta murid memeriksa hasil untuk siswa tanpa pasangan peminjaman."],"key":["F","T","T"],"why":"Umpan balik harus spesifik, aman, dan dapat ditindaklanjuti; revisi menunjukkan belajar dari asesmen.","section":"PCK","package":1,"uid":"p1-034","explanations":["Salinan query dapat memperbaiki keluaran, tetapi belum menunjukkan murid memahami penyebab hilangnya baris.","Penjelasan revisi membantu memastikan murid memahami perubahannya.","Petunjuk ini menghubungkan hasil yang hilang dengan perilaku penggabungan tabel tanpa langsung memberikan seluruh solusi."]},{"id":35,"code":"PF.1","type":"PG","stem":"Pembelajaran proyek aplikasi sekolah dianggap selesai jika website bisa dibuka. Agar tujuan pendidikan kejuruan tercapai lebih utuh, guru seharusnya juga ...","options":["Menilai alasan desain, tanggung jawab kerja, keamanan, dan tanggapan pengguna.","Menilai kesiapan kerja terutama dari kerapian halaman.","Menilai dari kemiripan tampilan dengan contoh.","Mengurutkan kemampuan kerja dari kecepatan mengetik tanpa meninjau kualitas solusi atau kontribusi kelompok."],"key":"A","why":"Kompetensi SMK mengaitkan penguasaan teknis, penalaran, kerja sama, etika, dan kemampuan beradaptasi.","section":"PCK","package":1,"uid":"p1-035","explanations":["Keputusan teknis, tanggung jawab, dan evaluasi pengguna menilai kecakapan kejuruan secara utuh.","Kerapian halaman belum cukup membuktikan fungsi, penalaran teknis, dan tanggung jawab kerja yang menjadi tujuan kejuruan.","Peniruan tampilan tidak menunjukkan kemampuan memenuhi kebutuhan.","Kecepatan mengetik bukan pengganti kualitas solusi dan etika kerja."]},{"id":36,"code":"PF.1","type":"Kategori","stem":"Proyek pembuatan sistem kelas dilakukan dalam pembelajaran. Nilai pernyataan sebagai Tepat atau Tidak tepat.","options":["Mengajarkan bahwa semua akun pengguna perlu hak admin agar akses lebih mudah.","Menganggap keberhasilan teknis membenarkan pengumpulan data pribadi berlebihan.","Mengaitkan kemampuan pemrograman dengan penyelesaian masalah nyata dan tanggung jawab sosial."],"key":["F","F","T"],"why":"Tujuan pendidikan menuntut kompetensi dan karakter; etika digital tidak boleh dikorbankan demi fitur.","section":"PCK","package":1,"uid":"p1-036","explanations":["Hak admin untuk semua akun tidak sesuai kebutuhan dan mengabaikan tanggung jawab pengelolaan akses.","Keberhasilan fitur tidak membenarkan pengumpulan data berlebihan.","Penyelesaian masalah dan tanggung jawab sosial mengaitkan teknik dengan tujuan pendidikan."]},{"id":37,"code":"PF.2","type":"PG","stem":"Saat mengajar keamanan aplikasi, murid membangun query dengan menggabungkan input pengguna ke string SQL. Penjelasan dan perbaikan yang tepat adalah ...","options":["Mengajarkan binding nilai dan membandingkan bagaimana data dipisahkan dari struktur SQL.","Menghapus petik lalu menganggap input lain pasti aman.","Memercayai validasi JavaScript untuk semua request.","Menyembunyikan error tanpa memperbaiki query."],"key":"A","why":"Parameter binding memisahkan data input dari struktur perintah SQL, sehingga efektif menjadi contoh konsep keamanan aplikasi.","section":"PCK","package":1,"uid":"p1-037","explanations":["Binding nilai memisahkan data dari struktur perintah; nama tabel dinamis tetap perlu mekanisme aman lain.","Menghapus petik bukan pengganti pemisahan data dan perintah.","Validasi klien dapat dilewati oleh request langsung.","Menyembunyikan error tidak memperbaiki kerentanan penggabungan input."]},{"id":38,"code":"PF.2","type":"MCMA","stem":"Dalam aplikasi koperasi, proses checkout menulis header transaksi dan detail barang. Simulasi kegagalan membuat header tersimpan tetapi detail tidak lengkap. Guru meminta murid menilai solusi yang menjaga atomisitas. Pilih semua yang tepat.","options":["Menangkap exception lalu tetap mengirim pesan sukses tanpa memeriksa konsistensi.","Menyimpulkan constraint foreign key saja menjamin semua langkah checkout selalu selesai bersama.","Membungkus penulisan terkait dalam satu transaksi basis data yang mendukung transaksi.","Melakukan commit header lebih dahulu agar selalu ada bukti meski penulisan detail gagal.","Melakukan rollback seluruh penulisan terkait jika satu langkah gagal dan menguji skenario kegagalannya."],"key":["C","E"],"why":"Atomisitas berarti seluruh perubahan terkait berhasil bersama atau dibatalkan bersama. Constraint relasi tidak menggantikan transaksi multi-langkah.","section":"PCK","package":1,"uid":"p1-038","explanations":["Pesan sukses setelah kegagalan menyembunyikan ketidakkonsistenan.","FK menjaga referensi, bukan menjamin beberapa operasi berhasil sebagai satu kesatuan.","Satu transaksi memungkinkan semua perubahan terkait di-commit bersama.","Commit header lebih awal menyisakan data parsial bila detail gagal.","Rollback dan simulasi gagal menunjukkan seluruh perubahan terkait dapat dibatalkan."]},{"id":39,"code":"PF.2","type":"PG","stem":"Murid mengirim form Laravel dengan method POST, tetapi route hanya didaftarkan untuk GET. Strategi pembelajaran tepat adalah ...","options":["Menambah token CSRF pada form saja dan menganggap permintaan POST kini pasti cocok dengan route GET.","Mengubah semua form penyimpanan menjadi GET agar sesuai route lama tanpa membahas maksud HTTP method.","Menelusuri method form dan route, lalu membetulkan route POST untuk operasi penyimpanan.","Menghapus validasi isian di controller dengan asumsi kegagalan mencapai route disebabkan aturan validasi data."],"key":"C","why":"Kesalahan method menjadi kesempatan memeriksa hubungan form, HTTP method, route, dan controller.","section":"PCK","package":1,"uid":"p1-039","explanations":["CSRF dan HTTP method menangani persoalan berbeda; token tidak membuat route GET menerima POST.","Mengubah penyimpanan ke GET menghindari diagnosis dan tidak sesuai maksud operasi.","Penelusuran request mengungkap ketidakcocokan dan mempertahankan method sesuai operasi.","Validasi isian tidak menyebabkan ketidakcocokan method route."]},{"id":40,"code":"PF.2","type":"Kategori","stem":"Tabel siswa berisi S1 dan S2; tabel peminjaman hanya berisi pinjaman milik S1. Query memakai ON siswa.id = peminjaman.id_siswa tanpa filter WHERE tambahan. Nilai konsep berikut sebagai Tepat atau Tidak tepat.","options":["Setiap LEFT JOIN selalu memiliki jumlah baris tepat sama dengan tabel kiri meski ada beberapa pasangan.","INNER JOIN pada kunci siswa hanya mengembalikan pasangan yang cocok dalam contoh ini.","LEFT JOIN dari tabel siswa ke peminjaman dapat tetap memunculkan S2 dengan kolom peminjaman bernilai NULL."],"key":["F","T","T"],"why":"INNER JOIN memerlukan pasangan; LEFT JOIN mempertahankan baris kiri, tetapi bisa menghasilkan lebih banyak baris jika satu baris kiri memiliki banyak pasangan.","section":"PCK","package":1,"uid":"p1-040","explanations":["Beberapa pinjaman S1 dapat menggandakan baris hasil sehingga jumlahnya tidak selalu sama dengan tabel kiri.","Tanpa filter tambahan, INNER JOIN mengembalikan baris yang cocok pada kondisi ON.","LEFT JOIN tetap memunculkan S2 tanpa pasangan dengan nilai kanan NULL."]},{"id":41,"code":"PF.2","type":"PG","stem":"Murid membuat kondisi “nilai >= 75” untuk menentukan tuntas. Saat nilai tepat 75, program menyatakan tuntas. Untuk menguji pemahaman kondisi batas, guru sebaiknya meminta ...","options":["Mengulang input 80 dan 90 untuk menguji batas 75.","Menguji 74, 75, dan 76 serta meminta alasan hasil operator >= pada tiap input.","Menguji 75 saja tanpa melihat kedua sisinya, lalu menyatakan seluruh perilaku perbandingan telah teruji.","Mengganti >= dengan > karena keduanya menghasilkan tuntas untuk contoh 80 yang sudah pernah dijalankan."],"key":"B","why":"Kasus batas 74, 75, 76 secara langsung menampakkan efek operator perbandingan.","section":"PCK","package":1,"uid":"p1-041","explanations":["Input jauh dari batas tidak membedakan >= dan > pada nilai 75.","Tiga input menguji kedua sisi dan titik batas sehingga makna operator terlihat.","Titik batas saja belum memeriksa perilaku sebelum dan sesudahnya.","Operator > tidak memasukkan 75 sehingga tidak setara dengan >=."]},{"id":42,"code":"PF.2","type":"MCMA","stem":"Murid membuat fungsi pencarian indeks dalam array. Tujuannya menguji bahwa hasil sesuai spesifikasi: kembalikan indeks pertama jika ada dan -1 jika tidak ada. Pilih semua rancangan uji yang benar.","options":["Menguji array kosong dan target yang tidak ada pada array berisi, dengan hasil yang diharapkan -1.","Menganggap hasil -1 salah untuk semua input karena indeks harus selalu nonnegatif.","Mengubah hasil yang diharapkan agar selalu mengikuti keluaran program tanpa meninjau spesifikasi.","Menguji array dengan target di dua posisi dan memastikan indeks kemunculan pertama yang dikembalikan.","Menyatakan satu contoh target di posisi awal sudah membuktikan seluruh kemungkinan benar."],"key":["A","D"],"why":"Spesifikasi menentukan hasil acuan pengujian: kemunculan pertama dan kondisi tidak ditemukan, termasuk array kosong, perlu dibedakan. Keluaran program bukan penentu hasil yang seharusnya benar.","section":"PCK","package":1,"uid":"p1-042","explanations":["Kedua input harus menghasilkan -1 sesuai kontrak tidak ditemukan.","Nilai -1 sengaja menjadi penanda tidak ditemukan dan bukan indeks elemen.","Hasil yang diharapkan harus berasal dari spesifikasi agar tes dapat mendeteksi kesalahan program.","Target berulang menguji syarat indeks pertama dalam spesifikasi.","Satu contoh awal tidak mencakup data berulang, kosong, atau target tidak ada."]},{"id":43,"code":"PF.3","type":"PG","stem":"Sebagian siswa memahami logika program tetapi kesulitan membaca instruksi teks panjang. Guru ingin mengukur logika seleksi kondisi. Penyesuaian terbaik adalah ...","options":["Memberi instruksi ringkas dan contoh masukan-keluaran, lalu meminta murid menyusun logika untuk kasus baru.","Mengganti asesmen logika dengan hafalan istilah.","Menurunkan target karena kesulitan membaca.","Menetapkan kerapian tulisan jawaban sebagai ukuran utama meskipun sasaran yang diminta ialah logika seleksi."],"key":"A","why":"Dukungan mengurangi hambatan bahasa sambil mempertahankan tuntutan menyusun logika seleksi. Hafalan istilah, penurunan target, dan penilaian tulisan tangan tidak mengukur tujuan yang sama.","section":"PCK","package":1,"uid":"p1-043","explanations":["Instruksi ringkas mengurangi hambatan membaca; murid tetap harus menyusun logika, bukan menyalin diagram solusi yang sudah lengkap.","Hafalan istilah mengganti kompetensi seleksi kondisi.","Hambatan bahasa tidak membuktikan ketidakmampuan logika.","Tulisan tangan bukan sasaran pemrograman yang diukur."]},{"id":44,"code":"PF.3","type":"MCMA","stem":"Sebelum proyek antarmuka aplikasi inventaris lokal, guru menemukan murid terbiasa layar besar tetapi calon pengguna memakai ponsel kecil dan jaringan lambat. Tujuan inti tetap kemampuan merancang dan menguji antarmuka yang dapat digunakan. Pilih adaptasi yang tepat.","options":["Menghilangkan tujuan pengujian antarmuka karena perangkat pengguna berbeda dari komputer lab.","Menyediakan prototipe lokal dan simulasi layar kecil untuk menguji akses ke fungsi inti.","Menganggap kebiasaan murid memakai media sosial otomatis membuktikan pemahaman desain antarmuka.","Membantu murid mengidentifikasi kebutuhan pengguna dan prasyarat tata letak sebelum membuat antarmuka.","Meminta murid membandingkan tugas pengguna pada dua ukuran layar dan menjelaskan hambatan yang ditemukan."],"key":["B","D","E"],"why":"Kebutuhan pengguna lokal dan karakteristik materi antarmuka menuntut pengujian ukuran layar serta dukungan prasyarat; kebiasaan memakai aplikasi belum membuktikan kemampuan merancang.","section":"PCK","package":1,"uid":"p1-044","explanations":["Perbedaan perangkat perlu diadaptasi, bukan menghapus kemampuan pengujian.","Prototipe lokal dan layar kecil menanggapi karakteristik penggunaan yang nyata.","Pemakai aplikasi belum tentu memahami prinsip perancangan antarmuka.","Identifikasi kebutuhan dan prasyarat membantu murid memasuki materi yang sesuai.","Perbandingan tugas pengguna menghasilkan bukti hambatan antarmuka."]},{"id":45,"code":"PF.3","type":"Kategori","stem":"Untuk menetapkan kesiapan kelas sebelum materi API, nilai tindakan berikut sebagai Tepat atau Tidak tepat.","options":["Memeriksa apakah murid sudah memahami request, response, dan format data sederhana.","Langsung memberi proyek integrasi API besar sebelum memeriksa pemahaman request dan format data.","Menganggap semua murid otomatis memahami API karena sering memakai aplikasi."],"key":["T","F","F"],"why":"Membaca kebutuhan berdasarkan prasyarat nyata, bukan asumsi kebiasaan memakai teknologi.","section":"PCK","package":1,"uid":"p1-045","explanations":["Prasyarat request-response memberi dasar menilai kesiapan API.","Proyek besar tanpa pemeriksaan prasyarat tidak menanggapi kebutuhan kesiapan murid.","Sering memakai aplikasi tidak menjamin memahami pertukaran data."]},{"id":46,"code":"PF.4","type":"PG","stem":"Sekolah perlu mengontekstualkan pembelajaran RPL dengan kebutuhan inventaris. Guru sedang menyusun alur tujuan pembelajaran. Pilihan terbaik adalah ...","options":["Mengganti capaian dengan dekorasi yang disukai.","Menulis tujuan mengikuti aktivitas yang populer.","Menurunkan tujuan analisis, model data, dan pengujian dari capaian dengan konteks inventaris.","Menetapkan dukungan sama tanpa memeriksa prasyarat."],"key":"C","why":"Adaptasi kurikulum tetap menurunkan tujuan dari capaian dan memilih konteks untuk mencapainya.","section":"PCK","package":1,"uid":"p1-046","explanations":["Dekorasi saja mengganti kompetensi yang seharusnya diturunkan dari capaian.","Aktivitas populer tanpa tujuan tidak membentuk alur kompetensi.","Tujuan teknis menjadi dasar; inventaris merupakan konteks penerapannya.","Menyamakan murid tanpa bukti awal mengabaikan kebutuhan pengembangan alur."]},{"id":47,"code":"PF.4","type":"MCMA","stem":"Framework web berubah versi. Guru ingin materi tetap relevan secara kurikuler. Mana yang tepat? Pilih semua.","options":["Memperbarui contoh sesuai dokumentasi tepercaya sambil menguji kompatibilitas.","Membandingkan perubahan sintaks dengan prinsip yang tetap berlaku.","Menghapus semua pelajaran dasar karena framework akan selalu berubah.","Mempertahankan prinsip request-response, validasi, dan pengelolaan data sebagai konsep lintas-versi.","Mewajibkan murid menghafal seluruh sintaks versi lama tanpa memahami konsep."],"key":["A","B","D"],"why":"Kurikulum adaptif memperbarui contoh tanpa mengorbankan konsep fundamental serta tujuan kompetensi.","section":"PCK","package":1,"uid":"p1-047","explanations":["Dokumentasi dan uji kompatibilitas menjaga ketepatan contoh baru.","Perbandingan perubahan membantu murid mengaitkan sintaks dengan prinsip.","Perubahan framework tidak menghapus relevansi dasar request dan data.","Konsep lintas-versi menjaga tujuan ketika sintaks alat berubah.","Hafalan versi lama tanpa konsep tidak mempersiapkan adaptasi."]},{"id":48,"code":"PF.4","type":"Kategori","stem":"Guru menyelaraskan unit analisis kebutuhan perangkat lunak dengan tujuan murid dapat menurunkan kriteria penerimaan dari kebutuhan pengguna. Nilai keputusan kurikuler sebagai Tepat atau Tidak tepat.","options":["Menyediakan kasus kebutuhan lokal dan meminta murid menjelaskan hubungan kebutuhan dengan kriteria penerimaan yang dapat diuji.","Menjadikan hafalan nama alat manajemen proyek sebagai satu-satunya asesmen kriteria penerimaan.","Menyusun rubrik yang memeriksa keterlacakan kebutuhan, kejelasan kriteria, dan kelayakan pengujiannya."],"key":["T","F","T"],"why":"Kriteria penerimaan diturunkan dari kebutuhan pengguna dan harus dapat diuji; tujuan, kegiatan, dan rubrik perlu mengukur kemampuan yang sama.","section":"PCK","package":1,"uid":"p1-048","explanations":["Kriteria yang diturunkan dari kebutuhan memungkinkan pembuktian ketercapaian tujuan.","Nama alat tidak menunjukkan kemampuan menyusun kriteria penerimaan.","Rubrik keterlacakan dan keterujian selaras dengan kompetensi analisis kebutuhan."]},{"id":49,"code":"PF.5","type":"PG","stem":"Guru mencatat bahwa murid berulang kali salah menentukan foreign key walau sudah diberi penjelasan. Tindakan pengembangan praktik paling ilmiah adalah ...","options":["Mengulang penjelasan sama dan menafsirkan kesalahan sebagai kurang usaha sebelum meninjau bukti kerja murid.","Menguji intervensi data berelasi dan menelaah bukti sebelum-sesudah beserta keterbatasannya.","Mengadopsi strategi populer tanpa menentukan pola kesalahan atau bukti perubahan yang hendak diamati.","Memakai soal akhir yang sudah dihafal sebagai satu-satunya bukti bahwa intervensi menghasilkan pemahaman FK."],"key":"B","why":"Perbaikan profesional bertumpu pada identifikasi masalah, tindakan beralasan, bukti hasil, dan refleksi.","section":"PCK","package":1,"uid":"p1-049","explanations":["Menyimpulkan kurang usaha tanpa bukti menghambat evaluasi pendekatan guru.","Intervensi beralasan dan bukti sebelum-sesudah mendukung perbaikan tanpa klaim sebab-akibat yang berlebihan.","Popularitas tidak memberi bukti efektivitas pada kelas ini.","Hafalan contoh dapat menaikkan nilai tanpa transfer pemahaman FK."]},{"id":50,"code":"PF.5","type":"MCMA","stem":"Setelah proyek web, guru menemukan murid belum menguji formulir dengan masukan kosong. Guru meminta masukan komunitas RPL untuk memperbaiki pembelajaran pengujian. Pilih tindakan yang etis dan bermanfaat.","options":["Membagikan rubrik pengujian formulir dan hasil belajar anonim untuk mendapat masukan.","Menyebarkan nilai beserta nomor telepon siswa kepada publik.","Menguji saran rekan pada pembelajaran kasus masukan kosong dan mengamati perubahan hasil kerja murid.","Mendokumentasikan keterbatasan uji coba agar tidak mengklaim pasti berhasil.","Menetapkan saran rekan sebagai standar seluruh kelas sebelum menilai kecocokannya dengan masalah murid."],"key":["A","C","D"],"why":"Pengembangan praktik harus reflektif, terbuka pada bukti, dan melindungi identitas murid.","section":"PCK","package":1,"uid":"p1-050","explanations":["Rubrik dan hasil anonim membantu rekan menelaah masalah pembelajaran pengujian tanpa membuka identitas murid.","Nilai dan kontak publik melampaui kebutuhan telaah praktik.","Uji pada kesulitan yang ditemukan memberi bukti apakah saran membantu murid merancang dan menjelaskan pengujian.","Keterbatasan membantu menilai jangkauan temuan secara proporsional.","Saran perlu ditelaah dan diuji dalam konteks kelas; penerapan langsung belum memberi dasar bahwa masalah pembelajaran tertangani."]},{"id":51,"code":"P.1","type":"PG","stem":"Guru IPS ingin siswa memahami perubahan lingkungan, menerapkan konsep pada lingkungan sekitar, lalu merefleksikan pilihan tindakannya. Rancangan terbaik adalah ...","options":["Meminta kutipan definisi sebagai satu-satunya bukti.","Mengadakan kuis istilah tentang lingkungan tanpa meminta hubungan hasilnya dengan pilihan tindakan murid.","Mengamati masalah, menganalisis konsep, mengusulkan tindakan, lalu merefleksikan pilihan.","Menilai banyaknya foto observasi sebagai bukti penerapan tanpa meminta penjelasan hubungan dengan konsep."],"key":"C","why":"Rancangan ini menyatukan pemahaman konsep, penerapan kontekstual, dan refleksi bermakna sebagaimana P.1.","section":"PU","package":1,"uid":"p1-051","explanations":["Kutipan definisi belum menunjukkan penerapan dan refleksi yang menjadi tujuan.","Kuis istilah belum menuntun keputusan dalam konteks sekitar.","Observasi, analisis, usulan, dan refleksi mencakup seluruh rangkaian tujuan.","Observasi dekat kehidupan perlu dihubungkan dengan konsep; banyak foto bukan bukti analisis."]},{"id":52,"code":"P.1","type":"Kategori","stem":"Setelah proyek pengurangan sampah kelas, sebagian murid dapat menyalin poster tetapi belum menghubungkan kegiatan dengan konsep yang dipelajari. Nilai tindak lanjut sebagai Tepat atau Tidak tepat.","options":["Menautkan kegiatan dengan tujuan yang jelas dan tantangan di kehidupan nyata.","Membuka ruang bagi siswa menjelaskan apa yang berubah dari pemahaman awalnya.","Membatasi keberhasilan pada selesai menyalin jawaban guru."],"key":["T","T","F"],"why":"Refleksi dan transfer menunjukkan pemahaman; reproduksi jawaban saja belum cukup.","section":"PU","package":1,"uid":"p1-052","explanations":["Tujuan dan masalah nyata membantu transfer dari kegiatan ke konsep.","Perubahan penjelasan memperlihatkan refleksi atas pemahaman awal.","Selesai menyalin belum menunjukkan konsep diterapkan dalam keputusan."]},{"id":53,"code":"P.1","type":"MCMA","stem":"Guru menemukan miskonsepsi pada konsep yang menjadi prasyarat pelajaran berikutnya. Strategi yang tepat adalah ... Pilih semua.","options":["Meminta siswa membandingkan gagasan awal dan hasil setelah eksplorasi.","Memberi nilai akhir hanya dari kecepatan menjawab.","Mengumpulkan jawaban awal untuk mengetahui penalaran siswa.","Memberi contoh pembanding yang menguji gagasan keliru.","Menolak pertanyaan karena mengganggu jadwal."],"key":["A","C","D"],"why":"Perubahan konsep dibantu diagnosis, bukti pembanding, dan refleksi pemahaman.","section":"PU","package":1,"uid":"p1-053","explanations":["Perbandingan gagasan awal dan akhir membantu perubahan konseptual.","Kecepatan saja tidak mengukur alasan dan perubahan pemahaman.","Jawaban awal mengungkap alasan di balik miskonsepsi.","Contoh pembanding memberi bukti untuk menguji gagasan keliru.","Menolak pertanyaan menutup sumber informasi kebutuhan belajar."]},{"id":54,"code":"P.2","type":"PG","stem":"Dalam satu kelas ada siswa dengan kemampuan membaca berbeda. Guru ingin semua memahami gagasan utama bacaan. Pilihan terbaik adalah ...","options":["Menambah waktu tanpa memeriksa hambatan membaca.","Memakai teks inti dan dukungan akses beragam sambil mengecek gagasan utama dengan sasaran sama.","Mengganti analisis gagasan utama dengan salinan judul.","Membagikan ringkasan berisi jawaban lalu menganggap salinan ringkasan sebagai bukti pemahaman mandiri murid."],"key":"B","why":"Kesetaraan tujuan dapat disertai variasi dukungan agar hambatan akses tidak menghalangi pencapaian.","section":"PU","package":1,"uid":"p1-054","explanations":["Tambahan waktu saja belum menanggapi hambatan kosakata atau representasi yang perlu diperiksa.","Dukungan berbeda tetap menuntut murid memahami gagasan utama tanpa mengganti sasaran.","Menyalin judul menurunkan tuntutan pemahaman bagi sebagian murid.","Salinan jawaban tidak menunjukkan murid dapat menemukan gagasan utama sendiri."]},{"id":55,"code":"P.2","type":"Kategori","stem":"Dalam diskusi untuk memahami gagasan utama bacaan, siswa memiliki latar bahasa beragam. Nilai tindakan berikut sebagai Tepat atau Tidak tepat.","options":["Menghentikan penjelasan gagasan untuk membetulkan setiap pelafalan yang sebenarnya sudah dipahami kelas.","Guru menganggap aksen berbeda sebagai tanda kemampuan berpikir rendah.","Guru memastikan istilah penting dipahami melalui contoh tanpa merendahkan bahasa rumah siswa."],"key":["F","F","T"],"why":"Pembelajaran responsif menghargai identitas bahasa sekaligus menjaga target akademik.","section":"PU","package":1,"uid":"p1-055","explanations":["Koreksi setiap pelafalan menghambat penyampaian gagasan yang sudah dapat dipahami, sementara tujuan diskusi bukan latihan pelafalan.","Aksen tidak menunjukkan tingkat kemampuan berpikir.","Contoh istilah membantu akses tanpa merendahkan bahasa rumah."]},{"id":56,"code":"P.2","type":"MCMA","stem":"Guru mengatur kerja kelompok dengan siswa yang berbeda kesiapan dan kebutuhan. Pilih keputusan yang tepat.","options":["Menyerahkan semua pekerjaan ke satu siswa yang dianggap pintar.","Mengecek secara berkala siapa yang belum mendapat kesempatan bicara.","Menyediakan kriteria tugas dan bantuan berjenjang.","Memberi label permanen kelompok pintar dan lemah.","Membagikan peran jelas dan kesempatan rotasi peran."],"key":["B","C","E"],"why":"Peran, pemantauan partisipasi, dan scaffolding mendukung keterlibatan seluruh siswa.","section":"PU","package":1,"uid":"p1-056","explanations":["Satu pelaksana menghilangkan kontribusi serta bukti anggota lain.","Pemantauan bicara membantu memperbaiki ketimpangan partisipasi.","Kriteria dan bantuan berjenjang memberi kejelasan dan dukungan.","Label tetap mengabaikan perkembangan dan menguatkan stigma.","Peran dan rotasi membagi kesempatan menunjukkan kemampuan."]},{"id":57,"code":"P.2","type":"PG","stem":"Siswa pindahan belum mengenal istilah teknis yang telah dipelajari kelas. Langkah awal paling tepat adalah ...","options":["Menyamakan tugas tanpa memeriksa prasyarat.","Mensyaratkan hafalan seluruh istilah sebelum diskusi.","Meminta teman menyelesaikan semua tugasnya.","Mengecek istilah yang belum dipahami melalui contoh singkat."],"key":"D","why":"Langkah awal ialah memetakan kesulitan istilah, bukan langsung menyamakan tugas, mensyaratkan seluruh hafalan, atau menyerahkan pekerjaan kepada teman. Dukungan dipilih setelah kebutuhan diketahui.","section":"PU","package":1,"uid":"p1-057","explanations":["Kesetaraan kesempatan memerlukan dukungan terhadap prasyarat yang belum dikenal.","Hafalan menyeluruh sebagai syarat partisipasi menghambat bantuan bertahap yang diperlukan.","Pengambilalihan tugas tidak memberi kesempatan atau bukti pemahaman murid pindahan.","Pemeriksaan awal memetakan istilah atau prasyarat yang perlu didukung; hasilnya menjadi dasar memilih glosarium dan bantuan berikutnya."]},{"id":58,"code":"P.3","type":"PG","stem":"Seorang siswa memberi jawaban salah dan beberapa teman tertawa. Guru sebaiknya ...","options":["Menghentikan ejekan, menghargai usaha, lalu meninjau alasan dan bukti secara aman.","Memindahkan pertanyaan ke murid tercepat tanpa membahas ejekan dan alasan jawaban yang semula keliru.","Menyatakan semua jawaban sama benarnya agar siswa merasa diterima tanpa meninjau ketepatan bukti.","Mengoreksi konsep dengan cepat tetapi menunda pembahasan ejekan sampai akhir semester agar jadwal tidak terganggu."],"key":"A","why":"Keamanan psikologis dan pembahasan alasan menciptakan ruang belajar yang berkesadaran dan menggembirakan.","section":"PU","package":1,"uid":"p1-058","explanations":["Respons ini memulihkan rasa aman sekaligus menjaga tuntutan penalaran dan ketepatan.","Pengalihan saja membiarkan ejekan serta miskonsepsi tidak ditanggapi.","Menghargai upaya tidak berarti menyamakan jawaban yang bertentangan dengan bukti.","Koreksi konsep saja belum memulihkan norma interaksi aman saat kejadian."]},{"id":59,"code":"P.3","type":"Kategori","stem":"Murid mengeluhkan permainan kuis sangat seru tetapi tidak mengetahui tujuan belajarnya. Guru akan merancang ulang kegiatan berkesadaran, bermakna, dan menggembirakan. Nilai gagasan berikut sebagai Tepat atau Tidak tepat.","options":["Pembelajaran menggembirakan selalu berarti tanpa tantangan akademik.","Aktivitas boleh menantang apabila ada dukungan, relevansi, dan suasana aman.","Siswa memahami tujuan belajar dan diberi ruang merefleksikan prosesnya."],"key":["F","T","T"],"why":"Kegembiraan belajar bukan hiburan semata; fokus, relevansi, tantangan yang terdukung, dan rasa aman bisa berjalan bersama.","section":"PU","package":1,"uid":"p1-059","explanations":["Kegembiraan tidak mengharuskan hilangnya tantangan akademik.","Tantangan dapat menyenangkan bila relevan, aman, dan didukung.","Tujuan dan refleksi membantu kesadaran atas proses belajar."]},{"id":60,"code":"P.4","type":"PG","stem":"Guru ingin siswa memakai AI untuk membuat rangkuman materi. Risiko utamanya ialah jawaban AI bisa keliru dan data siswa dapat terbuka. Langkah tepat adalah ...","options":["Memilih rangkuman dari kelancaran bahasa saja.","Mencocokkan klaim rangkuman dengan sumber tepercaya, membatasi data pribadi, dan meminta penjelasan dengan bahasa sendiri.","Menghapus nama saja lalu mengizinkan unggahan cerita keluarga yang masih dapat dikenali dari rincian kejadiannya.","Meminta dua layanan AI menghasilkan jawaban serupa dan menganggap kesepakatan itu telah cukup memverifikasi isi."],"key":"B","why":"Literasi digital meliputi verifikasi dan privasi, bukan hanya kemampuan menjalankan alat.","section":"PU","package":1,"uid":"p1-060","explanations":["Kelancaran bahasa tidak menjamin ketepatan isi rangkuman.","Pemeriksaan sumber, minimisasi data, dan penjelasan sendiri menanggapi dua risiko pada stimulus.","Cerita yang dapat dikenali tetap membuka informasi pribadi meskipun nama dihapus.","Kesepakatan keluaran AI dapat mengulang kekeliruan yang sama; sumber independen tetap dibutuhkan."]},{"id":61,"code":"P.4","type":"MCMA","stem":"Guru memilih media pembelajaran digital untuk kelas dengan akses beragam. Pertimbangan yang tepat adalah ... Pilih semua.","options":["Tampilan dan petunjuk dapat diakses oleh murid dengan beragam kebutuhan.","Selalu mewajibkan gawai spesifikasi tinggi walau banyak murid tidak memiliki.","Data murid yang diperlukan dibatasi sesuai tujuan.","Memilih media hanya karena sedang populer.","Tersedia versi berukuran ringan atau alternatif luring."],"key":["A","C","E"],"why":"Akses, inklusi, dan keamanan data menjadi dasar pemilihan TIK yang kritis.","section":"PU","package":1,"uid":"p1-061","explanations":["Petunjuk yang aksesibel menjaga partisipasi beragam kebutuhan.","Perangkat tinggi wajib menghalangi murid yang tidak memilikinya.","Pembatasan data mengurangi paparan yang tidak diperlukan.","Popularitas tidak membuktikan akses atau kesesuaian tujuan.","Versi ringan atau luring membantu murid dengan keterbatasan akses."]},{"id":62,"code":"P.5","type":"PG","stem":"Guru akan mengajar perbandingan dengan contoh kehidupan sekitar. Sebagian siswa belum akrab dengan konteks pasar tradisional. Pilihan terbaik adalah ...","options":["Menambah soal pasar tanpa menjelaskan istilah.","Menghapus seluruh konteks nyata dari pembelajaran.","Memakai beberapa konteks setara yang familier untuk menjelaskan perbandingan yang sama.","Mengelompokkan kemampuan secara tetap berdasarkan pengalaman pasar tanpa memeriksa penalaran perbandingan murid."],"key":"C","why":"Konteks beragam membantu transfer konsep tanpa mengasumsikan pengalaman semua siswa identik.","section":"PU","package":1,"uid":"p1-062","explanations":["Satu konteks yang tidak dipahami sebagian murid menghambat akses konsep.","Konteks nyata tetap berguna jika diberi dukungan atau alternatif.","Konteks setara memberi jalan berbeda menuju perbandingan yang sama.","Latar budaya tidak menentukan kemampuan yang tetap."]},{"id":63,"code":"P.5","type":"Kategori","stem":"Guru memilih bahan cerita lokal untuk latihan menyimpulkan bacaan. Sebagian murid belum mengenal tradisi dalam cerita tersebut. Nilai pertimbangan berikut sebagai Tepat atau Tidak tepat.","options":["Contoh lokal harus selalu dipakai meskipun menimbulkan stereotip kelompok tertentu.","Sumber lokal dipilih karena membantu mencapai tujuan dan dapat diakses murid.","Memilih cerita paling panjang tanpa mengecek istilah dan pengetahuan awal murid."],"key":["F","T","F"],"why":"Kontekstual bukan otomatis baik; guru perlu menjaga relevansi, akurasi, dan penghargaan pada keragaman.","section":"PU","package":1,"uid":"p1-063","explanations":["Stereotip tidak dibenarkan hanya karena suatu contoh bersifat lokal.","Sumber lokal bernilai bila relevan dengan tujuan dan terjangkau.","Panjang bahan tidak menjamin kesesuaian; istilah dan kesiapan perlu diperiksa."]},{"id":64,"code":"P.6","type":"PG","stem":"Di awal topik pecahan, guru memberi dua soal singkat untuk melihat apakah siswa memahami bagian dari keseluruhan. Informasi ini paling tepat dipakai untuk ...","options":["Memilih contoh dan dukungan dari diagnosis, lalu meninjau kelompok sesuai kemajuan.","Menetapkan kelompok tetap dari dua jawaban awal.","Memakai diagnosis sebagai nilai akhir pecahan.","Mencatat skor tanpa menyesuaikan pembelajaran."],"key":"A","why":"Asesmen awal dipakai untuk mengidentifikasi kebutuhan belajar, bukan memberi label atau hukuman.","section":"PU","package":1,"uid":"p1-064","explanations":["Diagnosis menuntun dukungan dan perlu ditinjau kembali dari perkembangan murid.","Bukti awal terbatas tidak membenarkan label kemampuan permanen.","Nilai awal tidak mewakili hasil setelah kesempatan pembelajaran.","Pencatatan saja belum memakai informasi untuk memenuhi kebutuhan belajar."]},{"id":65,"code":"P.6","type":"MCMA","stem":"Setelah exit ticket, guru mengetahui separuh kelas masih bingung menentukan alasan jawaban. Langkah tepat adalah ... Pilih semua.","options":["Mengelompokkan jawaban untuk mengidentifikasi pola kesalahan.","Memberi penjelasan/model tambahan yang menanggapi pola tersebut.","Mengajak siswa mengerjakan soal cek singkat untuk memastikan perbaikan.","Mengabaikan hasil karena materi sudah selesai diajarkan.","Mempermalukan siswa yang jawabannya belum tepat."],"key":["A","B","C"],"why":"Asesmen formatif bermakna jika hasilnya ditafsirkan dan digunakan untuk memperbaiki proses serta mengecek dampaknya.","section":"PU","package":1,"uid":"p1-065","explanations":["Pola kesalahan menuntun jenis bantuan yang diperlukan.","Model yang menanggapi pola memberi dukungan spesifik.","Cek ulang memberi bukti apakah tindak lanjut membantu.","Mengabaikan data membuat exit ticket tidak dipakai untuk pembelajaran.","Mempermalukan tidak memberi penjelasan atau bantuan yang dibutuhkan."]},{"id":66,"code":"P.6","type":"Kategori","stem":"Murid telah menyusun simpulan bacaan, tetapi satu bukti yang dipakai bertentangan dengan simpulannya. Guru ingin murid memperbaiki alasan secara mandiri. Nilai umpan balik berikut sebagai Tepat atau Tidak tepat.","options":["“Bandingkan jawabanmu dengan rubrik, revisi satu bagian, lalu jelaskan mengapa diubah.”","“Kamu memang tidak berbakat; jangan mencoba soal ini lagi.”","“Alasanmu sudah menyebut dua bukti; cek lagi apakah bukti ketiga mendukung simpulanmu.”"],"key":["T","F","T"],"why":"Umpan balik yang baik spesifik, menjaga martabat, dan menyebut langkah perbaikan yang dapat dilakukan.","section":"PU","package":1,"uid":"p1-066","explanations":["Rubrik, revisi, dan alasan perubahan memberi tindak lanjut yang dapat diamati.","Label tidak berbakat bersifat menghakimi dan tidak memberi langkah perbaikan.","Komentar menunjukkan kemajuan serta lokasi bukti yang perlu ditinjau."]},{"id":67,"code":"P.6","type":"PG","stem":"Hasil penilaian akhir memperlihatkan banyak siswa belum mencapai satu indikator. Tindakan guru berikutnya yang paling bertanggung jawab adalah ...","options":["Menutup tindak lanjut setelah nilai terbit dan memakai materi berikutnya tanpa memeriksa indikator yang lemah.","Mengurangi tuntutan soal berikutnya tanpa pembelajaran tambahan agar jumlah murid mencapai nilai target meningkat.","Menyimpan rincian hasil hanya untuk guru sehingga murid tidak mengetahui indikator yang perlu diperbaiki.","Menganalisis indikator lemah dan menyiapkan dukungan serta kesempatan perbaikan."],"key":"D","why":"Hasil asesmen digunakan untuk keputusan pembelajaran dan tindak lanjut, bukan sekadar angka akhir.","section":"PU","package":1,"uid":"p1-067","explanations":["Nilai terbit tidak mengakhiri tanggung jawab mendukung capaian.","Soal lebih mudah tanpa pembelajaran dapat menyamarkan kesulitan.","Menyembunyikan hasil menghambat murid memahami kebutuhan perbaikan.","Analisis indikator dan dukungan lanjutan menghubungkan hasil dengan kesempatan belajar."]},{"id":68,"code":"K.1","type":"PG","stem":"Seorang murid menceritakan sedang mengalami masalah keluarga dan meminta tidak diumumkan. Respons guru yang paling etis adalah ...","options":["Mengumumkan identitas agar teman memberi dukungan.","Mendengar secara empatik, menjaga privasi, dan merujuk proporsional bila ada risiko keselamatan.","Membagikan seluruh rincian ke grup guru tanpa menentukan siapa yang perlu terlibat dalam perlindungan murid.","Menjanjikan kerahasiaan mutlak dan mengabaikan tanda bahaya karena murid meminta cerita tidak diumumkan."],"key":"B","why":"Etika menuntut empati dan privasi; jika terdapat risiko keselamatan, guru mengikuti prosedur perlindungan dan rujukan yang tepat.","section":"PU","package":1,"uid":"p1-068","explanations":["Nama dan cerita publik melanggar kepercayaan serta privasi.","Kerahasiaan dijaga dengan pengecualian proporsional untuk perlindungan sesuai prosedur.","Grup luas tanpa kebutuhan bukan rujukan yang proporsional.","Tanda bahaya perlu ditindaklanjuti, bukan diabaikan atas nama privasi."]},{"id":69,"code":"K.1","type":"Kategori","stem":"Guru mendapati penilaiannya keliru dan mendapat permintaan menaikkan nilai kerabat tanpa bukti tugas tambahan. Nilai respons berikut sebagai Tepat atau Tidak tepat.","options":["Guru meninjau kembali nilai memakai kriteria yang sudah disampaikan sebelum tugas.","Guru mengakui kekeliruan penilaian, memperbaikinya berdasarkan bukti, dan menyampaikan koreksi kepada pihak terkait.","Guru menaikkan nilai murid tertentu karena kedekatan pribadi tanpa bukti belajar."],"key":["T","T","F"],"why":"Keteladanan ditunjukkan oleh keadilan, integritas, dan tanggung jawab memperbaiki kesalahan.","section":"PU","package":1,"uid":"p1-069","explanations":["Peninjauan memakai kriteria yang sama menjaga keadilan saat memperbaiki kesalahan penilaian.","Koreksi berbasis bukti dan komunikasi kepada pihak terkait menunjukkan integritas serta tanggung jawab atas penilaian.","Kedekatan pribadi tidak menjadi bukti capaian belajar."]},{"id":70,"code":"K.2","type":"PG","stem":"Setelah proyek kelompok gagal mencapai target, guru merasa metode yang dipilih tidak efektif. Refleksi profesional paling tepat adalah ...","options":["Menyimpulkan murid tidak cocok bekerja kelompok.","Mengganti anggota saja tanpa meninjau proses.","Menelaah bukti dan umpan balik murid, lalu menguji satu perbaikan yang beralasan.","Mengganti semua kegiatan dengan metode populer sebelum menemukan bagian proses yang menghambat ketercapaian target."],"key":"C","why":"Refleksi diri berbasis bukti mendukung pola pikir bertumbuh dan peningkatan praktik.","section":"PU","package":1,"uid":"p1-070","explanations":["Satu kegagalan belum membuktikan karakter murid menjadi penyebab.","Komposisi baru belum menanggapi kemungkinan hambatan instruksi, peran, atau kriteria.","Bukti dan umpan balik mengarahkan perubahan yang dapat dievaluasi dampaknya.","Pergantian metode tanpa diagnosis belum merupakan refleksi berbasis bukti."]},{"id":71,"code":"K.2","type":"MCMA","stem":"Guru ingin mengembangkan kompetensi secara berkelanjutan. Mana yang mencerminkan growth mindset profesional? Pilih semua.","options":["Mencoba strategi baru secara terukur dan membandingkan buktinya.","Menganggap kritik berarti dirinya bukan guru yang baik sehingga menolak masukan.","Berdiskusi dengan rekan dan menyesuaikan praktik dari temuan.","Mengklaim dirinya sudah tidak perlu belajar karena telah lulus pendidikan guru.","Mencatat satu aspek pembelajaran yang perlu diperbaiki dari umpan balik."],"key":["A","C","E"],"why":"Pola pikir bertumbuh tampak dalam penerimaan masukan, eksperimen terukur, dan tindak lanjut hasil refleksi.","section":"PU","package":1,"uid":"p1-071","explanations":["Percobaan terukur memungkinkan guru belajar dari hasil.","Kritik terhadap praktik tidak sama dengan vonis identitas guru.","Diskusi dan adaptasi menghubungkan masukan dengan perbaikan.","Kelulusan tidak mengakhiri kebutuhan belajar profesional.","Umpan balik yang ditindaklanjuti menjadi dasar perkembangan diri."]},{"id":72,"code":"K.3","type":"PG","stem":"Dalam diskusi kelas, hanya beberapa siswa berani berbicara. Guru ingin membangun budaya belajar saling mendukung. Langkah terbaik adalah ...","options":["Memberi label tidak aktif dari frekuensi bicara.","Menegur murid acak yang belum siap menjawab.","Membiarkan dominasi agar diskusi cepat selesai.","Menyepakati aturan diskusi, waktu berpikir, dan giliran berbagi yang aman."],"key":"D","why":"Keputusan guru perlu konsisten membangun partisipasi dan rasa aman untuk mengembangkan potensi semua murid.","section":"PU","package":1,"uid":"p1-072","explanations":["Pelabelan dari frekuensi bicara mengabaikan kesempatan dan hambatan murid untuk berpartisipasi.","Menegur ketidaksiapan sebelum memberi waktu berpikir belum mengatasi hambatan partisipasi.","Dominasi tetap tidak memberi kesempatan berkembang bagi yang lain.","Waktu berpikir dan giliran aman membangun partisipasi yang konsisten."]},{"id":73,"code":"K.3","type":"Kategori","stem":"Dalam satu semester, beberapa murid berhenti mencoba setelah mendapat peringkat rendah. Guru ingin membangun kebiasaan perbaikan yang konsisten. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Menetapkan kelompok ranking rendah tetap selama setahun agar dukungan tidak perlu ditinjau lagi.","Menilai perkembangan hanya dari perubahan peringkat meskipun capaian kriteria belajar murid meningkat.","Guru memberi kesempatan revisi tugas berdasarkan kriteria yang jelas."],"key":["F","F","T"],"why":"Budaya belajar positif menekankan perkembangan, standar yang jelas, dan peluang belajar dari kesalahan.","section":"PU","package":1,"uid":"p1-073","explanations":["Kelompok tetap dari ranking mengabaikan kemajuan dan kebutuhan yang berubah.","Peringkat menunjukkan posisi relatif; peringkat yang tetap tidak meniadakan peningkatan capaian kriteria belajar.","Revisi dengan kriteria memberi jalur nyata untuk memperbaiki capaian."]},{"id":74,"code":"S.1","type":"PG","stem":"Orang tua menghubungi guru karena anaknya merasa tidak dipahami di kelas. Respons komunikasi paling tepat adalah ...","options":["Menjelaskan aturan kelas lebih dahulu lalu menutup percakapan tanpa meminta kejadian yang dialami anak.","Mendengarkan, mengklarifikasi kejadian dan bukti, lalu menyepakati tindak lanjut.","Memindahkan pembahasan masalah anak ke grup kelas agar seluruh wali dapat menilai siapa yang benar.","Menjanjikan perubahan nilai anak untuk meredakan keberatan sebelum memeriksa pengalaman dan bukti belajarnya."],"key":"B","why":"Komunikasi inklusif dan empatik mencari pemahaman bersama dan tindakan yang berbasis informasi.","section":"PU","package":1,"uid":"p1-074","explanations":["Penjelasan sepihak tidak cukup memahami pengalaman yang memicu kekhawatiran.","Mendengar dan mengklarifikasi bukti memungkinkan komunikasi empatik dengan tindakan yang beralasan.","Pembahasan ke grup memperluas paparan masalah pribadi tanpa kebutuhan.","Janji nilai sebelum pemeriksaan tidak menjawab persoalan pemahaman dan mengabaikan bukti penilaian."]},{"id":75,"code":"S.1","type":"MCMA","stem":"Guru memberi umpan balik kepada siswa yang berbeda latar bahasa dan gaya komunikasi. Cara yang tepat adalah ... Pilih semua.","options":["Menggunakan kalimat jelas dan contoh spesifik.","Meminta murid menjelaskan kembali langkah perbaikan dan memberi kesempatan bertanya.","Mengejek pengucapan bahasa siswa.","Menyediakan saluran tertulis/visual bila membantu komunikasi.","Memotong penjelasan siswa karena lambat menyampaikan ide."],"key":["A","B","D"],"why":"Umpan balik inklusif menyesuaikan cara komunikasi sambil menghargai martabat dan kebutuhan murid.","section":"PU","package":1,"uid":"p1-075","explanations":["Kalimat dan contoh spesifik memperjelas pesan perbaikan.","Penjelasan kembali memberi bukti apakah murid memahami langkah perbaikan; kesempatan bertanya membantu mengklarifikasi bagian yang belum jelas.","Ejekan pengucapan menstigma latar bahasa.","Saluran visual atau tertulis membantu kebutuhan komunikasi tertentu.","Memotong penjelasan menghilangkan informasi dan partisipasi murid."]},{"id":76,"code":"S.2","type":"PG","stem":"Seorang siswa sering absen sehingga tertinggal tugas. Guru mata pelajaran belum memahami penyebabnya. Langkah kolaboratif paling tepat adalah ...","options":["Meminta tugas selesai sebelum mencari sebab absen.","Mengirim rincian masalah ke seluruh wali murid agar memperoleh dukungan luas meskipun kebutuhannya belum dipetakan.","Berkoordinasi dengan wali kelas dan/atau guru BK secara proporsional, mendengar murid dan keluarga, lalu menyusun dukungan.","Menetapkan nilai nol untuk seluruh tugas tertinggal dan menutup kesempatan perbaikan sebelum alasan absen diketahui."],"key":"C","why":"Kolaborasi dengan pihak terkait memetakan hambatan dan merancang dukungan, tetap menjaga privasi.","section":"PU","package":1,"uid":"p1-076","explanations":["Tuntutan tugas sebelum memetakan penyebab belum memberi dasar dukungan yang sesuai.","Penyebaran ke semua wali tidak proporsional dan membuka informasi pribadi yang tidak diperlukan.","Pihak terkait memetakan hambatan bersama dan menyepakati dukungan dengan tetap menjaga privasi.","Keputusan permanen sebelum memahami penyebab menutup kesempatan tindak lanjut belajar."]},{"id":77,"code":"S.2","type":"Kategori","stem":"Sekolah dan wali murid merancang dukungan untuk seorang murid yang sering tertinggal tugas. Nilai praktik kolaborasi berikut sebagai Tepat atau Tidak tepat.","options":["Mengalihkan seluruh tanggung jawab bantuan kepada keluarga tanpa menyepakati peran sekolah.","Guru berbagi perkembangan belajar yang relevan melalui jalur komunikasi yang tepat.","Guru menyebarkan data pribadi murid kepada semua orang tua agar transparan."],"key":["F","T","F"],"why":"Kolaborasi memerlukan komunikasi terarah dan perlindungan kerahasiaan data murid.","section":"PU","package":1,"uid":"p1-077","explanations":["Kolaborasi perlu peran bersama; pengalihan sepihak menghilangkan tanggung jawab sekolah.","Informasi perkembangan yang relevan membantu pihak terkait merencanakan dukungan.","Transparansi tidak berarti semua orang tua berhak atas data murid lain."]},{"id":78,"code":"S.3","type":"PG","stem":"Komunitas guru membahas cara meningkatkan keterlibatan siswa dalam diskusi. Kontribusi paling bermanfaat adalah ...","options":["Membagikan praktik dan bukti, menerima masukan, lalu menguji perbaikan sesuai konteks.","Membagikan materi rekan tanpa atribusi.","Menganjurkan satu strategi untuk semua sekolah.","Mengirim daftar kegiatan tanpa bukti hasil dan menolak peninjauan masukan karena metode tersebut pernah dipakai."],"key":"A","why":"Komunitas pembelajaran berguna ketika praktik, bukti, dan refleksi dibagikan secara bertanggung jawab.","section":"PU","package":1,"uid":"p1-078","explanations":["Kontribusi bukti dan tindak lanjut menjadikan komunitas tempat belajar profesional bersama.","Materi rekan perlu dibagikan dengan atribusi yang sesuai; penghilangan atribusi tidak menunjukkan kontribusi profesional yang bertanggung jawab.","Satu konteks tidak cukup mendukung penerapan universal.","Daftar aktivitas tanpa bukti dan refleksi sulit dipakai untuk menilai atau memperbaiki praktik."]},{"id":79,"code":"PF.1","type":"PG","stem":"Guru menilai proyek lintas mata pelajaran. Hasil belajar paling menggambarkan tujuan pendidikan yang luas adalah ...","options":["Menghasilkan produk sesuai contoh dan menjelaskan langkah kerja, tetapi belum menerapkannya pada masalah baru.","Mencapai angka tinggi tanpa bukti penerapan.","Menyelesaikan cepat tanpa alasan dan tanggung jawab.","Menalar, bekerja sama secara etis, dan menerapkan pengetahuan pada masalah bermakna."],"key":"D","why":"Tujuan pendidikan mencakup penguasaan pengetahuan, karakter, kolaborasi, dan penerapan yang bertanggung jawab.","section":"PU","package":1,"uid":"p1-079","explanations":["Produk dan penjelasan langkah menunjukkan sebagian capaian, tetapi belum menunjukkan penerapan pada masalah baru sebagaimana tujuan pendidikan yang lebih luas.","Angka saja belum memberi bukti penerapan pengetahuan, karakter, dan kolaborasi.","Kecepatan tanpa penalaran dan tanggung jawab belum menunjukkan tujuan pendidikan secara utuh.","Penalaran, etika, kolaborasi, dan penerapan memberi bukti hasil pendidikan yang lebih lengkap."]},{"id":80,"code":"P.5","type":"MCMA","stem":"Dalam proyek lingkungan, murid harus mencatat pengamatan, membandingkan data, dan menarik simpulan. Alat sekolah terbatas. Pilih adaptasi sumber belajar yang tetap mendukung tujuan tersebut.","options":["Menggunakan pengamatan lingkungan setempat dengan prosedur aman dan data yang dapat dicatat.","Menyediakan format pencatatan sederhana dan contoh analisis data.","Menghapus kompetensi analisis karena alat laboratorium terbatas.","Membandingkan hasil dengan konsep ilmiah dan membahas keterbatasan pengamatan.","Memaksakan alat yang tidak aman demi meniru sekolah lain."],"key":["A","B","D"],"why":"Pengamatan setempat yang aman menyediakan sumber data; format pencatatan dan contoh analisis membantu mengolahnya. Membandingkan hasil dengan konsep serta membahas keterbatasan menjaga ketepatan simpulan. Tujuan analisis tidak dihapus karena alat terbatas.","section":"PU","package":1,"uid":"p1-080","explanations":["Pengamatan aman dengan prosedur jelas memberi data lokal yang dapat dianalisis.","Format sederhana dan contoh membantu mengatasi kebutuhan prasyarat analisis.","Keterbatasan alat tidak otomatis mengharuskan penghapusan tujuan analisis.","Konsep dan batas data membantu murid menarik simpulan yang proporsional.","Meniru alat berisiko mengorbankan keselamatan tanpa keharusan pedagogis."]}]},{"id":2,"title":"Paket 2","version":"2026-11-18.1","file":"paket_2.json","reviewFile":"references/Paket_2_dan_Pembahasan.md","questions":[{"id":1,"uid":"p2-001","package":2,"section":"PCK","code":"P.1","type":"PG","difficulty":"sedang","cp_element":"Basis Data","case_focus":"NULL dan nol","stem":"Dalam data pengukuran, 0 berarti hasil ukur nol dan NULL berarti belum diukur. Murid mengganti semua NULL menjadi 0 agar rata-rata mudah dihitung. Langkah guru paling tepat adalah ...","options":["Meminta murid membulatkan rata-rata ke bilangan bulat.","Membandingkan rata-rata sebelum dan sesudah penggantian, lalu membahas makna penyebutnya.","Mengisi NULL dengan rata-rata sebelum memeriksa alasan data belum tersedia.","Mengajarkan penulisan alias kolom pada query."],"key":"B","why":"Rata-rata atas nilai yang diketahui berbeda dari rata-rata yang memasukkan nol buatan. Murid perlu menafsirkan makna data sebelum memilih perlakuan NULL.","explanations":["Pembulatan tidak menyelesaikan perbedaan makna data.","Perubahan penyebut memperlihatkan akibat menganggap belum diukur sebagai nol.","Imputasi memerlukan alasan dan asumsi; mengisinya langsung belum memperbaiki pemahaman perbedaan NULL dan nol.","Alias memperjelas nama, bukan makna nilai yang dihitung."]},{"id":2,"uid":"p2-002","package":2,"section":"PCK","code":"P.6","type":"Kategori","difficulty":"sedang","cp_element":"Basis Data","case_focus":"COUNT kolom","stem":"Guru menilai pemahaman COUNT pada tabel berisi lima respons; dua nilai komentar adalah NULL. Nilai bukti berikut sebagai Tepat atau Tidak tepat.","options":["Murid menjelaskan mengapa COUNT(*) bernilai 5 dan COUNT(komentar) bernilai 3.","Murid hanya menyebut kedua hasil harus sama karena tabelnya satu.","Murid memprediksi perubahan kedua hitungan saat satu NULL diisi teks."],"key":["T","F","T"],"why":"COUNT(*) menghitung baris; COUNT pada kolom menghitung nilai non-NULL. Prediksi perubahan lebih informatif daripada hafalan keluaran.","explanations":["Penjelasan membedakan jumlah baris dan nilai non-NULL.","Tabel yang sama tidak menjamin ekspresi COUNT menghitung hal yang sama.","Prediksi menguji pemahaman pengaruh nilai terhadap agregasi."]},{"id":3,"uid":"p2-003","package":2,"section":"PCK","code":"PF.2","type":"PG","difficulty":"menantang","cp_element":"Basis Data","case_focus":"filter agregat","stem":"Murid ingin menampilkan kategori dengan total penjualan di atas satu juta, tetapi menaruh SUM pada WHERE. Guru akan memakai dua tahap penyaringan. Demonstrasi paling tepat adalah ...","options":["Mengurutkan seluruh transaksi menurut harga satuan.","Menyaring transaksi dengan harga satuan di atas satu juta.","Memodelkan filter baris, pengelompokan, lalu HAVING.","Menambahkan DISTINCT pada nama kategori di hasil awal."],"key":"C","why":"Kesalahan terjadi pada tingkat data yang disaring. Model dua tahap menjelaskan perbedaan WHERE dan HAVING, bukan sekadar memperbaiki ejaan SQL.","explanations":["Pengurutan bukan penyaringan kelompok berdasarkan total.","Harga satuan tidak setara dengan total per kategori.","Urutan ini membedakan kondisi baris dan kondisi hasil agregasi.","Penghilangan duplikasi tidak menerapkan syarat agregat."]},{"id":4,"uid":"p2-004","package":2,"section":"PCK","code":"PF.2","type":"MCMA","difficulty":"menantang","cp_element":"Basis Data","case_focus":"tipe desimal","stem":"Hasil penjumlahan pecahan uang dengan tipe floating point menyisakan selisih kecil. Guru ingin murid memilih representasi berdasarkan kebutuhan ketepatan. Pilih semua kegiatan yang relevan.","options":["Membandingkan floating point dan DECIMAL untuk nilai uang yang sama.","Memperbanyak angka di belakang koma pada tampilan saja.","Menyimpulkan semua bilangan harus disimpan sebagai teks.","Menguji penyimpanan dalam satuan rupiah bulat bila aturan harga memungkinkan."],"key":["A","D"],"why":"Representasi dipilih menurut satuan dan operasi yang diperlukan. Memoles tampilan tidak memperbaiki ketepatan penyimpanan.","explanations":["Perbandingan menunjukkan konsekuensi representasi bilangan.","Format tampilan tidak mengubah nilai yang tersimpan.","Teks menyulitkan operasi numerik dan tidak mengikuti kebutuhan tiap data.","Satuan bulat dapat menjaga ketepatan bila tidak memerlukan pecahan rupiah."]},{"id":5,"uid":"p2-005","package":2,"section":"PCK","code":"PF.3","type":"PG","difficulty":"sedang","cp_element":"Basis Data","case_focus":"urut tanggal","stem":"Murid dapat mengurutkan angka, tetapi urutan tanggal berbentuk teks DD/MM/YYYY tidak kronologis. Guru ingin menemukan prasyarat yang belum dipahami. Pertanyaan awal terbaik adalah ...","options":["Membandingkan urutan teks dan waktu pada dua tanggal.","Berapa banyak tanggal yang mampu kalian ketik per menit?","Meminta murid menyeragamkan tanda pemisah tanggal sebelum membandingkan urutannya.","Apakah warna kolom tanggal sudah berbeda dari kolom lain?"],"key":"A","why":"Guru memeriksa hubungan tipe data dengan operasi pembandingan, lalu dapat menyiapkan konversi ke tipe tanggal sesuai kebutuhan belajar.","explanations":["Pasangan itu mengungkap perbedaan pembandingan teks dan tanggal.","Kecepatan mengetik tidak menjelaskan cara nilai dibandingkan.","Pemisah yang seragam belum mengubah pembandingan teks menjadi pembandingan waktu.","Warna kolom bukan prasyarat pengurutan kronologis."]},{"id":6,"uid":"p2-006","package":2,"section":"PCK","code":"P.6","type":"Kategori","difficulty":"dasar","cp_element":"Basis Data","case_focus":"backup dipulihkan","stem":"Kelompok menyerahkan file backup basis data. Tujuan asesmen ialah memastikan data dapat dipulihkan. Nilai bukti berikut sebagai Tepat atau Tidak tepat.","options":["Ukuran file backup besar sehingga pemulihan dianggap terbukti.","Pemulihan dicoba pada basis data uji dan hasilnya dibandingkan dengan data asal.","Kelompok mencatat versi alat dan langkah pemulihan yang berhasil."],"key":["F","T","T"],"why":"Backup dinilai dari keterpulihan dan kecocokan hasil, bukan keberadaan file saja. Pengujian dilakukan pada lingkungan uji agar data kerja aman.","explanations":["Ukuran tidak menjamin isi lengkap atau dapat dipulihkan.","Uji pemulihan memeriksa kemampuan yang ditargetkan.","Catatan membuat proses pemulihan dapat diperiksa ulang."]},{"id":7,"uid":"p2-007","package":2,"section":"PCK","code":"P.4","type":"PG","difficulty":"menantang","cp_element":"Basis Data","case_focus":"indeks dan pola akses","stem":"Guru memakai alat penampil rencana eksekusi untuk mengajarkan indeks. Murid menyimpulkan setiap query pasti lebih cepat setelah indeks ditambah. Pemanfaatan alat paling tepat adalah ...","options":["Memilih tangkapan layar rencana dengan warna paling sedikit.","Mengukur query sebelum dan sesudah indeks pada dua ukuran data yang berbeda.","Meminta murid menghafalkan nama semua operator pada alat.","Membandingkan query terpilih pada data sama, lalu membaca rencana dan hasil waktunya."],"key":"D","why":"Alat memperlihatkan bukti penggunaan indeks dan batas manfaatnya. Ukuran data, pola pencarian, dan biaya pemeliharaan indeks tetap perlu dipertimbangkan.","explanations":["Tampilan grafis tidak menjadi ukuran biaya query.","Perubahan ukuran data mengaburkan pengaruh indeks sehingga bukti perbandingan belum terkontrol.","Nama operator belum menjelaskan hubungan indeks dengan pola akses.","Kondisi yang sebanding membantu menilai kapan indeks digunakan."]},{"id":8,"uid":"p2-008","package":2,"section":"PCK","code":"P.5","type":"MCMA","difficulty":"sedang","cp_element":"Basis Data","case_focus":"kamus data lokal","stem":"Data curah hujan desa memakai kode kosong, 0, dan -999 dengan arti berbeda. Guru akan menggunakannya untuk latihan query. Pilih semua langkah pemanfaatan sumber lokal yang tepat.","options":["Menganggap -999 sebagai pengukuran sah karena berupa angka.","Membaca kamus data bersama narasumber sebelum menentukan filter.","Menyediakan cuplikan data beserta definisi kode untuk tugas analisis.","Menghapus semua nilai 0 sebelum tujuan analisis ditetapkan."],"key":["B","C"],"why":"Konteks lokal berguna bila makna datanya dipahami. Pemilihan filter harus mengikuti definisi sumber, bukan bentuk angka semata.","explanations":["Bentuk numerik tidak menjamin maknanya hasil pengukuran.","Kamus data menjelaskan arti kode dalam konteks sumber.","Definisi menjaga agar murid dapat menafsirkan hasil query.","Nol dapat merupakan pengukuran sah yang penting."]},{"id":9,"uid":"p2-009","package":2,"section":"PCK","code":"P.1","type":"PG","difficulty":"sedang","cp_element":"Basis Data","case_focus":"duplikasi hasil DISTINCT","stem":"Dua peserta berbeda memilih jawaban survei yang sama. Murid memakai DISTINCT pada seluruh jawaban lalu menyatakan jumlah responden berkurang. Tindakan guru terbaik adalah ...","options":["Menghitung kembali jumlah baris setelah DISTINCT untuk menentukan jumlah peserta.","Membedakan hitungan peserta dan daftar jawaban unik.","Mengurutkan jawaban sebelum menghitung kembali hasil DISTINCT.","Mengganti seluruh jawaban sama dengan teks acak."],"key":"B","why":"DISTINCT menjawab pertanyaan tentang nilai unik. Jumlah peserta memerlukan unit hitung yang sesuai, meskipun jawaban mereka sama.","explanations":["Hitungan itu tetap menghitung nilai unik, bukan peserta yang jawabannya dapat sama.","Dua tujuan tersebut menjelaskan mengapa hasil DISTINCT tidak mewakili jumlah responden.","Urutan tidak mengembalikan baris yang disatukan.","Perubahan isi merusak data, bukan memperbaiki penafsiran."]},{"id":10,"uid":"p2-010","package":2,"section":"PCK","code":"PF.1","type":"Kategori","difficulty":"sedang","cp_element":"Basis Data","case_focus":"otorisasi view","stem":"Dalam proyek laporan kesehatan sekolah di SMK, murid belajar bertanggung jawab atas penggunaan data. Nilai rancangan kegiatan berikut sebagai Tepat atau Tidak tepat.","options":["Menguji akun pembaca laporan yang hanya dapat melihat kolom agregat yang diperlukan.","Menilai kesiapan kerja dari banyaknya akun yang memperoleh akses penuh.","Menganggap view selalu mencegah akses tabel asal meski hak akun belum diperiksa."],"key":["T","F","F"],"why":"Tujuan kejuruan mencakup penguasaan teknik sekaligus penggunaannya secara bertanggung jawab. Hak akun perlu diuji, bukan diasumsikan dari keberadaan view.","explanations":["Pembatasan akses menghubungkan keterampilan teknis dan tanggung jawab pengguna.","Jumlah akses penuh bukan bukti tanggung jawab profesional.","View saja tidak menjamin pembatasan hak terhadap tabel asal."]},{"id":11,"uid":"p2-011","package":2,"section":"PCK","code":"P.2","type":"PG","difficulty":"sedang","cp_element":"Basis Data","case_focus":"impor CSV","stem":"Saat impor CSV, sebagian murid menemukan nama kolom bergeser karena koma di dalam alamat. Mereka sudah memahami tabel, tetapi belum aturan pemisah dan tanda kutip. Dukungan paling tepat adalah ...","options":["Memberikan contoh CSV dengan lebih banyak kolom tetapi semua nilainya tanpa koma.","Mengganti semua alamat menjadi nomor urut.","Membandingkan satu baris CSV yang dikutip benar dan yang keliru.","Meminta murid menghafal semua nama format pertukaran data."],"key":"C","why":"Dukungan menanggapi bukti kebutuhan yang spesifik: koma dalam nilai harus dibedakan dari pemisah kolom sesuai aturan CSV yang digunakan.","explanations":["Contoh itu menambah kolom tetapi tidak menguji kasus koma di dalam nilai yang menjadi kesulitan.","Perubahan itu menghindari kebutuhan membaca struktur CSV.","Contoh kecil menargetkan prasyarat pemisah dan pengutipan.","Daftar format tidak mengatasi kesulitan parsing yang ditemukan."]},{"id":12,"uid":"p2-012","package":2,"section":"PCK","code":"PF.4","type":"MCMA","difficulty":"sedang","cp_element":"Basis Data","case_focus":"retensi data","stem":"Unit basis data sebelumnya hanya meminta murid menambah data. Guru menyusun unit lanjutan tentang pengelolaan data sepanjang penggunaannya. Pilih semua penyesuaian kurikulum yang selaras.","options":["Menambahkan tujuan memilih masa simpan berdasarkan kebutuhan kasus.","Meminta rancangan prosedur arsip dan penghapusan beserta uji pada data tiruan.","Menambah daftar perintah administrasi sebagai satu-satunya ukuran capaian.","Menyelaraskan rubrik dengan alasan retensi dan kemampuan menjalankan prosedur."],"key":["A","B","D"],"why":"Adaptasi unit mempertahankan materi basis data sekaligus mengaitkan tujuan, kegiatan, dan asesmen dengan kebutuhan pengelolaan data nyata.","explanations":["Masa simpan memperluas pengelolaan data sesuai kebutuhan pengguna.","Kegiatan dan bukti kerja mendukung tujuan pengelolaan siklus data.","Hafalan perintah belum menilai keputusan pengelolaan data.","Rubrik mengukur alasan dan penerapan yang ditargetkan."]},{"id":13,"uid":"p2-013","package":2,"section":"PCK","code":"PF.5","type":"PG","difficulty":"sedang","cp_element":"Basis Data","case_focus":"desain data survei","stem":"Guru menduga formulir survei dengan pilihan bertingkat mengurangi data tidak konsisten. Ia ingin memperbaiki praktik pembelajaran desain data. Langkah paling dapat dipertanggungjawabkan adalah ...","options":["Membandingkan jenis kesalahan pada dua rancangan setara dan menelaah alasan murid.","Memilih rancangan yang paling cepat selesai dibuat.","Membandingkan jumlah pertanyaan pada dua formulir sebagai ukuran konsistensi.","Memakai kesukaan guru terhadap tampilan sebagai dasar keputusan."],"key":"A","why":"Perbaikan praktik membutuhkan bukti yang terkait dugaan, dengan tugas sebanding dan keterbatasan perbandingan yang diakui.","explanations":["Bukti kesalahan dan alasan membantu menilai manfaat rancangan pada pembelajaran.","Kecepatan pembuatan belum menunjukkan pengurangan kesalahan data.","Banyak pertanyaan tidak langsung menunjukkan apakah makna isian dipahami dan diisi konsisten.","Preferensi tampilan belum menguji dugaan tentang konsistensi."]},{"id":14,"uid":"p2-014","package":2,"section":"PCK","code":"P.1","type":"Kategori","difficulty":"menantang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","case_focus":"polimorfisme","stem":"Murid mengira method yang dipanggil dari referensi bertipe induk selalu menjalankan versi induk, meski object turunannya melakukan override. Nilai kegiatan pembelajaran berikut sebagai Tepat atau Tidak tepat.","options":["Membandingkan keluaran dua object turunan melalui referensi induk.","Meminta prediksi keluaran sebelum eksekusi dan revisi alasannya.","Mengganti contoh override dengan dua nama method berbeda untuk membuktikan polimorfisme."],"key":["T","T","F"],"why":"Contoh harus benar-benar menggunakan override dengan pemanggilan yang mendukung dispatch dinamis pada bahasa yang dipakai. Dua nama method berbeda tidak menguji dugaan awal.","explanations":["Perbandingan memperlihatkan pemilihan implementasi saat dijalankan.","Prediksi dan revisi mengungkap model mental dispatch.","Nama berbeda menghindari mekanisme override yang sedang dipelajari."]},{"id":15,"uid":"p2-015","package":2,"section":"PCK","code":"P.6","type":"PG","difficulty":"dasar","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","case_focus":"event GUI","stem":"Tombol GUI menjalankan aksi dua kali. Murid menduga event handler terpasang dua kali. Bukti yang paling membantu guru menilai diagnosisnya adalah ...","options":["Membandingkan label tombol sebelum dan sesudah layar dibuka ulang.","Ukuran file executable sebelum dan sesudah perubahan.","Tampilan tombol setelah warna diubah.","Merekam pendaftaran handler dan pemanggilannya per klik."],"key":"D","why":"Asesmen diagnosis meminta bukti yang dapat membedakan penyebab, bukan hanya menunjukkan aplikasi tampak normal.","explanations":["Label tidak menunjukkan berapa kali handler didaftarkan atau dijalankan.","Ukuran file bukan bukti jumlah pemanggilan event.","Warna tidak menguji sumber aksi ganda.","Log menautkan dugaan pendaftaran ganda dengan gejala."]},{"id":16,"uid":"p2-016","package":2,"section":"PCK","code":"PF.2","type":"MCMA","difficulty":"menantang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","case_focus":"koordinat gambar","stem":"Gambar pada canvas bergeser saat posisi klik dipakai langsung, karena koordinat layar berbeda dari koordinat canvas. Guru ingin murid menjelaskan perbaikannya. Pilih semua kegiatan yang tepat.","options":["Menandai titik asal kedua koordinat lalu menghitung posisi relatif klik.","Menggeser gambar dengan angka tetap sampai satu contoh terlihat pas.","Memindahkan canvas dan meminta murid memprediksi posisi relatif yang sama.","Menaikkan resolusi gambar untuk mengubah titik asal klik."],"key":["A","C"],"why":"Perbaikan harus menjelaskan transformasi dari satu sistem koordinat ke sistem lain. Penyesuaian angka kebetulan tidak menjamin hasil pada posisi baru.","explanations":["Hubungan titik asal menjelaskan transformasi koordinat.","Koreksi satu contoh belum berlaku ketika posisi canvas berubah.","Prediksi pada posisi baru menguji pemahaman transformasi.","Resolusi aset tidak menyelesaikan perbedaan titik asal koordinat."]},{"id":17,"uid":"p2-017","package":2,"section":"PCK","code":"P.1","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","case_focus":"animasi berbasis waktu","stem":"Animasi bergerak lebih cepat pada komputer dengan frame rate tinggi. Murid menambah posisi sebesar 5 setiap frame. Langkah pembelajaran terbaik adalah ...","options":["Menyamakan ukuran jendela kedua komputer.","Menguji perpindahan per detik dengan selang antarframe.","Membandingkan kelancaran visual animasi pada kedua komputer.","Membatasi tugas pada satu komputer agar hasilnya tetap."],"key":"B","why":"Gerak per detik dapat dimodelkan sebagai kecepatan dikali selang waktu. Murid perlu membedakannya dari pertambahan tetap per frame.","explanations":["Ukuran jendela tidak langsung menentukan waktu gerak.","Perbandingan menghubungkan kecepatan dengan selang waktu.","Gerak tampak halus belum menjamin jarak yang ditempuh per detik sama.","Satu perangkat menyembunyikan ketergantungan terhadap frame rate."]},{"id":18,"uid":"p2-018","package":2,"section":"PCK","code":"PF.4","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","case_focus":"pemisahan model tampilan","stem":"Guru merancang unit GUI agar murid dapat mengubah tampilan tanpa mengubah aturan perhitungan. Nilai keputusan kurikuler berikut sebagai Tepat atau Tidak tepat.","options":["Menetapkan tujuan hanya dari jumlah jenis widget yang digunakan.","Meminta model perhitungan yang dapat diuji terpisah dari tampilan.","Menilai apakah dua tampilan memakai aturan perhitungan yang sama."],"key":["F","T","T"],"why":"Tujuan, tugas, dan asesmen perlu mengukur pemisahan aturan dari antarmuka. Daftar widget tidak cukup membuktikan kemampuan tersebut.","explanations":["Banyak widget tidak menunjukkan pemisahan tanggung jawab.","Model terpisah mendukung tujuan perubahan antarmuka.","Dua tampilan memberi bukti penerapan pemisahan yang ditargetkan."]},{"id":19,"uid":"p2-019","package":2,"section":"PCK","code":"PF.3","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","case_focus":"rekursi","stem":"Sebelum mengajar rekursi, guru menemukan murid dapat menelusuri pemanggilan fungsi tetapi menganggap semua pemanggilan berbagi variabel lokal yang sama. Langkah awal terbaik adalah ...","options":["Memulai contoh pohon direktori yang sangat besar.","Mengulang definisi fungsi murni sebagai hafalan.","Memodelkan dua catatan pemanggilan dan variabel lokalnya.","Mengganti rekursi dengan materi pewarisan selama satu semester."],"key":"C","why":"Kebutuhan belajar terletak pada model keadaan pemanggilan. Contoh dangkal dua tingkat cukup untuk membedakan variabel lokal sebelum rekursi bertingkat.","explanations":["Ukuran kasus menambah beban sebelum model pemanggilan terbentuk.","Hafalan definisi belum menanggapi dugaan tentang variabel lokal.","Representasi ini menargetkan prasyarat keadaan tiap pemanggilan.","Penggantian materi tidak membantu membangun prasyarat rekursi."]},{"id":20,"uid":"p2-020","package":2,"section":"PCK","code":"P.2","type":"MCMA","difficulty":"menantang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","case_focus":"mutabilitas koleksi","stem":"Dalam kerja berpasangan, satu murid memahami referensi object, temannya masih mengira penyalinan list selalu menyalin seluruh object di dalamnya. Pilih dukungan yang tepat.","options":["Memberi pasangan tugas visual yang sama sekali tidak memakai list.","Memakai diagram referensi dan uji perubahan satu object pada dua list.","Meminta murid yang paham mengubah semua kode pasangannya.","Meminta tiap murid menjelaskan kapan perlu salinan dangkal atau mendalam."],"key":["B","D"],"why":"Dukungan menghubungkan representasi referensi dengan perilaku perubahan, sambil tetap meminta bukti pemahaman dari setiap murid.","explanations":["Tugas itu tidak menargetkan kesenjangan pemahaman referensi.","Diagram dan uji memperlihatkan object yang masih dibagi.","Pengambilalihan pekerjaan tidak menunjukkan perubahan pemahaman teman.","Penjelasan individu mempertahankan tantangan sesuai kesiapan."]},{"id":21,"uid":"p2-021","package":2,"section":"PCK","code":"P.5","type":"PG","difficulty":"dasar","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","case_focus":"aset transparan","stem":"Guru mengajak murid membuat papan informasi budaya setempat. Logo harus tampil di atas beberapa warna latar. Sumber belajar paling sesuai untuk membahas transparansi gambar adalah ...","options":["Kumpulan foto dengan latar putih yang sama.","Foto logo yang sudah menempel pada papan berlatar putih.","Contoh logo yang sudah menyatu dengan poster akhir.","Menguji logo dengan dan tanpa alpha pada beberapa latar."],"key":"D","why":"Sumber lokal dipakai untuk menguji kebutuhan nyata penempatan logo, bukan sekadar menghias tugas. Perbandingan perlu mengisolasi ada-tidaknya transparansi.","explanations":["Latar seragam tidak memperlihatkan kebutuhan transparansi.","Foto dapat memperlihatkan bentuk logo, tetapi tidak menyediakan aset terpisah untuk menguji transparansi.","Aset menyatu tidak memperlihatkan perilaku pada latar baru.","Perbandingan aset lokal menunjukkan fungsi transparansi."]},{"id":22,"uid":"p2-022","package":2,"section":"PCK","code":"P.4","type":"Kategori","difficulty":"dasar","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","case_focus":"pustaka dan dependensi","stem":"Guru menggunakan pengelola dependensi untuk proyek GUI. Murid mengira versi terbaru pustaka selalu cocok dengan proyek lama. Nilai kegiatan berikut sebagai Tepat atau Tidak tepat.","options":["Membandingkan kebutuhan versi proyek dengan dokumentasi pustaka dan mencoba pada salinan proyek.","Menghapus catatan versi agar instalasi selalu memilih yang terbaru.","Menilai pemahaman dari jumlah pustaka yang berhasil diinstal."],"key":["T","F","F"],"why":"Penggunaan alat secara kritis mencakup kompatibilitas dan reproduksibilitas, bukan mengejar versi atau jumlah pustaka.","explanations":["Kegiatan melatih pemilihan alat berdasarkan bukti kompatibilitas.","Hilangnya catatan mengurangi kemampuan mereproduksi lingkungan.","Jumlah instalasi tidak menunjukkan kecocokan pustaka dengan kebutuhan."]},{"id":23,"uid":"p2-023","package":2,"section":"PCK","code":"P.6","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","case_focus":"exception spesifik","stem":"Program pembaca file berhenti karena file tidak ditemukan. Murid mengusulkan menangkap semua exception lalu menampilkan hasil kosong. Umpan balik paling berguna adalah ...","options":["Bedakan file tidak ditemukan dan file rusak; tunjukkan respons yang diperlukan pengguna untuk keduanya.","Tambahkan pesan sukses agar pengguna tidak khawatir.","Meminta daftar semua exception yang tersedia dalam bahasa tersebut.","Pindahkan seluruh kode ke satu fungsi agar singkat."],"key":"A","why":"Umpan balik mengarahkan murid membedakan jenis kegagalan dan respons aplikasi, bukan sekadar membuat error menghilang.","explanations":["Dua kondisi menguji apakah penanganan mempertahankan informasi kegagalan.","Pesan sukses menyembunyikan kegagalan yang perlu ditangani.","Daftar luas belum menunjukkan respons yang tepat pada dua kegagalan pembacaan file.","Pemindahan kode tidak menjamin penanganan tiap kegagalan tepat."]},{"id":24,"uid":"p2-024","package":2,"section":"PCK","code":"PF.5","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","case_focus":"profiling","stem":"Guru ingin memperbaiki cara mengajar optimasi setelah murid mengubah bagian program yang ternyata jarang berjalan. Pilih langkah pengembangan praktik yang beralasan.","options":["Menggunakan profil eksekusi untuk memilih contoh bagian yang paling banyak memakai waktu.","Memilih contoh yang kodenya paling panjang sebagai satu-satunya prioritas.","Membandingkan alasan pemilihan optimasi sebelum dan sesudah penggunaan profil.","Mencatat jenis tugas dan perangkat saat menafsirkan hasilnya."],"key":["A","C","D"],"why":"Pengembangan praktik berfokus pada kemampuan murid memakai bukti biaya, bukan sekadar menghasilkan program lebih cepat pada satu contoh.","explanations":["Profil membantu mengaitkan contoh ajar dengan sumber biaya nyata.","Panjang kode tidak menunjukkan biaya eksekusi.","Perubahan alasan memberi bukti dampak strategi pembelajaran.","Konteks memengaruhi hasil pengukuran dan jangkauan temuan."]},{"id":25,"uid":"p2-025","package":2,"section":"PCK","code":"P.3","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","case_focus":"state diagram","stem":"Saat memodelkan pemutar audio, kelas berdebat apakah tombol jeda boleh bekerja dari keadaan berhenti. Guru ingin diskusi fokus dan bermakna. Respons terbaik adalah ...","options":["Memutuskan berdasarkan suara terbanyak sebelum membaca kebutuhan.","Mengganti diskusi dengan lomba menggambar diagram tercepat.","Menguji transisi diagram terhadap skenario pengguna.","Memilih diagram dengan jumlah keadaan paling sedikit agar mudah dibaca."],"key":"C","why":"Diskusi bermakna memakai kebutuhan dan skenario sebagai acuan. Guru memberi ruang perbedaan sambil menjaga alasan teknis yang dapat diperiksa.","explanations":["Popularitas pendapat bukan dasar perilaku sistem yang diminta.","Kecepatan gambar tidak menyelesaikan perbedaan aturan transisi.","Skenario memberi dasar bersama untuk membandingkan gagasan.","Kesederhanaan berguna, tetapi diagram harus tetap memuat perilaku yang diperlukan pengguna."]},{"id":26,"uid":"p2-026","package":2,"section":"PCK","code":"PF.1","type":"Kategori","difficulty":"dasar","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","case_focus":"integrasi audio","stem":"Dalam proyek panduan audio museum sekolah, guru menargetkan kesiapan kerja murid SMK, bukan hanya audio berhasil diputar. Nilai rancangan penilaian berikut sebagai Tepat atau Tidak tepat.","options":["Murid menjelaskan pemilihan aset audio dan batas izin penggunaannya.","Murid menyerahkan panduan menjalankan aplikasi beserta hasil uji suara.","Nilai akhir ditentukan dari volume suara paling keras."],"key":["T","T","F"],"why":"Kesiapan kerja mencakup keputusan aset, pengujian, dan penyerahan hasil yang dapat digunakan pihak lain.","explanations":["Keputusan aset menghubungkan teknik dan tanggung jawab profesional.","Dokumentasi dan uji membantu orang lain menggunakan hasil kerja.","Volume tertinggi tidak mewakili mutu, kegunaan, atau tanggung jawab kerja."]},{"id":27,"uid":"p2-027","package":2,"section":"PCK","code":"P.1","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Web","case_focus":"CSS cascade","stem":"Dua aturan CSS menargetkan elemen yang sama; murid mengira aturan terakhir selalu menang. Guru ingin memperbaiki model mentalnya. Contoh pembanding terbaik adalah ...","options":["Dua aturan dengan selector dan nilai yang sama persis.","Menukar urutan dua selector yang specificity-nya berbeda.","Halaman dengan semua gaya ditulis inline.","Membandingkan dua aturan dengan selector sama yang diletakkan bergantian."],"key":"B","why":"Pada kondisi asal dan kepentingan aturan yang sama, specificity dapat mengalahkan urutan. Contoh perlu mengendalikan faktor lain agar dugaan terakhir-selalu-menang dapat diuji.","explanations":["Keluaran yang sama tidak membedakan dugaan murid.","Pertukaran urutan menguji pengaruh specificity secara terpisah.","Satu sumber gaya tidak memperlihatkan kompetisi aturan.","Kasus specificity sama hanya menguatkan pengaruh urutan dan tidak menguji batas dugaan murid."]},{"id":28,"uid":"p2-028","package":2,"section":"PCK","code":"PF.2","type":"MCMA","difficulty":"menantang","cp_element":"Pemrograman Web","case_focus":"box model","stem":"Lebar kartu melampaui ruang setelah padding ditambah. Guru meminta murid memeriksa box model, dengan margin dianggap nol. Pilih kegiatan yang mendukung diagnosis.","options":["Menghitung content, padding, dan border pada mode content-box.","Mengubah jenis font sampai kartu tampak lebih sempit.","Meminta screenshot ukuran layar saja.","Membandingkan hasil ukuran pada content-box dan border-box."],"key":["A","D"],"why":"Penjelasan perlu menghubungkan ukuran yang dinyatakan dan ukuran luar elemen. Percobaan terkontrol lebih kuat daripada penyesuaian tampilan kebetulan.","explanations":["Perhitungan menunjukkan komponen yang menambah lebar luar.","Perubahan font tidak langsung menjelaskan perhitungan box.","Ukuran layar saja tidak menunjukkan komponen lebar elemen.","Dua mode menguji apakah padding termasuk dalam lebar yang ditetapkan."]},{"id":29,"uid":"p2-029","package":2,"section":"PCK","code":"P.2","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Web","case_focus":"HTML semantik","stem":"Murid terbiasa memakai div untuk semua elemen. Sebagian belum memahami perbedaan peran tombol dan tautan. Guru ingin semua dapat memilih elemen berdasarkan fungsi. Strategi paling tepat adalah ...","options":["Memberi skenario navigasi dan aksi, lalu meminta pilihan elemen beserta uji perilakunya.","Membagi murid ke kelompok mahir tetap berdasarkan banyaknya tag yang hafal.","Memilih elemen berdasarkan kemudahan menyamakan tampilannya dengan rancangan.","Memulai dengan daftar panjang atribut ARIA untuk dihafalkan."],"key":"A","why":"Dukungan dimulai dari perbedaan fungsi yang belum dipahami. Pengujian perilaku membantu murid melampaui pemilihan elemen berdasarkan tampilan.","explanations":["Skenario dan uji membantu murid mengaitkan semantik dengan fungsi.","Jumlah tag tidak cukup menjadi dasar pengelompokan permanen.","Kemudahan styling belum menjamin elemen memiliki peran dan perilaku yang sesuai.","Daftar atribut menambah beban sebelum fungsi elemen dipahami."]},{"id":30,"uid":"p2-030","package":2,"section":"PCK","code":"P.6","type":"Kategori","difficulty":"menantang","cp_element":"Pemrograman Web","case_focus":"event bubbling","stem":"Klik tombol hapus di dalam kartu juga membuka detail karena handler kartu ikut menerima event. Guru menilai diagnosis murid. Nilai bukti berikut sebagai Tepat atau Tidak tepat.","options":["Murid menyimpulkan masalah selesai karena ikon hapus diganti.","Murid menggambar jalur event dan menunjukkan handler yang dijalankan.","Murid menjelaskan perbedaan menghentikan propagasi dan mencegah aksi bawaan."],"key":["F","T","T"],"why":"Bukti pemahaman harus menjelaskan alur event dan pilihan penanganannya. preventDefault tidak identik dengan menghentikan propagasi.","explanations":["Perubahan ikon tidak membuktikan alur event berubah.","Jalur event memperlihatkan hubungan klik dengan aksi ganda.","Dua mekanisme menangani persoalan berbeda sehingga perlu dibedakan."]},{"id":31,"uid":"p2-031","package":2,"section":"PCK","code":"P.4","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Web","case_focus":"cache aset","stem":"Setelah deployment, beberapa browser menampilkan CSS lama. Guru menggunakan panel Network agar murid memahami cache. Aktivitas paling tepat adalah ...","options":["Menghapus seluruh riwayat setiap kali membuka halaman.","Membandingkan ukuran tampilan halaman lama dan baru setelah deployment.","Menambah ukuran file CSS agar dianggap versi baru.","Membaca URL, header cache, dan respons saat muat ulang."],"key":"D","why":"Alat digunakan untuk menelusuri bukti pemuatan aset. Nama atau versi aset dan kebijakan cache perlu dikaitkan dengan perilaku browser.","explanations":["Kebiasaan ini menghindari penjelasan asal aset yang dipakai.","Tampilan dapat memperlihatkan gejala, tetapi belum menelusuri sumber aset dan kebijakan cache.","Ukuran file bukan mekanisme penamaan versi yang dapat diandalkan.","Bukti permintaan membantu membedakan aset tersimpan dari aset baru."]},{"id":32,"uid":"p2-032","package":2,"section":"PCK","code":"P.1","type":"MCMA","difficulty":"menantang","cp_element":"Pemrograman Web","case_focus":"balapan response","stem":"Pencarian web mengirim request untuk kata pendek lalu kata panjang. Response lama tiba paling akhir dan menimpa hasil terbaru. Guru ingin murid menalar urutan asinkron. Pilih kegiatan yang tepat.","options":["Menganggap response terakhir tiba pasti berasal dari input terakhir.","Menyusun garis waktu input, request, dan response dari log.","Menguji pemeriksaan identitas request sebelum memperbarui tampilan.","Menambah animasi tunggu dengan durasi tetap sebagai jaminan urutan."],"key":["B","C"],"why":"Kasus menguji perbedaan urutan pengiriman dan penyelesaian. Tampilan perlu menerima hasil yang masih relevan dengan input saat ini.","explanations":["Urutan selesai tidak menjamin urutan request.","Garis waktu memperlihatkan sumber hasil yang menimpa.","Pemeriksaan dapat mencegah hasil usang mengganti hasil terbaru.","Durasi tetap tidak menjamin urutan penyelesaian jaringan."]},{"id":33,"uid":"p2-033","package":2,"section":"PCK","code":"PF.3","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Web","case_focus":"Pengodean nilai parameter URL","stem":"Murid dapat menyusun tautan pencarian untuk satu kata, tetapi nilai A&B terpecah menjadi dua parameter. Sebelum membahas pembentukan URL dinamis, dukungan awal terbaik adalah ...","options":["Menambah jumlah tautan yang harus disalin.","Mengganti semua istilah pencarian menjadi angka.","Menguji pengodean nilai parameter URL.","Meminta murid menghafal seluruh status HTTP."],"key":"C","why":"Kebutuhan belajar terletak pada pembedaan struktur URL dan nilai parameter. Pengodean nilai menjaga karakter khusus tetap menjadi bagian data, bukan pemisah parameter.","explanations":["Salinan tambahan tidak menjelaskan peran karakter khusus.","Penggantian data menghindari kebutuhan merepresentasikan nilai asli.","Perbandingan menargetkan prasyarat pemisahan struktur URL dan isi parameter.","Status HTTP tidak menjelaskan pembentukan parameter URL."]},{"id":34,"uid":"p2-034","package":2,"section":"PCK","code":"P.6","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Web","case_focus":"session timeout","stem":"Sesi web habis saat murid mengisi formulir panjang. Tujuan belajar ialah merancang respons aplikasi yang menjaga pekerjaan pengguna dan menjelaskan status autentikasi. Nilai bukti berikut sebagai Tepat atau Tidak tepat.","options":["Murid mendemonstrasikan penyimpanan draf yang sesuai dan alur login ulang pada data uji.","Murid hanya menunjukkan formulir berhasil dikirim saat sesi masih aktif.","Murid menjelaskan data yang boleh dipertahankan serta batas penyimpanannya."],"key":["T","F","T"],"why":"Asesmen harus memunculkan kondisi yang menjadi tujuan desain. Keberhasilan saat sesi aktif tidak cukup membuktikan penanganan sesi habis.","explanations":["Demonstrasi menguji pemulihan pekerjaan saat sesi habis.","Kondisi normal belum menguji skenario habis sesi.","Penjelasan menghubungkan pemulihan dengan pengelolaan data pengguna."]},{"id":35,"uid":"p2-035","package":2,"section":"PCK","code":"PF.2","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Web","case_focus":"pengodean keluaran","stem":"Teks komentar pengguna dirender sebagai HTML sehingga tag ikut dijalankan. Guru ingin murid memahami penyajian teks yang aman. Demonstrasi paling tepat adalah ...","options":["Menghapus komentar yang panjangnya melebihi satu baris.","Menguji penyisipan contoh sebagai teks dan sebagai HTML.","Memvalidasi bahwa kolom komentar terisi sebelum data disimpan.","Membatasi warna huruf yang boleh dipilih pengguna."],"key":"B","why":"Guru perlu menunjukkan bagaimana konteks penyajian memengaruhi interpretasi data. Pengodean keluaran yang sesuai konteks berbeda dari sekadar membatasi panjang atau tampilan.","explanations":["Panjang teks bukan penentu apakah isi ditafsirkan sebagai markup.","Perbandingan memperlihatkan perbedaan data teks dan markup yang dieksekusi.","Keterisian tidak mengatur apakah data ditampilkan sebagai teks atau ditafsirkan sebagai markup.","Pilihan warna tidak menangani interpretasi tag dari data."]},{"id":36,"uid":"p2-036","package":2,"section":"PCK","code":"P.5","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Web","case_focus":"deployment path","stem":"Situs informasi wisata desa bekerja di komputer murid, tetapi aset gagal saat dipasang dalam subfolder server mitra. Guru ingin memakai lingkungan setempat sebagai sumber belajar deployment. Pilih kegiatan yang tepat.","options":["Memetakan URL halaman dan aset pada struktur subfolder mitra.","Mengganti semua gambar dengan resolusi lebih rendah.","Menguji path relatif dan path dari root pada struktur tersebut.","Memindahkan proyek ke root lalu menganggap semua kebutuhan mitra terpenuhi."],"key":["A","C"],"why":"Konteks deployment lokal memberi alasan mempelajari path. Solusi dinilai terhadap struktur tujuan, bukan hanya keberhasilan pada komputer sendiri.","explanations":["Struktur nyata membantu menelusuri perbedaan alamat.","Resolusi tidak menyelesaikan alamat aset yang keliru.","Perbandingan menjelaskan konsekuensi pemilihan path.","Pemindahan menghindari kondisi pemasangan yang diminta mitra."]},{"id":37,"uid":"p2-037","package":2,"section":"PCK","code":"PF.4","type":"PG","difficulty":"dasar","cp_element":"Pemrograman Web","case_focus":"dokumentasi endpoint","stem":"Guru menyusun unit API web agar hasil kerja kelompok dapat dipakai kelompok lain. Targetnya memahami kontrak endpoint, bukan menghafal alat dokumentasi. Asesmen paling selaras adalah ...","options":["Kelompok lain mencoba endpoint dari dokumentasi lalu melaporkan ketidakcocokan request-response.","Menghitung jumlah halaman dokumentasi yang dibuat.","Memberi kuis nama menu aplikasi dokumentasi.","Menilai kelengkapan daftar endpoint dari jumlah alamat yang dicantumkan."],"key":"A","why":"Kurikulum menghubungkan tujuan dokumentasi dengan kegiatan penggunaan dan bukti keterpakaian, bukan penguasaan merek alat.","explanations":["Pemakaian lintas kelompok menguji kelengkapan kontrak yang ditulis.","Jumlah halaman tidak menjamin kontrak dapat digunakan.","Nama menu tidak mengukur kemampuan menjelaskan endpoint.","Alamat saja belum menjelaskan parameter, bentuk response, dan kondisi yang dibutuhkan pemakai."]},{"id":38,"uid":"p2-038","package":2,"section":"PCK","code":"PF.5","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Web","case_focus":"uji akses keyboard","stem":"Guru mencoba pendekatan audit keyboard pada pembelajaran web karena murid hanya menguji dengan mouse. Nilai tindakan pengembangan praktik berikut sebagai Tepat atau Tidak tepat.","options":["Mengumpulkan rekaman urutan fokus sebelum dan sesudah kegiatan audit.","Menganalisis alasan murid memilih urutan dan label kontrol.","Menyimpulkan semua pengguna pasti terbantu setelah satu halaman berhasil diuji."],"key":["T","T","F"],"why":"Perbaikan praktik membutuhkan bukti proses dan hasil beserta batas cakupannya. Audit keyboard menambah bukti, bukan menjamin seluruh aksesibilitas.","explanations":["Urutan fokus memberi bukti perubahan keterujian navigasi.","Alasan membantu menilai perubahan pemahaman aksesibilitas.","Satu halaman dan satu cara akses tidak mewakili semua kebutuhan pengguna."]},{"id":39,"uid":"p2-039","package":2,"section":"PCK","code":"P.1","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Perangkat Bergerak","case_focus":"rotasi layar","stem":"Setelah ponsel diputar, form mobile kembali kosong. Murid menyangka perubahan orientasi hanya mengubah ukuran gambar. Langkah guru terbaik adalah ...","options":["Mengunci semua orientasi sebagai penjelasan utama lifecycle.","Menguji hanya perubahan lebar komponen setelah orientasi berganti.","Menambah delay sebelum menampilkan form.","Melacak lifecycle dan tempat state disimpan."],"key":"D","why":"Pada platform yang membuat ulang layar ketika konfigurasi berubah, state lokal dapat hilang. Murid perlu menguji lifecycle dan strategi pemulihannya, bukan menganggap rotasi sekadar perubahan gambar.","explanations":["Penguncian dapat menutupi gejala, bukan menjelaskan pembuatan ulang layar.","Lebar menguji tata letak, tetapi belum menjelaskan hilangnya state akibat lifecycle.","Penundaan tidak menjamin state disimpan dan dipulihkan.","Log dan state menghubungkan perubahan orientasi dengan pembuatan ulang komponen."]},{"id":40,"uid":"p2-040","package":2,"section":"PCK","code":"P.2","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","case_focus":"izin lokasi","stem":"Murid merancang aplikasi peta jalur sekolah. Sebagian belum memahami bahwa izin lokasi dapat ditolak pengguna. Guru menyiapkan dukungan sesuai kesiapan. Pilih langkah yang tepat.","options":["Memberi diagram alur izin diberikan atau ditolak sebelum implementasi.","Meminta murid yang siap merancang pemilihan lokasi manual sebagai alternatif.","Menyamakan penolakan izin dengan kerusakan perangkat.","Mengecek tiap murid dapat menjelaskan tampilan ketika izin ditolak."],"key":["A","B","D"],"why":"Dukungan mempertimbangkan kesiapan dalam menalar cabang izin. Alternatif manual menjaga fungsi yang sesuai ketika akses lokasi tidak diberikan.","explanations":["Diagram membantu murid menyiapkan dua kondisi pengguna.","Tantangan memperdalam solusi sambil menjaga fungsi inti.","Penolakan merupakan pilihan pengguna yang sah, bukan bukti perangkat rusak.","Penjelasan individu memastikan prasyarat kondisi pengguna dipahami."]},{"id":41,"uid":"p2-041","package":2,"section":"PCK","code":"P.6","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","case_focus":"latar belakang","stem":"Pemutar audio mobile berhenti ketika aplikasi masuk latar belakang. Tujuan asesmen ialah murid dapat menjelaskan perilaku yang sesuai kebutuhan pengguna dan batas platform. Bukti terbaik adalah ...","options":["Video aplikasi dipakai terus dalam keadaan foreground.","Menguji perpindahan status dengan log dan alasan desain.","Membandingkan format audio pada dua file yang berhasil diputar saat layar aktif.","Tangkapan layar izin penyimpanan saja."],"key":"B","why":"Asesmen menilai keputusan desain berdasarkan skenario penggunaan. Tidak semua aplikasi harus terus memutar audio; keputusan harus dijelaskan terhadap kebutuhan dan kemampuan platform.","explanations":["Kondisi itu belum menguji perpindahan ke latar belakang.","Bukti menautkan perilaku aktual, kebutuhan, dan lifecycle.","Format dapat memengaruhi kompatibilitas, tetapi belum menguji perpindahan status aplikasi.","Izin penyimpanan bukan keseluruhan bukti perilaku pemutaran."]},{"id":42,"uid":"p2-042","package":2,"section":"PCK","code":"PF.3","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","case_focus":"thread UI","stem":"Murid memahami pemanggilan fungsi berurutan, tetapi mengira mengambil data jaringan pada thread UI tidak memengaruhi sentuhan. Guru memetakan kebutuhan sebelum praktik mobile. Nilai tindakan berikut sebagai Tepat atau Tidak tepat.","options":["Menganggap kelancaran pada jaringan cepat sudah membuktikan pemahaman responsivitas.","Meminta murid memprediksi respons tombol saat request sengaja diperlambat.","Memberi model antrean kerja UI sebelum meminta tugas asinkron."],"key":["F","T","T"],"why":"Kebutuhan murid terletak pada model penjadwalan kerja dan respons UI. Penundaan terkontrol membantu menampakkan masalah yang tersembunyi pada koneksi cepat.","explanations":["Jaringan cepat dapat menyembunyikan penundaan yang menghalangi UI.","Prediksi mengungkap hubungan tugas panjang dengan thread UI.","Model antrean menanggapi prasyarat penalaran yang belum terbentuk."]},{"id":43,"uid":"p2-043","package":2,"section":"PCK","code":"P.5","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","case_focus":"offline sync","stem":"Petugas posyandu setempat sering mencatat saat sinyal putus. Guru menjadikan kebutuhan itu konteks pembelajaran penyimpanan lokal mobile. Kegiatan paling sesuai adalah ...","options":["Meminta semua petugas menunggu sinyal untuk mulai mencatat.","Menggunakan contoh aplikasi yang selalu terhubung sebagai satu-satunya bahan.","Mensimulasikan catatan luring, antrean kirim, dan status sinkronisasi.","Meminta murid memperkecil ukuran paket request pada koneksi yang masih tersedia."],"key":"C","why":"Sumber kebutuhan setempat dipakai untuk mempelajari penyimpanan lokal dan proses pengiriman yang dapat diperiksa. Data latihan harus tiruan, bukan rekam kesehatan asli.","explanations":["Kegiatan itu tidak menanggapi kebutuhan pencatatan saat luring.","Contoh selalu daring menghindari kondisi sumber lokal.","Skenario lokal memberi alasan mempelajari persistensi dan sinkronisasi.","Paket kecil dapat membantu koneksi lambat, tetapi tidak menggantikan pencatatan saat sama sekali luring."]},{"id":44,"uid":"p2-044","package":2,"section":"PCK","code":"PF.2","type":"MCMA","difficulty":"menantang","cp_element":"Pemrograman Perangkat Bergerak","case_focus":"konflik versi","stem":"Dua perangkat mengubah catatan yang sama saat luring. Ketika tersambung, perubahan terakhir yang tiba menimpa perubahan lain. Guru ingin murid menilai strategi konflik. Pilih kegiatan yang tepat.","options":["Menjadikan waktu tiba di server sebagai bukti tunggal bahwa isi paling benar.","Membandingkan nomor versi asal dan perubahan yang dikirim tiap perangkat.","Meminta murid menguji kebijakan penyelesaian konflik terhadap skenario pengguna.","Menghapus salinan lokal segera setelah tombol kirim ditekan."],"key":["B","C"],"why":"Konflik memerlukan deteksi dan kebijakan yang dijelaskan. Tidak ada aturan penimpaan tunggal yang otomatis benar untuk semua kebutuhan.","explanations":["Urutan tiba bukan jaminan ketepatan isi perubahan.","Versi asal membantu mendeteksi perubahan bersamaan.","Kebijakan perlu memenuhi kebutuhan, bukan sekadar menghilangkan pesan konflik.","Pengiriman belum tentu berhasil sehingga data dapat hilang."]},{"id":45,"uid":"p2-045","package":2,"section":"PCK","code":"P.6","type":"PG","difficulty":"dasar","cp_element":"Pemrograman Perangkat Bergerak","case_focus":"daur hidup listener","stem":"Setelah beberapa kali membuka layar mobile, satu perubahan data memicu banyak pembaruan tampilan. Guru ingin menilai pemahaman pemasangan dan pelepasan listener. Bukti paling tepat adalah ...","options":["Log jumlah listener aktif saat masuk dan keluar layar, beserta penjelasan pelepasannya.","Mengamati jumlah baris yang terlihat setelah layar dibuka berulang kali.","Warna indikator saat data berubah.","Ukuran ikon aplikasi yang terpasang."],"key":"A","why":"Penilaian memerlukan jejak lifecycle dan callback. Gejala berulang tidak cukup dijelaskan dengan jumlah komponen visual.","explanations":["Log langsung menguji dugaan listener menumpuk sepanjang lifecycle.","Jumlah baris tidak menunjukkan apakah listener yang lama sudah dilepas.","Warna tidak menjelaskan berapa callback yang dijalankan.","Ukuran ikon tidak terkait pelepasan listener."]},{"id":46,"uid":"p2-046","package":2,"section":"PCK","code":"P.4","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","case_focus":"density layar","stem":"Guru memakai emulator untuk membahas ukuran antarmuka mobile. Murid menyimpulkan tombol 48 piksel fisik selalu sama besar pada setiap layar. Nilai penggunaan alat berikut sebagai Tepat atau Tidak tepat.","options":["Membandingkan ukuran tombol pada emulator dengan density berbeda.","Menganggap satu screenshot cukup membuktikan kenyamanan sentuh pada semua perangkat.","Menghubungkan hasil emulator dengan pengujian sentuh pada perangkat yang tersedia."],"key":["T","F","T"],"why":"Alat digital dipakai untuk menguji asumsi ukuran, bukan menggantikan seluruh bukti penggunaan. Satuan logis membantu konsistensi ukuran antarmuka lintas density.","explanations":["Perbandingan mengungkap beda piksel fisik dan satuan logis.","Screenshot tunggal tidak menunjukkan ukuran fisik dan interaksi beragam perangkat.","Perangkat nyata melengkapi bukti yang tidak diberikan emulator."]},{"id":47,"uid":"p2-047","package":2,"section":"PCK","code":"P.1","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Perangkat Bergerak","case_focus":"daftar daur ulang","stem":"Checkbox pada daftar mobile tampak mencentang item lain setelah digulir. Komponen baris dipakai ulang dan state hanya disimpan pada tampilannya. Langkah pembelajaran terbaik adalah ...","options":["Memperkecil font agar lebih banyak baris terlihat sekaligus.","Menghapus checkbox setiap kali daftar dibuka.","Mengurutkan daftar berdasarkan panjang label.","Melacak identitas item dan state saat baris didaur ulang."],"key":"D","why":"Model mental perlu memisahkan data item dan baris yang didaur ulang. Uji gulir bolak-balik memperlihatkan apakah state benar-benar mengikuti item.","explanations":["Perubahan font mengurangi guliran tetapi tidak memperbaiki kepemilikan state.","Penghapusan menghindari kebutuhan mempertahankan pilihan pengguna.","Urutan label tidak menjelaskan daur ulang komponen.","Pelacakan membedakan state item dari komponen tampilan sementara."]},{"id":48,"uid":"p2-048","package":2,"section":"PCK","code":"P.3","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","case_focus":"status HTTP","stem":"Dalam tantangan mobile, kelompok berlomba menampilkan pesan dari API. Ada yang menganggap setiap response HTTP berarti permintaan berhasil. Guru ingin kegiatan tetap menantang dan bermakna. Pilih langkah yang tepat.","options":["Memberi misi membedakan hasil 200, 404, dan kegagalan koneksi pada skenario uji.","Menetapkan pemenang hanya dari kecepatan memunculkan pesan apa pun.","Meminta kelompok menjelaskan keputusan tampilan sebelum bertukar skenario uji.","Menghentikan pembahasan ketika satu request berhasil."],"key":["A","C"],"why":"Kegembiraan kegiatan berasal dari tantangan yang punya tujuan jelas. Response HTTP dapat berisi status gagal; kegagalan koneksi berbeda dari response server.","explanations":["Variasi kondisi mengarahkan tantangan pada penalaran status.","Pesan yang muncul belum membuktikan penafsiran hasil benar.","Penjelasan dan pertukaran menjaga tantangan sekaligus refleksi.","Satu keberhasilan tidak menguji pemahaman kondisi lain."]},{"id":49,"uid":"p2-049","package":2,"section":"PCK","code":"PF.4","type":"PG","difficulty":"dasar","cp_element":"Pemrograman Perangkat Bergerak","case_focus":"notifikasi","stem":"Guru menyusun unit mobile tentang pengingat kegiatan. Platform menyediakan mekanisme notifikasi, tetapi murid cenderung hanya menyalin kode jadwal. Tujuan pembelajaran yang paling tepat adalah ...","options":["Menyebut nama semua kelas notifikasi dari dokumentasi.","Merancang pengingat, menangani izin, dan menguji jadwal.","Menghasilkan sebanyak mungkin notifikasi dalam satu menit.","Menyamakan rancangan ikon dan bunyi pengingat pada seluruh aplikasi kelas."],"key":"B","why":"Tujuan kurikuler diturunkan dari kemampuan aplikasi yang dibutuhkan. API merupakan sarana, bukan daftar sintaks yang menjadi tujuan akhir.","explanations":["Hafalan nama belum mengukur perancangan perilaku pengingat.","Tujuan mencakup keputusan dan penerapan pada kondisi penggunaan.","Jumlah notifikasi bukan ukuran ketercapaian kebutuhan.","Keseragaman tampilan belum mengukur pengelolaan izin dan perubahan jadwal."]},{"id":50,"uid":"p2-050","package":2,"section":"PCK","code":"PF.1","type":"Kategori","difficulty":"dasar","cp_element":"Pemrograman Perangkat Bergerak","case_focus":"dokumentasi build","stem":"Dalam penyerahan aplikasi mobile SMK kepada tim lain, guru menilai tanggung jawab profesional murid. Nilai praktik berikut sebagai Tepat atau Tidak tepat.","options":["Menyerahkan file instalasi saja karena aplikasi pernah berjalan di ponsel pembuat.","Mengganti semua peringatan build dengan catatan bahwa perangkat penerima bermasalah.","Mencatat versi alat, konfigurasi yang dibutuhkan, dan langkah build yang dapat dicoba."],"key":["F","F","T"],"why":"Kesiapan kerja mencakup penyerahan hasil yang dapat diteruskan. Catatan lingkungan dan build membantu pihak lain bertanggung jawab atas pekerjaan berikutnya.","explanations":["Pengalaman satu perangkat tidak cukup membantu tim lain membangun dan menguji.","Pernyataan itu belum menelusuri kebutuhan lingkungan proyek.","Dokumentasi memungkinkan penyerahan pekerjaan yang dapat direproduksi."]},{"id":51,"uid":"p2-051","package":2,"section":"PU","code":"P.1","type":"PG","difficulty":"sedang","cp_element":null,"case_focus":"transfer rasio","stem":"Murid dapat menghitung rasio pada resep minuman, tetapi gagal saat satuan diubah dari liter ke mililiter. Guru ingin pemahaman dapat diterapkan pada situasi baru. Langkah terbaik adalah ...","options":["Meminta murid membuat tabel rasio dari resep dengan satuan tetap.","Meminta murid menghafal jawaban contoh resep.","Membandingkan resep setara dalam dua satuan beserta alasannya.","Mengganti topik menjadi membaca nama satuan."],"key":"C","why":"Transfer memerlukan pemahaman hubungan yang tetap meski penyajian berubah. Perbedaan satuan menjadi bukti untuk meninjau cara murid membandingkan besaran.","explanations":["Tabel dapat membantu rasio, tetapi belum menanggapi kesulitan ketika satuannya berubah.","Jawaban contoh tidak menjelaskan hubungan besaran.","Perbandingan menguji hubungan rasio, bukan rupa angka.","Pengenalan nama belum mencapai penerapan rasio."]},{"id":52,"uid":"p2-052","package":2,"section":"PU","code":"P.1","type":"MCMA","difficulty":"sedang","cp_element":null,"case_focus":"contoh dan noncontoh","stem":"Murid mengira semua bangun berempat sisi adalah persegi. Guru akan memakai contoh dan noncontoh. Pilih kegiatan yang tepat.","options":["Membandingkan persegi dengan persegi panjang yang sisinya tidak sama.","Memutar gambar persegi dan meminta alasan apakah jenis bangunnya berubah.","Menampilkan hanya persegi dengan ukuran dan warna sama.","Meminta murid mengelompokkan bangun baru memakai ciri yang mereka rumuskan."],"key":["A","B","D"],"why":"Contoh bervariasi dan noncontoh membantu murid menemukan ciri penentu, bukan menghafal gambar yang biasa terlihat.","explanations":["Pasangan memperlihatkan perlunya syarat tambahan selain empat sisi.","Rotasi menguji apakah murid bergantung pada orientasi gambar.","Keseragaman dapat mempertahankan pengenalan dari tampilan sempit.","Pengelompokan baru menguji penerapan ciri konseptual."]},{"id":53,"uid":"p2-053","package":2,"section":"PU","code":"P.2","type":"PG","difficulty":"sedang","cp_element":null,"case_focus":"hambatan menulis","stem":"Dalam pelajaran sejarah, seorang murid mampu menjelaskan hubungan sebab-akibat secara lisan tetapi kesulitan menulis panjang karena hambatan motorik. Tujuan asesmen ialah penalaran sejarah. Penyesuaian terbaik adalah ...","options":["Menerima rekaman penjelasan dengan kriteria bukti dan alasan yang sama.","Mengganti seluruh tugasnya menjadi menyalin judul bab.","Memberi tambahan waktu untuk menyalin jawaban lisan menjadi tulisan panjang.","Meminta teman menyampaikan jawaban atas namanya."],"key":"A","why":"Hambatan cara menyampaikan jawaban perlu dipisahkan dari kemampuan yang dinilai. Kriteria tetap, sedangkan moda respons dapat disesuaikan.","explanations":["Cara respons disesuaikan sambil mempertahankan sasaran penalaran.","Tugas itu tidak mengukur penalaran sejarah.","Tambahan waktu mungkin membantu sebagian tugas, tetapi tetap membebani hambatan motorik saat sasaran utamanya penalaran sejarah.","Jawaban teman tidak memberi bukti penalaran individu."]},{"id":54,"uid":"p2-054","package":2,"section":"PU","code":"P.2","type":"Kategori","difficulty":"sedang","cp_element":null,"case_focus":"penutur bahasa baru","stem":"Murid yang baru belajar bahasa pengantar dapat mengurutkan gambar proses, tetapi belum lancar menjelaskan dengan kalimat lengkap. Tujuan kelas ialah menjelaskan urutan sebab-akibat. Nilai dukungan berikut sebagai Tepat atau Tidak tepat.","options":["Memberi kerangka kalimat yang menghubungkan urutan gambar.","Mengizinkan penjelasan bertahap dengan gambar dan kata kunci.","Menyimpulkan kemampuan bernalarnya rendah dari kelancaran bahasa saja."],"key":["T","T","F"],"why":"Dukungan bahasa membantu menampilkan penalaran, bukan menggantinya. Guru perlu membedakan hambatan ekspresi dan pemahaman hubungan.","explanations":["Kerangka membantu ekspresi hubungan yang sudah mulai dipahami.","Respons bertahap membuka akses pada tujuan yang sama.","Kelancaran bahasa tidak cukup mewakili penalaran proses."]},{"id":55,"uid":"p2-055","package":2,"section":"PU","code":"P.3","type":"PG","difficulty":"sedang","cp_element":null,"case_focus":"perencanaan konsentrasi","stem":"Saat membaca teks panjang, murid cepat berpindah aktivitas dan tidak menyadari bagian yang belum dipahami. Guru ingin membangun kesadaran mengelola perhatian. Langkah terbaik adalah ...","options":["Meminta seluruh teks selesai dengan waktu yang makin pendek.","Mengganti bacaan dengan permainan yang tidak terkait isinya.","Mencatat durasi duduk tenang sebagai satu-satunya bukti kesadaran membaca.","Menentukan jeda baca untuk memeriksa pemahaman."],"key":"D","why":"Kesadaran belajar melibatkan pemantauan tujuan dan proses. Jeda dipakai memeriksa pemahaman, bukan sekadar menghentikan kegiatan.","explanations":["Tekanan kecepatan belum mengajarkan pemantauan pemahaman.","Aktivitas itu menghindari tujuan pengelolaan perhatian saat membaca.","Duduk tenang belum menunjukkan murid mengenali bagian yang dipahami dan yang belum.","Perencanaan jeda membantu murid menyadari serta mengelola proses belajarnya."]},{"id":56,"uid":"p2-056","package":2,"section":"PU","code":"P.3","type":"MCMA","difficulty":"sedang","cp_element":null,"case_focus":"tantangan kolaboratif","stem":"Dalam tantangan menyusun jembatan kertas, murid mulai memburu skor dan meninggalkan penjelasan mengapa desainnya kuat. Guru ingin kegiatan tetap menggembirakan dan bermakna. Pilih tindakan yang tepat.","options":["Menambah hadiah untuk kelompok yang paling cepat selesai.","Menyisipkan kesempatan memprediksi dan menjelaskan perubahan desain.","Memberi waktu mencoba ulang setelah kelompok membandingkan hasil uji.","Mengumumkan pemenang sebelum kelompok sempat menjelaskan desain."],"key":["B","C"],"why":"Kegiatan menarik tetap perlu menghubungkan tindakan, bukti, dan refleksi. Tantangan tidak harus dihapus, tetapi diarahkan kembali pada tujuan.","explanations":["Hadiah kecepatan memperkuat fokus yang sedang menggeser tujuan.","Prediksi mengembalikan tantangan pada penalaran.","Percobaan ulang mendukung refleksi dan rasa mampu.","Pengumuman dini menutup kesempatan mengaitkan hasil dan alasan."]},{"id":57,"uid":"p2-057","package":2,"section":"PU","code":"P.4","type":"PG","difficulty":"dasar","cp_element":null,"case_focus":"simulasi digital","stem":"Guru memakai simulasi digital pertumbuhan populasi. Murid menganggap gambar yang tampak realistis pasti memprediksi lingkungan sebenarnya. Tindakan paling tepat adalah ...","options":["Memilih simulasi dengan warna paling menyerupai alam.","Menguji satu parameter lalu membahas asumsi model.","Meminta murid mengubah beberapa parameter sekaligus lalu memilih grafik paling menarik.","Memperbesar tampilan grafik sampai memenuhi layar."],"key":"B","why":"Literasi penggunaan teknologi mencakup membaca model dan asumsi. Tampilan realistis tidak menggantikan pemeriksaan kesesuaian dengan fenomena.","explanations":["Kemiripan visual tidak menjamin ketepatan prediksi.","Percobaan dan asumsi memperlihatkan bahwa simulasi merupakan representasi terbatas.","Perubahan serentak menyulitkan penafsiran pengaruh parameter dan tidak membahas asumsi model.","Ukuran grafik tidak menentukan validitas model."]},{"id":58,"uid":"p2-058","package":2,"section":"PU","code":"P.4","type":"Kategori","difficulty":"sedang","cp_element":null,"case_focus":"rekam video","stem":"Guru merekam gerak percobaan agar kelas dapat menganalisis urutannya. Nilai penggunaan rekaman berikut sebagai Tepat atau Tidak tepat.","options":["Memutar bagian tertentu lebih lambat lalu membandingkan pengamatan murid.","Menyimpulkan kecepatan gerak nyata dari video yang sudah diperlambat tanpa faktor skala waktu.","Memilih rekaman dari efek visualnya sebagai satu-satunya dasar."],"key":["T","F","F"],"why":"Rekaman memberi akses pengamatan, tetapi penafsiran perlu mempertimbangkan perubahan cara penyajian waktunya.","explanations":["Kontrol waktu membantu melihat kejadian yang sukar diamati langsung.","Perubahan pemutaran harus diperhitungkan dalam penafsiran waktu.","Efek visual tidak menjamin rekaman membantu tujuan pengamatan."]},{"id":59,"uid":"p2-059","package":2,"section":"PU","code":"P.5","type":"PG","difficulty":"sedang","cp_element":null,"case_focus":"narasumber lokal","stem":"Guru mengundang perajin lokal untuk pelajaran pengukuran. Istilah ukuran yang dipakai perajin berbeda dari satuan pada buku. Kegiatan terbaik adalah ...","options":["Meminta murid mencatat seluruh istilah ukuran lokal sebagai hasil akhir tugas.","Menerima semua ukuran lokal sebagai setara dengan satuan baku.","Membandingkan cara ukur perajin dengan alat baku.","Mengalihkan kunjungan menjadi sesi foto produk saja."],"key":"C","why":"Sumber lokal dipakai untuk menghubungkan cara pengukuran setempat dengan satuan baku, dengan tetap memeriksa makna dan ketepatan hasilnya.","explanations":["Pencatatan menghargai sumber lokal, tetapi belum menghubungkan dan membandingkan sistem pengukurannya.","Kesetaraan perlu diperiksa, bukan diasumsikan.","Perbandingan menghubungkan sumber lokal dan tujuan pengukuran.","Dokumentasi produk tidak mencapai tujuan pengukuran."]},{"id":60,"uid":"p2-060","package":2,"section":"PU","code":"P.6","type":"MCMA","difficulty":"menantang","cp_element":null,"case_focus":"moderasi penilaian","stem":"Dua guru memberi nilai sangat berbeda pada jawaban esai yang sama. Mereka ingin memperbaiki konsistensi penilaian. Pilih langkah yang tepat.","options":["Membandingkan alasan pemberian skor pada beberapa jawaban contoh.","Merata-ratakan skor lalu menganggap perbedaan penafsiran selesai.","Menyepakati contoh bukti tiap tingkat rubrik lalu mencoba menilai ulang.","Menghapus semua kriteria alasan agar skor cepat diberikan."],"key":["A","C"],"why":"Moderasi penilaian memerlukan pemeriksaan bukti dan kriteria. Kesepakatan angka saja belum menyamakan makna tingkat capaian.","explanations":["Perbandingan mengungkap perbedaan penerapan kriteria.","Rata-rata tidak menyelesaikan sumber ketidakkonsistenan.","Contoh acuan membantu menyamakan penerapan kriteria.","Penghapusan alasan dapat menghilangkan sasaran kemampuan yang dinilai."]},{"id":61,"uid":"p2-061","package":2,"section":"PU","code":"P.6","type":"PG","difficulty":"menantang","cp_element":null,"case_focus":"bias soal","stem":"Hampir semua murid salah pada soal yang memakai konteks olahraga asing, padahal jawaban pada konteks sehari-hari menunjukkan konsep yang sama dikuasai. Tindak lanjut penilaian paling tepat adalah ...","options":["Menguji soal setara dengan konteks yang lebih dikenal.","Memberikan latihan tambahan dengan istilah olahraga yang sama sebelum menelaah soalnya.","Menghapus semua soal berkonteks dari asesmen berikutnya.","Menambah istilah olahraga agar konteks lebih rinci."],"key":"A","why":"Guru perlu memeriksa apakah soal mengukur konsep atau pengalaman dengan konteks. Keputusan diambil setelah membandingkan bukti yang setara.","explanations":["Perbandingan membantu memisahkan pemahaman konsep dari hambatan konteks.","Latihan bisa memperkenalkan konteks, tetapi belum memeriksa apakah asesmen semula mengukur pengalaman konteks alih-alih konsep.","Penghapusan menyeluruh tidak didukung satu temuan.","Rincian tambahan dapat menambah hambatan yang tidak ditargetkan."]},{"id":62,"uid":"p2-062","package":2,"section":"PU","code":"K.1","type":"Kategori","difficulty":"dasar","cp_element":null,"case_focus":"ketidakpastian guru","stem":"Guru menyadari penjelasannya tentang suatu fakta belum didukung sumber yang cukup. Murid meminta kepastian untuk tugas. Nilai respons berikut sebagai Tepat atau Tidak tepat.","options":["Mempertahankan klaim karena guru harus selalu tampak yakin.","Menyatakan bagian yang belum pasti dan menjadwalkan pemeriksaan sumber.","Kembali menjelaskan hasil pemeriksaan beserta koreksi bila diperlukan."],"key":["F","T","T"],"why":"Keteladanan mencakup kejujuran intelektual dan pemenuhan janji memeriksa, bukan sekadar mengakui belum tahu lalu membiarkannya.","explanations":["Wibawa tidak membenarkan kepastian yang belum didukung.","Kejujuran tentang batas pengetahuan memberi teladan tanggung jawab.","Tindak lanjut menunjukkan tanggung jawab atas informasi yang diberikan."]},{"id":63,"uid":"p2-063","package":2,"section":"PU","code":"K.1","type":"PG","difficulty":"dasar","cp_element":null,"case_focus":"keberagaman ibadah","stem":"Jadwal presentasi bertepatan dengan kegiatan keagamaan beberapa murid. Tujuan dan waktu pembelajaran masih dapat dipenuhi melalui dua jadwal setara. Keputusan guru yang paling etis adalah ...","options":["Mengurangi skor murid yang memilih kegiatan keagamaannya.","Membatalkan presentasi untuk seluruh kelas secara permanen.","Meminta murid membuktikan bahwa keyakinannya lebih penting dari tugas.","Menawarkan dua jadwal setara dengan kriteria yang sama."],"key":"D","why":"Keadilan memberi kesempatan setara untuk mencapai tujuan. Penyesuaian jadwal bukan pemberian nilai tanpa bukti.","explanations":["Pengurangan itu tidak didasarkan pada bukti capaian presentasi.","Pembatalan menghilangkan kesempatan menunjukkan capaian meski alternatif tersedia.","Perbandingan itu tidak diperlukan untuk pengaturan belajar yang adil.","Penyesuaian menghormati keberagaman sambil menjaga standar capaian."]},{"id":64,"uid":"p2-064","package":2,"section":"PU","code":"K.2","type":"MCMA","difficulty":"sedang","cp_element":null,"case_focus":"catatan waktu tunggu","stem":"Guru menduga ia terlalu cepat menjawab pertanyaannya sendiri sehingga murid jarang berpikir mandiri. Pilih langkah refleksi yang memberi bukti berguna.","options":["Mencatat selang waktu antara pertanyaan dan respons guru pada beberapa pelajaran.","Mencoba waktu tunggu lebih panjang dan mengamati variasi alasan murid.","Memakai jumlah slide sebagai ukuran utama refleksi.","Meminta rekan mengamati pola pertanyaan dan tindak lanjutnya."],"key":["A","B","D"],"why":"Refleksi diarahkan pada perilaku yang dapat diamati dan diubah. Bukti alasan murid lebih informatif daripada kesan bahwa kelas terlihat aktif.","explanations":["Catatan waktu menguji dugaan perilaku guru sendiri.","Percobaan menautkan perubahan praktik dengan bukti partisipasi berpikir.","Jumlah slide tidak memeriksa perilaku menunggu jawaban.","Observasi rekan dapat melengkapi catatan yang rentan bias diri."]},{"id":65,"uid":"p2-065","package":2,"section":"PU","code":"K.2","type":"PG","difficulty":"dasar","cp_element":null,"case_focus":"belajar konten baru","stem":"Guru harus mengajar topik baru yang belum dikuasainya. Tersedia waktu persiapan dan rekan yang ahli. Langkah pengembangan diri terbaik adalah ...","options":["Mengumpulkan beberapa presentasi siap pakai lalu memilih yang paling menarik.","Mempelajari konsep inti, menguji pemahamannya bersama rekan, lalu menyiapkan contoh.","Menyalin seluruh presentasi rekan sebagai pengganti memahami isi.","Membatasi seluruh kegiatan pada membaca buku oleh murid."],"key":"B","why":"Belajar berkelanjutan memerlukan usaha memperbaiki penguasaan dan menggunakan dukungan profesional, bukan hanya memperoleh bahan siap tayang.","explanations":["Bahan menarik belum memastikan guru menguasai konsep atau mampu menjawab pertanyaan murid.","Persiapan dan pemeriksaan pemahaman menanggapi kebutuhan kompetensi.","Salinan bahan belum membuktikan guru mampu menjelaskan konsep.","Pengalihan kegiatan tidak menyelesaikan kebutuhan belajar guru."]},{"id":66,"uid":"p2-066","package":2,"section":"PU","code":"K.3","type":"Kategori","difficulty":"sedang","cp_element":null,"case_focus":"budaya meminta bantuan","stem":"Kelas menyepakati bahwa meminta bantuan harus disertai penjelasan usaha yang sudah dicoba. Guru ingin kebiasaan ini mendukung kemandirian. Nilai penerapannya sebagai Tepat atau Tidak tepat.","options":["Guru memodelkan cara menyampaikan kebuntuan dan usaha yang telah dilakukan.","Guru menolak semua permintaan bantuan agar murid terbiasa mandiri.","Guru meninjau apakah syarat meminta bantuan dapat dipahami dan dipakai murid."],"key":["T","F","T"],"why":"Kemandirian mencakup kemampuan mengenali kebutuhan bantuan dan menggunakannya. Konsistensi aturan tetap perlu disertai pemantauan dampak pada murid.","explanations":["Pemodelan memperjelas perilaku meminta bantuan yang diharapkan.","Penolakan menyeluruh menghambat dukungan saat usaha murid belum cukup.","Peninjauan menjaga kebiasaan tetap mendukung perkembangan, bukan sekadar aturan."]},{"id":67,"uid":"p2-067","package":2,"section":"PU","code":"K.3","type":"PG","difficulty":"sedang","cp_element":null,"case_focus":"kebiasaan membaca","stem":"Program membaca kelas awalnya dinilai dari jumlah halaman. Murid lalu memilih buku sangat mudah untuk mengejar angka. Guru ingin membangun budaya membaca yang berkembang. Keputusan terbaik adalah ...","options":["Menaikkan target halaman sambil memperbarui daftar hadiah mingguan.","Membatasi semua murid pada satu buku dengan tingkat kesulitan sama.","Meninjau pemahaman dan pilihan bacaan secara berkala.","Menghapus seluruh kesempatan memilih buku."],"key":"C","why":"Keputusan konsisten perlu mendorong tujuan budaya belajar, bukan perilaku mengejar ukuran pengganti yang mudah dimanipulasi.","explanations":["Ukuran dan hadiah tetap mendorong pengejaran jumlah, bukan pilihan tantangan serta pemahaman.","Keseragaman belum menanggapi kesiapan dan perkembangan yang berbeda.","Bukti proses dan pemahaman mengarahkan kebiasaan pada pertumbuhan.","Penghilangan pilihan belum membangun kemampuan memilih tantangan sesuai kebutuhan."]},{"id":68,"uid":"p2-068","package":2,"section":"PU","code":"S.1","type":"MCMA","difficulty":"dasar","cp_element":null,"case_focus":"komunikasi instruksi","stem":"Instruksi guru berbunyi “bahas bagian penting”, tetapi tiap kelompok mengerjakan hal berbeda. Guru ingin memperbaiki komunikasi tugas. Pilih tindakan yang tepat.","options":["Menjelaskan produk yang diminta dan memberi satu contoh batas cakupannya.","Mengulang kalimat yang sama dengan suara lebih keras.","Meminta wakil kelompok menyampaikan kembali rencana pengerjaan.","Menganggap perbedaan hasil pasti berarti murid enggan mendengar."],"key":["A","C"],"why":"Komunikasi efektif memerlukan kejelasan dan pemeriksaan pemaknaan. Pengulangan bunyi saja tidak memperbaiki instruksi yang terlalu umum.","explanations":["Produk dan batas membantu murid menafsirkan maksud instruksi.","Volume tidak menambah kejelasan maksud tugas.","Penyampaian kembali memberi bukti apakah instruksi ditafsirkan sama.","Kesimpulan itu mengabaikan kemungkinan instruksi ambigu."]},{"id":69,"uid":"p2-069","package":2,"section":"PU","code":"S.1","type":"PG","difficulty":"dasar","cp_element":null,"case_focus":"rapat dengan keluarga","stem":"Dalam rapat, keluarga menafsirkan istilah “belum berkembang” sebagai label tetap untuk anak. Guru bermaksud menjelaskan capaian sementara. Respons paling tepat adalah ...","options":["Menjelaskan capaian sementara dengan bukti dan contoh.","Mengulang istilah administrasi hingga keluarga menghafalnya.","Memberi daftar istilah penilaian lengkap untuk dibaca keluarga di rumah.","Menganggap keluarga menolak semua bentuk penilaian."],"key":"A","why":"Guru perlu menyesuaikan bahasa kepada penerima dan memeriksa pemahaman, sambil tetap menyampaikan informasi capaian secara akurat.","explanations":["Bukti dan contoh memperjelas makna sementara istilah penilaian.","Hafalan istilah belum menyamakan pemaknaan.","Daftar dapat menjadi pendamping, tetapi belum menjernihkan pemaknaan capaian anak dalam percakapan yang sedang berlangsung.","Kesalahpahaman istilah tidak membuktikan penolakan penilaian."]},{"id":70,"uid":"p2-070","package":2,"section":"PU","code":"S.2","type":"Kategori","difficulty":"sedang","cp_element":null,"case_focus":"koordinasi proyek lintas mapel","stem":"Proyek lintas mata pelajaran memberi tiga tenggat besar pada minggu yang sama. Murid kesulitan membagi waktu. Nilai keputusan kolaboratif berikut sebagai Tepat atau Tidak tepat.","options":["Guru memetakan beban dan ketergantungan tugas bersama sebelum menyepakati tenggat.","Tim menyepakati bukti bersama yang dapat memenuhi tujuan beberapa mata pelajaran.","Setiap guru menganggap koordinasi selesai setelah mengirim jadwalnya sendiri."],"key":["T","T","F"],"why":"Kolaborasi membutuhkan penyesuaian bersama berdasarkan tujuan dan beban, bukan sekadar saling memberi informasi jadwal.","explanations":["Pemetaan memberi dasar koordinasi yang terkait pengalaman murid.","Bukti terintegrasi dapat mengurangi pengulangan bila tujuan tetap terpenuhi.","Pengiriman jadwal belum berarti konflik beban telah diselesaikan."]},{"id":71,"uid":"p2-071","package":2,"section":"PU","code":"S.2","type":"PG","difficulty":"dasar","cp_element":null,"case_focus":"mitra museum","stem":"Museum daerah menawarkan kunjungan, tetapi kegiatan bakunya hanya tur bebas. Guru ingin murid membandingkan sumber sejarah. Langkah kerja sama terbaik adalah ...","options":["Menerima tur baku lalu meminta murid menulis semua benda yang dilihat.","Meminta museum memberikan jawaban seluruh tugas murid.","Mengganti tujuan menjadi hafalan nama petugas museum.","Menyepakati sumber, pertanyaan pembanding, dan peran pemandu."],"key":"D","why":"Kemitraan memberi akses pada sumber dan keahlian yang mendukung tujuan. Kegiatan perlu dirancang bersama agar kunjungan tidak sekadar perpindahan tempat.","explanations":["Daftar benda memberi dokumentasi kunjungan, tetapi belum menuntun perbandingan sumber sejarah.","Jawaban jadi menghilangkan kesempatan menalar sumber.","Tujuan berubah dan tidak memanfaatkan potensi sumber sejarah.","Kesepakatan mengaitkan keahlian mitra dengan tujuan pembelajaran."]},{"id":72,"uid":"p2-072","package":2,"section":"PU","code":"S.3","type":"MCMA","difficulty":"dasar","cp_element":null,"case_focus":"kontribusi komunitas","stem":"Komunitas guru hendak menyusun bank contoh pertanyaan terbuka. Anggota memiliki pengalaman berbeda. Pilih kontribusi yang mendukung pengembangan profesi bersama.","options":["Mengirim daftar soal sebanyak mungkin tanpa menjelaskan tujuan penggunaannya.","Menyertakan tujuan, contoh respons murid, dan alasan pertanyaan perlu diperbaiki.","Menelaah contoh rekan dengan kriteria yang disepakati dan memberi masukan spesifik.","Mengakhiri kegiatan setelah berkas terkumpul meski belum pernah ditelaah."],"key":["B","C"],"why":"Partisipasi profesional mencakup kontribusi yang dapat ditelaah dan kesediaan memperbaiki bersama, bukan hanya menyumbang jumlah soal.","explanations":["Jumlah besar belum membantu rekan memilih pertanyaan yang sesuai.","Konteks penggunaan membuat contoh dapat ditelaah rekan.","Telaah terarah membangun pengetahuan bersama.","Kumpulan berkas saja belum menunjukkan proses belajar komunitas."]},{"id":73,"uid":"p2-073","package":2,"section":"PU","code":"PF.1","type":"PG","difficulty":"dasar","cp_element":null,"case_focus":"tujuan pendidikan dasar","stem":"Sekolah dasar menilai proyek kebun kelas. Guru ingin hasilnya sesuai tujuan pendidikan dasar, termasuk kebiasaan bernalar dan bertanggung jawab. Bukti paling kuat adalah ...","options":["Jumlah tanaman yang dibawa keluarga ke sekolah.","Catatan pengamatan murid, alasan keputusan perawatan, dan pelaksanaan tanggung jawabnya.","Menggunakan kerapian catatan sebagai pengganti penilaian alasan perawatan.","Harga alat kebun yang digunakan setiap kelompok."],"key":"B","why":"Tujuan pendidikan dasar perlu diterjemahkan menjadi bukti perkembangan murid, bukan kualitas sumber daya keluarga atau keseragaman produk.","explanations":["Jumlah sumbangan tidak mewakili hasil belajar murid.","Bukti mencakup penalaran dasar dan perilaku bertanggung jawab.","Kerapian membantu komunikasi, tetapi bukan bukti penalaran dan pelaksanaan tanggung jawab.","Harga alat mencerminkan sumber daya, bukan capaian belajar."]},{"id":74,"uid":"p2-074","package":2,"section":"PU","code":"PF.3","type":"Kategori","difficulty":"menantang","cp_element":null,"case_focus":"prasyarat interpretasi grafik","stem":"Sebelum tugas interpretasi grafik, guru menemukan murid mampu membaca angka tetapi menyamakan tinggi batang dengan besar perubahan. Nilai pemetaan kebutuhan berikut sebagai Tepat atau Tidak tepat.","options":["Guru menyimpulkan seluruh materi aritmetika harus diulang dari awal.","Guru memeriksa pemahaman nilai awal dan selisih melalui dua grafik sederhana.","Guru menyiapkan contoh yang membedakan nilai akhir besar dan kenaikan besar."],"key":["F","T","T"],"why":"Kebutuhan belajar ditentukan dari hubungan kemampuan awal dan tuntutan interpretasi. Mengulang seluruh hitungan belum tentu menanggapi miskonsepsi grafik.","explanations":["Bukti menunjukkan masalah interpretasi, bukan seluruh kemampuan hitung.","Pemeriksaan menargetkan prasyarat perubahan yang diperlukan.","Contoh menanggapi karakteristik materi serta kebutuhan yang ditemukan."]},{"id":75,"uid":"p2-075","package":2,"section":"PU","code":"PF.4","type":"PG","difficulty":"sedang","cp_element":null,"case_focus":"adaptasi urutan kurikulum","stem":"Sekolah mengubah urutan unit karena kegiatan lapangan musiman hanya dapat dilakukan bulan ini. Guru ingin adaptasi tetap menjaga perkembangan kompetensi. Langkah paling tepat adalah ...","options":["Memindahkan tanggal kegiatan lapangan saja sementara urutan dan asesmen tetap.","Mengikuti kesempatan lapangan dengan menghapus tujuan yang sulit dicapai.","Memetakan prasyarat sebelum menyesuaikan urutan dan asesmen.","Menjalankan jadwal lama meskipun sumber lapangan tidak tersedia lagi."],"key":"C","why":"Kurikulum adaptif bukan sekadar memindahkan kegiatan. Prasyarat, tujuan, pengalaman, dan asesmen perlu tetap saling mendukung.","explanations":["Perubahan tanggal belum memeriksa apakah murid sudah memiliki prasyarat untuk kegiatan yang dimajukan.","Penghapusan tujuan tidak dibenarkan hanya oleh perubahan jadwal.","Adaptasi mempertimbangkan kesempatan lokal dan kesinambungan kompetensi.","Kekakuan jadwal mengabaikan kesempatan kontekstual yang dapat direncanakan."]},{"id":76,"uid":"p2-076","package":2,"section":"PU","code":"PF.5","type":"MCMA","difficulty":"menantang","cp_element":null,"case_focus":"uji praktik pembelajaran","stem":"Guru mencoba diskusi berpasangan sebelum jawaban kelas untuk memperbaiki alasan berbasis bukti. Hasil awal tampak lebih baik, tetapi tugas kedua lebih mudah. Pilih langkah pengembangan praktik yang tepat.","options":["Mencatat perbedaan kesulitan tugas sebagai keterbatasan penafsiran.","Menyimpulkan metode pasti efektif untuk semua materi.","Menghitung hanya jumlah murid yang menyukai diskusi sebagai bukti pemahaman.","Menguji kembali dengan tugas sebanding dan kriteria alasan yang sama."],"key":["A","D"],"why":"Pengembangan praktik memerlukan pemeriksaan penjelasan alternatif. Temuan awal layak ditindaklanjuti, bukan langsung dijadikan kesimpulan sebab-akibat.","explanations":["Kesulitan tugas merupakan penjelasan alternatif hasil.","Bukti terbatas tidak mendukung generalisasi universal.","Kesukaan tidak identik dengan kualitas alasan berbasis bukti.","Perbandingan lebih setara membantu menilai dugaan perbaikan."]},{"id":77,"uid":"p2-077","package":2,"section":"PU","code":"P.6","type":"PG","difficulty":"dasar","cp_element":null,"case_focus":"asesmen teman sebaya","stem":"Dalam penilaian teman sebaya, murid memberi skor tinggi kepada teman dekat meski alasan jawaban lemah. Guru ingin memperbaiki fungsi asesmen. Tindak lanjut terbaik adalah ...","options":["Melatih penilaian jawaban anonim dengan alasan berbasis rubrik.","Memakai seluruh skor teman langsung sebagai nilai akhir.","Meminta penilai menambahkan komentar pujian pada setiap skor tinggi.","Menambah banyak penilai tanpa membahas dasar skornya."],"key":"A","why":"Penilaian teman sebaya perlu dukungan agar umpan balik dan skor mengacu pada bukti. Guru tetap bertanggung jawab memeriksa kualitas penilaian.","explanations":["Latihan memusatkan penilaian pada bukti, bukan kedekatan.","Skor yang belum dapat dipercaya tidak layak langsung menentukan hasil akhir.","Pujian tidak menjamin skor dan komentar mengacu pada kualitas bukti serta alasan.","Jumlah penilai tidak otomatis memperbaiki bias kriteria."]},{"id":78,"uid":"p2-078","package":2,"section":"PU","code":"P.1","type":"Kategori","difficulty":"sedang","cp_element":null,"case_focus":"generalisasi contoh","stem":"Murid menyimpulkan semua benda berat pasti tenggelam setelah mengamati sebuah batu. Guru ingin memperluas cara membangun penjelasan. Nilai kegiatan berikut sebagai Tepat atau Tidak tepat.","options":["Membandingkan benda dengan massa dan volume berbeda lalu meminta revisi dugaan.","Menambah sepuluh batu sejenis sebagai satu-satunya bukti simpulan umum.","Mengganti dugaan murid dengan kalimat hafalan tanpa pengamatan pembanding."],"key":["T","F","F"],"why":"Murid perlu memeriksa batas generalisasi melalui contoh pembanding. Fokusnya cara menilai bukti, bukan jumlah contoh yang semuanya mendukung dugaan semula.","explanations":["Variasi bukti dapat menantang generalisasi dari satu contoh.","Pengulangan contoh serupa tidak menguji batas dugaan.","Penggantian jawaban tidak memperlihatkan alasan perubahan konsep."]},{"id":79,"uid":"p2-079","package":2,"section":"PU","code":"S.3","type":"PG","difficulty":"dasar","cp_element":null,"case_focus":"pemanfaatan komunitas","stem":"Seusai pelatihan komunitas, guru mencoba satu teknik bertanya dan menemukan beberapa kondisi yang tidak cocok. Tindak lanjut ke komunitas paling bermanfaat adalah ...","options":["Menyimpan hasil karena hanya keberhasilan yang layak dibagikan.","Menganjurkan anggota berhenti memakai teknik itu di semua kelas.","Membagikan bahan pelatihan yang sama lagi sebagai satu-satunya tindak lanjut.","Membahas kondisi uji, respons murid, dan batas penerapan."],"key":"D","why":"Partisipasi berkelanjutan membawa pengalaman penerapan kembali ke komunitas. Batas keberhasilan sama pentingnya dengan cerita keberhasilan untuk pengembangan profesi.","explanations":["Temuan ketidakcocokan juga dapat menjadi sumber belajar bersama.","Satu pengalaman tidak mendukung penolakan di seluruh konteks.","Bahan awal belum membawa pengalaman ketidakcocokan ke pembahasan profesional bersama.","Bukti berkonteks membantu komunitas menyempurnakan pemahaman praktik."]},{"id":80,"uid":"p2-080","package":2,"section":"PU","code":"PF.4","type":"MCMA","difficulty":"menantang","cp_element":null,"case_focus":"integrasi kurikulum","stem":"Tim kurikulum ingin menggabungkan dua tugas yang sama-sama meminta laporan pengamatan. Tujuan tiap mata pelajaran sebagian berbeda. Pilih keputusan yang menjaga keselarasan kurikulum.","options":["Memetakan bukti yang dapat dipakai bersama dan bukti yang tetap perlu dibedakan.","Memberikan satu nilai identik untuk semua tujuan karena produknya satu.","Menyusun kriteria sesuai tujuan masing-masing meski artefaknya sama.","Menjelaskan kepada murid bagian laporan yang memenuhi tiap tujuan."],"key":["A","C","D"],"why":"Integrasi dapat mengurangi pengulangan kerja, tetapi tidak menyamakan seluruh konstruk penilaian. Tujuan dan bukti tetap perlu ditelusuri.","explanations":["Pemetaan menjaga agar penggabungan tidak menghilangkan tujuan khusus.","Produk tunggal dapat menunjukkan capaian berbeda pada tujuan berbeda.","Kriteria menjaga penafsiran capaian setiap mata pelajaran.","Kejelasan hubungan tugas dan tujuan membantu pengerjaan serta refleksi."]}]},{"id":3,"title":"Paket 3","version":"2026-11-18.1","file":"paket_3.json","reviewFile":"references/Paket_3_dan_Pembahasan.md","questions":[{"package":3,"id":1,"uid":"p3-001","section":"PCK","code":"PF.4","type":"PG","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"UbD; keselarasan bukti","case_focus":"normalisasi dan bukti transfer","stem":"Guru menyusun unit basis data. Targetnya murid dapat memperbaiki rancangan yang menyebabkan perubahan alamat cabang harus dilakukan di banyak baris. Bukti akhir yang paling selaras adalah ...","options":["Menjelaskan definisi normalisasi dari modul.","Merevisi rancangan, menguji perubahan alamat pada kasus baru, dan menjelaskan mengapa pembaruan tidak lagi berulang.","Meminta diagram rancangan yang sama persis dengan contoh latihan.","Menghitung jumlah tabel dalam rancangan akhir."],"key":"B","why":"Dalam perancangan mundur, bukti harus menunjukkan kemampuan yang ditargetkan. Perubahan alamat pada kasus baru menguji alasan rancangan, bukan kemiripan dengan contoh.","explanations":["Definisi belum membuktikan keputusan perbaikan pada kasus.","Uji baru memperlihatkan apakah anomali pembaruan teratasi.","Kesamaan contoh belum menguji apakah murid memahami alasan perbaikan pada kasus baru.","Jumlah tabel saja tidak menjamin rancangan mengatasi masalah."]},{"package":3,"id":2,"uid":"p3-002","section":"PCK","code":"P.1","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Discovery dengan bukti pembanding","case_focus":"short circuit","stem":"Murid menulis kondisi A dan B, dengan B memanggil fungsi pencatat. Pada bahasa yang memakai short circuit, fungsi tidak dipanggil ketika A salah. Nilai kegiatan berikut sebagai Tepat atau Tidak tepat.","options":["Mengajarkan bahwa setiap operand selalu dievaluasi agar penelusuran seragam.","Membandingkan log saat A benar dan salah.","Meminta murid menjelaskan risiko efek samping pada operand kedua."],"key":["F","T","T"],"why":"Murid perlu membedakan hasil logika dan evaluasi ekspresi. Log pemanggilan menjadi bukti pembentukan konsep.","explanations":["Aturan itu bertentangan dengan short circuit yang dinyatakan.","Perbandingan menunjukkan kapan operand kedua dievaluasi.","Efek samping dapat tidak terjadi sehingga perlu dipertimbangkan."]},{"package":3,"id":3,"uid":"p3-003","section":"PCK","code":"P.6","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Web","ppg_concept":"Asesmen kinerja berbasis ancaman","case_focus":"otorisasi object","stem":"Pada web tugas kelas, akun A dapat membaca berkas akun B setelah ID pada URL diganti. Murid berpendapat menyembunyikan tombol sudah cukup. Bukti perbaikan paling kuat adalah ...","options":["Tombol berkas B hilang dari tampilan akun A.","URL berkas diberi ID yang lebih panjang.","Menguji hanya alur akses berkas milik akun yang sedang login.","Menguji penolakan request akun A ke berkas B di server."],"key":"D","why":"Asesmen harus menguji batas hak akses di server. Menyembunyikan kontrol hanya mengubah antarmuka.","explanations":["Tampilan belum menguji permintaan langsung ke sumber.","ID sulit ditebak tidak menggantikan pemeriksaan hak akses.","Akses sah perlu berjalan, tetapi belum membuktikan akses ke berkas orang lain ditolak.","Uji itu langsung memeriksa otorisasi sumber yang bermasalah."]},{"package":3,"id":4,"uid":"p3-004","section":"PCK","code":"PF.1","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Tujuan kejuruan dan etika kerja","case_focus":"penyimpanan rahasia mobile","stem":"Dalam proyek mobile SMK, murid menyimpan rahasia layanan bersama di dalam paket aplikasi agar tim penerima mudah memasangnya. Guru ingin menilai tanggung jawab profesional. Pilih semua tindakan yang tepat.","options":["Meminta murid memeriksa apakah rahasia dapat diekstrak dari paket.","Mengganti nama variabel rahasia sebagai perlindungan utama.","Menilai rancangan layanan perantara yang tidak membagikan rahasia bersama ke klien.","Menilai keamanan dari kecilnya ukuran file instalasi."],"key":["A","C"],"why":"Kesiapan kerja mencakup keputusan distribusi dan tanggung jawab atas kredensial. Rahasia bersama dalam aplikasi klien bukan terlindungi hanya karena kodenya dikompilasi.","explanations":["Pemeriksaan menguji asumsi kerahasiaan distribusi aplikasi.","Nama variabel tidak menjamin isi paket tidak dapat diperiksa.","Rancangan memindahkan kewenangan rahasia ke lingkungan yang dapat dikendalikan.","Ukuran paket tidak menunjukkan perlindungan rahasia."]},{"package":3,"id":5,"uid":"p3-005","section":"PCK","code":"PF.2","type":"PG","difficulty":"menantang","cp_element":"Basis Data","ppg_concept":"Representasi konkret konsep isolasi","case_focus":"isolasi laporan","stem":"Laporan membaca saldo dua rekening melalui dua query terpisah. Transfer terjadi di antaranya sehingga total tampak berubah. Guru ingin murid memahami konsistensi pembacaan. Demonstrasi terbaik adalah ...","options":["Memodelkan pembacaan pada satu snapshot.","Membulatkan saldo laporan agar selisih tidak terlihat.","Mengulang laporan saat aktivitas transfer dihentikan sementara.","Mengganti tipe tampilan saldo menjadi teks."],"key":"A","why":"Masalahnya bukan penjumlahan, melainkan penggabungan dua keadaan berbeda. Snapshot yang konsisten perlu diuji pada dukungan basis data yang digunakan.","explanations":["Urutan memperlihatkan campuran keadaan yang berbeda.","Pembulatan tidak menyelesaikan waktu pembacaan berbeda.","Kondisi tenang dapat menghasilkan laporan benar tetapi menyembunyikan masalah pembacaan serentak.","Format teks tidak memberi konsistensi pembacaan."]},{"package":3,"id":6,"uid":"p3-006","section":"PCK","code":"PF.3","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Diagnosis prasyarat materi","case_focus":"biaya algoritma","stem":"Sebelum membahas efisiensi algoritma, guru menemukan murid menyamakan panjang kode dengan banyaknya operasi. Nilai pemetaan kebutuhan berikut sebagai Tepat atau Tidak tepat.","options":["Meminta hitungan operasi untuk dua ukuran masukan pada contoh pendek.","Menentukan kesiapan dari jumlah bahasa pemrograman yang pernah dipakai.","Membandingkan loop tunggal dan loop bersarang dengan pencatatan operasi."],"key":["T","F","T"],"why":"Kebutuhan materi terletak pada cara menghitung pekerjaan program terhadap ukuran masukan. Kode pendek belum tentu murah.","explanations":["Perubahan ukuran membantu mengungkap model biaya murid.","Jumlah bahasa tidak menunjukkan pemahaman pertumbuhan operasi.","Perbandingan menanggapi prasyarat hubungan struktur dan biaya."]},{"package":3,"id":7,"uid":"p3-007","section":"PCK","code":"P.4","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"TPACK; literasi alat jaringan","case_focus":"CORS dan keamanan","stem":"Murid menyimpulkan API aman dari akses tak sah karena browser menolak response lintas origin. Guru memakai alat jaringan untuk menguji dugaan itu. Kegiatan terbaik adalah ...","options":["Mengganti origin sampai pesan browser hilang.","Membandingkan status HTTPS dan HTTP sebagai satu-satunya uji akses API.","Menguji CORS browser dan autentikasi server secara terpisah.","Menghapus dokumentasi origin dari tugas kelompok."],"key":"C","why":"CORS mengatur perilaku berbagi response pada browser, bukan menggantikan pemeriksaan identitas dan hak pada server.","explanations":["Hilangnya pesan belum menguji otorisasi layanan.","Keamanan transport tidak membuktikan otorisasi sumber atau menjelaskan pembatasan lintas origin.","Dua bukti membedakan CORS dari kontrol akses server.","Penghapusan informasi menghindari konsep yang sedang salah dipahami."]},{"package":3,"id":8,"uid":"p3-008","section":"PCK","code":"P.5","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Pembelajaran kontekstual","case_focus":"umur data lokasi","stem":"Aplikasi pemandu nelayan setempat menampilkan posisi terakhir walau pengukuran sudah lama. Guru memakai kebutuhan mitra untuk mengajarkan pembacaan data lokasi. Pilih semua kegiatan yang tepat.","options":["Memilih koordinat dengan angka desimal paling banyak sebagai posisi terkini.","Meminta murid menyertakan waktu pengukuran saat menilai kelayakan posisi.","Menghapus penanda waktu agar layar lebih sederhana.","Membandingkan keputusan tampilan untuk posisi lama dan baru pada skenario mitra."],"key":["B","D"],"why":"Sumber lokal memberi alasan teknis memeriksa kesegaran data, bukan sekadar menambahkan tema nelayan pada tugas.","explanations":["Ketelitian penulisan bukan bukti waktu pengukuran.","Umur data penting untuk kebutuhan pengguna yang bergerak.","Penyederhanaan menghilangkan informasi yang relevan.","Skenario menautkan umur data dengan tindakan aplikasi."]},{"package":3,"id":9,"uid":"p3-009","section":"PCK","code":"P.1","type":"PG","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"Pemahaman konseptual dan representasi","case_focus":"zona waktu","stem":"Dua log dari zona waktu berbeda tampak menunjukkan balasan terjadi sebelum permintaan. Murid ingin mengurutkannya sebagai teks waktu lokal. Langkah guru terbaik adalah ...","options":["Mengurutkan berdasarkan nama perangkat pengirim.","Menyamakan acuan waktu log.","Menyeragamkan format penulisan waktu sambil mengabaikan offset zona.","Memilih log yang tampil paling rinci sebagai urutan benar."],"key":"B","why":"Waktu lokal tidak dapat langsung dibandingkan lintas zona. Murid perlu memeriksa offset dan acuan sebelum menarik simpulan urutan.","explanations":["Nama tidak menjelaskan urutan peristiwa.","Acuan bersama memungkinkan pembandingan waktu yang bermakna.","Format seragam belum membuat nilai lokal merujuk pada acuan yang sama.","Kerincian format tidak memastikan acuan waktu sama."]},{"package":3,"id":10,"uid":"p3-010","section":"PCK","code":"P.2","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"UDL; representasi jamak","case_focus":"dukungan GUI sejak rancangan","stem":"Guru merancang unit GUI tentang status proses. Sejak awal ia ingin status dapat dipahami murid yang sulit membedakan warna, dengan sasaran interpretasi status yang sama. Nilai rancangan berikut sebagai Tepat atau Tidak tepat.","options":["Memadukan warna, label teks, dan simbol yang dijelaskan.","Menguji apakah status masih dipahami ketika warna tidak ditampilkan.","Mengganti sasaran murid tersebut menjadi menghafal nama warna."],"key":["T","T","F"],"why":"Rancangan inklusif menyediakan beberapa representasi sejak awal sambil mempertahankan konstruk belajar.","explanations":["Beberapa petunjuk membantu akses terhadap makna status.","Uji memeriksa ketergantungan informasi pada warna.","Penggantian sasaran tidak menilai interpretasi status proses."]},{"package":3,"id":11,"uid":"p3-011","section":"PCK","code":"P.6","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Web","ppg_concept":"Umpan balik dan uji tandingan","case_focus":"pengiriman ganda","stem":"Web pendaftaran membuat dua entri ketika pengguna menekan kirim dua kali. Murid menonaktifkan tombol, lalu menyatakan masalah selesai. Umpan balik paling tepat adalah ...","options":["Perbesar tombol agar pengguna melihatnya dengan jelas.","Menambahkan konfirmasi di browser sebelum request dikirim.","Menguji satu kali klik pada koneksi cepat lalu mencatat respons sukses.","Menguji request ulang dan menjelaskan aturan servernya."],"key":"D","why":"Umpan balik mengarah pada jaminan pemrosesan di server, misalnya identitas operasi yang diproses sekali, bukan sekadar mengubah tampilan tombol.","explanations":["Keterlihatan tidak menjamin satu pemrosesan.","Konfirmasi dapat mengurangi klik tidak sengaja, tetapi belum menjamin server menangani request berulang secara tepat.","Uji alur normal belum memunculkan pengiriman ulang yang menjadi sumber masalah.","Uji melampaui penguncian tombol untuk memeriksa pemrosesan berulang."]},{"package":3,"id":12,"uid":"p3-012","section":"PCK","code":"PF.4","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"UbD","case_focus":"upgrade skema lokal","stem":"Guru merancang unit upgrade aplikasi mobile yang menambah kolom lokal tetapi harus mempertahankan data versi lama. Pilih semua bukti dan kegiatan yang selaras.","options":["Menetapkan keberhasilan dari data lama yang tetap terbaca setelah migrasi.","Menguji instalasi bersih saja sebagai bukti upgrade.","Menyiapkan basis data versi lama berisi contoh untuk uji migrasi.","Meminta murid menjelaskan aturan nilai awal untuk kolom baru."],"key":["A","C","D"],"why":"Perancangan mundur membedakan instalasi baru dan upgrade. Aktivitas harus menghadirkan kondisi awal yang hendak dipertahankan.","explanations":["Bukti sesuai tujuan mempertahankan data.","Instalasi bersih belum memeriksa perpindahan data lama.","Kondisi awal memungkinkan pengujian tujuan sebenarnya.","Aturan diperlukan agar data lama memiliki makna setelah skema berubah."]},{"package":3,"id":13,"uid":"p3-013","section":"PCK","code":"P.2","type":"PG","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"ZPD; fading scaffolding","case_focus":"bantuan DELETE aman","stem":"Murid mampu menjelaskan kondisi DELETE ketika didampingi, tetapi ragu memilih baris secara mandiri. Guru hendak mengurangi bantuan secara bertahap. Langkah berikut paling tepat adalah ...","options":["Memberi kondisi baru untuk dipilih murid, meminta prediksi baris, lalu menguji keputusan pada data latihan yang aman.","Mempertahankan seluruh petunjuk langkah demi langkah pada setiap kasus baru.","Langsung memberi akses penghapusan data produksi mitra.","Mengganti unit dengan hafalan nama perintah administrasi."],"key":"A","why":"Scaffolding dikurangi berdasarkan bukti kesiapan. Prediksi dan data uji memberi ruang keputusan murid sebelum pengaman dilepas.","explanations":["Tugas mempertahankan tantangan sambil memberi pengaman yang dapat dikurangi.","Petunjuk tetap dapat membantu penyelesaian, tetapi belum menguji kemandirian yang mulai ditargetkan.","Risiko data nyata tidak diperlukan untuk mengukur kesiapan.","Penggantian tidak mengembangkan keputusan yang sudah mulai dikuasai."]},{"package":3,"id":14,"uid":"p3-014","section":"PCK","code":"P.1","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Discovery melalui variasi kebutuhan","case_focus":"komposisi object","stem":"Murid membuat subclass untuk setiap kombinasi alat pembayaran dan jenis diskon. Guru ingin mereka menilai kapan komposisi lebih sesuai. Nilai kegiatan berikut sebagai Tepat atau Tidak tepat.","options":["Menganggap jumlah subclass besar selalu membuktikan desain lengkap.","Menguji perubahan satu kebijakan diskon tanpa mengganti alat pembayaran.","Membandingkan delegasi ke object kebijakan dengan penambahan subclass."],"key":["F","T","T"],"why":"Pemilihan desain dinilai melalui variasi kebutuhan, bukan menghafal bahwa pewarisan atau komposisi selalu lebih baik.","explanations":["Banyak subclass dapat menunjukkan kombinasi tanggung jawab yang sulit diubah.","Perubahan independen memperlihatkan kebutuhan memisahkan tanggung jawab.","Perbandingan menilai konsekuensi desain terhadap kebutuhan perubahan."]},{"package":3,"id":15,"uid":"p3-015","section":"PCK","code":"PF.5","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"Pengembangan praktik berbasis bukti","case_focus":"gambar web dan kinerja","stem":"Guru mencoba demonstrasi pengukuran waktu muat gambar agar murid menyeimbangkan mutu visual dan kinerja web. Bukti dampak pembelajaran paling kuat adalah ...","options":["Membandingkan ukuran file akhir sebagai satu-satunya ukuran pemahaman.","Meminta murid memberi peringkat kualitas visual gambar pada layar yang sama.","Menilai alasan pilihan aset baru beserta bukti waktu muat.","Kecepatan guru menyelesaikan demonstrasi."],"key":"C","why":"Perbaikan praktik dinilai dari keputusan murid pada tugas baru, bukan sekadar keberhasilan demonstrasi alat.","explanations":["Ukuran file merupakan bukti teknis parsial, bukan alasan memilih trade-off mutu dan waktu muat.","Penilaian visual memberi sebagian bukti mutu, tetapi belum menunjukkan keputusan trade-off dengan waktu muat.","Bukti menghubungkan pengukuran dengan keputusan yang dapat ditransfer.","Kinerja guru belum menunjukkan perubahan pemahaman murid."]},{"package":3,"id":16,"uid":"p3-016","section":"PCK","code":"P.6","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Bukti asesmen berlapis","case_focus":"pengujian sensor","stem":"Murid menguji aplikasi penghitung langkah dengan menggoyangkan ponsel. Guru ingin membedakan pemahaman aturan pengolahan data dari keberhasilan sensor nyata. Pilih semua bukti yang relevan.","options":["Uji aturan hitung dengan urutan data sensor buatan yang diketahui.","Uji perangkat nyata dengan prosedur gerak dan pembanding yang dijelaskan.","Jumlah sensor yang tercantum pada spesifikasi ponsel.","Kemiripan ikon aplikasi dengan penghitung langkah komersial."],"key":["A","B"],"why":"Uji logika dan uji integrasi menjawab pertanyaan berbeda. Keduanya perlu dibedakan agar keberhasilan satu tidak dianggap membuktikan lainnya.","explanations":["Masukan terkendali membantu memeriksa logika pengolahan.","Pengujian ini memeriksa perilaku integrasi sensor.","Daftar sensor bukan bukti aturan hitung bekerja.","Ikon tidak menunjukkan ketepatan pengolahan data."]},{"package":3,"id":17,"uid":"p3-017","section":"PCK","code":"P.5","type":"PG","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"CRT; kebutuhan sumber lokal","case_focus":"kolasi dan budaya","stem":"Data nama kegiatan budaya lokal diurutkan berbeda oleh dua konfigurasi basis data. Guru ingin murid memahami kaitan aturan pembandingan dengan kebutuhan masyarakat pengguna. Langkah terbaik adalah ...","options":["Menghapus karakter yang berbeda dari ejaan pengguna.","Membahas collation dan kebutuhan urutan bersama pengguna.","Menyeragamkan urutan berdasarkan konfigurasi bawaan komputer sekolah.","Menyediakan tabel padanan ejaan lalu menganggap aturan pembandingan otomatis sama."],"key":"B","why":"Konteks budaya memengaruhi kebutuhan pembandingan teks. Murid perlu menilai pilihan teknis tanpa menganggap satu kebiasaan ejaan berlaku bagi semua pengguna.","explanations":["Penghapusan mengubah informasi budaya untuk menyesuaikan alat.","Aturan teknis ditelaah terhadap kebutuhan bahasa setempat.","Bawaan alat dapat menjadi titik awal, tetapi belum diperiksa terhadap kebutuhan bahasa pengguna setempat.","Padanan ejaan dapat membantu mengenali nama, tetapi tidak otomatis menetapkan perilaku collation sesuai kebutuhan pengguna."]},{"package":3,"id":18,"uid":"p3-018","section":"PCK","code":"P.1","type":"Kategori","difficulty":"menantang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Model mental; prediksi dan uji","case_focus":"closure pada loop","stem":"Dalam bahasa yang menangkap binding variabel loop yang sama, beberapa callback menampilkan nilai akhir loop. Guru ingin murid membedakan nilai saat pembuatan dan pemanggilan callback. Nilai kegiatan berikut sebagai Tepat atau Tidak tepat.","options":["Mencatat kedua waktu tersebut pada contoh dua callback.","Mengubah teks label tombol sebagai penjelasan utama.","Membandingkan binding per iterasi dengan binding bersama."],"key":["T","F","T"],"why":"Masalah bergantung pada semantik binding bahasa yang dinyatakan, bukan semua callback selalu salah. Contoh kecil menampakkan waktu pembacaan nilai.","explanations":["Dua waktu memperlihatkan kapan nilai dibaca.","Label tidak mengubah binding yang ditangkap.","Perbandingan menguji penyebab perilaku callback."]},{"package":3,"id":19,"uid":"p3-019","section":"PCK","code":"PF.3","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"Diagnosis prasyarat materi","case_focus":"state pada URL","stem":"Murid memahami state pencarian selama halaman terbuka, tetapi belum mengerti mengapa tautan yang dibagikan membuka hasil awal. Sebelum membahas navigasi web, diagnosis awal terbaik adalah ...","options":["Mengecek kemampuan mengganti warna hasil pencarian.","Menguji pencarian berulang pada tab yang sama selama sesi tetap terbuka.","Meminta daftar browser yang dipakai murid.","Memetakan state URL dan memori."],"key":"D","why":"Kebutuhan belajar terletak pada representasi keadaan yang dapat dibawa tautan. State memori tidak otomatis dikirim kepada penerima tautan.","explanations":["Styling bukan prasyarat berbagi keadaan pencarian.","Uji ini dapat mempertahankan state memori tetapi belum menunjukkan keadaan yang ikut dalam tautan.","Nama browser belum mengungkap model state.","Pembedaan menargetkan prasyarat navigasi dan berbagi tautan."]},{"package":3,"id":20,"uid":"p3-020","section":"PCK","code":"P.2","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"UDL; kesetaraan tujuan","case_focus":"label kontrol mobile","stem":"Pada layar mobile, beberapa tombol bergambar memiliki label pembaca layar yang sama. Guru ingin seluruh murid dapat menguji hubungan fungsi dan label. Pilih semua dukungan yang tepat.","options":["Menyediakan daftar fungsi kontrol dan meminta pasangan memeriksa label yang terbaca.","Meminta murid menghafal urutan posisi tombol sebagai solusi permanen.","Menggunakan uji audio label disertai catatan teks hasilnya.","Mengganti tujuan menjadi mengenali warna ikon saja."],"key":["A","C"],"why":"Dukungan menyediakan cara mengamati yang beragam, tetapi semua tetap menilai fungsi kontrol, bukan sekadar mengoperasikan alat bantu.","explanations":["Daftar fungsi menjadi acuan saat menilai makna label.","Posisi bukan pengganti identifikasi fungsi yang dapat diakses.","Dua cara pengamatan membuka akses pada tujuan pengujian yang sama.","Warna tidak mengukur kecocokan label dengan fungsi."]},{"package":3,"id":21,"uid":"p3-021","section":"PCK","code":"PF.1","type":"PG","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"Tujuan pendidikan kejuruan","case_focus":"jejak koreksi data","stem":"Dalam proyek sistem pencatatan layanan SMK, pengguna ingin mengetahui siapa mengoreksi data dan alasannya. Guru menargetkan tanggung jawab kerja, bukan sekadar hasil data terbaru. Bukti paling sesuai adalah ...","options":["Menguji jejak pelaku, waktu, dan alasan pada koreksi data lalu menjelaskan bagaimana pengguna yang berwenang menelusurinya.","Menilai dari banyaknya perubahan data yang dapat diselesaikan tim.","Kesamaan warna pada seluruh layar koreksi.","Kecilnya ukuran tabel setelah riwayat dihapus."],"key":"A","why":"Tujuan kejuruan mencakup pekerjaan yang dapat ditelusuri. Jejak harus relevan dan aksesnya dikelola, bukan mengumpulkan informasi pribadi tanpa tujuan.","explanations":["Jejak menghubungkan keterampilan dengan akuntabilitas pekerjaan.","Banyak perubahan tidak menunjukkan pelaku, waktu, dan alasan koreksi dapat ditelusuri.","Kesamaan tampilan bukan bukti jejak perubahan.","Penghapusan justru menghilangkan bukti yang diminta pengguna."]},{"package":3,"id":22,"uid":"p3-022","section":"PCK","code":"P.6","type":"Kategori","difficulty":"menantang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Asesmen penalaran pengujian","case_focus":"invarian pengujian","stem":"Murid menguji fungsi membalik urutan list hanya dengan satu contoh. Guru ingin mereka menilai sifat yang seharusnya tetap benar untuk berbagai masukan. Nilai bukti berikut sebagai Tepat atau Tidak tepat.","options":["Murid menguji bahwa membalik dua kali menghasilkan urutan awal.","Murid memeriksa panjang serta elemen list tetap terjaga.","Murid menganggap dua sifat itu sudah membuktikan semua implementasi pasti benar."],"key":["T","T","F"],"why":"Asesmen meminta penalaran tentang sifat dan keterbatasan tes. Invarian memperluas bukti, tetapi perlu dilengkapi contoh yang membedakan operasi membalik dari tidak mengubah urutan.","explanations":["Sifat itu menguji hubungan dua pemanggilan pada banyak masukan.","Invarian ini memeriksa bahwa operasi tidak membuang atau menambah elemen.","Fungsi identitas pun dapat memenuhi kedua sifat sehingga contoh hasil tetap diperlukan."]},{"package":3,"id":23,"uid":"p3-023","section":"PCK","code":"P.2","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"Diferensiasi proses; scaffolding","case_focus":"render awal dan kebutuhan","stem":"Kelas membuat situs informasi darurat. Murid dapat menulis konten HTML, tetapi beberapa belum memahami pengambilan data lewat JavaScript. Tujuan inti ialah informasi awal tetap terbaca ketika script gagal. Strategi paling tepat adalah ...","options":["Mewajibkan pemuatan seluruh konten melalui script sebelum halaman bisa dibaca.","Menilai jumlah animasi sebelum memeriksa konten awal.","Membangun konten HTML dasar lalu menambah pengayaan bertahap.","Mengganti informasi dengan pesan agar pengguna memasang browser tertentu."],"key":"C","why":"Tahap dasar dan pengayaan dipisahkan berdasarkan tujuan serta kesiapan. Penggunaan teknologi lebih banyak bukan otomatis pembelajaran lebih baik.","explanations":["Pilihan itu dapat bekerja pada kondisi normal, tetapi tidak memenuhi kebutuhan ketika script gagal.","Animasi tidak membuktikan informasi terbaca saat script gagal.","Tahapan menjaga tujuan inti sambil menyesuaikan dukungan.","Pesan itu menghindari kebutuhan menyediakan konten awal yang dapat dibaca."]},{"package":3,"id":24,"uid":"p3-024","section":"PCK","code":"P.3","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"PSE; diskusi bermakna","case_focus":"gestur dan konflik","stem":"Dalam proyek mobile, murid berdebat karena gestur dari tepi layar bertabrakan dengan navigasi sistem. Guru ingin diskusi tetap produktif. Pilih semua tindakan yang tepat.","options":["Memilih usulan dari anggota yang paling cepat menyelesaikan kode.","Menguji skenario pengguna pada perangkat dan mencatat konflik yang terjadi.","Menetapkan semua gestur buatan aplikasi harus dipertahankan.","Memberi giliran menjelaskan alasan dan mencoba alternatif yang dapat dibatalkan."],"key":["B","D"],"why":"Diskusi perlu standar bukti dan iklim yang aman. Konflik desain tidak selesai hanya dengan memilih orang yang dianggap paling mahir.","explanations":["Kecepatan tidak menjawab konflik gestur dengan sistem.","Bukti bersama mengalihkan debat pribadi menjadi penilaian desain.","Keputusan itu mengabaikan interaksi dengan navigasi sistem.","Prosedur aman mendukung partisipasi serta eksperimen bermakna."]},{"package":3,"id":25,"uid":"p3-025","section":"PCK","code":"P.1","type":"PG","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"Konflik kognitif berbasis bukti","case_focus":"aturan domain CHECK","stem":"Tabel pemesanan mensyaratkan tanggal selesai tidak lebih awal daripada tanggal mulai. Murid merasa tipe DATE sudah menjamin aturan itu. Langkah guru terbaik adalah ...","options":["Meminta murid mengganti format tampilan tanggal.","Menguji hubungan dua tanggal sah.","Memeriksa bahwa kedua tanggal dapat dibaca dan disimpan oleh basis data.","Mengganti nama kolom dengan istilah yang lebih panjang."],"key":"B","why":"Tipe memeriksa bentuk nilai tertentu, bukan seluruh aturan bisnis antarkolom. Data tandingan membantu murid menemukan kebutuhan constraint tambahan.","explanations":["Format tidak memeriksa hubungan dua nilai.","Contoh membedakan validitas tipe dan aturan domain.","Dua nilai dapat sama-sama valid sebagai DATE tetapi melanggar hubungan mulai dan selesai.","Nama kolom tidak menegakkan syarat hubungan nilai."]},{"package":3,"id":26,"uid":"p3-026","section":"PCK","code":"PF.2","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Representasi visual konsep grafis","case_focus":"rasio gambar","stem":"Murid membuat fungsi resize gambar dan menganggap lebar serta tinggi boleh diubah sendiri-sendiri tanpa konsekuensi bentuk. Nilai kegiatan guru berikut sebagai Tepat atau Tidak tepat.","options":["Memilih hasil yang ukuran filenya paling kecil sebagai bukti bentuk terjaga.","Membandingkan lingkaran sebelum dan sesudah skala horizontal berbeda dari vertikal.","Meminta murid menjelaskan hubungan faktor skala dan rasio aspek."],"key":["F","T","T"],"why":"Pemahaman grafis memerlukan hubungan proporsi dan transformasi, bukan hanya tampilan atau ukuran file hasil.","explanations":["Ukuran file tidak menjamin proporsi gambar sama.","Bentuk lingkaran memperlihatkan distorsi proporsi.","Penjelasan menautkan hasil visual dengan perhitungan ukuran."]},{"package":3,"id":27,"uid":"p3-027","section":"PCK","code":"P.6","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Web","ppg_concept":"Bukti asesmen pada kasus pembeda","case_focus":"pagination stabil","stem":"Pagination memakai ORDER BY skor saja, padahal beberapa baris berskor sama. Murid melihat urutan antarhalaman berubah meski data tidak diedit. Bukti pemahaman perbaikan paling kuat adalah ...","options":["Menguji jumlah baris per halaman dan menganggap urutannya ikut terjamin.","Tampilan angka halaman menjadi lebih besar.","Nama kolom hasil dibuat lebih singkat.","Menambah pembanding unik pada skor seri, mengulang pembacaan, dan meminta alasan kestabilan urutan pada data tetap."],"key":"D","why":"Data tetap dengan nilai seri memerlukan pemecah seri agar urutan deterministik. Ini berbeda dari persoalan data baru masuk saat pagination berjalan.","explanations":["Jumlah baris dan kestabilan urutan pada skor seri merupakan dua hal berbeda.","Ukuran tampilan tidak memengaruhi pengurutan query.","Nama keluaran tidak menentukan urutan.","Pembanding tambahan menetapkan urutan total yang stabil untuk data tetap."]},{"package":3,"id":28,"uid":"p3-028","section":"PCK","code":"P.4","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"TPACK; literasi pengujian","case_focus":"deep link","stem":"Guru memakai penguji deep link mobile. Murid menganggap semua tautan yang membuka aplikasi pasti boleh menjalankan aksi di dalamnya. Pilih kegiatan penggunaan alat yang kritis.","options":["Menguji path dan parameter yang tidak dikenali aplikasi.","Menilai keamanan dari kemiripan alamat dengan nama aplikasi.","Membandingkan pembukaan layar dan pemeriksaan hak sebelum aksi sensitif.","Menerima semua parameter agar demonstrasi selalu berhasil."],"key":["A","C"],"why":"Alat dipakai untuk menelaah batas masukan dan kewenangan. Kemampuan membuka aplikasi tidak otomatis memberi izin melakukan setiap aksi.","explanations":["Masukan tak dikenal menguji batas penafsiran tautan.","Kemiripan teks tidak membuktikan validitas atau hak menjalankan aksi.","Dua tahap membedakan navigasi dari otorisasi.","Penerimaan bebas menghilangkan pemeriksaan yang diperlukan."]},{"package":3,"id":29,"uid":"p3-029","section":"PCK","code":"P.1","type":"PG","difficulty":"menantang","cp_element":"Basis Data","ppg_concept":"Pemahaman konseptual agregasi","case_focus":"rerata tertimbang","stem":"Kelompok A berisi 2 respons dengan rata-rata 90; kelompok B berisi 8 respons dengan rata-rata 60. Murid mengambil rata-rata dua rata-rata untuk laporan gabungan. Tindakan guru paling tepat adalah ...","options":["Menghitung kontribusi tiap respons dengan bobot ukuran kelompok.","Memberi bobot setengah untuk masing-masing rata-rata karena ada dua kelompok.","Membulatkan kedua rata-rata sebelum digabung.","Memeriksa rata-rata tiap kelompok sudah benar lalu menjumlahkan keduanya dengan bobot sama."],"key":"A","why":"Rata-rata gabungan membobot menurut banyaknya respons. Contoh ini menghasilkan 66, bukan 75; perbedaannya memberi bukti akibat memperlakukan kelompok tidak seimbang sebagai setara.","explanations":["Jumlah anggota yang berbeda harus tercermin dalam kontribusi total.","Bobot kelompok sama mengabaikan jumlah respons yang tidak sama.","Pembulatan tidak memperbaiki bobot kelompok.","Kebenaran rata-rata kelompok belum membenarkan bobot sama ketika jumlah respons berbeda."]},{"package":3,"id":30,"uid":"p3-030","section":"PCK","code":"PF.3","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"PF.3; diagnosis representasi","case_focus":"Unicode","stem":"Murid terbiasa teks ASCII dan mengira satu karakter selalu satu byte. Sebelum praktik pembacaan teks UTF-8, guru memetakan kesiapan. Nilai tindakan berikut sebagai Tepat atau Tidak tepat.","options":["Membandingkan jumlah byte dan code point pada contoh huruf ASCII serta huruf non-ASCII.","Menentukan kesiapan hanya dari kecepatan mengetik.","Menganggap semua kegagalan decoding disebabkan file terlalu besar."],"key":["T","F","F"],"why":"Karakter yang terlihat, code point, dan byte tidak selalu satu banding satu. Guru perlu menemukan asumsi representasi sebelum memilih bantuan pembacaan teks.","explanations":["Perbandingan menargetkan asumsi representasi satu byte.","Kecepatan tidak menjelaskan representasi teks.","Ukuran file tidak menentukan kecocokan encoding."]},{"package":3,"id":31,"uid":"p3-031","section":"PCK","code":"P.2","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"ZPD; scaffolding bertahap","case_focus":"scaffold regex","stem":"Pada tugas regex sederhana, murid dapat mencocokkan satu digit tetapi masih bergantung pada contoh untuk menyatakan satu atau lebih digit. Guru ingin mengurangi bantuan. Langkah berikut terbaik adalah ...","options":["Menampilkan pola lengkap setiap kali murid mencoba contoh baru.","Memindahkan murid langsung ke pola bertingkat yang lebih panjang.","Menguji dua pola dengan petunjuk pengulangan yang dikurangi.","Meminta murid melengkapi bagian pola yang hilang dengan contoh yang identik setiap kali."],"key":"C","why":"Bantuan disesuaikan dengan batas kemampuan saat ini. Tugas baru yang setara dapat menunjukkan apakah dukungan mulai dapat dikurangi.","explanations":["Contoh lengkap membantu meniru tetapi belum memberi ruang untuk mengurangi bantuan berdasarkan kesiapan.","Lompatan tuntutan belum didukung bukti kesiapan.","Petunjuk terbatas menjaga tantangan dan membuka bukti kemandirian.","Tugas itu memberi sebagian praktik, tetapi belum memperlihatkan transfer ketika bantuan dan contoh mulai diubah."]},{"package":3,"id":32,"uid":"p3-032","section":"PCK","code":"PF.5","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Refleksi praktik berbasis bukti","case_focus":"emulator dan kamera","stem":"Guru memakai emulator kamera saat mengajar pemindaian kode. Murid berhasil membaca gambar contoh, tetapi belum mencoba pencahayaan berbeda. Pilih semua langkah pengembangan praktik yang beralasan.","options":["Memisahkan keberhasilan logika baca gambar dari integrasi kamera nyata.","Mengumpulkan hasil pada kondisi cahaya yang direncanakan.","Menyimpulkan emulator selalu lebih buruk sehingga harus dihapus.","Menilai apakah tugas tambahan mengubah alasan murid tentang batas pengujian."],"key":["A","B","D"],"why":"Pengembangan praktik menguji batas representasi emulator dan pemahaman murid terhadapnya. Pengalaman satu gambar tidak mewakili seluruh kondisi penggunaan.","explanations":["Dua keberhasilan tersebut memerlukan bukti berbeda.","Variasi kondisi menelaah batas keberhasilan demonstrasi.","Temuan terbatas tidak membenarkan penolakan seluruh manfaat emulator.","Perubahan alasan menjadi bukti pembelajaran, bukan hanya angka keberhasilan alat."]},{"package":3,"id":33,"uid":"p3-033","section":"PCK","code":"PF.2","type":"PG","difficulty":"menantang","cp_element":"Basis Data","ppg_concept":"Ketepatan materi dan demonstrasi","case_focus":"NOT IN dan NULL","stem":"Dalam SQL, subquery daftar pengecualian dapat memuat NULL. Murid memakai NOT IN lalu heran tidak ada baris yang lolos. Guru ingin mengajarkan logika tiga nilai. Demonstrasi terbaik adalah ...","options":["Memperpanjang timeout query agar hasil muncul.","Menguji NULL dalam kondisi NOT IN.","Memeriksa bahwa nilai biasa tidak ada dalam daftar sambil melewati pengujian NULL.","Mengganti nama tabel daftar pengecualian."],"key":"B","why":"NOT IN yang membandingkan terhadap NULL dapat menghasilkan UNKNOWN sehingga baris tidak lolos WHERE. Alternatif harus tetap sesuai makna kebutuhan, bukan penggantian sintaks secara membabi buta.","explanations":["Masalah logika tidak diselesaikan oleh waktu tunggu.","Contoh menampakkan UNKNOWN dan alternatif penulisan kondisi.","Tidak adanya nilai biasa belum menjelaskan hasil UNKNOWN yang dapat timbul dari NULL.","Nama tabel tidak menjelaskan pengaruh NULL."]},{"package":3,"id":34,"uid":"p3-034","section":"PCK","code":"PF.4","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"UbD; tujuan bermakna","case_focus":"dependensi bersiklus","stem":"Guru menyusun unit pemodelan modul. Proyek contoh memiliki A bergantung pada B dan B bergantung pada A sehingga build sulit disusun. Nilai tujuan belajar berikut sebagai Tepat atau Tidak tepat.","options":["Murid menjelaskan siklus dan menilai pemisahan tanggung jawab untuk memutuskannya.","Murid menghafal pesan error build sebagai bukti utama penguasaan desain modul.","Murid mengganti warna diagram sebagai pengganti analisis ketergantungan."],"key":["T","F","F"],"why":"Tujuan kurikuler ditentukan dari kemampuan yang ingin dibangun. Build menjadi bukti konsekuensi rancangan, bukan daftar pesan yang harus dihafalkan.","explanations":["Tujuan menautkan masalah build dengan penalaran hubungan antarmodul.","Pesan error dapat membantu diagnosis, tetapi hafalan belum mengukur keputusan rancangan.","Warna dapat membantu pembacaan, tetapi tidak menggantikan penalaran dependensi."]},{"package":3,"id":35,"uid":"p3-035","section":"PCK","code":"P.4","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"TPACK; literasi digital","case_focus":"unggah file","stem":"Guru memakai penguji unggah web. Murid menganggap file aman jika ekstensi namanya sesuai. Pilih semua kegiatan yang mendukung literasi pengujian.","options":["Memilih nama file yang paling pendek agar mudah diperiksa.","Membandingkan ekstensi, informasi tipe, dan isi file uji yang sengaja tidak cocok.","Meminta murid menjelaskan pemeriksaan server sesuai jenis berkas yang diizinkan.","Menerima berkas selama ikon pada komputer tampak benar."],"key":["B","C"],"why":"Alat membantu menilai bukti format dan batas penerimaan. Pemeriksaan jenis file perlu berlapis; ekstensi atau informasi tipe dari klien saja tidak cukup.","explanations":["Panjang nama bukan bukti format isi.","Ketidakcocokan menguji asumsi dari nama file saja.","Pemeriksaan harus mengikuti kebutuhan dan batas format.","Ikon dapat mengikuti asosiasi nama dan bukan validasi isi."]},{"package":3,"id":36,"uid":"p3-036","section":"PCK","code":"P.5","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Pemanfaatan lingkungan; keputusan teknis","case_focus":"sampling sensor","stem":"Mitra pemantau suhu ruang penyimpanan pangan hanya memerlukan perubahan lambat, tetapi aplikasi mobile mengambil sampel sangat rapat dan baterai cepat habis. Kegiatan kontekstual terbaik adalah ...","options":["Menguji interval sampel terhadap perubahan suhu yang dibutuhkan.","Menetapkan interval paling rapat berdasarkan kemampuan maksimum sensor.","Menghapus seluruh riwayat agar baterai tampak lebih awet.","Memilih interval dari aplikasi populer sebelum mencocokkannya dengan perubahan suhu ruang mitra."],"key":"A","why":"Kebutuhan sumber lokal menentukan resolusi waktu yang berguna. Penghematan tidak boleh menghilangkan perubahan yang memang perlu diketahui pengguna.","explanations":["Keputusan teknis diuji terhadap kebutuhan setempat.","Kemampuan alat belum menjadi bukti bahwa rapatnya sampel diperlukan untuk perubahan yang dicari.","Penghapusan tidak menelaah biaya pengambilan sampel.","Praktik aplikasi lain dapat memberi ide, tetapi intervalnya belum tentu memenuhi kebutuhan pengukuran setempat."]},{"package":3,"id":37,"uid":"p3-037","section":"PCK","code":"P.3","type":"PG","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"PSE; diskusi berbasis bukti","case_focus":"trigger dan refleksi","stem":"Saat menyelidiki perubahan data yang tidak tampak di kode aplikasi, kelompok mulai saling menyalahkan. Ada trigger basis data yang belum mereka periksa. Guru ingin memulihkan diskusi berbukti. Langkah terbaik adalah ...","options":["Menugasi anggota paling berpengalaman membaca kode sendiri lalu menyerahkan simpulan akhir.","Menilai setiap potongan kode aplikasi secara terpisah sebelum membuka log basis data.","Menyepakati bahasa netral lalu menelusuri log dan trigger.","Memberi nilai dari banyaknya dugaan yang diajukan."],"key":"C","why":"Guru menggabungkan pengelolaan hubungan dan penyelidikan teknis. Perubahan data dapat berasal dari mekanisme basis data, bukan hanya kode yang sedang dilihat.","explanations":["Keahlian dapat membantu, tetapi proses ini belum memulihkan diskusi bersama dan pemeriksaan lintas lapisan yang dibutuhkan.","Pemeriksaan kode berguna tetapi belum mencakup mekanisme trigger dan pemulihan diskusi saling menyalahkan.","Iklim aman dan bukti lintas lapisan mendukung penyelidikan.","Jumlah dugaan tidak menjamin pemeriksaan penyebab."]},{"package":3,"id":38,"uid":"p3-038","section":"PCK","code":"PF.2","type":"Kategori","difficulty":"menantang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Penalaran object dan kontrak","case_focus":"kontrak interface","stem":"Sebuah implementasi interface mengembalikan null pada kondisi yang menurut kontrak harus mengembalikan list kosong. Guru ingin murid menilai substitusi implementasi. Nilai kegiatan berikut sebagai Tepat atau Tidak tepat.","options":["Menganggap nama method sama sudah menjamin implementasi dapat saling menggantikan.","Menguji pemanggil yang sah terhadap dua implementasi.","Meminta murid membedakan perbaikan implementasi dan perubahan kontrak."],"key":["F","T","T"],"why":"Penilaian desain perlu memeriksa janji perilaku, bukan hanya kesamaan bentuk deklarasi. Kontrak yang dinyatakan menjadi acuan bukti.","explanations":["Kesamaan nama tidak menjamin perilaku memenuhi kontrak.","Pemanggil memperlihatkan apakah jaminan kontrak dipenuhi.","Kedua tindakan memberi konsekuensi berbeda bagi pemanggil."]},{"package":3,"id":39,"uid":"p3-039","section":"PCK","code":"PF.1","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"Tujuan kejuruan; inklusi","case_focus":"urutan DOM dan visual","stem":"Dalam proyek web SMK, urutan visual sudah menarik tetapi urutan baca DOM membingungkan pengguna. Guru ingin murid bertanggung jawab pada kegunaan produknya. Bukti terkuat adalah ...","options":["Menggunakan screenshot sebagai bukti utama kesesuaian urutan informasi.","Menguji urutan baca dari struktur DOM, membandingkannya dengan kebutuhan pengguna, lalu menjelaskan revisi struktur yang dipilih.","Jumlah efek transisi yang berhasil dipasang.","Kemiripan screenshot dengan contoh industri."],"key":"B","why":"Tujuan kejuruan mencakup kegunaan bagi pengguna beragam. Kualitas visual dan struktur baca harus dinilai sebagai dimensi yang berbeda.","explanations":["Screenshot menunjukkan urutan visual, bukan urutan baca DOM yang menjadi masalah.","Bukti menghubungkan teknik dan kebutuhan penggunaan nyata.","Efek tidak menjamin struktur informasi dapat dipahami.","Kemiripan visual tidak membuktikan akses terhadap isi."]},{"package":3,"id":40,"uid":"p3-040","section":"PCK","code":"P.6","type":"MCMA","difficulty":"menantang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Asesmen diagnosis","case_focus":"jam durasi mobile","stem":"Aplikasi mobile mengukur durasi latihan dari jam kalender. Ketika jam perangkat disesuaikan, durasi meloncat. Guru ingin menilai diagnosis murid. Pilih semua bukti yang relevan.","options":["Murid membandingkan jam kalender dan sumber waktu berlalu yang sesuai platform.","Murid memperbesar angka timer agar loncatan lebih terlihat.","Murid menyimpan durasi sebagai teks agar tidak berubah.","Murid menguji penyesuaian jam pada skenario yang dikendalikan."],"key":["A","D"],"why":"Durasi memerlukan acuan waktu berlalu yang tepat, dengan perilaku tidur perangkat diperiksa sesuai kebutuhan. Jam kalender dapat disesuaikan dan bukan selalu acuan durasi yang stabil.","explanations":["Perbandingan membedakan penanda tanggal dan ukuran durasi.","Tampilan tidak menjelaskan sumber kesalahan pengukuran.","Representasi teks tidak memperbaiki acuan perhitungan.","Uji menilai dugaan perubahan acuan, bukan kebetulan satu hasil."]},{"package":3,"id":41,"uid":"p3-041","section":"PCK","code":"P.6","type":"PG","difficulty":"menantang","cp_element":"Basis Data","ppg_concept":"Keselarasan asesmen dan tujuan","case_focus":"agregat jendela","stem":"Tujuan SQL ialah menampilkan setiap transaksi beserta total per kelompok pada baris yang sama. Murid hanya menyerahkan hasil GROUP BY sehingga detail transaksi hilang. Bukti asesmen paling sesuai adalah ...","options":["Jumlah kelompok pada hasil rekap.","Meminta hasil total setiap kelompok sebagai satu-satunya keluaran tugas.","Nama alias kolom yang mudah dibaca.","Menyajikan keluaran pada setiap transaksi disertai total kelompok, lalu menjelaskan mengapa agregat jendela mempertahankan baris detail."],"key":"D","why":"Asesmen mengikuti kebutuhan mempertahankan baris detail. Fungsi agregat berjendela dapat menambahkan ringkasan tanpa mereduksi setiap kelompok menjadi satu baris.","explanations":["Jumlah kelompok belum menunjukkan detail tetap tersedia.","Rekap kelompok belum memenuhi kebutuhan mempertahankan setiap baris transaksi.","Alias membantu keterbacaan tetapi tidak menjaga baris detail.","Bukti memeriksa bentuk hasil serta alasan teknisnya."]},{"package":3,"id":42,"uid":"p3-042","section":"PCK","code":"P.3","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"CASEL; regulasi dan keterampilan berelasi","case_focus":"audio video dan kerja tim","stem":"Kelompok membuat pemutar video dengan audio terpisah. Saat suara terlambat, anggota saling memotong penjelasan. Guru ingin murid mengelola konflik sambil menelusuri sinkronisasi. Nilai tindakan berikut sebagai Tepat atau Tidak tepat.","options":["Memberi jeda singkat lalu meminta tiap anggota menyebut pengamatan, bukan tuduhan.","Meminta kelompok menyepakati acuan waktu sebelum menguji offset audio.","Memilih usulan dari anggota yang paling keras mempertahankannya."],"key":["T","T","F"],"why":"Pengelolaan emosi mendukung penyelidikan, bukan menggantikannya. Acuan waktu yang disepakati membuat bukti offset dapat dibandingkan.","explanations":["Pemisahan pengamatan dan tuduhan membantu pemulihan komunikasi.","Acuan bersama mengembalikan diskusi pada penyebab teknis.","Kekuatan suara tidak membuktikan ketepatan acuan sinkronisasi."]},{"package":3,"id":43,"uid":"p3-043","section":"PCK","code":"P.1","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"Pembentukan konsep lewat eksperimen","case_focus":"konfigurasi build","stem":"Alamat API pada web tetap menunjuk server uji meski file konfigurasi server produksi diubah. Nilai itu dimasukkan ke bundle saat build. Guru ingin meluruskan dugaan bahwa semua konfigurasi dibaca saat runtime. Demonstrasi terbaik adalah ...","options":["Membandingkan bundle dari dua build dengan nilai konfigurasi berbeda.","Mengganti file konfigurasi lalu memuat ulang browser tanpa membuat bundle baru.","Mengurutkan nama file konfigurasi berdasarkan panjangnya.","Memeriksa bahwa file konfigurasi produksi berisi nilai benar sebelum menguji isi bundle yang dikirim."],"key":"A","why":"Murid perlu membedakan konfigurasi build dan runtime sesuai alat yang dipakai. Mengubah file setelah build tidak otomatis mengubah nilai yang sudah tertanam.","explanations":["Perbandingan menampakkan kapan nilai dimasukkan.","Muat ulang saja tidak mengubah nilai yang telah dimasukkan ke bundle saat build.","Urutan nama tidak menentukan apakah nilai sudah tertanam.","Isi file penting, tetapi nilai yang telah tertanam saat build tidak otomatis mengikuti perubahan file tersebut."]},{"package":3,"id":44,"uid":"p3-044","section":"PCK","code":"PF.3","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"PF.3; prasyarat interpretasi data","case_focus":"akurasi lokasi","stem":"Murid mampu membaca koordinat mobile, tetapi menganggapnya titik pasti ketika aplikasi memeriksa batas lokasi. API juga memberi estimasi akurasi. Pilih semua dukungan prasyarat yang tepat.","options":["Mengajarkan bahwa lebih banyak desimal selalu menghilangkan ketidakpastian.","Memodelkan posisi sebagai estimasi dengan daerah ketidakpastian.","Menguji titik dekat batas dengan beberapa nilai akurasi.","Menghapus informasi akurasi agar murid fokus pada koordinat."],"key":["B","C"],"why":"Kebutuhan belajar terletak pada perbedaan koordinat terlapor dan kepastian posisi. Estimasi akurasi perlu ditafsirkan sesuai dokumentasi platform, bukan dianggap jaminan mutlak.","explanations":["Jumlah desimal tidak menjamin akurasi pengukuran.","Representasi menargetkan asumsi posisi yang dianggap pasti.","Kasus dekat batas menunjukkan pengaruh ketidakpastian terhadap keputusan.","Penghapusan menghilangkan konsep yang perlu dipahami."]},{"package":3,"id":45,"uid":"p3-045","section":"PCK","code":"P.2","type":"PG","difficulty":"menantang","cp_element":"Basis Data","ppg_concept":"Diferensiasi; scaffolding","case_focus":"prioritas CASE","stem":"Sebagian murid memahami satu kondisi CASE, tetapi kesulitan saat dua kondisi sama-sama benar. SQL memakai hasil dari WHEN pertama yang cocok. Guru menyiapkan dukungan bertahap. Langkah terbaik adalah ...","options":["Menambah label keluaran tanpa mengubah atau membandingkan urutan kondisi.","Memberi tugas dengan sepuluh kondisi langsung.","Menukar urutan dua WHEN yang sama-sama cocok.","Meminta semua murid menyalin satu hasil akhir."],"key":"C","why":"Bantuan menargetkan kesiapan pada aturan pertama-cocok. Setelah alasan dipahami, jumlah kondisi dapat ditambah dan bantuan dikurangi.","explanations":["Label dapat membantu membaca hasil tetapi belum menjelaskan pemilihan WHEN pertama yang cocok.","Penambahan kompleksitas belum didukung bukti kesiapan.","Contoh kecil menampakkan pengaruh urutan sebelum diperluas.","Salinan hasil tidak menunjukkan pemahaman evaluasi."]},{"package":3,"id":46,"uid":"p3-046","section":"PCK","code":"PF.5","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"PF.5; pengujian praktik","case_focus":"pengujian acak","stem":"Guru ingin memperbaiki pembelajaran program acak karena murid sulit membedakan bug dan variasi hasil. Ia mencoba penggunaan seed tetap saat diagnosis. Nilai evaluasi praktik berikut sebagai Tepat atau Tidak tepat.","options":["Membandingkan kemampuan murid mereproduksi kegagalan sebelum dan sesudah strategi.","Menyimpulkan satu seed berhasil membuktikan program benar untuk semua masukan.","Memeriksa apakah murid tetap menguji beberapa seed setelah diagnosis."],"key":["T","F","T"],"why":"Seed tetap membantu reproduksi, sedangkan variasi seed memperluas pengujian. Perbaikan praktik dinilai dari kemampuan membedakan kedua tujuan itu.","explanations":["Reproduksi merupakan kemampuan yang ditargetkan.","Satu rangkaian acak tidak mencakup semua kemungkinan.","Variasi diperlukan untuk menilai jangkauan perilaku program."]},{"package":3,"id":47,"uid":"p3-047","section":"PCK","code":"PF.4","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"Keselarasan tujuan kurikuler","case_focus":"ketahanan tes web","stem":"Guru menyusun unit tes otomatis web. Tes murid gagal setelah teks tombol diterjemahkan meski fungsi tetap sama. Tujuan yang paling sesuai untuk unit lanjutan adalah ...","options":["Murid mempertahankan semua teks antarmuka agar tes lama tidak berubah.","Murid memilih acuan tes berdasarkan perilaku yang ingin dijamin.","Menjadikan jumlah selector yang ditulis sebagai ukuran utama keberhasilan tes.","Mengganti seluruh tes dengan pemeriksaan bahwa halaman berhasil dibuka setelah teks diterjemahkan."],"key":"B","why":"Kurikulum perlu mengarahkan murid membedakan perubahan perilaku dan perubahan presentasi. Pemilihan selector tetap mempertimbangkan aksesibilitas serta tujuan tes, bukan aturan tunggal semua teks harus dihindari.","explanations":["Pembatasan itu menghindari kebutuhan merancang tes yang sesuai perubahan sah.","Tujuan menuntut alasan pemilihan acuan, bukan hafalan selector.","Jumlah selector tidak membuktikan tes menjamin perilaku yang tetap relevan saat teks berubah.","Halaman dapat terbuka meski fungsi penting rusak; tes perlu tetap mengukur perilaku yang ingin dijamin."]},{"package":3,"id":48,"uid":"p3-048","section":"PCK","code":"P.4","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"TPACK; penilaian bukti digital","case_focus":"Bluetooth dan status aksi","stem":"Guru memakai alat pemantau Bluetooth untuk aplikasi pengendali lampu. Murid menyimpulkan status tersambung berarti perintah sudah dijalankan perangkat. Pilih semua kegiatan yang tepat.","options":["Membandingkan status koneksi, pengiriman perintah, dan konfirmasi perangkat.","Menganggap ikon koneksi sebagai bukti tunggal lampu berubah.","Menguji kasus perintah gagal meski koneksi masih ada.","Meminta murid menjelaskan tampilan ketika konfirmasi belum diterima."],"key":["A","C","D"],"why":"Alat digunakan untuk membaca batas bukti sistem terhubung. Aplikasi perlu membedakan status sambungan dari hasil aksi.","explanations":["Tiga peristiwa itu memberi bukti berbeda.","Koneksi tidak menjamin perintah telah diterima dan dijalankan.","Kasus tandingan menguji dugaan koneksi sama dengan keberhasilan aksi.","Tampilan perlu mengikuti kepastian yang benar-benar tersedia."]},{"package":3,"id":49,"uid":"p3-049","section":"PCK","code":"PF.4","type":"PG","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"UbD; tujuan dan bukti","case_focus":"kesegaran ringkasan","stem":"Unit laporan basis data akan memakai ringkasan tersimpan untuk mempercepat pembacaan. Pengguna membutuhkan data yang dapat berubah setiap jam. Guru ingin tujuan, kegiatan, dan asesmen selaras. Pilihan terbaik adalah ...","options":["Menilai hanya waktu baca laporan setelah ringkasan tersimpan dipakai.","Menghapus penanda waktu pembaruan dari laporan.","Meminta murid menghafal semua nama tabel sumber.","Merancang jadwal pembaruan ringkasan dan menguji apakah jeda kesegaran masih memenuhi kebutuhan pengguna yang berubah setiap jam."],"key":"D","why":"Adaptasi kurikulum memasukkan konsekuensi ringkasan tersimpan, bukan hanya teknik mempercepat query. Kriteria kesegaran perlu diturunkan dari kebutuhan pengguna.","explanations":["Waktu baca mengukur kinerja, tetapi belum menguji batas kesegaran data pengguna.","Penghapusan menyembunyikan informasi kesegaran.","Hafalan sumber belum menilai keputusan pembaruan ringkasan.","Tugas menghubungkan kinerja dengan kebutuhan waktu data."]},{"package":3,"id":50,"uid":"p3-050","section":"PCK","code":"PF.1","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Tujuan pendidikan kejuruan","case_focus":"streaming file","stem":"Dalam proyek pengolah file besar di SMK, program berhasil pada contoh kecil tetapi kehabisan memori pada data mitra. Nilai bukti kesiapan kerja berikut sebagai Tepat atau Tidak tepat.","options":["Murid hanya menyerahkan hasil dari file contoh kecil.","Murid menjelaskan pemrosesan bertahap dan menguji penggunaan memori.","Murid mendokumentasikan batas ukuran dan kondisi pengujiannya."],"key":["F","T","T"],"why":"Tujuan kejuruan menuntut solusi yang dapat dipakai pada kondisi relevan dan batasnya diketahui. Pemrosesan streaming dapat mengurangi kebutuhan memori tanpa menganggap semua operasi selalu bisa dilakukan sekali lewat.","explanations":["Bukti itu belum mencakup kondisi penggunaan mitra.","Penjelasan serta uji menghubungkan teknik dengan batas sumber daya.","Batas yang jelas membantu penyerahan hasil secara bertanggung jawab."]},{"package":3,"id":51,"uid":"p3-051","section":"PU","code":"PF.4","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"UbD","case_focus":"UbD","stem":"Guru merencanakan unit tentang menilai kekuatan argumen. Ia sudah memilih debat yang menarik, tetapi asesmen hanya meminta definisi argumen. Langkah perbaikan paling tepat adalah ...","options":["Menetapkan bukti penilaian argumen sebelum merancang dukungan debat.","Memperbaiki aturan giliran debat sebelum menelaah bukti asesmen.","Memperpanjang daftar definisi untuk ujian akhir.","Mempertahankan kuis definisi lalu menambah catatan bahwa kegiatan debat berlangsung aktif."],"key":"A","why":"Perancangan mundur menghubungkan tujuan dengan bukti sebelum memutuskan pengalaman belajar. Kegiatan menarik tetap perlu mendukung konstruk yang ditargetkan.","explanations":["Bukti menentukan apakah kegiatan mencapai kemampuan yang diinginkan.","Aturan giliran dapat membantu kegiatan, tetapi belum memastikan penilaian argumen benar-benar diukur.","Daftar itu tetap mengukur ingatan istilah.","Catatan aktivitas membantu evaluasi proses, tetapi tidak membuktikan kemampuan menilai kekuatan argumen."]},{"package":3,"id":52,"uid":"p3-052","section":"PU","code":"P.2","type":"MCMA","difficulty":"sedang","cp_element":null,"ppg_concept":"Pemilihan PBL/PjBL","case_focus":"PBL atau PjBL","stem":"Guru memilih antara penyelidikan masalah dan proyek produk. Kelas perlu belajar menimbang dua solusi masalah banjir dari data yang tersedia; produk fisik bukan tujuan. Pilih semua keputusan yang tepat.","options":["Memilih proyek miniatur karena semua pembelajaran aktif harus menghasilkan benda.","Memulai masalah dan membimbing penyelidikan alasan memilih solusi.","Menilai dari keindahan poster sebagai bukti utama.","Meminta perbandingan solusi beserta batas bukti sebelum simpulan."],"key":["B","D"],"why":"Pemilihan model mengikuti tujuan dan kebutuhan murid. PBL dapat dipakai untuk penyelidikan masalah; produk PjBL bukan kewajiban untuk setiap tujuan.","explanations":["Bentuk produk tidak menjadi syarat semua pembelajaran aktif.","Penyelidikan selaras dengan keputusan berbasis data.","Keindahan tidak mengukur pertimbangan solusi.","Perbandingan menargetkan kemampuan yang dinyatakan."]},{"package":3,"id":53,"uid":"p3-053","section":"PU","code":"P.1","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Discovery terbimbing","case_focus":"discovery terarah","stem":"Murid menemukan dugaan pola pada tiga contoh bilangan. Guru memakai discovery learning dan ingin mencegah generalisasi terlalu cepat. Tindakan terbaik adalah ...","options":["Mengumumkan bahwa setiap pola dari tiga contoh pasti benar.","Menambah contoh yang semuanya mendukung dugaan awal sebagai pembuktian akhir.","Menguji dugaan pada contoh pembeda lalu membahas batasnya.","Meminta tiap kelompok menyatakan dugaan dengan istilah matematika yang lebih baku."],"key":"C","why":"Penemuan perlu diikuti pemeriksaan dan generalisasi beralasan. Guru memberi penopang penyelidikan, bukan membiarkan setiap dugaan dianggap benar.","explanations":["Banyak contoh terbatas belum menjamin generalisasi.","Contoh pendukung saja belum memeriksa batas atau kemungkinan contoh tandingan.","Pembuktian menilai apakah pola bertahan di luar contoh awal.","Ketepatan istilah membantu komunikasi, tetapi belum menguji dugaan atau batas generalisasinya."]},{"package":3,"id":54,"uid":"p3-054","section":"PU","code":"P.2","type":"Kategori","difficulty":"sedang","cp_element":null,"ppg_concept":"UDL","case_focus":"UDL sejak awal","stem":"Guru merancang unit peta wilayah sejak awal untuk kelas dengan kebutuhan akses beragam. Tujuan tetap menafsirkan hubungan lokasi. Nilai rancangan berikut sebagai Tepat atau Tidak tepat.","options":["Menyediakan peta dengan label jelas serta uraian hubungan spasial yang setara.","Mengizinkan penjelasan lisan atau tertulis dengan kriteria hubungan lokasi yang sama.","Membebaskan semua murid yang memakai dukungan dari penalaran lokasi."],"key":["T","T","F"],"why":"UDL memberi keluwesan sejak perancangan, bukan menunggu hambatan muncul atau menurunkan sasaran bagi penerima dukungan.","explanations":["Representasi alternatif membantu mengakses informasi yang sama.","Pilihan ekspresi mempertahankan sasaran penafsiran.","Dukungan akses tidak mengharuskan penghapusan tujuan."]},{"package":3,"id":55,"uid":"p3-055","section":"PU","code":"P.2","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"TaRL; diferensiasi","case_focus":"TaRL fleksibel","stem":"Asesmen membaca menunjukkan tiga tingkat capaian. Setelah dua pekan, beberapa murid telah maju. Guru menerapkan pembelajaran sesuai tahap capaian. Keputusan terbaik adalah ...","options":["Mempertahankan kelompok awal sambil menambah jumlah latihan yang sama.","Meninjau kelompok memakai bukti terbaru.","Memindahkan semua murid ke tugas tersulit secara bersamaan.","Menetapkan kelompok dari usia yang sama saja."],"key":"B","why":"TaRL memakai capaian aktual sebagai dasar bantuan dan pengelompokan fleksibel. Pengukuran ulang diperlukan agar bantuan tidak menjadi label tetap.","explanations":["Tambahan latihan belum menyesuaikan dukungan dengan perubahan capaian yang sudah diketahui.","Kelompok fleksibel mengikuti capaian saat ini.","Perpindahan seragam tidak mengikuti kebutuhan tiap murid.","Usia tidak menggantikan bukti capaian pada keterampilan yang ditargetkan."]},{"package":3,"id":56,"uid":"p3-056","section":"PU","code":"P.3","type":"MCMA","difficulty":"sedang","cp_element":null,"ppg_concept":"CASEL; manajemen diri","case_focus":"regulasi emosi murid","stem":"Seorang murid kecewa setelah idenya ditolak dan hendak merobek hasil kerja kelompok. Guru ingin menumbuhkan pengelolaan emosi dan tanggung jawab. Pilih semua langkah yang tepat.","options":["Membantu murid mengenali perasaan dan mengambil jeda aman.","Langsung memaksa murid menyetujui ide kelompok agar cepat selesai.","Setelah tenang, meminta murid memilih cara menyampaikan keberatan yang tidak merusak.","Menganggap semua perilaku saat kecewa tidak perlu ditindaklanjuti."],"key":["A","C"],"why":"Kesadaran emosi dan pengendalian diri perlu diikuti tindakan yang menghormati orang lain. Ini latihan keterampilan, bukan hafalan label CASEL.","explanations":["Pengenalan emosi mendukung pengendalian respons sebelum bertindak.","Persetujuan paksa belum membangun pengelolaan emosi.","Pilihan tindakan melatih komunikasi dan tanggung jawab.","Pengakuan emosi tidak menghapus tanggung jawab atas tindakan."]},{"package":3,"id":57,"uid":"p3-057","section":"PU","code":"S.1","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Komunikasi empatik","case_focus":"komunikasi setelah konflik","stem":"Dua murid berbeda pendapat tentang pembagian peran dan mulai menganggap temannya tidak mau bekerja. Guru ingin membantu komunikasi empatik. Respons terbaik adalah ...","options":["Menilai pembagian peran dari jumlah pekerjaan yang terlihat selesai pada akhir pertemuan.","Meminta keduanya menuliskan usulan masing-masing tanpa memeriksa maksud teman.","Mengganti seluruh anggota kelompok sebelum mendengar masing-masing.","Meminta tiap murid memparafrasekan maksud teman sebelum bersepakat."],"key":"D","why":"Komunikasi empatik memerlukan mendengar serta memeriksa makna, bukan hanya giliran menyatakan posisi. Kesepakatan dibangun setelah kedua pandangan dipahami.","explanations":["Jumlah pekerjaan dapat menjadi satu bukti kontribusi, tetapi belum menjernihkan pemaknaan yang menimbulkan tuduhan.","Tulisan dapat memperjelas posisi sendiri, tetapi belum memperbaiki pemaknaan silang yang memicu konflik.","Pergantian tidak memberi kesempatan belajar menyelesaikan perbedaan.","Parafrasa membantu memeriksa pemahaman dan mengurangi tuduhan."]},{"package":3,"id":58,"uid":"p3-058","section":"PU","code":"K.1","type":"Kategori","difficulty":"sedang","cp_element":null,"ppg_concept":"PSE; kematangan emosi guru","case_focus":"regulasi emosi guru","stem":"Guru merasa marah ketika murid menyela penjelasannya. Ia menyadari nada suaranya mulai meninggi. Nilai respons berikut sebagai Tepat atau Tidak tepat.","options":["Mengambil jeda singkat dan kembali menyatakan batas perilaku dengan tenang.","Menetapkan konsekuensi saat marah agar tampak konsisten.","Meninjau kejadian bersama murid setelah kondisi lebih tenang."],"key":["T","F","T"],"why":"Keteladanan menuntut regulasi emosi guru, bukan menghilangkan aturan. Jeda membantu keputusan tidak didorong kemarahan sesaat.","explanations":["Guru mengelola responsnya sambil menjaga batas kelas.","Keputusan impulsif belum menunjukkan pertimbangan yang adil.","Tindak lanjut memungkinkan pemahaman dan tanggung jawab."]},{"package":3,"id":59,"uid":"p3-059","section":"PU","code":"K.3","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Growth mindset; budaya belajar","case_focus":"usaha dan strategi","stem":"Murid telah berlatih berulang dengan cara yang sama tetapi hasilnya belum membaik. Guru ingin membangun pola pikir bertumbuh yang disertai strategi. Respons terbaik adalah ...","options":["Menelaah pola salah lalu mencoba dan memantau strategi baru.","Menambah durasi latihan dengan strategi lama sebagai satu-satunya tindak lanjut.","Menyimpulkan kemampuan tidak dapat berkembang.","Menetapkan target hasil lebih rendah sambil tetap mempertahankan cara latihan yang tidak membantu."],"key":"A","why":"Budaya bertumbuh menghubungkan usaha, strategi, dukungan, dan bukti kemajuan. Mengulang cara yang sama bukan satu-satunya makna bertekun.","explanations":["Usaha diarahkan oleh bukti dan perubahan cara belajar.","Waktu tambahan belum menanggapi bukti bahwa cara yang diulang tidak membantu.","Kesulitan saat ini bukan bukti batas kemampuan tetap.","Target dapat disesuaikan bila ada dasar kebutuhan, tetapi perubahan ini belum menanggapi pola kesalahan strategi yang ditemukan."]},{"package":3,"id":60,"uid":"p3-060","section":"PU","code":"P.6","type":"MCMA","difficulty":"sedang","cp_element":null,"ppg_concept":"Assessment as learning","case_focus":"assessment as learning","stem":"Murid menilai drafnya sendiri dengan rubrik dan menyadari simpulan belum didukung data. Guru ingin penilaian diri menjadi bagian pembelajaran. Pilih semua tindakan yang tepat.","options":["Mengumpulkan skor diri saja sebagai akhir kegiatan.","Meminta murid memilih bagian yang perlu diperbaiki dan alasannya.","Membandingkan draf revisi dengan sasaran yang dipilih murid.","Mengajak murid mencatat strategi yang akan dipakai pada tugas berikutnya."],"key":["B","C","D"],"why":"Assessment as learning menempatkan murid sebagai pemantau dan pengarah belajarnya. Penggunaan hasil lebih penting daripada sekadar memberi skor pada diri sendiri.","explanations":["Angka tanpa tindak lanjut belum menunjukkan penggunaan penilaian diri.","Keputusan revisi memakai bukti dari rubrik.","Perbandingan menilai apakah strategi perbaikan membantu.","Rencana transfer membuat penilaian diri mengarahkan belajar berikutnya."]},{"package":3,"id":61,"uid":"p3-061","section":"PU","code":"P.6","type":"PG","difficulty":"menantang","cp_element":null,"ppg_concept":"Asesmen formatif dan tindak lanjut","case_focus":"penggunaan bukti formatif","stem":"Exit ticket menunjukkan separuh kelas dapat memilih jawaban benar tetapi alasan mereka bertentangan dengan konsep. Guru harus menentukan kegiatan besok. Pilihan terbaik adalah ...","options":["Mencatat nilai benar lalu melanjutkan topik karena target angka tercapai.","Mengulang pilihan soal yang sama untuk memperlancar pengenalan jawaban.","Membahas dua alasan pembanding lalu mengecek alasan pada kasus baru.","Memberi tambahan waktu pada soal identik lalu menilai kembali pilihan akhirnya."],"key":"C","why":"Assessment for learning memakai bukti untuk mengubah pembelajaran. Jawaban tepat tidak selalu menunjukkan pemahaman jika alasannya keliru.","explanations":["Angka benar menutupi alasan keliru yang ditemukan.","Pengenalan pilihan dapat meningkat sementara alasan yang keliru tetap bertahan.","Tindak lanjut menargetkan kesenjangan penalaran yang terbukti.","Waktu dan pilihan akhir saja belum menunjukkan alasan yang semula bertentangan dengan konsep sudah diperbaiki."]},{"package":3,"id":62,"uid":"p3-062","section":"PU","code":"P.6","type":"Kategori","difficulty":"menantang","cp_element":null,"ppg_concept":"Assessment of learning; validitas konstruk","case_focus":"sumatif dan triangulasi","stem":"Guru menentukan capaian akhir unit berdasarkan tugas kinerja dan penjelasan individu. Satu murid sangat cemas saat presentasi, tetapi produk dan percakapan terstruktur memberi bukti penguasaan. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Menggunakan kelancaran presentasi sebagai pengganti seluruh kriteria penguasaan materi.","Menafsirkan beberapa bukti terhadap kriteria tujuan yang sama.","Mencatat kebutuhan dukungan komunikasi tanpa otomatis menghapus bukti capaian materi."],"key":["F","T","T"],"why":"Asesmen sumatif merangkum capaian berdasarkan tujuan dan mutu bukti, bukan satu kesan performa. Kriteria komunikasi tetap dinilai tersendiri jika memang menjadi tujuan.","explanations":["Kelancaran dapat mengukur hal lain dari sasaran materi.","Bukti beragam membantu memisahkan konstruk dari hambatan penyajian.","Informasi dukungan dan keputusan capaian dapat dibedakan."]},{"package":3,"id":63,"uid":"p3-063","section":"PU","code":"P.3","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Pembelajaran berkesadaran","case_focus":"kesadaran menjelang ujian","stem":"Menjelang ujian, murid mengatakan gugup membuatnya beralih soal sebelum membaca tujuan pertanyaan. Guru ingin membantu kesadaran proses, bukan memberi trik menebak. Langkah paling tepat adalah ...","options":["Menaikkan target kecepatan berpindah soal sebelum membahas pemicu kegugupan.","Melatih jeda sadar membaca tuntutan soal.","Menjamin semua murid akan lulus jika mengikuti nasihat guru.","Menghapus seluruh latihan soal menjelang ujian."],"key":"B","why":"Kesadaran membantu murid mengenali kondisi dan memilih respons yang relevan. Latihan pengelolaan perhatian tidak dimaksudkan menggantikan penguasaan materi.","explanations":["Tekanan kecepatan belum memberi keterampilan mengenali ketegangan dan tuntutan soal.","Latihan menghubungkan kesadaran emosi dengan tindakan belajar.","Jaminan itu tidak didukung bukti dan tidak mengembangkan keterampilan.","Penghapusan menyeluruh belum menanggapi kebutuhan mengelola proses."]},{"package":3,"id":64,"uid":"p3-064","section":"PU","code":"P.4","type":"MCMA","difficulty":"sedang","cp_element":null,"ppg_concept":"SAMR; TPACK","case_focus":"SAMR dan tujuan","stem":"Tim guru ingin mengganti lembar latihan dengan aplikasi yang fiturnya lebih tinggi menurut SAMR. Tujuan unit sudah tercapai lewat latihan sederhana; waktu belajar terbatas. Pilih semua keputusan yang beralasan.","options":["Menilai manfaat perubahan tugas terhadap tujuan sebelum memilih alat.","Memilih tingkat tertinggi agar pembelajaran otomatis mendalam.","Menghapus alat sederhana meski memberi bukti belajar yang baik.","Mempertahankan cara sederhana bila alat baru tidak memberi manfaat yang diperlukan."],"key":["A","D"],"why":"SAMR dapat membantu menelaah perubahan tugas, bukan mewajibkan semua kegiatan berada pada tingkat tertinggi. TPACK menuntut kecocokan konten, pedagogi, dan teknologi.","explanations":["Tingkat teknologi bukan tujuan pembelajaran itu sendiri.","Posisi pada kerangka tidak membuktikan mutu pemahaman.","Kesederhanaan alat bukan alasan menolaknya.","Keputusan mengikuti tujuan, waktu, dan bukti yang tersedia."]},{"package":3,"id":65,"uid":"p3-065","section":"PU","code":"P.5","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"CRT","case_focus":"CRT dan sumber budaya","stem":"Kelas membahas kisah lokal, tetapi satu versi yang dianggap umum tidak sesuai pengalaman beberapa murid. Guru ingin pembelajaran tanggap budaya. Respons terbaik adalah ...","options":["Memilih versi kelompok terbesar sebagai satu-satunya pengalaman yang sah.","Memakai satu versi buku sebagai pengganti seluruh penjelasan pengalaman murid.","Meminta murid yang berbeda menyesuaikan ceritanya dengan buku.","Menelaah versi kisah dan sumber bersama murid."],"key":"D","why":"CRT bukan menganggap setiap anggota kelompok budaya memiliki pengalaman sama. Guru menghubungkan variasi perspektif dengan tujuan dan pemeriksaan sumber.","explanations":["Jumlah pendukung tidak menjamin keseragaman pengalaman budaya.","Buku dapat menjadi sumber, tetapi penggunaannya sebagai satu-satunya versi menutup telaah variasi budaya.","Penyesuaian paksa menutup penelaahan perspektif.","Perbandingan menghargai variasi sambil menjaga penelaahan bukti."]},{"package":3,"id":66,"uid":"p3-066","section":"PU","code":"K.1","type":"Kategori","difficulty":"menantang","cp_element":null,"ppg_concept":"Etika; suara murid dan perlindungan","case_focus":"suara murid dan perlindungan","stem":"Murid meminta memilih isu diskusi sendiri. Salah satu usulan berpotensi membuka pengalaman pribadi teman yang belum memberi persetujuan. Guru ingin menghargai suara murid sekaligus menjaga martabat. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Menawarkan pembahasan kasus rekaan dengan persoalan serupa.","Membiarkan identitas teman dibahas karena keputusan berasal dari mayoritas.","Menjelaskan batas pilihan dan melibatkan murid mencari bentuk diskusi yang aman."],"key":["T","F","T"],"why":"Pilihan murid penting, tetapi tidak menghapus tanggung jawab etis guru. Bimbingan dapat mempertahankan isu sambil melindungi martabat.","explanations":["Pilihan menjaga substansi isu sambil mengurangi paparan pengalaman pribadi.","Persetujuan mayoritas tidak menggantikan perlindungan pihak yang terdampak.","Guru menghormati otonomi dengan alasan perlindungan yang terbuka."]},{"package":3,"id":67,"uid":"p3-067","section":"PU","code":"K.2","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Growth mindset; refleksi diri guru","case_focus":"bias ekspektasi guru","stem":"Dari rekaman pelajaran, guru melihat ia memberi pertanyaan menantang kepada murid tertentu dan pertanyaan ingatan kepada yang lain. Nilai awal mereka ternyata sebanding. Langkah refleksi paling tepat adalah ...","options":["Menelaah ekspektasi dan merancang kesempatan menalar yang adil.","Membandingkan nilai akhir saja untuk menyatakan pola pertanyaan guru sudah adil.","Mengganti semua pertanyaan menjadi hafalan.","Menjadikan kesan kelancaran berbicara sebagai dasar tetap pembagian pertanyaan."],"key":"A","why":"Refleksi berbasis bukti dapat mengungkap bias ekspektasi. Perbaikannya memberi kesempatan yang sesuai, bukan meniadakan tantangan.","explanations":["Bukti menunjukkan keputusan guru perlu ditinjau, bukan kemampuan murid diasumsikan.","Nilai sebanding tidak otomatis membuktikan kesempatan menalar sebanding; proses pemberian pertanyaan tetap perlu ditelaah.","Keseragaman rendah menghilangkan kesempatan menalar bagi semua.","Kelancaran bicara perlu dibedakan dari kesiapan menalar; bukti nilai yang sebanding menuntut pemeriksaan ekspektasi."]},{"package":3,"id":68,"uid":"p3-068","section":"PU","code":"S.2","type":"MCMA","difficulty":"sedang","cp_element":null,"ppg_concept":"Inklusi; kemitraan keluarga","case_focus":"dukungan kolaboratif","stem":"Sekolah ingin menyesuaikan dukungan untuk murid yang sering kewalahan oleh tugas. Guru memiliki catatan kelas; keluarga melaporkan murid dapat bekerja baik dengan jadwal singkat. Pilih semua langkah kolaboratif yang tepat.","options":["Menentukan dukungan hanya dari catatan salah satu pihak.","Menyepakati dukungan terbatas dan bukti kemajuan yang dipantau bersama.","Melibatkan murid menjelaskan bagian tugas yang paling membebaninya.","Menganggap laporan keluarga pasti membantah laporan guru."],"key":["B","C"],"why":"Kolaborasi memadukan bukti dan pengalaman pihak terkait. Dukungan perlu ditinjau dari dampak, bukan ditetapkan sebagai label tetap.","explanations":["Satu sudut pandang belum memeriksa perbedaan kondisi.","Kesepakatan membuat dukungan dapat dinilai dampaknya.","Suara murid membantu memahami hambatan yang dialami.","Dua laporan dapat menggambarkan kondisi yang berbeda, bukan saling meniadakan."]},{"package":3,"id":69,"uid":"p3-069","section":"PU","code":"S.3","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Lesson study; komunitas profesi","case_focus":"lesson study","stem":"Komunitas guru mengadakan lesson study. Pengamat cenderung menilai gaya bicara guru model, padahal fokus yang disepakati ialah cara murid menghubungkan dua konsep. Kontribusi paling tepat adalah ...","options":["Membandingkan jumlah slide tiap guru model.","Membandingkan kejelasan penjelasan guru model sebagai satu-satunya fokus telaah.","Menelaah catatan respons murid bersama komunitas.","Meminta guru model menjelaskan maksud setiap langkah tanpa membawa catatan respons murid."],"key":"C","why":"Partisipasi komunitas berfokus pada pembelajaran murid dan perbaikan rancangan, bukan sekadar evaluasi penampilan rekan.","explanations":["Jumlah slide tidak menunjukkan hubungan konsep yang dibangun murid.","Kejelasan guru dapat relevan tetapi fokus yang disepakati ialah hubungan konsep dalam respons murid.","Catatan memberi dasar pembahasan profesi sesuai fokus.","Penjelasan maksud membantu membaca rancangan, tetapi belum menunjukkan bagaimana murid menghubungkan konsep dalam pelaksanaan."]},{"package":3,"id":70,"uid":"p3-070","section":"PU","code":"PF.1","type":"Kategori","difficulty":"sedang","cp_element":null,"ppg_concept":"Filosofi pendidikan; kemandirian","case_focus":"otonomi sesuai jenjang","stem":"Di sekolah dasar, murid ingin menentukan aturan penggunaan pojok baca. Guru menargetkan kemandirian sekaligus tanggung jawab terhadap hak teman. Nilai tindakan berikut sebagai Tepat atau Tidak tepat.","options":["Membimbing murid menimbang akibat aturan bagi pembaca lain.","Menyepakati aturan yang dapat ditinjau setelah dicoba.","Menyerahkan semua konflik kepada murid tanpa dukungan karena otonomi berarti guru tidak terlibat."],"key":["T","T","F"],"why":"Tujuan pendidikan menuntun perkembangan otonomi melalui bimbingan, bukan kebebasan tanpa tanggung jawab atau seluruh keputusan selalu diambil guru.","explanations":["Bimbingan mengembangkan keputusan sesuai tujuan pendidikan dasar.","Peninjauan memberi pengalaman bertanggung jawab atas keputusan.","Pelepasan dukungan tidak sama dengan pengembangan kemandirian."]},{"package":3,"id":71,"uid":"p3-071","section":"PU","code":"PF.3","type":"PG","difficulty":"menantang","cp_element":null,"ppg_concept":"PF.3; kebutuhan dan karakteristik materi","case_focus":"motivasi atau prasyarat","stem":"Murid menolak tugas grafik dan disebut kurang motivasi. Percakapan menunjukkan ia ingin menyelesaikannya tetapi tidak memahami skala sumbu; pada tugas dengan skala sederhana ia bertahan lebih lama. Keputusan awal terbaik adalah ...","options":["Menambah hadiah penyelesaian sambil mempertahankan skala yang belum dipahami.","Menguji prasyarat skala dan menyiapkan dukungan yang sesuai.","Menetapkan murid tidak berminat pada semua kegiatan numerik.","Mengurangi seluruh data grafik menjadi satu angka agar murid segera menyelesaikan tugas."],"key":"B","why":"Penolakan tugas dapat berkaitan dengan tuntutan prasyarat. Guru perlu membedakan dugaan motivasi dari kesulitan materi sebelum memilih bantuan.","explanations":["Insentif belum mengatasi prasyarat skala yang ditunjukkan bukti percakapan dan tugas.","Bukti mengarahkan penafsiran kebutuhan materi.","Satu kesulitan tidak membenarkan label minat menyeluruh.","Penyederhanaan dapat mengurangi beban, tetapi penghilangan hubungan skala belum membantu mencapai kemampuan membaca grafik."]},{"package":3,"id":72,"uid":"p3-072","section":"PU","code":"PF.5","type":"MCMA","difficulty":"menantang","cp_element":null,"ppg_concept":"PF.5; transfer dan retensi","case_focus":"transfer tertunda","stem":"Guru mencoba strategi penjelasan berpasangan. Nilai tugas langsung meningkat, tetapi ia ingin mengetahui apakah murid dapat memakai konsep secara mandiri beberapa hari kemudian. Pilih semua langkah evaluasi praktik yang tepat.","options":["Memberi tugas baru yang setara setelah jeda dengan kriteria yang sama.","Menggunakan kesukaan murid sebagai bukti tunggal keberhasilan.","Membandingkan alasan murid saat bekerja sendiri dengan saat berpasangan.","Menyimpulkan nilai langsung sudah cukup membuktikan dampak jangka panjang."],"key":["A","C"],"why":"Pengembangan praktik perlu bukti sesuai klaim. Jika klaimnya penerapan mandiri setelah jeda, asesmen harus menghadirkan kondisi itu.","explanations":["Bukti menilai retensi dan transfer, bukan sekadar ingatan contoh.","Kesukaan tidak menunjukkan penerapan mandiri setelah jeda.","Perbandingan menilai apakah bantuan berubah menjadi pemahaman individu.","Bukti segera tidak menjamin ketahanan pemahaman."]},{"package":3,"id":73,"uid":"p3-073","section":"PU","code":"K.3","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"K.3; disiplin positif","case_focus":"disiplin positif","stem":"Murid berulang kali meninggalkan alat bersama dalam keadaan berantakan. Teguran singkat belum mengubah kebiasaan. Guru ingin disiplin positif yang membangun tanggung jawab. Keputusan terbaik adalah ...","options":["Mengganti alat bersama dengan alat individual agar kewajiban merapikan tidak perlu dibahas lagi.","Mengabaikan kondisi alat agar hubungan tetap nyaman.","Menambah frekuensi teguran dengan prosedur merapikan yang tetap belum diajarkan.","Menyepakati pemulihan dampak dan meninjau kebiasaan merapikan."],"key":"D","why":"Disiplin positif bukan ketiadaan batas. Guru menuntun pemulihan dampak dan latihan perilaku yang diharapkan secara konsisten.","explanations":["Pembagian alat dapat mengubah logistik, tetapi belum membangun tanggung jawab atas dampak perilaku pada pengguna lain.","Pengabaian membiarkan dampak pada pengguna lain.","Pengulangan teguran belum memberi latihan perilaku dan pemulihan dampak yang diperlukan.","Tindakan menghubungkan tanggung jawab dengan perilaku yang dapat dipelajari."]},{"package":3,"id":74,"uid":"p3-074","section":"PU","code":"S.1","type":"Kategori","difficulty":"sedang","cp_element":null,"ppg_concept":"Komunikasi empatik dan asertif","case_focus":"empati dan batas","stem":"Murid mengatakan penjelasan guru terlalu cepat. Guru merasa sudah mengulang beberapa kali. Ia ingin merespons empatik sekaligus menjaga kebutuhan kelas. Nilai respons berikut sebagai Tepat atau Tidak tepat.","options":["Menjelaskan bahwa pengulangan membuktikan semua murid seharusnya paham.","Meminta contoh bagian yang sulit lalu memparafrasekan keluhan murid.","Menyepakati cara memberi tanda ketika penjelasan perlu dijeda."],"key":["F","T","T"],"why":"Empati tidak berarti menerima semua tuntutan tanpa pertimbangan. Guru memahami hambatan dahulu dan membangun komunikasi yang dapat digunakan bersama.","explanations":["Pengulangan tidak membuktikan penerima memaknai penjelasan.","Klarifikasi dan parafrasa memeriksa pemahaman atas pengalaman murid.","Saluran komunikasi membantu menanggapi kebutuhan secara terarah."]},{"package":3,"id":75,"uid":"p3-075","section":"PU","code":"S.2","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"PjBL; kolaborasi pembelajaran","case_focus":"koordinasi proyek","stem":"Dalam proyek pameran, mitra menuntut produk cepat sementara guru ingin murid belajar merencanakan dan mengevaluasi proses. Langkah kolaborasi paling tepat adalah ...","options":["Menyepakati tonggak dan bukti proses dengan mitra serta murid.","Membiarkan mitra menyelesaikan bagian sulit atas nama murid.","Membebaskan kelompok menentukan jadwal masing-masing tanpa menyepakati tonggak dengan mitra.","Memakai mutu produk akhir sebagai satu-satunya bukti meski tujuan mencakup perencanaan."],"key":"A","why":"PjBL memerlukan pengelolaan proyek dan evaluasi pengalaman. Kolaborasi menjaga tujuan belajar ketika kebutuhan produk pihak lain juga perlu dipertimbangkan.","explanations":["Kesepakatan menjaga kebutuhan produk dan tujuan belajar.","Produk selesai belum menunjukkan pembelajaran murid.","Pilihan murid penting, tetapi koordinasi kebutuhan produk dan bukti proses memerlukan kesepakatan lintas pihak.","Produk penting, tetapi tidak cukup untuk menilai sasaran proses yang telah dinyatakan."]},{"package":3,"id":76,"uid":"p3-076","section":"PU","code":"K.2","type":"MCMA","difficulty":"sedang","cp_element":null,"ppg_concept":"K.2; growth mindset guru","case_focus":"refleksi batas profesional","stem":"Guru merasa semua kegagalan murid merupakan kesalahan dirinya, lalu menambah bantuan hingga murid tidak lagi mencoba sendiri. Pilih langkah refleksi yang tepat.","options":["Menghentikan seluruh bantuan agar murid sepenuhnya mandiri.","Memilah bukti tentang kebutuhan murid dan dampak bantuan yang diberikan.","Menganggap kerja keras guru selalu menjamin hasil yang sama untuk semua murid.","Menyepakati dengan rekan kapan bantuan ditambah atau dikurangi berdasarkan bukti."],"key":["B","D"],"why":"Refleksi bertumbuh bukan menyalahkan diri secara mutlak. Guru bertanggung jawab memperbaiki tindakan sambil menjaga kesempatan murid membangun kemandirian.","explanations":["Penghentian seragam mengabaikan kebutuhan yang nyata.","Pemisahan membantu menilai kontribusi keputusan guru secara proporsional.","Hasil juga dipengaruhi kebutuhan dan kondisi yang berbeda.","Kriteria membantu perbaikan praktik yang dapat ditinjau."]},{"package":3,"id":77,"uid":"p3-077","section":"PU","code":"P.1","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"P.1; refleksi dan penerapan","case_focus":"refleksi menjadi rencana","stem":"Setelah tugas penyelidikan, murid menulis “harus lebih teliti” tetapi terus mengulang kesalahan memilih bukti. Guru ingin refleksi mengubah cara belajar. Respons terbaik adalah ...","options":["Meminta refleksi memakai istilah teori yang lebih lengkap.","Meminta murid mengurutkan kesulitan yang dirasakan tanpa menghubungkannya dengan rencana berikutnya.","Mengaitkan satu kesalahan dengan langkah pemeriksaan bukti berikutnya.","Menerima semua refleksi sebagai bukti pemahaman yang sama."],"key":"C","why":"Refleksi bermakna menghasilkan langkah yang dapat dicoba dan diperiksa. Pernyataan umum belum menunjukkan murid memahami perubahan proses yang diperlukan.","explanations":["Kelancaran istilah tidak menjamin refleksi menghasilkan langkah pemeriksaan bukti yang dapat dicoba.","Pemetaan kesulitan membantu refleksi, tetapi belum mengubah langkah memeriksa bukti yang ditargetkan.","Rencana spesifik menghubungkan pengalaman dan tindakan baru.","Refleksi dapat berbeda tingkat keterkaitannya dengan proses belajar."]},{"package":3,"id":78,"uid":"p3-078","section":"PU","code":"S.3","type":"Kategori","difficulty":"sedang","cp_element":null,"ppg_concept":"S.3; komunitas belajar","case_focus":"adaptasi teori komunitas","stem":"Komunitas memperkenalkan strategi diskusi yang berhasil di kelas kecil. Guru mengajar kelas besar dengan waktu terbatas. Nilai kontribusi berikut sebagai Tepat atau Tidak tepat.","options":["Mengajukan adaptasi peran dan melaporkan bukti penerapannya ke komunitas.","Menyalin seluruh prosedur sebagai kewajiban semua sekolah.","Membahas bagian prinsip yang perlu dipertahankan dan bagian teknis yang dapat diubah."],"key":["T","F","T"],"why":"Kegiatan komunitas perlu mengembangkan pengetahuan penerapan, bukan sekadar mengedarkan prosedur. Adaptasi tetap harus dapat diperiksa terhadap tujuan.","explanations":["Adaptasi berkonteks menjadi bahan belajar profesional bersama.","Keberhasilan satu konteks tidak membenarkan penerapan seragam.","Pembedaan membantu komunitas memahami batas adaptasi."]},{"package":3,"id":79,"uid":"p3-079","section":"PU","code":"P.4","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Literasi digital; etika AI","case_focus":"AI dan kepengarangan","stem":"Murid memakai AI untuk menyusun draf laporan, tetapi penjelasan lisannya tidak sesuai dengan klaim dalam draf. Aturan tugas mengizinkan AI sebagai bantuan dengan pengungkapan penggunaannya. Tindakan guru paling tepat adalah ...","options":["Melarang semua bantuan digital secara permanen setelah satu kasus.","Meminta jejak penggunaan AI dan penjelasan ulang klaim berbukti.","Memakai kelancaran draf sebagai bukti utama bahwa seluruh klaim sudah dipahami.","Meminta murid mengganti semua kalimat draf dengan sinonim sebelum menilai proses penggunaannya."],"key":"B","why":"Etika AI dinilai sesuai aturan yang sudah diketahui. Guru menelaah kepengarangan, bukti klaim, dan pemahaman, bukan hanya mendeteksi gaya bahasa.","explanations":["Larangan menyeluruh tidak mengikuti aturan dan kebutuhan kasus.","Bukti proses dan pemahaman menilai tanggung jawab kepengarangan.","Kelancaran tulisan perlu dibedakan dari kepengarangan dan penguasaan klaim pada aturan bantuan AI yang diberikan.","Perubahan redaksi tidak menunjukkan kepengarangan, ketepatan klaim, atau pemahaman terhadap isi yang dibantu AI."]},{"package":3,"id":80,"uid":"p3-080","section":"PU","code":"P.6","type":"MCMA","difficulty":"menantang","cp_element":null,"ppg_concept":"Rubrik; assessment for learning","case_focus":"rubrik sesuai tujuan","stem":"Guru menilai dua sasaran: ketepatan penalaran dan kualitas penyajian laporan. Ia membutuhkan informasi bagian yang perlu ditindaklanjuti, bukan hanya urutan nilai akhir. Pilih semua rancangan asesmen yang tepat.","options":["Memakai kriteria terpisah dengan deskripsi capaian untuk kedua sasaran.","Mengembalikan hasil per kriteria beserta bukti pada laporan.","Memberi satu kesan umum tanpa menunjukkan dimensi yang dinilai.","Menentukan tindak lanjut dari pola capaian pada tiap kriteria."],"key":["A","B","D"],"why":"Rubrik analitik sesuai kebutuhan informasi per dimensi. Rubrik holistik dapat berguna untuk tujuan lain, tetapi satu kesan umum tidak cukup untuk diagnosis yang dinyatakan.","explanations":["Pemisahan membantu diagnosis kebutuhan per dimensi.","Umpan balik menghubungkan penilaian dengan bagian yang dapat diperbaiki.","Kesan tunggal tidak cukup memberi informasi rinci yang diminta.","Tindak lanjut memanfaatkan informasi analitik yang dikumpulkan."]}]},{"id":4,"title":"Paket 4","version":"2026-11-18.1","file":"paket_4.json","reviewFile":"references/Paket_4_dan_Pembahasan.md","questions":[{"package":4,"id":1,"uid":"p4-001","section":"PCK","code":"P.1","type":"PG","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"Pembentukan konsep; contoh pembeda","case_focus":"prioritas AND OR","stem":"Query untuk menampilkan peserta aktif dari kelas A atau B juga menampilkan peserta tidak aktif di kelas B. Murid memakai aktif AND kelas_A OR kelas_B. Langkah guru paling tepat adalah ...","options":["Mengurutkan hasil menurut status untuk memeriksa peserta aktif.","Menguji query dengan peserta aktif dari kedua kelas.","Menelusuri logika pada peserta tidak aktif di B.","Memisahkan kondisi tiap kelas lalu membandingkan jumlah hasil saja."],"key":"C","why":"Pada SQL, AND didahulukan daripada OR. Murid perlu menghubungkan pengelompokan logika dengan kebutuhan, bukan sekadar menambah tanda kurung secara acak.","explanations":["Urutan membantu melihat hasil tetapi tidak menjelaskan pengelompokan kondisi.","Data itu tidak membedakan dua pengelompokan kondisi.","Kasus ini membedakan makna aktif AND (A OR B).","Jumlah dapat menyamarkan baris yang salah lolos dan belum menjelaskan pengelompokan."]},{"package":4,"id":2,"uid":"p4-002","section":"PCK","code":"P.6","type":"Kategori","difficulty":"menantang","cp_element":"Basis Data","ppg_concept":"Asesmen diagnosis lintas representasi","case_focus":"perkalian baris gabungan","stem":"Laporan menggabungkan tabel peserta dengan dua catatan prestasi dan tiga catatan kehadiran miliknya. Total prestasi terhitung berulang. Guru menilai diagnosis murid. Nilai bukti berikut sebagai Tepat atau Tidak tepat.","options":["Murid menggambar enam pasangan baris sebelum menghitung total.","Murid mengganti SUM dengan COUNT dan menyatakan masalah selesai.","Murid menjelaskan alasan merangkum masing-masing sumber sebelum menggabungkan."],"key":["T","F","T"],"why":"Kunci diagnosis ialah unit baris hasil gabungan. Dua sumber banyak dapat saling menggandakan, meskipun tiap kondisi JOIN benar.","explanations":["Pasangan memperlihatkan perkalian dua relasi banyak.","Pergantian agregat tidak otomatis memperbaiki unit hitung.","Ringkasan dapat mencegah penggandaan fakta yang independen."]},{"package":4,"id":3,"uid":"p4-003","section":"PCK","code":"PF.3","type":"PG","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"PF.3; prasyarat materi","case_focus":"pembagian integer","stem":"Sebelum membuat laporan persentase, guru menemukan murid dapat membagi di kalkulator tetapi heran hasil pembagian integer pada alat SQL latihan adalah 0 untuk 1/2. Pertanyaan awal terbaik adalah ...","options":["Tipe apa yang dipakai operasi pembagiannya?","Apakah formatnya sudah persen?","Berapa digit desimal yang ditampilkan?","Apakah penyebut pada laporan sudah berisi jumlah seluruh peserta?"],"key":"A","why":"Perilaku pembagian bergantung pada tipe dan sistem yang dipakai. Stimulus telah menyatakan alat melakukan pembagian integer; diagnosis perlu memisahkan operasi dari format persen.","explanations":["Pertanyaan menargetkan prasyarat representasi operasi.","Pertanyaan format masuk akal tetapi belum memeriksa operasi yang menghasilkan nol.","Format dapat diuji kemudian, tetapi tipe operasi adalah prasyarat yang lebih langsung.","Penyebut relevan pada laporan tetapi kasus 1/2 sudah menunjukkan persoalan tipe."]},{"package":4,"id":4,"uid":"p4-004","section":"PCK","code":"PF.2","type":"MCMA","difficulty":"menantang","cp_element":"Basis Data","ppg_concept":"Model mental query","case_focus":"scope subquery","stem":"Subquery yang seharusnya menghitung catatan per peserta justru memberi total sama untuk semua peserta karena tidak terhubung ke baris luar. Pilih kegiatan guru yang membantu murid memahami scope.","options":["Memakai data kecil yang total tiap pesertanya berbeda untuk menguji hasil.","Menelusuri dua baris luar dan parameter yang dibaca subquery.","Menambahkan alias keluaran yang lebih rinci sebagai perbaikan utama.","Membandingkan subquery berkorelasi dan tak berkorelasi pada data kecil."],"key":["A","B","D"],"why":"Murid perlu memahami nilai mana yang berubah saat baris luar berubah. Perbaikan sintaks dinilai dari hubungannya dengan kebutuhan per peserta.","explanations":["Data pembeda memperlihatkan apakah hasil benar-benar mengikuti peserta.","Penelusuran menunjukkan apakah perhitungan bergantung pada peserta.","Nama keluaran tidak membuat korelasi antarquery.","Perbandingan memperlihatkan perubahan unit perhitungan."]},{"package":4,"id":5,"uid":"p4-005","section":"PCK","code":"P.2","type":"PG","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"Diferensiasi; scaffolding","case_focus":"hierarki bersiklus","stem":"Dalam tugas hierarki kategori, sebagian murid dapat mengikuti hubungan induk-anak tetapi belum mengenali siklus. Guru ingin memberi bantuan sebelum query penelusuran bertingkat. Pilihan terbaik adalah ...","options":["Memberi bagan besar dan menandai seluruh cabang yang memiliki banyak anak.","Meminta murid mengisi bagian kosong pada query rekursif yang disediakan.","Menguji hierarki tanpa siklus dahulu lalu langsung menulis query lengkap.","Menelusuri diagram kecil yang memiliki siklus."],"key":"D","why":"Dukungan menargetkan kesiapan menalar struktur. Menambah kompleksitas query sebelum siklus dipahami tidak membantu kebutuhan yang ditemukan.","explanations":["Banyak anak berbeda dari siklus dan menambah beban representasi.","Dukungan kode belum menargetkan pengenalan siklus pada struktur.","Keberhasilan pada hierarki aman belum mengatasi kebutuhan yang ditemukan.","Jejak mengungkap pengulangan dan kebutuhan menghentikannya."]},{"package":4,"id":6,"uid":"p4-006","section":"PCK","code":"PF.4","type":"Kategori","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"UbD; keselarasan tujuan","case_focus":"median laporan","stem":"Guru merancang unit laporan waktu layanan. Ada beberapa waktu sangat tinggi; pengguna ingin melihat nilai tengah sekaligus sebaran. Nilai keputusan kurikuler berikut sebagai Tepat atau Tidak tepat.","options":["Memakai data berpencilan dan tanpa pencilan untuk menguji alasan pilihan ringkasan.","Meminta murid membandingkan median, rata-rata, dan data asal.","Memakai rubrik yang memeriksa alasan pemilihan ringkasan."],"key":["T","T","T"],"why":"Tujuan unit bukan menghafal fungsi agregat. Bukti akhir harus menunjukkan murid memilih informasi yang tepat ketika pencilan memengaruhi laporan.","explanations":["Data pembanding membantu menilai hubungan ciri data dan tujuan laporan.","Perbandingan menilai pilihan ringkasan terhadap kebutuhan.","Alasan menghubungkan teknik laporan dan tujuan pengguna."]},{"package":4,"id":7,"uid":"p4-007","section":"PCK","code":"P.6","type":"PG","difficulty":"menantang","cp_element":"Basis Data","ppg_concept":"Bukti asesmen sesuai kondisi","case_focus":"durabilitas","stem":"Pada simulasi penyimpanan, aplikasi mengaku selesai sebelum data di buffer ditulis ke penyimpanan persisten. Setelah simulasi listrik putus, data hilang. Bukti pemahaman murid paling kuat adalah ...","options":["Bukti data muncul sesaat setelah disimpan.","Murid menjelaskan hasil uji simpan dan pemulihan setelah gangguan.","Bukti pesan simpan berhasil.","Murid membandingkan isi buffer sebelum dan sesudah tombol Simpan ditekan."],"key":"B","why":"Asesmen durabilitas memerlukan bukti setelah pemulihan. Kasus merujuk alat simulasi, bukan klaim bahwa setiap basis data selalu kehilangan commit pada listrik padam.","explanations":["Bukti ini belum menguji ketahanan setelah pemulihan.","Penjelasan membedakan data sementara dan data yang bertahan.","Pesan dan waktu belum membuktikan data bertahan melewati gangguan.","Perbandingan buffer belum menguji ketahanan penyimpanan persisten."]},{"package":4,"id":8,"uid":"p4-008","section":"PCK","code":"P.5","type":"MCMA","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"Pembelajaran kontekstual; CRT","case_focus":"LIKE literal","stem":"Arsip motif lokal memakai tanda % sebagai bagian kode. Murid memakai LIKE dan memperoleh banyak kode lain. Guru ingin mempertahankan makna sumber lokal. Pilih kegiatan yang tepat.","options":["Membandingkan pencarian tanda literal dan wildcard pada contoh kode arsip.","Menghapus tanda dari semua kode agar query lebih mudah.","Membaca aturan escape sistem SQL yang dipakai lalu mengujinya.","Menganggap setiap hasil yang lebih banyak pasti lebih lengkap."],"key":["A","C"],"why":"Sumber lokal dipahami bersama aturan teknis pencarian. Simbol dalam kode tidak boleh diam-diam ditafsirkan sebagai pola lalu dianggap data lain cocok.","explanations":["Perbandingan menampakkan perbedaan makna simbol dalam data dan pola.","Penghapusan mengubah sistem kode sumber tanpa kebutuhan.","Aturan alat diperlukan untuk mempertahankan simbol literal.","Banyak hasil dapat berasal dari pola yang tidak sesuai kebutuhan."]},{"package":4,"id":9,"uid":"p4-009","section":"PCK","code":"PF.2","type":"PG","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"Ketepatan materi dan demonstrasi","case_focus":"UNION dan posisi kolom","stem":"Dua SELECT akan digabungkan dengan UNION. Kolomnya bertipe kompatibel tetapi posisi kota dan kategori tertukar. Guru ingin murid menjelaskan mengapa hasilnya tampak sah namun salah makna. Kegiatan terbaik adalah ...","options":["Menyamakan alias kolom lalu memeriksa keberhasilan eksekusi.","Menguji bahwa query berhasil dijalankan tanpa pesan error.","Melacak arti tiap posisi kolom pada kedua SELECT.","Mengurutkan seluruh hasil menurut kolom pertama."],"key":"C","why":"UNION menyelaraskan kolom menurut posisi. Tipe yang kompatibel tidak cukup membuktikan dua keluaran mempunyai arti yang selaras.","explanations":["Alias keluaran tidak menyelaraskan arti posisi kolom pada SELECT yang berbeda.","Keberhasilan sintaks belum menjamin makna kolom sesuai.","Pelacakan menghubungkan kompatibilitas tipe dan kesesuaian makna.","Urutan tidak menukar kembali isi yang salah posisi."]},{"package":4,"id":10,"uid":"p4-010","section":"PCK","code":"P.2","type":"Kategori","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"Dukungan sesuai miskonsepsi","case_focus":"nol awal kode","stem":"Kode wilayah seperti 0012 kehilangan nol awal ketika diimpor sebagai angka. Sebagian murid masih menganggap semua deretan digit adalah bilangan untuk dihitung. Nilai dukungan berikut sebagai Tepat atau Tidak tepat.","options":["Membandingkan fungsi kode wilayah dan jumlah penduduk sebelum memilih tipe.","Mengajarkan semua deretan digit harus bertipe numerik.","Membatasi asesmen pada kecepatan memasukkan kode."],"key":["T","F","F"],"why":"Dukungan menghubungkan makna data dengan operasi yang dibutuhkan. Nol awal adalah bagian kode ketika kode dipakai sebagai pengenal, bukan nilai hitung.","explanations":["Kebutuhan operasi membedakan identitas teks dan kuantitas.","Bentuk digit tidak selalu menunjukkan kuantitas.","Kecepatan tidak menunjukkan alasan pemilihan representasi."]},{"package":4,"id":11,"uid":"p4-011","section":"PCK","code":"P.1","type":"PG","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"Pemahaman konseptual","case_focus":"self join peran","stem":"Murid mengira satu tabel pegawai hanya boleh muncul sekali dalam query. Guru ingin membangun konsep dua peran pada self join untuk pegawai dan atasannya. Representasi terbaik adalah ...","options":["Dua kartu peran untuk menelusuri pasangan baris.","Dua salinan tabel pegawai.","Daftar pegawai beserta nama atasannya.","Contoh query jadi dengan latihan mengganti nama alias secara bergantian."],"key":"A","why":"Alias dapat mewakili dua peran logis dari sumber yang sama. Representasi perlu menjelaskan pasangan baris, bukan membuat duplikasi penyimpanan.","explanations":["Peran membantu membedakan baris yang dibandingkan.","Duplikasi penyimpanan dapat memperkuat anggapan bahwa satu tabel tidak boleh dipakai dua peran.","Daftar memudahkan pembacaan tetapi belum menjelaskan dua peran dari sumber yang sama.","Penggantian alias saja belum memberi makna pasangan baris."]},{"package":4,"id":12,"uid":"p4-012","section":"PCK","code":"P.4","type":"MCMA","difficulty":"menantang","cp_element":"Basis Data","ppg_concept":"TPACK; literasi pengukuran","case_focus":"latensi query end to end","stem":"Waktu aplikasi menampilkan laporan 5 detik, tetapi log basis data mencatat query selesai dalam 0,1 detik. Guru memakai alat ukur untuk menilai dugaan murid bahwa SQL pasti lambat. Pilih langkah yang tepat.","options":["Menambah indeks segera sebagai satu-satunya diagnosis.","Memisahkan waktu query, pengiriman data, dan render hasil.","Menyamakan rentang pengukuran sebelum membandingkan angka.","Menguji dugaan dengan data dan kondisi jaringan terkontrol."],"key":["B","C","D"],"why":"Alat harus ditafsirkan menurut bagian proses yang diukur. Waktu respons akhir tidak identik dengan waktu mesin basis data.","explanations":["Bukti awal belum menunjukkan waktu habis pada eksekusi query.","Pemisahan mengungkap lokasi biaya yang mungkin berbeda.","Dua angka harus mengukur tahap yang sebanding.","Kontrol membantu membedakan penyebab keterlambatan."]},{"package":4,"id":13,"uid":"p4-013","section":"PCK","code":"PF.5","type":"PG","difficulty":"sedang","cp_element":"Basis Data","ppg_concept":"Pengembangan praktik berbasis bukti","case_focus":"populasi log","stem":"Guru ingin memperbaiki tugas analisis log. Murid menyimpulkan layanan sangat andal, tetapi log latihan hanya berisi permintaan yang berhasil. Langkah pengembangan praktik paling tepat adalah ...","options":["Menambah variasi waktu respons pada log berhasil agar datanya lebih kaya.","Meminta murid membandingkan dua grafik dari log berhasil yang sama.","Menaikkan jumlah data lalu mengulang tugas dan membandingkan skor.","Menguji tugas baru dengan log sukses dan gagal."],"key":"D","why":"Perbaikan praktik perlu mengajarkan bahwa simpulan dibatasi sumber datanya. Catatan sukses saja tidak mewakili seluruh permintaan.","explanations":["Variasi belum memperbaiki cakupan permintaan yang tidak tercatat.","Bentuk grafik tidak memperbaiki cakupan bukti keandalan.","Skor dapat naik tanpa pemahaman batas populasi log.","Perubahan memungkinkan pemeriksaan alasan batas simpulan murid."]},{"package":4,"id":14,"uid":"p4-014","section":"PCK","code":"P.1","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Discovery dengan pembanding","case_focus":"argumen default","stem":"Pada contoh Python, list sebagai argumen default dipakai kembali pada pemanggilan berikutnya. Murid mengira list baru selalu dibuat setiap fungsi dipanggil. Nilai kegiatan berikut sebagai Tepat atau Tidak tepat.","options":["Mencatat isi list pada dua pemanggilan berturut-turut.","Membandingkan default mutable dengan pembuatan list baru di dalam fungsi.","Mengajarkan semua argumen default selalu dibuat ulang saat pemanggilan."],"key":["T","T","F"],"why":"Murid perlu memahami waktu evaluasi default dan keadaan object. Contoh ini tidak digeneralisasi sebagai perilaku semua bahasa.","explanations":["Jejak memperlihatkan keadaan yang bertahan antar-pemanggilan.","Perbandingan menampakkan waktu pembuatan object.","Pernyataan itu bertentangan dengan kasus Python yang diberikan."]},{"package":4,"id":15,"uid":"p4-015","section":"PCK","code":"P.6","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Asesmen dengan kasus pembeda","case_focus":"sorting stabil","stem":"Murid melakukan dua tahap sorting dan ingin mempertahankan urutan tahap pertama ketika kunci tahap kedua seri. Bukti pemahaman sorting stabil paling kuat adalah ...","options":["Urutan benar pada data yang semua kuncinya berbeda.","Prediksi item seri pada dua tahap sorting.","Perbandingan waktu dua implementasi.","Penjelasan arah naik dan turun untuk setiap kolom yang dipakai."],"key":"B","why":"Asesmen perlu menghadirkan beberapa item dengan kunci sama. Stabil berarti mempertahankan urutan relatif item yang setara menurut pembanding.","explanations":["Kasus tanpa nilai seri tidak membedakan sifat stabil.","Item seri menjadi kasus pembeda sifat stabil.","Kecepatan bukan bukti pemertahanan urutan relatif item seri.","Arah urutan relevan tetapi belum membuktikan perlakuan terhadap nilai seri."]},{"package":4,"id":16,"uid":"p4-016","section":"PCK","code":"PF.2","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Penalaran teknis melalui eksperimen","case_focus":"resource file","stem":"Program membuka file, lalu gagal saat memproses isinya. Murid menutup file hanya pada akhir alur sukses. Guru ingin murid memahami pengelolaan resource. Pilih kegiatan yang tepat.","options":["Menguji jalur sukses dan jalur gagal sambil memantau penutupan resource.","Menyembunyikan pesan gagal supaya pengguna melihat layar normal.","Membandingkan penutupan di akhir biasa dengan mekanisme cleanup yang dijamin bahasa.","Menambah jumlah file uji tanpa memeriksa status resource."],"key":["A","C"],"why":"Pengelolaan resource perlu mencakup alur gagal. Mekanisme seperti context manager atau finally dipilih sesuai bahasa dan jenis resource.","explanations":["Dua jalur menguji jaminan pelepasan, bukan hasil normal saja.","Pesan yang hilang tidak menutup resource.","Perbandingan menunjukkan kebutuhan cleanup saat alur terputus.","Banyak file tidak otomatis menunjukkan resource dilepas."]},{"package":4,"id":17,"uid":"p4-017","section":"PCK","code":"PF.4","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"UbD; bukti pemahaman","case_focus":"serialisasi object","stem":"Guru merancang unit penyimpanan object ke JSON. Murid harus mampu menjelaskan data yang bertahan dan perilaku yang perlu dibangun kembali. Tujuan asesmen paling tepat adalah ...","options":["Penjelasan struktur JSON bersarang.","Perbandingan ukuran file hasil ekspor.","Perbandingan object sebelum dan sesudah dimuat.","Murid berhasil membaca ulang seluruh field yang ditulis ke JSON."],"key":"C","why":"Serialisasi data tidak otomatis menyimpan method atau seluruh identitas runtime. Bukti akhir harus menilai penjelasan batas representasi tersebut.","explanations":["Struktur JSON penting tetapi belum menunjukkan batas serialisasi object.","Ukuran file bukan bukti langsung data dan perilaku yang bertahan.","Perbandingan terhadap tujuan harus menjelaskan data dan perilaku yang perlu dibangun kembali.","Keberhasilan field belum menguji pemahaman perilaku atau identitas runtime."]},{"package":4,"id":18,"uid":"p4-018","section":"PCK","code":"PF.3","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Diagnosis prasyarat object","case_focus":"identitas dan kesamaan","stem":"Sebelum unit koleksi object, murid dapat membandingkan atribut tetapi menyamakan dua object dengan isi sama sebagai satu object yang identik. Nilai pemetaan prasyarat berikut sebagai Tepat atau Tidak tepat.","options":["Menganggap kesamaan isi selalu membuktikan satu identitas object.","Memakai kesamaan seluruh atribut sebagai satu-satunya bukti kesamaan identitas.","Menetapkan aturan pembandingan yang digunakan bahasa atau class pada contoh."],"key":["F","F","T"],"why":"Guru perlu memisahkan konsep identitas dari kesetaraan nilai sebelum koleksi memakai pembanding. Perilaku operator tidak boleh diasumsikan sama pada semua bahasa.","explanations":["Dua object berbeda dapat memiliki isi setara.","Atribut setara masih dapat dimiliki dua object yang berbeda.","Aturan perlu jelas agar hasil perbandingan dapat ditafsirkan."]},{"package":4,"id":19,"uid":"p4-019","section":"PCK","code":"P.3","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"PSE; penyelidikan berbukti","case_focus":"shared counter","stem":"Dalam proyek penghitung pekerjaan, dua tugas paralel membaca nilai counter yang sama lalu masing-masing menulis tambah satu. Hasil kurang dari dugaan membuat murid saling menyalahkan. Respons guru terbaik adalah ...","options":["Menelusuri jejak baca-tulis bersama secara netral.","Membandingkan hasil akhir anggota lalu memakai versi yang paling sering benar.","Mengulang eksekusi sambil mencatat jumlah akhir dari beberapa percobaan.","Membagi kepemilikan counter per anggota sebelum mengubah rancangan program."],"key":"A","why":"Diskusi bermakna menelusuri bukti sebelum menyalahkan orang. Operasi tambah yang terdiri dari baca dan tulis dapat saling menimpa jika tidak dikoordinasikan.","explanations":["Jejak bersama menargetkan penyebab teknis dan memulihkan diskusi.","Frekuensi keberhasilan belum menjelaskan pembaruan yang saling menimpa.","Catatan hasil berguna tetapi belum menjelaskan urutan operasi atau memulihkan diskusi yang saling menyalahkan.","Pembagian peran belum menjelaskan risiko operasi pada counter bersama."]},{"package":4,"id":20,"uid":"p4-020","section":"PCK","code":"P.1","type":"MCMA","difficulty":"menantang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Representasi dan contoh tandingan","case_focus":"hash collision","stem":"Murid menganggap hash yang sama berarti dua nilai pasti sama. Guru mengajarkan struktur pencarian berbasis hash. Pilih kegiatan yang membangun konsep tepat.","options":["Meminta murid mengurutkan nilai menurut warna label.","Memakai contoh dua nilai berbeda dengan hash buatan yang sama.","Mengajarkan bahwa collision selalu berarti program rusak.","Menelusuri pemeriksaan kesamaan nilai setelah kelompok hash ditemukan."],"key":["B","D"],"why":"Hash membantu mempersempit pencarian, tetapi kesamaan hash saja bukan bukti kesamaan nilai. Fungsi hash buatan dipakai agar collision mudah diperiksa.","explanations":["Warna tidak menjelaskan peran hash.","Contoh sederhana menunjukkan kemungkinan collision.","Collision dapat ditangani oleh struktur yang dirancang benar.","Penelusuran membedakan penyaringan kandidat dan penentuan kesamaan."]},{"package":4,"id":21,"uid":"p4-021","section":"PCK","code":"P.5","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Sumber budaya lokal; penyelidikan","case_focus":"atlas gambar","stem":"Murid membuat permainan dari atlas gambar motif daerah dengan izin pemiliknya. Saat satu tile ditampilkan, tepinya mengambil warna tile tetangga. Guru ingin pengalaman lokal itu tetap menjadi bahan belajar pengolahan gambar. Langkah paling tepat adalah ...","options":["Menguji atlas contoh buatan guru.","Menguji batas potongan dan jarak antartile.","Memperkecil seluruh atlas agar lebih ringan saat permainan dijalankan.","Menilai kemiripan motif dari tangkapan layar akhir saja."],"key":"B","why":"Atlas lokal tetap dipakai sebagai sumber belajar. Pemeriksaan area potong dan jarak pemisah membantu murid menjelaskan masuknya warna tetangga, bukan sekadar menghilangkan gejalanya.","explanations":["Contoh pembanding berguna, tetapi belum menelusuri batas potongan pada atlas sumber.","Uji pada atlas lokal menghubungkan artefak dengan representasi sumber yang digunakan.","Ukuran lebih kecil tidak memastikan area potong dan batas sampling benar.","Tangkapan layar tidak cukup menjelaskan asal warna tetangga."]},{"package":4,"id":22,"uid":"p4-022","section":"PCK","code":"PF.2","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Pembentukan konsep dengan perbandingan","case_focus":"kompresi berulang","stem":"Pada latihan ekspor gambar lossy, murid melihat artefak setelah beberapa kali membuka dan menyimpan ulang hasil ekspor. Guru menyiapkan gambar sumber yang sama. Nilai arahan berikut sebagai Tepat atau Tidak tepat.","options":["Membandingkan ekspor sekali dari sumber dengan rangkaian ekspor ulang pada pengaturan terkontrol.","Menyimpulkan bahwa membuka hasil ekspor memulihkan detail sumber.","Menjelaskan bahwa hasil tergantung algoritma dan pengaturan, sambil menelaah artefak contoh."],"key":["T","F","T"],"why":"Kompresi lossy dapat membuang informasi. Ekspor ulang dapat menambah artefak, tetapi besar perubahan tidak dapat digeneralisasi tanpa memperhatikan encoder dan pengaturannya.","explanations":["Perbandingan membantu mengisolasi pengaruh ekspor berulang.","Informasi yang telah dibuang tidak pulih hanya dengan decoding.","Kesimpulan terikat bukti dan tidak menganggap semua encoder berperilaku identik."]},{"package":4,"id":23,"uid":"p4-023","section":"PCK","code":"P.4","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Pemilihan alat diagnosis","case_focus":"module shadowing","stem":"Latihan Python yang semula berjalan gagal setelah murid membuat file random.py. Pesan menyebut atribut modul tidak ditemukan, padahal pustaka standar tersedia. Guru hendak memakai alat diagnosis yang memberi bukti langsung. Pilihan terbaik adalah ...","options":["Membandingkan versi Python semua komputer terlebih dahulu.","Memasang ulang pustaka yang namanya sama melalui pengelola paket.","Memindahkan latihan ke editor yang memberi pelengkapan otomatis.","Menampilkan lokasi modul yang benar-benar diimpor."],"key":"D","why":"Diagnosis memeriksa resolusi impor terlebih dahulu. File lokal yang bernama sama dapat membuat impor menunjuk file tersebut; mengganti nama perlu diikuti pengecekan ulang hasil impor.","explanations":["Versi bisa relevan, tetapi petunjuk perubahan nama file lebih langsung.","Pustaka standar belum terbukti hilang dan instalasi tidak mengatasi penamaan lokal.","Pelengkapan tidak memastikan modul yang dimuat saat eksekusi.","Lokasi impor menguji dugaan file lokal menutupi modul yang dimaksud."]},{"package":4,"id":24,"uid":"p4-024","section":"PCK","code":"P.2","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Diferensiasi berdasarkan diagnosis","case_focus":"konversi tipe","stem":"Form latihan menghasilkan string \"2\" dan \"3\". Saat digabung, layar menampilkan \"23\", bukan jumlah 5. Sebagian murid sudah memahami penjumlahan, tetapi belum membedakan teks dan angka. Pilih dukungan yang sesuai kebutuhan ini.","options":["Menampilkan nilai beserta tipenya sebelum dan sesudah konversi.","Mengulang seluruh unit penjumlahan bilangan bulat.","Membandingkan penggabungan teks dengan penjumlahan hasil konversi yang valid.","Mengganti semua input menjadi pilihan angka tanpa membahas konversi."],"key":["A","C"],"why":"Diferensiasi menargetkan kebutuhan yang teramati: representasi nilai dan operasi. Contoh konversi memakai input valid; penanganan input tidak valid dapat menyusul setelah konsep dasarnya jelas.","explanations":["Dukungan menghubungkan representasi input dengan operasi.","Bukti belum menunjukkan masalah pada konsep penjumlahan.","Contoh berpasangan menargetkan perbedaan operasi yang belum dipahami.","Antarmuka baru dapat menutupi kesenjangan konsep tipe."]},{"package":4,"id":25,"uid":"p4-025","section":"PCK","code":"PF.5","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Refleksi empiris; evaluasi perbaikan","case_focus":"lazy evaluation","stem":"Setelah demonstrasi generator, banyak murid masih mengira seluruh nilainya dihitung saat generator dibuat. Guru ingin memperbaiki cara mengajarnya dan memeriksa dampaknya. Rencana terbaik adalah ...","options":["Menguji jejak evaluasi lalu tugas prediksi baru.","Demonstrasi ulang dengan angka berbeda.","Mendahulukan demonstrasi list lengkap dan menunda generator sampai unit berikutnya.","Menggunakan kuis pendapat murid tentang kejelasan penjelasan guru."],"key":"A","why":"Perbaikan bertolak dari dugaan bahwa waktu evaluasi belum terlihat. Jejak harus sesuai perilaku generator yang dipakai, lalu prediksi pada contoh baru menguji apakah murid membedakan pembuatan dan konsumsi.","explanations":["Model waktu menargetkan konsep dan tugas setara memeriksa transfer.","Hasil dapat berubah karena ingatan contoh tanpa pemahaman waktu evaluasi.","Urutan baru belum menguji apakah bantuan memperbaiki konsep yang bermasalah.","Pendapat bermanfaat untuk refleksi tetapi belum membuktikan pemahaman waktu evaluasi."]},{"package":4,"id":26,"uid":"p4-026","section":"PCK","code":"PF.1","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Berbasis Teks, Grafis, dan Multimedia","ppg_concept":"Tujuan pendidikan kejuruan","case_focus":"grafik vektor","stem":"SMK menyiapkan unit desain logo yang dipakai pada kartu kecil dan spanduk besar. Tujuannya lulusan mampu memilih format sesuai kebutuhan pengguna, bukan hanya memakai aplikasi tertentu. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Menguji hasil pembesaran dari logo vektor dan raster dengan bentuk awal sebanding.","Memakai hasil ukuran kartu saja sebagai bukti kecocokan format untuk spanduk.","Menetapkan file terkecil sebagai hasil terbaik untuk semua penggunaan."],"key":["T","F","F"],"why":"Tujuan pendidikan kejuruan mencakup keputusan yang dapat dipertanggungjawabkan. Representasi vektor sesuai untuk banyak logo berskala, tetapi pilihan akhir tetap mempertimbangkan bentuk karya dan kebutuhan pengguna.","explanations":["Uji menunjukkan konsekuensi representasi bagi penggunaan nyata.","Bukti ukuran kecil belum menunjukkan kualitas pada skala besar.","Ukuran file saja tidak menunjukkan kecocokan kualitas dan kebutuhan pengguna."]},{"package":4,"id":27,"uid":"p4-027","section":"PCK","code":"P.1","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"Miskonsepsi autentikasi dan maksud tindakan","case_focus":"CSRF","stem":"Dalam latihan web berbasis session cookie, server menerima perubahan profil dari halaman lain karena browser mengirim cookie pengguna yang sedang login. Murid menyimpulkan permintaan itu pasti dikehendaki pengguna. Kegiatan guru paling tepat adalah ...","options":["Mengganti request perubahan menjadi POST.","Menunjukkan bahwa cookie tidak dapat dibaca JavaScript bila diberi HttpOnly.","Membedakan bukti login dan bukti kehendak tindakan.","Meminta murid menghapus cookie setiap selesai mengubah profil."],"key":"C","why":"Cookie yang terkirim membuktikan konteks session, bukan otomatis persetujuan terhadap tindakan. Guru dapat menelusuri validasi anti-CSRF yang sesuai rancangan server, tanpa menganggap POST atau HttpOnly saja cukup.","explanations":["POST saja tidak membuktikan asal dan kehendak pengguna.","Perlindungan pembacaan cookie belum mencegah browser mengirimkannya.","Perbandingan membongkar penyamaan identitas session dan maksud pengguna.","Langkah ini menghindari session aktif tanpa menjelaskan kelemahan proses."]},{"package":4,"id":28,"uid":"p4-028","section":"PCK","code":"P.2","type":"MCMA","difficulty":"menantang","cp_element":"Pemrograman Web","ppg_concept":"ZPD; scaffolding bertahap","case_focus":"kendala flex","stem":"Pada latihan flex, kartu melebar ketika berisi satu kata sangat panjang. Murid sudah memahami width, tetapi belum memahami batas ukuran minimum item. Guru memilih scaffolding sebelum murid memperbaiki halaman sendiri. Pilih langkah yang tepat.","options":["Mengganti halaman dengan template responsif lengkap untuk ditiru.","Menyederhanakan contoh menjadi dua item lalu membandingkan isi pendek dan panjang.","Menghapus kata panjang dari semua data latihan.","Menguji batas ukuran minimum dan aturan pemenggalan satu per satu."],"key":["B","D"],"why":"Dukungan memisahkan pengaruh ukuran minimum dan pemenggalan teks. Setelah mampu menjelaskan hasil uji kecil, murid menerapkan keputusan ke halaman semula tanpa bergantung pada template.","explanations":["Template menyembunyikan hubungan antara isi dan batas ukuran.","Contoh terkontrol memperlihatkan pengaruh isi pada ukuran item.","Data yang dipermudah menutupi kebutuhan menangani isi nyata.","Perubahan bertahap membantu membedakan dua penyebab overflow."]},{"package":4,"id":29,"uid":"p4-029","section":"PCK","code":"PF.3","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"Prasyarat berbasis tuntutan materi","case_focus":"format angka lokal","stem":"Murid dapat menghitung desimal dan membuat input web, tetapi konversi bawaan menghasilkan nilai tidak valid untuk masukan \"1,5\". Aplikasi ditujukan bagi pengguna yang biasa memakai koma desimal. Prasyarat yang paling perlu diperiksa sebelum unit validasi adalah ...","options":["Penjumlahan desimal bersusun.","Format lokal, parsing, dan nilai numerik program.","Kelengkapan pesan kesalahan ketika sebuah input tidak berhasil dikonversi.","Pemahaman cara menghitung luas dengan pembulatan dua digit."],"key":"B","why":"Diagnosis terikat tuntutan materi: parsing dan validasi perlu aturan format yang jelas. Koma tidak otomatis dipahami semua fungsi konversi; guru perlu memeriksa representasi sebelum memperluas aturan input.","explanations":["Kemampuan menghitung sudah ditunjukkan dan bukan petunjuk utama masalah.","Perbedaan ini diperlukan agar masukan ditafsirkan sesuai konteks.","Pesan berguna pada tahap berikut, tetapi belum memetakan pemahaman representasi.","Keterampilan itu tidak menjelaskan kegagalan penafsiran masukan."]},{"package":4,"id":30,"uid":"p4-030","section":"PCK","code":"P.6","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"Keselarasan asesmen dengan target","case_focus":"riwayat browser","stem":"Target latihan: setelah menulis kata pencarian, tombol Back membawa pengguna ke halaman sebelumnya. Prototipe justru menambah satu entri history setiap huruf sehingga Back menghapus huruf satu per satu. Nilai bukti asesmen berikut sebagai Tepat atau Tidak tepat.","options":["Screenshot hasil pencarian sudah cukup membuktikan target tercapai.","Rekaman urutan navigasi dan perubahan entri history dapat menguji target.","Murid perlu menjelaskan kapan mengganti entri saat ini dan kapan menambah entri baru."],"key":["F","T","T"],"why":"Target perilaku dinilai dengan menjalankan urutan navigasi. Mengganti entri saat ini dapat sesuai untuk perubahan ketikan pada rancangan ini; menambah entri tetap berguna pada perpindahan yang memang perlu ditelusuri kembali.","explanations":["Screenshot tidak menunjukkan urutan history saat Back digunakan.","Bukti sesuai perilaku yang diminta, bukan hanya tampilan.","Penjelasan menunjukkan hubungan keputusan history dengan tujuan navigasi."]},{"package":4,"id":31,"uid":"p4-031","section":"PCK","code":"P.1","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"Prediksi–uji; konsep pengelompokan","case_focus":"radio name","stem":"Dua pertanyaan PG berada dalam satu form web. Memilih jawaban nomor 2 menghapus pilihan nomor 1. Semua id unik, tetapi seluruh radio memakai name yang sama. Respons guru yang paling membangun konsep adalah ...","options":["Meminta murid mengacak id agar setiap input lebih mudah dibedakan.","Mengubah semua radio menjadi checkbox lalu membatasi pilihan melalui instruksi.","Memisahkan pertanyaan ke dua halaman sebelum membahas penyebabnya.","Menguji kelompok name per pertanyaan dan menjelaskan hasilnya."],"key":"D","why":"Dalam konteks form yang sama, name mengelompokkan radio. Guru menggunakan prediksi dan uji kelompok, sehingga murid memahami mengapa id yang unik belum menjadikan kedua pertanyaan independen.","explanations":["Keunikan id sudah terpenuhi dan tidak menentukan kelompok radio.","Pergantian menghindari pemahaman pengelompokan radio.","Pemisahan dapat menghilangkan gejala tanpa menjelaskan mekanisme.","Eksperimen menghubungkan atribut kelompok dengan perilaku pilihan tunggal."]},{"package":4,"id":32,"uid":"p4-032","section":"PCK","code":"PF.4","type":"MCMA","difficulty":"menantang","cp_element":"Pemrograman Web","ppg_concept":"Adaptasi kurikulum; keselarasan tujuan","case_focus":"push dan polling","stem":"Unit web menargetkan kemampuan memilih mekanisme pembaruan data. Untuk papan status, perubahan jarang terjadi, keterlambatan sampai satu menit dapat diterima, dan server latihan hanya mendukung HTTP biasa. Pilih keputusan kurikulum yang tepat.","options":["Membandingkan polling berkala dengan kebutuhan latensi dan beban pada kasus ini.","Mewajibkan server push agar unit selalu memakai teknologi paling baru.","Menilai alasan pilihan, kemudian memberi kasus pembanding dengan tuntutan berbeda.","Mengganti tujuan menjadi hafalan singkatan protokol agar fasilitas cukup."],"key":["A","C"],"why":"Kurikulum dapat memakai batas fasilitas sebagai masalah desain. Polling bisa memadai dalam kasus ini; kasus dengan tuntutan lain dipakai untuk menguji penalaran, tanpa menyatakan satu teknik selalu unggul.","explanations":["Perbandingan menilai kesesuaian solusi dengan batas kebutuhan.","Kebaruan tidak otomatis memenuhi sumber daya dan tujuan unit.","Transfer alasan lebih sesuai tujuan daripada satu teknik wajib.","Tujuan pengambilan keputusan hilang padahal masih dapat dipelajari."]},{"package":4,"id":33,"uid":"p4-033","section":"PCK","code":"PF.2","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"Representasi konsep tata letak","case_focus":"lebar container","stem":"Komponen grafik muat pada halaman penuh, tetapi meluap saat ditempatkan di panel sempit pada layar desktop yang sama. Murid hanya memeriksa lebar viewport. Representasi guru paling tepat adalah ...","options":["Diagram lebar viewport, panel, dan komponen.","Daftar resolusi perangkat.","Perbandingan ukuran font grafik pada panel sempit dan halaman penuh.","Daftar ukuran minimum layar yang didukung seluruh halaman aplikasi."],"key":"A","why":"Ruang komponen ditentukan pula oleh induknya. Diagram ukuran membantu murid menentukan aturan tata letak yang sesuai tanpa menyamakan viewport dengan lebar panel.","explanations":["Representasi membedakan ruang layar dengan ruang yang tersedia bagi komponen.","Perbedaan resolusi belum memperlihatkan perubahan ruang induk dalam layar yang sama.","Uji font belum menjelaskan bahwa ruang induk dapat berubah pada viewport tetap.","Daftar layar tidak menjelaskan relasi ukuran induk dan komponen."]},{"package":4,"id":34,"uid":"p4-034","section":"PCK","code":"P.6","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"Asesmen dengan kasus pembeda","case_focus":"prioritas route","stem":"Router latihan memilih aturan pertama yang cocok. Aturan /produk/:id ditempatkan sebelum /produk/baru, sehingga kata baru dibaca sebagai id. Nilai kesimpulan asesmen berikut sebagai Tepat atau Tidak tepat.","options":["Menelusuri aturan yang cocok secara berurutan menguji pemahaman penyebab.","Keberhasilan membuka /produk/12 membuktikan kedua aturan sudah tepat.","Meminta alasan urutan aturan dan pemeriksaan id memberi bukti lebih lengkap."],"key":["T","F","T"],"why":"Pada router dalam soal, urutan pencocokan menentukan hasil. Asesmen perlu jalur yang membedakan aturan, bukan hanya jalur yang memang cocok dengan parameter id.","explanations":["Jejak mengaitkan hasil dengan kebijakan router yang dinyatakan.","Satu jalur yang berhasil tidak menguji benturan dengan jalur statis.","Keduanya menguji pemilihan rute serta validitas nilai yang diteruskan."]},{"package":4,"id":35,"uid":"p4-035","section":"PCK","code":"P.2","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Web","ppg_concept":"Scaffolding sesuai kesiapan","case_focus":"array promise","stem":"Murid telah lancar memakai map untuk nilai sinkron. Pada fungsi async, mereka mencoba membaca properti hasil padahal map menghasilkan array Promise. Semua Promise pada contoh berhasil. Bantuan awal paling tepat adalah ...","options":["Mengulang latihan array dari deklarasi sampai perulangan dasar.","Mengganti seluruh proses menjadi request sinkron agar hasil mudah dilihat.","Membandingkan isi array sebelum dan setelah Promise.all ditunggu.","Menambah jeda tetap sebelum array dibaca kembali."],"key":"C","why":"Scaffolding bertolak dari pengetahuan map yang sudah ada. Menunggu Promise.all pada contoh yang semuanya berhasil menghasilkan array nilai; kegagalan Promise menjadi bahasan lanjutan, bukan asumsi tersembunyi untuk soal ini.","explanations":["Bukti menunjukkan prasyarat array sudah dikuasai.","Penggantian menghindari konsep yang justru perlu dipelajari.","Perbandingan menargetkan peralihan dari Promise ke nilai hasil.","Jeda tidak mengubah array Promise menjadi array nilai hasil."]},{"package":4,"id":36,"uid":"p4-036","section":"PCK","code":"PF.1","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"PjBL; tujuan SMK; aksesibilitas produk","case_focus":"fokus modal","stem":"Dalam proyek kelas SMK, tim membuat dialog konfirmasi web berdasarkan tugas pengguna dan meninjau hasilnya pada tiap tahap. Tampilan rapi, tetapi pengguna keyboard tetap berpindah ke tombol di belakang dialog. Tujuan proyek mencakup produk yang dapat digunakan secara bertanggung jawab. Pilih bukti kelulusan yang sesuai.","options":["Kesamaan warna dialog dengan rancangan awal.","Uji penyelesaian tugas dengan keyboard saat dialog terbuka.","Jumlah baris CSS untuk membuat latar redup.","Penjelasan dan uji pengembalian fokus setelah dialog ditutup."],"key":["B","D"],"why":"Tanggung jawab hasil kerja mencakup akses interaksi. Bukti perlu menunjukkan alur fokus ketika dialog aktif dan setelah ditutup, bukan hanya kemiripan tampilan.","explanations":["Warna saja tidak menunjukkan akses interaksi keyboard.","Uji menilai tanggung jawab kegunaan produk bagi pengguna.","Jumlah kode tidak menunjukkan apakah fokus dikelola.","Pemulihan fokus membantu pengguna melanjutkan tugas semula."]},{"package":4,"id":37,"uid":"p4-037","section":"PCK","code":"P.4","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Web","ppg_concept":"Evaluasi kritis teknologi dan privasi","case_focus":"cache personal","stem":"Dalam demo web, server cache mengembalikan halaman akun A kepada B. Backend telah memeriksa session, tetapi cache memakai URL saja sebagai kunci untuk halaman personal. Guru perlu memilih cara pemeriksaan teknologinya. Langkah terbaik adalah ...","options":["Mengubah warna halaman untuk membedakan pengguna saat pengujian.","Uji dua session beserta kebijakan cache response.","Mengurangi masa aktif session lalu mengulang tes satu akun.","Memindahkan URL halaman tanpa memeriksa konfigurasi penyimpanan."],"key":"B","why":"Teknologi cache harus dinilai menurut sifat data. Uji dua session beserta kebijakan cache mengungkap bahwa autentikasi backend saja tidak cukup jika response personal dibagikan oleh lapisan cache.","explanations":["Warna membantu melihat gejala tetapi belum menguji kebijakan cache.","Uji menghubungkan kebocoran dengan penyimpanan response personal.","Satu akun tidak menguji pemisahan response antar pengguna.","URL baru tidak menyelesaikan kebijakan cache personal yang keliru."]},{"package":4,"id":38,"uid":"p4-038","section":"PCK","code":"PF.5","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Web","ppg_concept":"Refleksi praktik berbasis bukti","case_focus":"cancel request","stem":"Guru menduga demonstrasi pembatalan request menimbulkan miskonsepsi: tombol Batal dianggap pasti membatalkan transaksi di server. Dalam log latihan, server sudah menyimpan transaksi sebelum browser membatalkan penantian. Nilai rencana perbaikan praktik berikut.","options":["Menyandingkan garis waktu browser dan server lalu meminta murid menjelaskan status transaksi.","Memakai kasus baru dengan waktu pembatalan berbeda untuk memeriksa hasil perbaikan.","Menilai keberhasilan perbaikan dari hilangnya indikator loading saja."],"key":["T","T","F"],"why":"Perbaikan berbasis bukti membedakan berhenti menunggu di klien dan pembatalan operasi bisnis. Efek pembatalan bergantung rancangan server; pada log yang diberikan, transaksi sudah tersimpan.","explanations":["Jejak dua sisi menargetkan miskonsepsi yang teramati.","Kasus pembanding menguji penalaran terhadap bukti baru.","Tampilan klien tidak membuktikan perubahan pemahaman atau pembatalan transaksi."]},{"package":4,"id":39,"uid":"p4-039","section":"PCK","code":"PF.1","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Etika profesi; tanggung jawab hasil kerja","case_focus":"photo picker","stem":"Proyek aplikasi SMK hanya perlu foto yang dipilih pengguna. Platform menyediakan photo picker dengan akses terbatas ke pilihan itu. Tim meminta akses seluruh galeri agar fitur cepat selesai. Umpan balik guru paling tepat adalah ...","options":["Menilai kecocokan foto yang tampil dahulu.","Rubrik foto berhasil tampil.","Menambahkan halaman persetujuan sebelum mengakses seluruh foto pengguna.","Menguji kecukupan akses picker dalam rubrik produk."],"key":"D","why":"Guru SMK menilai keputusan teknis beserta dampaknya. Akses dipilih sesuai kebutuhan nyata; picker yang tersedia harus diuji terhadap tugas memilih foto sebelum meminta akses lebih luas.","explanations":["Keberhasilan menampilkan foto belum menilai proporsionalitas akses pengguna.","Keberhasilan fungsi saja belum menilai proporsionalitas akses.","Persetujuan luas belum memberi alasan kebutuhan teknis akses seluruh galeri.","Kriteria menghubungkan kemampuan teknis dengan tanggung jawab kerja."]},{"package":4,"id":40,"uid":"p4-040","section":"PCK","code":"P.2","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"UDL; akses sesuai kebutuhan","case_focus":"skala font","stem":"Beberapa murid menggunakan ukuran font sistem besar. Pada aplikasi latihan, label terpotong karena tinggi baris tetap. Tujuannya semua murid dapat menguji dan menjelaskan alur aplikasi, bukan membaca huruf kecil. Pilih tindak lanjut yang tepat.","options":["Menguji pembesaran font dengan tata letak yang menyesuaikan isi.","Meminta murid mengembalikan font sistem sebelum pembelajaran.","Memeriksa keterbacaan label dan keterjangkauan tombol setelah perubahan.","Mengganti label dengan ikon baru yang belum dikenali murid."],"key":["A","C"],"why":"UDL mengarahkan pengurangan hambatan yang dapat diperkirakan. Tata letak harus mengakomodasi isi dan skala font sambil menjaga makna serta akses kontrol.","explanations":["Uji menargetkan hambatan akses tanpa menurunkan tujuan.","Penyesuaian dipindahkan kepada murid meskipun antarmuka dapat diperbaiki.","Akses perlu diuji pada keseluruhan tugas, bukan ukuran huruf saja.","Ikon belum tentu mengatasi hambatan pemahaman tanpa dukungan makna."]},{"package":4,"id":41,"uid":"p4-041","section":"PCK","code":"P.6","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Asesmen bukti pemahaman","case_focus":"identitas signing","stem":"Murid menyatakan aplikasi siap diperbarui karena application ID sama. Uji instalasi pembaruan gagal; platform dalam latihan mensyaratkan identitas penandatangan yang sesuai, sedangkan build baru memakai kunci berbeda. Bukti asesmen terbaik adalah ...","options":["Penjelasan kecocokan ID dan penandatangan pada dua build.","Kesamaan ikon dan nama dua build.","Murid berhasil menjalankan build baru setelah menghapus versi lama.","Murid menyebutkan langkah ekspor file instalasi sesuai urutan."],"key":"A","why":"Asesmen memisahkan instalasi bersih dari pembaruan. Kecocokan ID saja belum cukup pada kebijakan platform dalam soal; penjelasan perlu memakai bukti identitas penandatangan tanpa membagikan kunci privat.","explanations":["Bukti menilai pemahaman syarat pembaruan yang dinyatakan.","Tampilan identitas tidak membuktikan kecocokan penandatangan.","Instalasi bersih belum membuktikan pembaruan atas versi lama.","Urutan ekspor belum menjelaskan penyebab pembaruan ditolak."]},{"package":4,"id":42,"uid":"p4-042","section":"PCK","code":"P.1","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Representasi; prediksi–uji","case_focus":"metadata kamera","stem":"Foto kamera tampak tegak pada satu penampil, tetapi miring pada komponen aplikasi murid. File menyimpan orientasi dalam metadata; kedua penampil membaca metadata secara berbeda. Guru ingin membangun konsep representasi gambar. Nilai kegiatan berikut.","options":["Meminta prediksi tampilan pada dua penampil sebelum memeriksa metadata.","Membandingkan urutan piksel dan metadata orientasi pada file yang sama.","Menguji salinan dengan orientasi dinormalisasi sambil mencatat perubahan metadata."],"key":["T","T","T"],"why":"Orientasi dapat ditentukan melalui metadata tanpa mengubah urutan piksel asli. Perbandingan terkontrol membantu murid menjelaskan perbedaan penampil, bukan menganggap file berubah sendiri.","explanations":["Prediksi lalu pemeriksaan menghubungkan dugaan dengan bukti representasi.","Perbandingan membedakan data gambar dari petunjuk penampilannya.","Uji membantu menghubungkan transformasi data dengan hasil tampilan."]},{"package":4,"id":43,"uid":"p4-043","section":"PCK","code":"PF.3","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Diagnosis prasyarat materi","case_focus":"pointer multitouch","stem":"Pada latihan multitouch, dua jari memiliki ID tetap, tetapi posisi mereka dalam daftar event dapat berubah ketika satu jari diangkat. Murid lancar membaca koordinat namun sering melacak jari yang salah. Prasyarat yang perlu dipetakan adalah ...","options":["Penanganan event sentuhan awal.","Cara menghitung jarak antara dua titik koordinat.","Perbedaan ID penunjuk dan indeks daftar event.","Kemampuan menggambar bentuk dengan dua ukuran layar."],"key":"C","why":"Diagnosis mengikuti tuntutan materi. Murid perlu membedakan identitas yang stabil dari posisi yang dapat berubah; koordinat yang benar tetap dapat milik jari yang berbeda.","explanations":["Menangkap event awal belum menunjukkan pemahaman identitas ketika daftar berubah.","Perhitungan jarak belum diperlukan untuk membedakan identitas jari.","Konsep ini menentukan kesinambungan pelacakan ketika daftar berubah.","Ukuran layar tidak menunjukkan pemahaman identitas event."]},{"package":4,"id":44,"uid":"p4-044","section":"PCK","code":"P.6","type":"MCMA","difficulty":"menantang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Asesmen berbasis bukti teknis","case_focus":"integritas unduhan","stem":"Pada unit unduhan offline, murid melanjutkan unduhan setelah koneksi putus. Guru menyediakan salinan acuan dan manifest tepercaya. Target asesmen: murid membuktikan file akhir sesuai versi acuan. Pilih bukti yang memadai untuk mendukung kesimpulan itu.","options":["Ikon file muncul dan nama sesuai dengan judul materi.","Checksum file akhir cocok dengan checksum manifest menggunakan algoritma yang ditetapkan.","Panjang file sama dengan panjang yang tercantum di manifest.","Isi file akhir sama pada pembandingan byte dengan salinan acuan tepercaya."],"key":["B","D"],"why":"Checksum mendukung pemeriksaan integritas terhadap manifest tepercaya; perbandingan byte dengan salinan acuan merupakan bukti langsung kesamaan isi. Keberadaan file atau panjangnya saja tidak cukup. Integritas isi juga tidak menjamin materi aman atau layak secara pedagogis.","explanations":["Keberadaan dan nama tidak menguji isi byte file.","Kecocokan mendukung integritas isi terhadap manifest tepercaya.","Panjang sama masih mungkin memuat isi yang berbeda.","Pembandingan isi secara langsung mendukung kesesuaian dengan acuan."]},{"package":4,"id":45,"uid":"p4-045","section":"PCK","code":"P.1","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Pemodelan dan penelusuran state","case_focus":"back stack","stem":"Setelah login berhasil, menekan Back justru menampilkan formulir login lagi. Aplikasi latihan menyimpan setiap perpindahan sebagai penambahan layar ke stack. Guru ingin murid memahami penyebab sebelum mengubah kode. Langkah terbaik adalah ...","options":["Menyembunyikan tombol Back pada semua layar setelah login.","Menelusuri isi stack sebelum dan sesudah transisi login.","Menambah pemeriksaan warna halaman untuk membedakan status login.","Mengulang login beberapa kali sampai urutan layar berubah."],"key":"B","why":"Jejak stack membantu murid menjelaskan perlunya mengakhiri atau mengganti layar tertentu sesuai rancangan alur. Guru tidak perlu menetapkan satu API untuk semua platform.","explanations":["Penyembunyian menghindari gejala tanpa menjelaskan susunan stack.","Model memperlihatkan layar yang masih tersimpan untuk dikunjungi kembali.","Warna tidak menentukan layar yang tersisa pada stack.","Pengulangan tidak memberi model penyebab transisi."]},{"package":4,"id":46,"uid":"p4-046","section":"PCK","code":"P.5","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"CRT; sumber belajar lokal","case_focus":"format pesan lokal","stem":"Aplikasi informasi acara kampung akan memakai dua bahasa setempat. Narasumber menunjukkan urutan kata pada pesan jumlah peserta berbeda antarkeduanya. Guru ingin sumber lokal benar-benar memengaruhi rancangan belajar. Nilai tindakan berikut.","options":["Mengajak murid memeriksa contoh pesan bersama penutur lalu menyusun template per bahasa.","Menerjemahkan kata satu per satu dengan susunan bahasa pertama.","Meminta murid menjelaskan perubahan rancangan berdasarkan masukan penutur."],"key":["T","F","T"],"why":"Sumber lokal membantu memahami makna dan susunan pesan. Template dirancang menurut bahasa yang digunakan dan diverifikasi bersama penutur, bukan dipaksa mengikuti urutan satu bahasa.","explanations":["Sumber lokal menjadi bukti untuk keputusan format pesan.","Urutan yang sama justru bertentangan dengan bukti narasumber.","Penjelasan menunjukkan pemanfaatan pengetahuan lokal, bukan tempelan nama daerah."]},{"package":4,"id":47,"uid":"p4-047","section":"PCK","code":"PF.4","type":"PG","difficulty":"menantang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Adaptasi kurikulum sesuai karakter materi","case_focus":"jadwal background","stem":"Kurikulum unit mobile menargetkan pemilihan mekanisme kerja latar. Platform latihan dapat menunda pekerjaan berkala untuk menghemat daya. Rencana tugas semula menuntut pengiriman tepat tiap menit walau aplikasi tidak aktif. Adaptasi guru terbaik adalah ...","options":["Asesmen kode pendaftaran pekerjaan dan hasil satu percobaan tepat waktu.","Tambahan percobaan dengan interval lebih pendek agar data terkumpul cepat.","Mengganti tujuan unit menjadi hafalan nama layanan latar.","Kasus sinkronisasi toleran tunda dengan penilaian alasan pilihan."],"key":"D","why":"Adaptasi kurikulum menjaga tujuan dan memperbaiki tuntutan yang tidak cocok dengan mekanisme yang tersedia. Pekerjaan latar berkala tidak diperlakukan sebagai timer presisi pada platform yang dinyatakan.","explanations":["Satu keberhasilan tidak menunjukkan kecocokan mekanisme dengan kebutuhan jaminan waktu.","Interval lebih pendek belum menyelesaikan ketidakcocokan jaminan jadwal.","Tujuan pemilihan mekanisme hilang meskipun masih relevan.","Kasus sesuai batas platform sambil mempertahankan penalaran rancangan."]},{"package":4,"id":48,"uid":"p4-048","section":"PCK","code":"P.4","type":"MCMA","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Literasi digital; evaluasi teknologi","case_focus":"verifikasi server","stem":"Aplikasi latihan dapat terhubung ke server uji setelah verifikasi sertifikat dimatikan. Guru ingin penggunaan alat pengembangan tetap mendidik murid menilai keamanan koneksi. Pilih tindak lanjut yang tepat.","options":["Menelusuri identitas server yang seharusnya dipercaya dan konfigurasi sertifikatnya.","Menganggap koneksi terenkripsi cukup meskipun identitas server tidak diverifikasi.","Membedakan konfigurasi kepercayaan khusus pengujian dari rilis yang akan digunakan.","Mencatat alasan dan batas konfigurasi kepercayaan yang dipilih murid."],"key":["A","C","D"],"why":"Alat pengembangan dinilai menurut tujuan dan risikonya. Guru memeriksa rantai kepercayaan yang sesuai lingkungan; mematikan verifikasi bukan bukti bahwa masalah sudah terselesaikan dengan aman.","explanations":["Pemeriksaan menargetkan penyebab kegagalan kepercayaan.","Enkripsi tanpa verifikasi identitas masih dapat terhubung ke pihak yang keliru.","Batas lingkungan mencegah jalan pintas uji terbawa ke produk.","Catatan membantu menilai pemahaman risiko dan tujuan penggunaan alat."]},{"package":4,"id":49,"uid":"p4-049","section":"PCK","code":"PF.2","type":"PG","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Ketepatan konsep sensor","case_focus":"gravitasi sensor","stem":"API accelerometer yang dipakai latihan melaporkan komponen gravitasi. Ponsel diam tetap menampilkan nilai bukan nol. Murid menyimpulkan sensornya rusak karena tidak bergerak. Penjelasan guru paling tepat adalah ...","options":["Membedakan keluaran API dan dugaan bahwa diam harus bernilai nol.","Menyarankan pengurangan bacaan awal sebagai kalibrasi sebelum menguji kembali.","Menggunakan perpindahan ikon sebagai pengganti angka agar hasil lebih mudah dilihat.","Perbandingan bacaan dua ponsel."],"key":"A","why":"Penguasaan materi menuntut pembacaan definisi keluaran sensor. Pada API dalam soal, gravitasi termasuk dalam bacaan; keadaan diam tidak berarti setiap komponen bernilai nol.","explanations":["Penjelasan sesuai definisi API dan menargetkan kesimpulan murid.","Kalibrasi dapat menjadi teknik tersendiri, tetapi tidak menjelaskan bahwa gravitasi memang termasuk keluaran.","Pergantian tampilan tidak memperbaiki penafsiran besaran sensor.","Perbandingan antargawai belum menjelaskan definisi bacaan API yang digunakan."]},{"package":4,"id":50,"uid":"p4-050","section":"PCK","code":"P.3","type":"Kategori","difficulty":"sedang","cp_element":"Pemrograman Perangkat Bergerak","ppg_concept":"Bermakna dan menggembirakan; pilihan terarah","case_focus":"kemampuan runtime","stem":"Kelas membuat permainan gerak. Fitur sensor tambahan hanya tersedia pada sebagian perangkat. Tujuan belajar ialah merancang aturan interaksi dan menjelaskan respons, bukan membandingkan mahalnya ponsel. Nilai rancangan pembelajaran berikut.","options":["Menyediakan input sentuh setara untuk menguji aturan interaksi yang sama.","Mengelompokkan nilai tantangan menurut banyaknya fitur perangkat yang tersedia.","Menampilkan peringkat keberhasilan menurut kelengkapan sensor perangkat."],"key":["T","F","F"],"why":"Pembelajaran menggembirakan bertumpu pada tantangan yang relevan dan dapat diakses. Pilihan input tetap harus menghasilkan bukti penjelasan aturan interaksi yang menjadi tujuan.","explanations":["Alternatif menjaga tujuan dan mengurangi hambatan perangkat.","Ketersediaan fitur tidak menunjukkan perkembangan penjelasan aturan interaksi.","Peringkat itu mengukur kepemilikan fitur, bukan tujuan pembelajaran."]},{"package":4,"id":51,"uid":"p4-051","section":"PU","code":"P.1","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Penalaran; penyelidikan berbasis masalah","case_focus":"korelasi dan sebab","stem":"Murid membaca grafik: kelas yang sering memakai perpustakaan memiliki nilai membaca lebih tinggi. Mereka menyimpulkan menambah kunjungan pasti menaikkan nilai. Guru hendak membangun penalaran sebab-akibat. Kegiatan paling tepat adalah ...","options":["Daftar manfaat membaca dari pengalaman.","Menghitung kembali rata-rata nilai tiap kelas sampai hasilnya sama.","Menimbang penjelasan alternatif dan bukti pembedanya.","Menambah contoh kelas yang sesuai dengan kesimpulan awal."],"key":"C","why":"Grafik menunjukkan keterkaitan, belum memastikan sebab. Guru membantu murid mempertimbangkan penjelasan alternatif dan merancang bukti pembeda tanpa menolak manfaat perpustakaan.","explanations":["Manfaat membaca tidak menguji hubungan sebab-akibat pada data grafik.","Perhitungan dapat benar tanpa memperbaiki kesimpulan sebab-akibat.","Kegiatan membangun batas inferensi dari data hubungan.","Contoh pendukung saja belum membedakan hubungan dan penyebab."]},{"package":4,"id":52,"uid":"p4-052","section":"PU","code":"P.2","type":"MCMA","difficulty":"sedang","cp_element":null,"ppg_concept":"Diferensiasi; TaRL; asesmen diagnostik","case_focus":"strategi vs skor sama","stem":"Dua kelompok mendapat skor awal sama. Kelompok A memilih strategi sesuai soal tetapi sering salah hitung; B menghitung lancar namun kerap memilih strategi keliru. Pilih tindak lanjut yang sesuai bukti.","options":["Memisahkan bukti pemilihan strategi dan ketelitian hitung dalam catatan diagnosis.","Memberi A dukungan pemeriksaan hasil, B perbandingan alasan memilih strategi.","Menetapkan kelompok tetap sampai akhir semester berdasarkan skor awal.","Memeriksa ulang kebutuhan setelah tugas singkat yang menuntut strategi dan perhitungan."],"key":["A","B","D"],"why":"Diferensiasi dan TaRL menggunakan informasi kemampuan yang relevan, bukan angka total semata. Pengelompokan serta dukungan bersifat sementara dan diperiksa ulang.","explanations":["Pemisahan memberi dasar yang lebih tepat untuk memilih dukungan.","Dukungan menargetkan jenis kesulitan masing-masing.","Data awal tidak cukup untuk mengunci dukungan dan perkembangan murid.","Asesmen lanjutan memungkinkan penyesuaian dukungan berdasarkan perkembangan."]},{"package":4,"id":53,"uid":"p4-053","section":"PU","code":"P.3","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"CASEL; kesadaran diri; rasa aman","case_focus":"check in sukarela","stem":"Guru ingin memulai diskusi isu sensitif dengan check-in emosi. Seorang murid tidak ingin mengungkap perasaannya di depan kelas, tetapi bersedia menuliskannya untuk diri sendiri. Tujuan kegiatan adalah kesadaran diri dan kesiapan belajar. Respons terbaik adalah ...","options":["Daftar emosi untuk dibacakan satu per satu.","Pilihan refleksi pribadi dan penentuan dukungan belajar.","Pengecualian murid dari diskusi.","Menunda diskusi sampai seluruh murid siap membagikan perasaan di depan kelas."],"key":"B","why":"Pembelajaran berkesadaran membutuhkan rasa aman. Tujuan mengenali kondisi diri dapat dicapai melalui refleksi pribadi; dukungan diberikan tanpa memaksa murid membagikan pengalaman sensitif.","explanations":["Daftar membantu penamaan, tetapi tetap mewajibkan pengungkapan publik yang menjadi hambatan.","Pilihan menjaga tujuan kesadaran diri tanpa memaksa pengungkapan publik.","Keengganan berbagi emosi tidak membuktikan ketidaksiapan berdiskusi.","Kesiapan belajar tidak harus dibuktikan lewat pengungkapan emosi kepada kelas."]},{"package":4,"id":54,"uid":"p4-054","section":"PU","code":"P.4","type":"Kategori","difficulty":"sedang","cp_element":null,"ppg_concept":"Literasi digital; evaluasi sumber","case_focus":"peringkat informasi","stem":"Alat pencarian menempatkan hasil berbayar paling atas. Murid menganggap urutan itu menunjukkan kualitas bukti terbaik. Guru ingin mengembangkan penggunaan teknologi secara kritis. Nilai tindakan berikut.","options":["Mengganti alat pencarian tanpa membahas bagaimana hasil diperingkat.","Membandingkan label sponsor, penulis, dan bukti pada beberapa hasil.","Meminta murid menjelaskan alasan memilih sumber setelah memeriksa isinya."],"key":["F","T","T"],"why":"Urutan hasil tidak otomatis menjadi penilaian mutu bukti. Guru mengajarkan pemeriksaan tujuan publikasi, kepengarangan, dan dukungan isi, bukan sekadar memilih alat lain.","explanations":["Penggantian belum mengatasi cara murid menafsirkan urutan.","Perbandingan membantu memisahkan posisi tampilan dan mutu informasi.","Alasan berbasis isi menjadi bukti literasi digital."]},{"package":4,"id":55,"uid":"p4-055","section":"PU","code":"P.5","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Sumber lingkungan; pembelajaran kontekstual","case_focus":"observasi rute lokal","stem":"Pada unit perencanaan rute, peta lingkungan sekolah belum memuat jalur pejalan kaki yang baru. Warga juga menyampaikan bahwa beberapa ruas padat saat pasar berlangsung. Tujuan unit ialah memberi alasan pemilihan rute yang dapat digunakan. Pemanfaatan sumber setempat terbaik adalah ...","options":["Mengumpulkan observasi jalur lalu menguji alasan pilihan rute.","Memakai peta lama karena sumber tercetak lebih mudah disamakan antar kelompok.","Mengikuti rute yang paling sering dipilih warga tanpa menanyakan kondisinya.","Pemilihan garis terpendek pada peta."],"key":"A","why":"Sumber lingkungan dipakai karena memberi informasi yang diperlukan untuk tujuan belajar. Observasi terarah dan keterangan kondisi jalur melengkapi peta; murid tetap harus menjelaskan alasan keputusan, bukan sekadar mengikuti rute populer.","explanations":["Lingkungan menjadi sumber bukti untuk menilai keterpakaian rute.","Kemudahan menyamakan bahan tidak mengatasi ketidaklengkapan informasi yang relevan.","Kebiasaan warga perlu dipahami bersama waktu dan kebutuhan penggunaan.","Panjang saja tidak menilai kepadatan dan akses jalur yang menjadi bukti kasus."]},{"package":4,"id":56,"uid":"p4-056","section":"PU","code":"P.6","type":"MCMA","difficulty":"menantang","cp_element":null,"ppg_concept":"Assessment for learning; tindak lanjut","case_focus":"rerata menutupi kebutuhan","stem":"Rata-rata kelas pada tujuan membuat inferensi sudah melewati batas capaian. Namun lembar jawaban menunjukkan delapan murid menyalin kalimat tanpa menghubungkan bukti. Pilih tindak lanjut yang tepat.","options":["Memeriksa alasan delapan murid dengan tugas singkat yang setara.","Memulai materi lanjutan untuk semua karena rata-rata kelas sudah cukup.","Memberi dukungan menghubungkan bukti dan inferensi, lalu menilai ulang.","Mengganti batas capaian agar lebih banyak murid masuk kategori tuntas."],"key":["A","C"],"why":"Keputusan asesmen harus menelusuri bukti terhadap tujuan. Rata-rata kelas dapat menyembunyikan kebutuhan kelompok; tindak lanjut memerlukan dukungan spesifik dan bukti baru.","explanations":["Bukti individu diperlukan untuk menegaskan kebutuhan tindak lanjut.","Rata-rata tidak memastikan capaian setiap murid pada tujuan.","Tindak lanjut sesuai kesulitan yang teramati.","Perubahan batas tidak memperbaiki pemahaman yang belum tampak."]},{"package":4,"id":57,"uid":"p4-057","section":"PU","code":"K.1","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Etika guru; hak dan martabat murid","case_focus":"hak karya murid","stem":"Sekolah meminta contoh karya untuk pameran publik. Satu karya murid memuat kisah keluarga yang sensitif dan awalnya hanya dibuat untuk dibaca guru. Sikap guru paling tepat adalah ...","options":["Membicarakan izin dan bagian yang nyaman dibagikan bersama murid.","Mengunggah karya setelah menghapus nama murid saja.","Meminta ketua kelas memutuskan karena pameran mewakili kelas.","Menampilkan karya utuh karena tugas sekolah menjadi milik sekolah."],"key":"A","why":"Integritas dan penghormatan kepada murid mencakup penggunaan karya sesuai tujuan dan persetujuan. Menghapus nama saja belum selalu melindungi identitas atau kenyamanan pemilik kisah.","explanations":["Langkah menghormati kepemilikan karya dan batas informasi pribadi.","Isi kisah masih dapat mengungkap identitas atau hal sensitif.","Perwakilan kelas tidak menggantikan persetujuan pemilik karya.","Pemberian tugas tidak otomatis memberi izin publikasi pengalaman pribadi."]},{"package":4,"id":58,"uid":"p4-058","section":"PU","code":"K.2","type":"Kategori","difficulty":"menantang","cp_element":null,"ppg_concept":"Refleksi diri; keterbukaan terhadap masukan","case_focus":"bukti keterbacaan umpan balik","stem":"Guru merasa umpan baliknya sudah jelas karena semua jawaban salah diberi tanda. Murid mengatakan belum tahu bagian penalaran yang perlu diubah. Pada sampel pekerjaan, tanda memang tidak disertai penjelasan. Nilai respons refleksi guru berikut.","options":["Menelaah sampel bersama kriteria sebelum menilai kejelasan umpan baliknya.","Menganggap keberadaan tanda koreksi cukup membuktikan murid tahu cara memperbaiki.","Mencoba komentar terarah lalu memeriksa cara murid merevisi alasannya."],"key":["T","F","T"],"why":"Refleksi guru menguji keyakinan pribadi terhadap bukti. Masukan murid dan sampel koreksi menunjukkan kebutuhan menghubungkan umpan balik dengan langkah perbaikan; hasil revisi menjadi dasar penilaian berikutnya.","explanations":["Guru menguji penilaian diri memakai bukti yang relevan.","Penandaan lokasi salah belum menunjukkan penjelasan penalaran.","Percobaan memberi dasar belajar dari dampak perubahan praktik."]},{"package":4,"id":59,"uid":"p4-059","section":"PU","code":"K.3","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Disiplin positif; kebiasaan belajar","case_focus":"kebijakan tenggat","stem":"Murid terlambat menyerahkan tugas karena hambatan yang telah dibicarakan dengan guru. Ia sudah punya rencana pengerjaan, tetapi teman mempertanyakan kelonggaran tenggat. Guru ingin membangun kebiasaan belajar sekaligus tanggung jawab. Respons terbaik adalah ...","options":["Pengungkapan hambatan murid kepada kelas.","Membebaskan murid dari tugas agar tidak muncul persoalan tenggat.","Tenggat penyesuaian disertai titik cek kemajuan.","Penerapan tenggat seragam."],"key":"C","why":"Komitmen pada kebiasaan belajar diwujudkan melalui dukungan dan tanggung jawab yang konsisten. Penyesuaian memiliki rencana serta pemantauan; prinsipnya dapat dijelaskan tanpa membocorkan keadaan pribadi murid.","explanations":["Rincian pribadi tidak diperlukan untuk menjelaskan prinsip dukungan.","Pembebasan menghilangkan kesempatan membangun tanggung jawab belajar.","Dukungan tetap menuntut komitmen dan memantau pembentukan kebiasaan.","Kesamaan tenggat mengabaikan hambatan yang sudah diketahui."]},{"package":4,"id":60,"uid":"p4-060","section":"PU","code":"S.1","type":"MCMA","difficulty":"sedang","cp_element":null,"ppg_concept":"Komunikasi empatik dan inklusif","case_focus":"makna diam","stem":"Saat guru menawarkan kesempatan bertanya, beberapa murid diam. Dalam percakapan pribadi mereka mengatakan masih bingung, tetapi takut pertanyaannya dianggap sudah dijelaskan. Pilih respons komunikasi yang sesuai.","options":["Menyimpulkan diam berarti setuju lalu mengakhiri pembahasan.","Mengakui bahwa instruksi mungkin perlu diperjelas dan memberi kanal bertanya tanpa nama.","Meminta murid yang diam mewakili kelas menjawab pertanyaan sulit.","Mengecek pemaknaan melalui contoh singkat dan menanggapi kebingungan dengan netral."],"key":["B","D"],"why":"Komunikasi empatik tidak menafsirkan diam secara sepihak. Guru menyediakan cara bertanya yang aman dan mengecek makna melalui respons nyata, bukan menuntut keberanian tampil terlebih dahulu.","explanations":["Bukti percakapan menunjukkan makna diam tidak sama dengan paham.","Bahasa dan kanal mengurangi hambatan menyampaikan kebingungan.","Tekanan publik tidak menargetkan rasa takut yang diungkapkan.","Cek makna memberi bukti sekaligus membangun komunikasi aman."]},{"package":4,"id":61,"uid":"p4-061","section":"PU","code":"S.2","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Kolaborasi; co-teaching","case_focus":"co teaching","stem":"Dua guru akan mengajar bersama dalam unit argumentasi. Pada pertemuan pertama keduanya memberi arahan bersamaan, sedangkan bukti diskusi murid tidak tercatat. Langkah kolaborasi terbaik sebelum pertemuan berikutnya adalah ...","options":["Membagi kelas menjadi dua dengan tujuan dan penilaian masing-masing.","Menyepakati pembagian fasilitasi, pengamatan, dan waktu menelaah bukti.","Meminta guru yang lebih senior memimpin seluruh kegiatan sampai unit berakhir.","Menggilir penyampaian materi per sepuluh menit agar waktu setara."],"key":"B","why":"Kolaborasi berorientasi pembelajaran membutuhkan peran yang jelas dan penelaahan bukti bersama. Kesepakatan dapat diubah setelah melihat kebutuhan murid, bukan sekadar membagi jatah berbicara.","explanations":["Pemisahan belum menyelesaikan koordinasi untuk tujuan bersama.","Peran saling melengkapi dan terhubung pada keputusan pembelajaran.","Cara itu belum memanfaatkan kontribusi dua guru secara terencana.","Kesetaraan waktu bicara tidak memastikan fungsi dan bukti terkoordinasi."]},{"package":4,"id":62,"uid":"p4-062","section":"PU","code":"S.3","type":"Kategori","difficulty":"sedang","cp_element":null,"ppg_concept":"Komunitas profesi; belajar berkelanjutan","case_focus":"partisipasi anggota baru","stem":"Komunitas guru membahas praktik asesmen. Anggota baru membawa catatan kasus, tetapi diskusi selalu diisi tiga pembicara lama. Ia ingin ikut belajar dan memberi kontribusi tanpa menunggu menjadi ahli. Nilai pilihan berikut.","options":["Mengajukan satu pertanyaan dari catatan kasus dan meminta tanggapan anggota.","Mengusulkan giliran berbagi singkat agar lebih banyak bukti praktik terdengar.","Menunggu sampai seluruh praktiknya berhasil sebelum ikut berdiskusi."],"key":["T","T","F"],"why":"Keaktifan komunitas tidak mensyaratkan praktik sempurna. Guru dapat membawa pertanyaan berbukti dan membantu memperbaiki ruang partisipasi, sambil tetap mendengar kontribusi anggota lain.","explanations":["Kontribusi konkret membuka percakapan yang berorientasi praktik.","Usulan memperluas partisipasi dan pembelajaran komunitas.","Komunitas juga menjadi tempat belajar dari kesulitan yang terurai."]},{"package":4,"id":63,"uid":"p4-063","section":"PU","code":"PF.1","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Tujuan pendidikan; kemandirian belajar","case_focus":"tujuan lintas platform","stem":"Sekolah mengganti platform pembelajaran. Sebagian guru ingin mempertahankan latihan menghafal letak tombol. Tujuan sekolah adalah murid dapat mencari informasi, memeriksa sumber, dan bekerja mandiri. Prioritas guru paling tepat adalah ...","options":["Panduan tombol diikuti tes praktik langkah demi langkah sebagai hasil utama.","Menunda semua kegiatan sampai tampilan platform stabil sepanjang tahun.","Menyamakan kecepatan klik sebagai ukuran kemandirian belajar.","Penilaian pencarian dan pemeriksaan sumber, dibantu pengenalan alat."],"key":"D","why":"Pemahaman tujuan pendidikan memandu pilihan isi dan bukti hasil. Keterampilan alat menjadi sarana menuju kemandirian serta penilaian informasi, sehingga perpindahan platform tidak mengganti tujuan utama.","explanations":["Panduan membantu akses tetapi prosedur alat belum mewakili tujuan pendidikan.","Penundaan menghilangkan kesempatan mencapai tujuan yang dapat berjalan lintas alat.","Kecepatan operasi belum menunjukkan pertimbangan sumber dan pengelolaan belajar.","Prioritas menjaga tujuan pendidikan sambil menyediakan dukungan operasional."]},{"package":4,"id":64,"uid":"p4-064","section":"PU","code":"PF.3","type":"MCMA","difficulty":"menantang","cp_element":null,"ppg_concept":"Prasyarat materi; diagnosis kesiapan","case_focus":"inferensi bacaan","stem":"Sebelum unit membaca inferensial, guru menemukan murid mampu membaca kata dengan lancar, tetapi tidak menghubungkan dua petunjuk terpisah untuk menyimpulkan maksud tokoh. Pilih diagnosis prasyarat yang tepat.","options":["Meminta murid menunjukkan petunjuk yang dipakai dan hubungan di antaranya.","Menguji kecepatan membaca nyaring sebagai satu-satunya dasar dukungan.","Memeriksa pemahaman kata penghubung pada pasangan petunjuk yang digunakan.","Menentukan kemampuan dari jumlah buku yang dibawa ke kelas."],"key":["A","C"],"why":"Pemetaan kebutuhan perlu mengikuti tuntutan isi: inferensi menghubungkan petunjuk, bukan hanya melafalkan kata. Guru memeriksa cara murid membangun hubungan tanpa langsung memberi label kemampuan umum.","explanations":["Respons mengungkap kesiapan mengintegrasikan bukti.","Kelancaran sudah tampak dan tidak cukup menjelaskan kesulitan inferensi.","Makna penghubung bisa menjadi prasyarat hubungan yang perlu dipetakan.","Jumlah buku tidak menunjukkan prasyarat inferensi murid."]},{"package":4,"id":65,"uid":"p4-065","section":"PU","code":"PF.4","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"UbD; adaptasi kurikulum","case_focus":"cakupan unit kurikulum","stem":"Saat menyusun kurikulum unit, guru mengetahui kelas telah mahir menjalankan prosedur eksperimen tetapi belum mampu membandingkan dua penjelasan berdasarkan bukti. Tujuan akhir tetap menuntut evaluasi penjelasan. Adaptasi terbaik adalah ...","options":["Mengurangi pengulangan prosedur dan menilai perbandingan penjelasan.","Mempertahankan seluruh latihan prosedur karena urutan buku harus sama.","Mengganti tujuan akhir menjadi kelancaran mengikuti prosedur.","Menambah eksperimen yang lebih banyak tanpa mengubah pertanyaan analisis."],"key":"A","why":"Adaptasi kurikulum menggunakan kebutuhan murid untuk mengatur kedalaman, waktu, dan bukti. Tujuan evaluasi tetap dijaga; kegiatan prosedural tidak harus diulang dengan porsi sama jika prasyaratnya sudah kuat.","explanations":["Adaptasi memakai capaian awal untuk menjaga tuntutan tujuan akhir.","Urutan buku belum mempertimbangkan kebutuhan yang teramati.","Pergantian menurunkan tuntutan yang justru belum tercapai.","Jumlah kegiatan tidak memastikan latihan membandingkan penjelasan."]},{"package":4,"id":66,"uid":"p4-066","section":"PU","code":"PF.5","type":"Kategori","difficulty":"menantang","cp_element":null,"ppg_concept":"Refleksi empiris; keterlaksanaan intervensi","case_focus":"fidelitas pelaksanaan","stem":"Guru menguji rancangan diskusi yang mewajibkan setiap murid menulis alasan sebelum berbagi. Hasil belum meningkat. Catatan pelaksanaan menunjukkan beberapa pertemuan langsung masuk diskusi tanpa tahap menulis. Nilai keputusan penelitian praktik berikut.","options":["Menyimpulkan tahap menulis tidak berguna karena nilai belum naik.","Mencatat keterlaksanaan tiap tahap bersama bukti hasil murid.","Memperbaiki keterlaksanaan lalu menguji kembali dengan tugas yang sebanding."],"key":["F","T","T"],"why":"Perbaikan praktik perlu data keterlaksanaan, bukan hasil akhir saja. Rancangan yang tidak dijalankan sesuai rencana belum dapat dinilai dampaknya dengan tegas; uji berikut tetap perlu bukti hasil dan keterbandingan tugas.","explanations":["Rancangan belum terlaksana konsisten sehingga kesimpulan itu terlalu jauh.","Data proses membantu menafsirkan hasil intervensi.","Langkah memisahkan kelemahan pelaksanaan dari dugaan kelemahan rancangan."]},{"package":4,"id":67,"uid":"p4-067","section":"PU","code":"P.1","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Transfer konsep; Discovery Learning terbimbing","case_focus":"alasan aturan","stem":"Murid dapat mengulang aturan memisahkan dua jenis sampah, tetapi salah saat menghadapi kemasan gabungan yang belum dicontohkan. Tujuan guru ialah transfer prinsip pemilahan. Kegiatan terbaik adalah ...","options":["Meminta murid menyalin aturan dengan tulisan lebih rapi.","Mengulang contoh yang sudah dijawab benar dengan urutan berbeda.","Membandingkan kemasan baru dan menjelaskan alasan pemilahan berdasarkan cirinya.","Menghitung kecepatan menyebutkan nama dua tempat sampah."],"key":"C","why":"Transfer memerlukan pengenalan ciri yang relevan, bukan hanya ingatan contoh. Guru dapat menyediakan informasi bahan yang diperlukan agar kesulitan berasal dari penalaran, bukan menebak isi kemasan.","explanations":["Kerapian tidak mengungkap cara menerapkan prinsip pada kasus baru.","Pengulangan terbatas belum memberi kesempatan menguji batas prinsip.","Kegiatan menguji penggunaan prinsip pada variasi yang relevan.","Kecepatan label bukan bukti transfer pemilahan."]},{"package":4,"id":68,"uid":"p4-068","section":"PU","code":"P.2","type":"MCMA","difficulty":"sedang","cp_element":null,"ppg_concept":"Diferensiasi; ZPD; scaffolding","case_focus":"hambatan kerja kelompok","stem":"Dalam kerja kelompok, tiga murid memiliki hambatan berbeda: sulit memulai tugas yang terbuka, belum memahami teks sumber, dan sudah siap menguji gagasan lebih lanjut. Pilih respons yang sesuai kebutuhan.","options":["Memberi contoh langkah awal yang dapat dilepas setelah murid mampu memulai.","Memberi pemantik langkah awal dan bantuan memahami sumber kepada yang memerlukannya.","Menetapkan murid yang siap sebagai penjelas tetap bagi semua kelompok.","Memberi tugas menguji batas gagasan kepada murid yang sudah siap."],"key":["A","B","D"],"why":"Diferensiasi menyediakan dukungan dan tantangan berdasarkan bukti. Scaffolding dikurangi saat murid mampu melanjutkan; tugas lanjutan tetap terkait tujuan, bukan sekadar tambahan jumlah pekerjaan.","explanations":["Dukungan sementara membantu kemandirian sesuai kesiapan.","Scaffolding menargetkan hambatan tanpa mengubah tujuan bersama.","Peran tetap dapat mengabaikan tantangan belajarnya sendiri.","Tantangan lanjutan menjaga perkembangan murid dengan kesiapan lebih tinggi."]},{"package":4,"id":69,"uid":"p4-069","section":"PU","code":"P.3","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Pembelajaran menggembirakan; growth mindset","case_focus":"tantangan tanpa leaderboard","stem":"Pada tantangan kelas, leaderboard membuat murid memilih soal termudah demi poin. Tujuan guru adalah keberanian mencoba strategi dan merefleksikan hasil. Perubahan paling tepat adalah ...","options":["Menaikkan poin soal mudah agar lebih banyak murid mendapat penghargaan.","Pilihan tantangan disertai telaah strategi.","Menghapus kesempatan memilih sehingga semua mengerjakan soal tersulit.","Memberi hadiah hanya bagi murid yang paling cepat mengganti strategi."],"key":"B","why":"Menggembirakan tidak harus berarti kompetisi poin. Pilihan tantangan dan refleksi memberi ruang mencoba secara aman, sedangkan keberhasilan dibaca sebagai perkembangan strategi terhadap tujuan.","explanations":["Perubahan tetap mengarahkan perhatian pada perolehan poin.","Rancangan menghubungkan rasa mampu dengan proses dan tujuan belajar.","Tuntutan seragam dapat menghilangkan tantangan yang terdukung.","Kecepatan pergantian belum menunjukkan pertimbangan strategi yang tepat."]},{"package":4,"id":70,"uid":"p4-070","section":"PU","code":"P.4","type":"Kategori","difficulty":"sedang","cp_element":null,"ppg_concept":"TPACK; evaluasi manfaat teknologi","case_focus":"anotasi digital","stem":"Guru memakai papan anotasi digital untuk membahas teks. Banyak komentar muncul, tetapi mayoritas hanya \"setuju\" tanpa alasan. Tujuannya argumentasi berbukti. Nilai evaluasi penggunaan teknologi berikut.","options":["Menilai kualitas hubungan klaim, kutipan, dan tanggapan, bukan jumlah komentar.","Menyebut penggunaan teknologi berhasil karena kegiatan telah berpindah ke layar.","Meminta murid menautkan alasan ke kutipan lalu menanggapi alasan teman."],"key":["T","F","T"],"why":"TPACK menghubungkan pilihan fitur dengan materi dan pedagogi. Penilaian manfaat teknologi memerlukan bukti kualitas argumentasi; label tingkat SAMR atau banyaknya aktivitas digital saja tidak cukup.","explanations":["Kriteria ini sesuai tujuan penalaran yang ingin didukung alat.","Perpindahan media tidak otomatis memperbaiki kualitas belajar.","Fitur anotasi diarahkan untuk mendukung proses argumentasi."]},{"package":4,"id":71,"uid":"p4-071","section":"PU","code":"P.5","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Sumber lokal; literasi kritis","case_focus":"iklan sumber lokal","stem":"Kelas meneliti cara iklan memengaruhi pilihan warga. Toko sekitar bersedia memberikan brosur lama, daftar perubahan promosi, dan kesempatan bertanya tentang sasaran pembeli. Penggunaan sumber lokal terbaik adalah ...","options":["Menjadikan nama toko sebagai pengganti nama pada soal buku.","Meminta murid meniru brosur yang paling berwarna.","Menilai pilihan warga hanya dari promosi yang disukai pemilik toko.","Menganalisis perubahan pesan dan memeriksa tanggapan warga dengan pertanyaan terarah."],"key":"D","why":"Sumber lingkungan dipilih karena memberi bukti yang relevan, bukan sekadar dekorasi konteks. Perspektif pembuat iklan dan penerima pesan perlu dibedakan saat menafsirkan pengaruhnya.","explanations":["Pergantian nama belum memanfaatkan bukti dari lingkungan.","Peniruan tampilan tidak menjawab tujuan analisis pengaruh.","Pandangan pemilik saja belum mewakili penerimaan warga.","Bukti lokal dipakai untuk menguji hubungan pesan dan penerimaan."]},{"package":4,"id":72,"uid":"p4-072","section":"PU","code":"P.6","type":"MCMA","difficulty":"menantang","cp_element":null,"ppg_concept":"Validitas; reliabilitas; rubrik","case_focus":"reliabel belum valid","stem":"Dua penilai memberi skor sangat konsisten pada tugas presentasi. Namun rubrik hanya menilai volume suara dan kerapian, sedangkan tujuan unit ialah kekuatan argumen. Pilih kesimpulan yang tepat.","options":["Konsistensi skor belum membuktikan kesesuaian asesmen dengan tujuan.","Nilai yang konsisten menunjukkan argumen pasti sudah diukur dengan baik.","Rubrik perlu memuat alasan, bukti, dan hubungan keduanya sesuai tujuan.","Menambah jumlah penilai saja akan menyelesaikan ketidakselarasan tujuan."],"key":["A","C"],"why":"Asesmen memerlukan konsistensi sekaligus kesesuaian konstruk. Rubrik dapat reliabel untuk aspek tampilan tetapi lemah untuk argumentasi; perubahan perlu menyasar kriteria, lalu menyamakan pemaknaannya.","explanations":["Reliabilitas tidak menggantikan bukti validitas terhadap tujuan.","Skor dapat konsisten mengukur aspek yang kurang relevan.","Kriteria tersebut lebih mewakili kualitas argumentasi yang dituju.","Jumlah penilai tidak memperbaiki isi kriteria yang keliru."]},{"package":4,"id":73,"uid":"p4-073","section":"PU","code":"K.1","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Integritas; keadilan; pengelolaan emosi","case_focus":"dugaan menyontek","stem":"Dua tugas sangat mirip, sehingga guru menduga ada penyalinan. Belum ada bukti tentang proses kerja atau komunikasi kedua murid. Sikap paling tepat adalah ...","options":["Klarifikasi proses secara pribadi.","Menyatakan pelanggaran kepada kelas agar aturan segera dipahami.","Memberi nilai rata-rata kedua tugas sebagai jalan tengah.","Menganggap kemiripan wajar karena tujuan tugas sama."],"key":"A","why":"Etika menuntut penilaian berbukti dan komunikasi yang menjaga martabat. Kemiripan memicu pemeriksaan yang adil, bukan vonis ataupun pengabaian; keputusan mengikuti bukti dan aturan yang berlaku.","explanations":["Klarifikasi menjaga keadilan dan mengumpulkan bukti yang belum tersedia.","Dugaan belum cukup untuk pengumuman yang dapat merugikan murid.","Rata-rata tidak menyelesaikan kejelasan proses dan keadilan keputusan.","Kemungkinan wajar perlu diperiksa, bukan langsung dipastikan."]},{"package":4,"id":74,"uid":"p4-074","section":"PU","code":"K.2","type":"Kategori","difficulty":"sedang","cp_element":null,"ppg_concept":"Refleksi guru; keterbukaan belajar","case_focus":"hasil tinggi dan refleksi","stem":"Nilai kelas tinggi setelah guru memakai contoh yang hampir sama dengan latihan. Dalam refleksi ia ingin mengetahui apakah murid mampu menggunakan prinsip di situasi lain. Nilai langkah berikut.","options":["Memeriksa tugas transfer dengan informasi baru tetapi prinsip yang sama.","Mencatat batas kesimpulan dari nilai tinggi sebagai bahan belajar guru.","Menganggap mempertanyakan nilai tinggi berarti meremehkan usaha murid."],"key":["T","T","F"],"why":"Growth mindset guru mencakup kemauan menguji penjelasan keberhasilan. Capaian tetap dihargai, sementara tugas transfer memberi informasi untuk memperbaiki praktik berikutnya.","explanations":["Tugas baru membantu menafsirkan kedalaman keberhasilan awal.","Refleksi terbuka mengakui hal yang belum dibuktikan.","Menelaah bukti untuk perbaikan tidak meniadakan penghargaan pada usaha."]},{"package":4,"id":75,"uid":"p4-075","section":"PU","code":"K.3","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Keteladanan; komitmen pada kebiasaan belajar","case_focus":"konsistensi janji dukungan","stem":"Guru berjanji memberi waktu konsultasi mingguan agar murid terbiasa menyusun rencana belajar. Dua kali jadwal batal tanpa kabar dan murid mulai enggan menyiapkan pertanyaan. Tindakan terbaik adalah ...","options":["Meminta murid lebih mandiri sehingga konsultasi tidak diperlukan.","Memperpanjang konsultasi berikutnya tanpa membicarakan jadwal yang batal.","Mengakui pembatalan dan memulihkan kepastian jadwal.","Memberi tugas tambahan untuk memastikan murid tetap menyiapkan pertanyaan."],"key":"C","why":"Komitmen membangun kebiasaan belajar tampak pada tindakan yang konsisten. Guru memperbaiki janji yang belum terpenuhi dan memberi kepastian agar persiapan murid memiliki tindak lanjut.","explanations":["Kemandirian belum dibangun melalui dukungan yang dijanjikan.","Tambahan waktu belum memulihkan kepastian kebiasaan.","Keteladanan konsisten memulihkan dasar kebiasaan belajar.","Tambahan tugas tidak menyelesaikan ketidakpastian dukungan guru."]},{"package":4,"id":76,"uid":"p4-076","section":"PU","code":"S.1","type":"MCMA","difficulty":"sedang","cp_element":null,"ppg_concept":"Komunikasi empatik; privasi","case_focus":"batas informasi keluarga","stem":"Orang tua meminta melalui grup kelas penjelasan rinci tentang murid lain yang mendapat penyesuaian tugas. Guru perlu menjelaskan prinsip keadilan tanpa membuka informasi pribadi. Pilih respons yang tepat.","options":["Menyampaikan diagnosis murid tanpa nama agar konteksnya jelas.","Menjelaskan bahwa dukungan disesuaikan dengan kebutuhan dan tujuan tetap diperiksa.","Mengakhiri percakapan dengan pernyataan bahwa keputusan tidak dapat ditanyakan.","Mengundang percakapan pribadi tentang kebutuhan anak penanya bila diperlukan."],"key":["B","D"],"why":"Komunikasi inklusif menjelaskan prinsip dan mengecek pemahaman. Guru menjaga batas data murid lain, sambil tetap membuka ruang dialog tentang kebutuhan anak masing-masing.","explanations":["Dalam grup kecil identitas tetap dapat mudah dikenali.","Penjelasan prinsip menjawab kekhawatiran tanpa membuka data pribadi.","Respons menutup komunikasi dan tidak membantu pemahaman.","Percakapan diarahkan ke informasi yang menjadi kewenangan orang tua tersebut."]},{"package":4,"id":77,"uid":"p4-077","section":"PU","code":"S.2","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Kolaborasi sekolah–keluarga","case_focus":"koordinasi tenaga sekolah","stem":"Seorang murid beberapa kali terlambat karena rute transportasi berubah. Guru kelas, wali kelas, dan petugas layanan sekolah masing-masing sudah menghubungi keluarga dengan permintaan berbeda. Koordinasi terbaik adalah ...","options":["Meminta setiap pihak melanjutkan cara masing-masing agar pilihan dukungan banyak.","Menyepakati satu penghubung, pembagian peran, dan peninjauan dukungan bersama keluarga.","Menyerahkan seluruh masalah kepada keluarga sebelum menyusun dukungan.","Memusatkan semua keputusan pada guru kelas tanpa masukan pihak lain."],"key":"B","why":"Kolaborasi efektif mengurangi komunikasi yang tumpang tindih. Keluarga dilibatkan untuk memeriksa kebutuhan, sedangkan peran dan evaluasi dukungan disepakati bersama.","explanations":["Permintaan yang berbeda dapat membebani keluarga dan saling bertentangan.","Koordinasi memperjelas komunikasi serta tindak lanjut yang dapat dipantau.","Sekolah mengabaikan peluang kolaborasi yang relevan.","Pemutusan tunggal belum memanfaatkan informasi dan peran yang tersedia."]},{"package":4,"id":78,"uid":"p4-078","section":"PU","code":"S.3","type":"Kategori","difficulty":"sedang","cp_element":null,"ppg_concept":"Komunitas profesi; observasi sejawat","case_focus":"belajar observasi sejawat","stem":"Komunitas guru merencanakan kunjungan observasi kelas. Tujuannya belajar bagaimana pertanyaan guru membuka penalaran murid, bukan menilai pribadi pengajar. Nilai kesepakatan berikut.","options":["Menyusun peringkat guru dari jumlah pertanyaan yang diajukan.","Mencatat contoh pertanyaan dan respons murid untuk dibahas bersama.","Meminta persetujuan penggunaan catatan dan menyepakati batas penyebarannya."],"key":["F","T","T"],"why":"Komunitas belajar memerlukan fokus bukti dan kepercayaan. Observasi menjadi sarana memahami praktik, dengan penggunaan catatan yang disepakati dan pembahasan yang berorientasi perbaikan.","explanations":["Jumlah pertanyaan tidak mewakili kualitas penalaran dan tujuan komunitas.","Catatan memberi bahan belajar yang terkait fokus observasi.","Kesepakatan membangun kepercayaan bagi pembelajaran profesi."]},{"package":4,"id":79,"uid":"p4-079","section":"PU","code":"PF.1","type":"PG","difficulty":"sedang","cp_element":null,"ppg_concept":"Tujuan pendidikan dasar; pendidikan nilai","case_focus":"nilai dan kepatuhan","stem":"Pada jenjang dasar, guru ingin membangun tanggung jawab. Selama ini murid merapikan alat hanya ketika guru membawa daftar hadiah. Bukti hasil pendidikan yang lebih sesuai tujuan adalah ...","options":["Murid mampu menyebutkan seluruh hadiah yang tersedia.","Murid cepat merapikan saat namanya akan diumumkan.","Murid selalu meminta guru memilih siapa yang harus merapikan.","Murid menjelaskan dampak tindakannya dan mengambil peran tanpa menunggu hadiah."],"key":"D","why":"Tujuan pendidikan dasar mencakup perkembangan nilai dan kemandirian bertindak. Bukti tidak berhenti pada kepatuhan sesaat; guru melihat alasan, tindakan, dan konsistensinya secara bertahap.","explanations":["Ingatan hadiah bukan bukti tanggung jawab.","Kecepatan dalam situasi berhadiah belum menunjukkan pemahaman nilai.","Ketergantungan keputusan belum menunjukkan tanggung jawab yang berkembang.","Alasan dan tindakan menunjukkan perkembangan tanggung jawab."]},{"package":4,"id":80,"uid":"p4-080","section":"PU","code":"P.6","type":"MCMA","difficulty":"menantang","cp_element":null,"ppg_concept":"Assessment as learning; metakognisi","case_focus":"kalibrasi keyakinan","stem":"Dalam refleksi asesmen, murid menandai tingkat keyakinan sebelum melihat umpan balik. Sebagian sangat yakin tetapi alasannya keliru; sebagian benar namun ragu. Pilih penggunaan data yang tepat.","options":["Membahas selisih keyakinan dan bukti alasan untuk merencanakan belajar.","Menambahkan nilai hanya karena murid menyatakan sangat yakin.","Meminta murid menguji ulang alasan setelah revisi dan menilai keyakinannya kembali.","Membedakan ketepatan jawaban dari ketepatan penilaian diri saat memberi umpan balik."],"key":["A","C","D"],"why":"Assessment as learning membantu murid mengkalibrasi penilaian diri. Guru menghubungkan keyakinan dengan bukti alasan serta rencana uji ulang, tanpa menjadikan keyakinan sebagai skor capaian.","explanations":["Murid memakai data diri sebagai dasar tindakan belajar.","Keyakinan tidak menggantikan bukti ketepatan pemahaman.","Siklus ini melatih pemantauan belajar berdasarkan bukti baru.","Kedua informasi memberi kebutuhan belajar yang berbeda."]}]}],"legacyQuestions":[{"id":1,"code":"P.1","type":"PG","stem":"Dalam rancangan ERD perpustakaan kelas, beberapa murid menjadikan nama siswa sebagai primary key karena setiap murid punya nama. Guru menemukan dua murid bernama Nisa. Tindakan pembelajaran yang paling tepat adalah ...","options":["Memberi definisi primary key untuk dicatat lalu meminta murid lanjut menggambar.","Memperlihatkan dua rekaman bernama Nisa, mengajak murid menguji identitas unik, lalu merevisi rancangan dengan ID siswa.","Langsung mengganti semua nama menjadi nomor urut tanpa diskusi.","Menghapus salah satu rekaman Nisa agar tidak ada duplikasi."],"key":"B","why":"Pertentangan data nyata mengungkap miskonsepsi: nama tidak menjamin keunikan, sedangkan ID siswa dapat menjadi PK. Guru membantu murid menemukan alasan sebelum memperbaiki ERD.","section":"PCK"},{"id":2,"code":"P.1","type":"MCMA","stem":"Kelompok merancang basis data peminjaman alat lab. Guru ingin menghubungkan konsep relasi satu-ke-banyak dengan implementasi SQL. Aktivitas mana yang paling mendukung? Pilih semua jawaban yang tepat.","options":["Meminta murid menyalin definisi foreign key berulang kali.","Membuat contoh satu siswa yang memiliki beberapa peminjaman.","Mengabaikan tabel referensi agar latihan lebih singkat.","Menempatkan id_siswa pada tabel peminjaman dan menguji data yang terhubung.","Meminta murid menjelaskan dampak jika id_siswa pada peminjaman tidak merujuk siswa yang ada."],"key":["B","D","E"],"why":"B, D, E menghubungkan kardinalitas, implementasi FK, dan integritas referensial. Menyalin definisi atau menghilangkan referensi tidak memfasilitasi pemahaman.","section":"PCK"},{"id":3,"code":"P.1","type":"PG","stem":"Murid membuat formulir Laravel yang bisa dikirim walaupun kolom email kosong. Mereka menyimpulkan atribut required di HTML saja pasti cukup menjaga validitas data. Cara paling tepat meluruskan konsep adalah ...","options":["Menyuruh murid menghafal semua aturan validasi Laravel.","Mengganti framework agar validasi otomatis sempurna.","Mendemonstrasikan pengiriman request yang melewati validasi browser, lalu membimbing penerapan validasi sisi server.","Menganggap hasilnya benar selama tampilan formulir rapi."],"key":"C","why":"Validasi browser membantu pengalaman pengguna, tetapi pemeriksaan data tetap diperlukan di server. Demonstrasi request memperlihatkan alasan teknisnya.","section":"PCK"},{"id":4,"code":"P.1","type":"Kategori","stem":"Guru memakai dua tabel kecil, siswa dan peminjaman, untuk membangun pemahaman JOIN. Nilai tiap tindakan sebagai Tepat atau Tidak tepat.","options":["Murid memprediksi hasil JOIN sebelum menjalankan query, lalu membandingkan prediksi dengan keluaran.","Guru langsung memberikan query jadi tanpa membahas relasi tabel.","Murid menjelaskan mengapa baris tertentu muncul atau tidak muncul dalam hasil INNER JOIN."],"key":["T","F","T"],"why":"Prediksi, uji, dan penjelasan hasil membangun model mental. Query yang hanya disalin dapat menghasilkan keluaran tanpa pemahaman relasi.","section":"PCK"},{"id":5,"code":"P.1","type":"PG","stem":"Saat mengenalkan objek dalam pemrograman berorientasi objek, murid menyamakan class dan object. Representasi awal mana yang paling membantu?","options":["Membandingkan class dengan rancangan atribut/perilaku dan object dengan dua instans nyata berbeda.","Meminta murid langsung membuat aplikasi kompleks tanpa contoh.","Mengatakan class dan object identik agar mudah diingat.","Menunda pembahasan hingga ujian akhir."],"key":"A","why":"Contoh dua objek dari satu class membedakan cetak biru dan instans sambil mempertahankan keterkaitan konsep dengan kode.","section":"PCK"},{"id":6,"code":"P.1","type":"MCMA","stem":"Kelompok belajar kolaborasi Git pada proyek website kelas. Bukti pemahaman alur kerja yang layak diminta guru adalah ... Pilih semua yang tepat.","options":["Mengumpulkan satu file ZIP terakhir tanpa riwayat perubahan.","Memperlihatkan commit dengan pesan yang menjelaskan perubahan.","Menjelaskan kapan sebuah branch perlu digabung dan bagaimana menangani konflik.","Memastikan semua murid memakai satu akun agar mudah.","Menjelaskan perubahan lewat perbandingan diff pada dua versi kode."],"key":["B","C","E"],"why":"Commit, branch/merge, dan diff merupakan bukti proses version control; satu file ZIP atau satu akun bersama menghilangkan jejak kontribusi.","section":"PCK"},{"id":7,"code":"P.1","type":"PG","stem":"Pada kasus transaksi koperasi sekolah, setiap transaksi bisa berisi banyak jenis barang. Murid membuat satu kolom barang1, barang2, barang3 pada tabel transaksi. Pertanyaan pemantik terbaik adalah ...","options":["“Kenapa kalian tidak memilih nama kolom lebih pendek?”","“Siapa yang paling cepat bisa menghafal SQL?”","“Bagaimana jika satu transaksi memuat enam barang dan jumlah tiap barang berbeda?” lalu mengarahkan ke tabel detail_transaksi.","“Maukah kalian menghapus transaksi yang berisi banyak barang?”"],"key":"C","why":"Kasus enam barang menonjolkan keterbatasan kolom berulang dan kebutuhan tabel detail yang terhubung dengan transaksi serta barang.","section":"PCK"},{"id":8,"code":"P.1","type":"Kategori","stem":"Guru mengajar perulangan dengan tabel pelacakan nilai variabel. Nilai tindakan sebagai Tepat atau Tidak tepat.","options":["Mengajak murid menelusuri nilai variabel pada setiap iterasi sebelum menjalankan program.","Menilai jawaban benar dari keluaran akhir saja tanpa memeriksa alasan murid.","Membandingkan pelacakan manual dengan keluaran program lalu membahas selisihnya."],"key":["T","F","T"],"why":"Trace table membantu menjelaskan keadaan program, bukan hanya hasil akhir. Membandingkan hasil merupakan kesempatan refleksi.","section":"PCK"},{"id":9,"code":"P.2","type":"PG","stem":"Asesmen awal menunjukkan sebagian murid sudah lancar SELECT-WHERE, sebagian belum mengenal kondisi WHERE. Strategi paling responsif adalah ...","options":["Memberikan tugas identik dengan target waktu sama untuk semuanya.","Membagi dukungan dan tingkat tantangan secara fleksibel sesuai bukti awal, dengan tujuan belajar inti yang sama.","Memindahkan murid yang belum lancar ke luar kelas.","Hanya menunjuk murid paling cepat untuk menjawab."],"key":"B","why":"Diferensiasi menyesuaikan jalan menuju tujuan yang sama berdasarkan kebutuhan nyata; bukan pelabelan kelompok tetap.","section":"PCK"},{"id":10,"code":"P.2","type":"Kategori","stem":"Di laboratorium, empat murid belum mendapat komputer. Nilai keputusan guru sebagai Tepat atau Tidak tepat.","options":["Menyusun giliran operator, penguji, dan pencatat sehingga semua berperan dan berganti peran.","Memberikan penilaian keterampilan komputer hanya kepada murid yang kebagian perangkat.","Menyiapkan tugas prediksi query atau rancangan ERD saat menunggu giliran praktik."],"key":["T","F","T"],"why":"Rotasi dan tugas tanpa perangkat menjaga partisipasi serta kesempatan menunjukkan capaian. Penilaian harus adil terhadap akses.","section":"PCK"},{"id":11,"code":"P.2","type":"MCMA","stem":"Salah satu murid memiliki kendala penglihatan dan kesulitan membaca tangkapan layar kode yang kecil. Penyesuaian apa yang tepat? Pilih semua.","options":["Menyediakan teks kode yang dapat diperbesar atau dibaca pembaca layar.","Mengurangi target menjadi hanya menonton teman tanpa kontribusi.","Memastikan kontras dan keterbacaan bahan praktik.","Mengizinkan alternatif cara menjelaskan logika program selama mengukur tujuan yang sama.","Mengecualikan murid dari asesmen agar tidak kesulitan."],"key":["A","C","D"],"why":"Penyesuaian akses dan cara respons dapat menjaga target kompetensi. Menghapus kesempatan praktik atau asesmen bukan pilihan inklusif.","section":"PCK"},{"id":12,"code":"P.2","type":"PG","stem":"Murid yang cepat selesai CRUD mulai tidak tertantang, sementara teman lain masih membuat tabel. Tindakan terbaik adalah ...","options":["Memberikan tantangan lanjutan validasi dan uji kasus batas, sambil menyediakan bantuan bertahap bagi yang masih kesulitan.","Menjadikan murid cepat selesai sebagai pengganti guru sepanjang jam.","Menghentikan kegiatan semua murid sampai seluruh kelas sama cepat.","Memberi tugas menyalin ulang kode tanpa tujuan baru."],"key":"A","why":"Tantangan pengayaan dan scaffolding disesuaikan kesiapan. Tutor sebaya boleh membantu, tetapi tidak menggantikan tanggung jawab guru.","section":"PCK"},{"id":13,"code":"P.2","type":"PG","stem":"Dalam diskusi ERD ada murid yang sulit mengikuti penjelasan lisan di ruang bising. Respons guru yang paling tepat adalah ...","options":["Menganggap murid tidak fokus dan menegur di depan kelas.","Menambah volume bicara saja tanpa melihat hambatan.","Memberikan instruksi tertulis/visual, memastikan posisi dan akses komunikasi, serta mengecek pemahaman secara pribadi.","Membebaskan murid dari tujuan pembelajaran."],"key":"C","why":"Akses multimodal dan pengecekan pemahaman membuat murid dapat ikut tanpa distigma.","section":"PCK"},{"id":14,"code":"P.3","type":"PG","stem":"Saat latihan debugging banyak murid malu karena error. Guru ingin kelas aman untuk mencoba. Respons terbaik adalah ...","options":["Mengumumkan siapa paling banyak error.","Menunjukkan contoh error dari kode sederhana, menormalisasi revisi, dan meminta murid menjelaskan langkah diagnosis.","Menghapus latihan debugging dari kegiatan.","Menghitung semua error sebagai pelanggaran tata tertib."],"key":"B","why":"Menormalisasi kesalahan sebagai bukti proses belajar dan mengajarkan strategi diagnosis mendukung keberanian bereksperimen.","section":"PCK"},{"id":15,"code":"P.3","type":"Kategori","stem":"Guru menyiapkan proyek pencatatan peminjaman kelas. Nilai praktik berikut sebagai Tepat atau Tidak tepat.","options":["Membuka pembelajaran dengan masalah yang dekat dengan kebutuhan murid dan menjelaskan alasan mempelajarinya.","Mewajibkan setiap kelompok menghias slide tanpa menguji fungsi database.","Mengakhiri proyek dengan refleksi keputusan desain, kendala, dan perbaikan."],"key":["T","F","T"],"why":"Pembelajaran bermakna menghubungkan tujuan, pengalaman, dan refleksi; hiasan bukan bukti capaian teknis.","section":"PCK"},{"id":16,"code":"P.3","type":"MCMA","stem":"Guru ingin suasana diskusi kode menyenangkan tetapi tetap menantang. Pilih praktik yang tepat.","options":["Mengizinkan kelompok menjelaskan alternatif solusi tanpa diejek.","Menyebut kode murid tertentu “paling bodoh” sebagai humor.","Memberi kriteria keberhasilan yang jelas dan kesempatan memperbaiki produk.","Memuji proses pengujian dan argumentasi, bukan hanya jawaban tercepat.","Mewajibkan semua murid meniru satu cara tanpa berdiskusi."],"key":["A","C","D"],"why":"Keamanan psikologis, kesempatan revisi, dan penghargaan atas alasan membangun keterlibatan tanpa menurunkan standar.","section":"PCK"},{"id":17,"code":"P.3","type":"PG","stem":"Menjelang akhir sesi SQL, murid mulai kehilangan fokus. Pilihan yang tetap bermakna adalah ...","options":["Memberi ceramah baru selama 30 menit tanpa interaksi.","Menutup pelajaran lebih awal tanpa asesmen.","Meminta murid menyalin definisi JOIN sebanyak sepuluh kali.","Melakukan tantangan singkat: prediksi query, uji di DB, lalu simpulkan satu temuan dan satu pertanyaan."],"key":"D","why":"Aktivitas singkat yang mengaktifkan prediksi–uji–refleksi memulihkan keterlibatan sekaligus memeriksa pemahaman.","section":"PCK"},{"id":18,"code":"P.4","type":"PG","stem":"Murid menggunakan AI untuk membuat kode autentikasi dan menganggap hasilnya pasti aman. Guru sebaiknya ...","options":["Melarang pembicaraan tentang AI selamanya.","Meminta murid menguji dan menjelaskan kode, memeriksa pengelolaan sandi serta input, dan mendiskusikan keterbatasan keluaran AI.","Memberi nilai penuh karena aplikasi berhasil dijalankan.","Membagikan kredensial server sekolah ke AI untuk meminta perbaikan."],"key":"B","why":"Literasi AI mencakup verifikasi fungsi, keamanan, sumber data, dan tanggung jawab penggunaan.","section":"PCK"},{"id":19,"code":"P.4","type":"Kategori","stem":"Guru memakai platform daring untuk penugasan RPL. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Menyiapkan alternatif akses saat jaringan atau perangkat murid terbatas.","Mengunggah data identitas siswa asli ke layanan publik agar contoh terlihat realistis.","Memilih alat berdasarkan kontribusinya terhadap tujuan belajar, bukan popularitasnya."],"key":["T","F","T"],"why":"Penggunaan TIK perlu mempertimbangkan akses, privasi, dan kesesuaian tujuan, bukan semata fitur.","section":"PCK"},{"id":20,"code":"P.4","type":"MCMA","stem":"Saat internet lab tidak stabil, guru tetap ingin murid mempelajari hubungan tabel. Pilih alternatif yang tepat.","options":["Menggunakan kartu entitas dan atribut untuk memodelkan relasi secara luring.","Menunggu internet pulih tanpa aktivitas belajar apa pun.","Menyiapkan skrip SQL lokal atau dataset contoh yang bisa dijalankan tanpa internet.","Menggunakan kertas untuk memprediksi hasil JOIN, lalu menguji saat perangkat siap.","Menghapus tujuan belajar hari itu selamanya."],"key":["A","C","D"],"why":"Model fisik, SQL lokal, dan prediksi kertas tetap menargetkan konsep yang sama meski koneksi tidak tersedia.","section":"PCK"},{"id":21,"code":"P.4","type":"PG","stem":"Guru hendak memilih aplikasi gambar ERD daring. Murid mampu menggambar ERD di kertas. Prinsip pilihan paling tepat adalah ...","options":["Gunakan aplikasi apa pun asalkan paling ramai dipakai.","Teknologi wajib digunakan di setiap tahap meskipun waktu terbuang untuk registrasi.","Pilih alat apabila membantu menguji relasi, merevisi rancangan, atau kolaborasi; kertas tetap sah bila mencapai tujuan.","Hanya hasil digital yang boleh dinilai."],"key":"C","why":"Teknologi alat, bukan tujuan. Pilihan didasarkan pada nilai tambah pedagogis dan kondisi akses.","section":"PCK"},{"id":22,"code":"P.4","type":"PG","stem":"Sebuah generator kode AI menghasilkan query yang menampilkan informasi pribadi siswa tanpa pembatasan. Tugas belajar yang paling tepat adalah ...","options":["Membandingkan keluaran dengan kebutuhan dan prinsip akses data, lalu merancang query yang hanya menampilkan informasi yang diperlukan.","Menggunakan query itu apa adanya karena dapat dijalankan.","Mempublikasikan hasil query agar mudah dinilai.","Menghapus topik keamanan data dari silabus."],"key":"A","why":"Kritik terhadap keluaran otomatis menuntut pemahaman kebutuhan, minimisasi data, dan pengujian hasil.","section":"PCK"},{"id":23,"code":"P.5","type":"PG","stem":"Guru ingin memberi tugas rancangan basis data yang dekat dengan kehidupan murid. Masalah peminjaman alat olahraga sekolah tersedia dan datanya bisa disimulasikan. Kegiatan terbaik adalah ...","options":["Memilih kasus industri yang rumit walaupun murid belum memahami entitas.","Menyalin rancangan dari internet tanpa memahami kebutuhan.","Membiarkan murid menggambar tabel sesuka hati tanpa spesifikasi.","Mengobservasi kebutuhan peminjaman, menyusun entitas-relasi, dan menguji rancangan dengan contoh transaksi."],"key":"D","why":"Kebutuhan lokal yang konkret dapat menghubungkan konsep ERD, relasi, dan validasi rancangan.","section":"PCK"},{"id":24,"code":"P.5","type":"Kategori","stem":"Guru mengadaptasi studi kasus untuk SMK. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Memakai contoh proses koperasi setempat tanpa menganggap semua murid memiliki pengalaman yang sama.","Memilih konteks hanya karena tren walaupun tidak mendukung kompetensi yang dinilai.","Mengajak murid menyebutkan contoh alur data lain yang setara bila pengalaman awal berbeda."],"key":["T","F","T"],"why":"Konteks lokal membantu jika relevan dan membuka beragam pengalaman; guru tidak boleh berasumsi semua murid sama.","section":"PCK"},{"id":25,"code":"P.5","type":"MCMA","stem":"Pada kelas RPL dengan komputer terbatas, guru menerapkan proyek inventaris. Tindakan yang mempertahankan substansi belajar adalah ... Pilih semua.","options":["Membagi peran perancang ERD, penulis SQL, dan penguji dengan rotasi.","Menilai hanya keberhasilan mengetik tercepat.","Menyediakan contoh data kecil untuk menguji PK/FK.","Mengadakan presentasi alasan desain yang dapat diikuti anggota tanpa perangkat.","Membiarkan murid yang tak mendapat komputer tidak mengerjakan apa pun."],"key":["A","C","D"],"why":"Peran rotasi, data uji, dan pertanggungjawaban desain memberi kontribusi nyata bagi seluruh murid.","section":"PCK"},{"id":26,"code":"P.5","type":"PG","stem":"Kelompok hendak memakai data asli pelanggan usaha keluarga siswa untuk praktik. Respons paling tepat adalah ...","options":["Menggunakan semua nomor telepon asli agar realistis.","Membuat data simulasi/anonym dan mempertahankan struktur kebutuhan usaha, sambil menjelaskan perlindungan data pribadi.","Membagikan data ke seluruh sekolah.","Menghapus semua konteks usaha dari pembelajaran."],"key":"B","why":"Kasus lokal tetap dapat dipakai tanpa membuka data pribadi; tujuan pembelajaran terletak pada model dan logika data.","section":"PCK"},{"id":27,"code":"P.6","type":"PG","stem":"Sebelum mengajar PK dan FK, guru bertanya apakah dua orang boleh memiliki nama sama dan apakah dua peminjaman bisa dilakukan satu siswa. Fungsi utama pertanyaan itu ialah ...","options":["Asesmen diagnostik untuk memetakan gagasan awal tentang identitas dan relasi.","Penilaian akhir yang langsung menentukan nilai rapor.","Menguji hafalan seluruh sintaks SQL lanjutan.","Menentukan murid mana yang tidak boleh praktik."],"key":"A","why":"Pertanyaan sebelum pembelajaran memunculkan konsepsi awal dan membantu memilih dukungan belajar.","section":"PCK"},{"id":28,"code":"P.6","type":"MCMA","stem":"Murid menghasilkan query JOIN tetapi sebagian rekaman hilang. Bukti asesmen formatif apa yang membantu guru menemukan sumber masalah? Pilih semua.","options":["Meminta murid menjelaskan tabel mana yang menjadi asal setiap kolom.","Mencatat hanya waktu tercepat menjalankan query.","Meminta prediksi baris yang seharusnya muncul dan membandingkannya dengan hasil.","Memeriksa apakah kondisi JOIN dan data kunci cocok.","Memberikan nilai nol sebelum mengetahui alasan kesalahan."],"key":["A","C","D"],"why":"Penelusuran asal kolom, prediksi data, dan pemeriksaan kondisi JOIN menunjukkan miskonsepsi secara spesifik.","section":"PCK"},{"id":29,"code":"P.6","type":"Kategori","stem":"Guru membuat rubrik tugas ERD. Nilai pernyataan berikut sebagai Tepat atau Tidak tepat.","options":["Kriteria mencakup kecocokan entitas, PK, kardinalitas, dan alasan hubungan dengan kasus.","Penilaian hanya berdasarkan warna dan kerapian gambar, tanpa memeriksa kebenaran model.","Guru menjelaskan rubrik sebelum bekerja sehingga murid dapat menggunakannya untuk revisi."],"key":["T","F","T"],"why":"Rubrik selaras dengan tujuan belajar dan transparan sejak awal. Tampilan boleh dipertimbangkan, tetapi bukan inti kompetensi ERD.","section":"PCK"},{"id":30,"code":"P.6","type":"PG","stem":"Murid menggambar relasi siswa–peminjaman sebagai 1:1 padahal satu siswa dapat meminjam berkali-kali. Umpan balik yang paling berguna adalah ...","options":["“Salah semua, ulang dari awal.”","“Bagus, yang penting garisnya lurus.”","“Coba uji kasus satu siswa dengan tiga transaksi. Apakah rancanganmu masih menampung semuanya? Perbaiki kardinalitasnya.”","“Ikuti gambar kelompok lain tanpa bertanya.”"],"key":"C","why":"Umpan balik spesifik memicu pengujian model terhadap kasus sehingga siswa memahami alasan perbaikan.","section":"PCK"},{"id":31,"code":"P.6","type":"PG","stem":"Setelah kuis JOIN, 70% murid salah membedakan INNER dan LEFT JOIN. Langkah selanjutnya paling tepat adalah ...","options":["Melanjutkan bab baru karena rencana sudah ditulis.","Mengelompokkan tipe kesalahan, mengajar ulang dengan data kecil yang punya baris tanpa pasangan, lalu mengecek ulang pemahaman.","Menaikkan nilai agar semua terlihat berhasil.","Memberikan tugas menyalin sintaks tanpa analisis kesalahan."],"key":"B","why":"Hasil asesmen harus dipakai untuk mengubah pengajaran. Data tanpa pasangan memberi bukti konkret perbedaan jenis JOIN.","section":"PCK"},{"id":32,"code":"P.6","type":"MCMA","stem":"Untuk menilai kompetensi implementasi relasi basis data, bukti yang relevan adalah ... Pilih semua.","options":["Skrip pembuatan tabel lengkap dengan PK dan FK yang valid.","Screenshot editor kosong yang rapi.","Data uji yang membuktikan relasi dan penjelasan hasil query.","Uraian alasan memilih kardinalitas dari kebutuhan kasus.","Jumlah ikon pada halaman presentasi."],"key":["A","C","D"],"why":"Bukti autentik harus mencakup artefak teknis, uji perilaku, dan justifikasi rancangan.","section":"PCK"},{"id":33,"code":"P.6","type":"PG","stem":"Tujuan pembelajaran adalah “murid mampu menentukan primary key yang tepat dalam kasus pencatatan data”. Bentuk asesmen paling selaras adalah ...","options":["Menghafalkan sejarah SQL.","Menggambar ikon database.","Menyalin definisi entitas dari modul.","Memilih dan membenarkan PK pada dua kasus dengan nama/atribut yang berpotensi sama."],"key":"D","why":"Tugas memilih dan menjelaskan PK mengukur keputusan teknis sesuai tujuan, bukan hafalan lepas konteks.","section":"PCK"},{"id":34,"code":"P.6","type":"Kategori","stem":"Nilai tindakan umpan balik berikut sebagai Tepat atau Tidak tepat.","options":["Guru menyebut bagian query yang sudah benar dan memberi petunjuk pada kondisi yang perlu diperiksa.","Guru mempublikasikan peringkat murid paling banyak salah untuk mempermalukan mereka.","Guru meminta murid memperbaiki hasilnya lalu menjelaskan perubahan dan alasan revisi."],"key":["T","F","T"],"why":"Umpan balik harus spesifik, aman, dan dapat ditindaklanjuti; revisi menunjukkan belajar dari asesmen.","section":"PCK"},{"id":35,"code":"PF.1","type":"PG","stem":"Pembelajaran proyek aplikasi sekolah dianggap selesai jika website bisa dibuka. Agar tujuan pendidikan kejuruan tercapai lebih utuh, guru seharusnya juga ...","options":["Memastikan murid dapat menjelaskan keputusan, bekerja bertanggung jawab, mengevaluasi keamanan, dan menerima umpan balik pengguna.","Menilai estetika saja.","Membatasi murid pada meniru tampilan tanpa memahami kebutuhan.","Mengutamakan ranking kecepatan mengetik."],"key":"A","why":"Kompetensi SMK mengaitkan penguasaan teknis, penalaran, kerja sama, etika, dan kemampuan beradaptasi.","section":"PCK"},{"id":36,"code":"PF.1","type":"Kategori","stem":"Proyek pembuatan sistem kelas dilakukan dalam pembelajaran. Nilai pernyataan sebagai Tepat atau Tidak tepat.","options":["Mengajak murid membahas hak akses dan dampak aplikasi terhadap pengguna.","Menganggap keberhasilan teknis membenarkan pengumpulan data pribadi berlebihan.","Mengaitkan kemampuan pemrograman dengan penyelesaian masalah nyata dan tanggung jawab sosial."],"key":["T","F","T"],"why":"Tujuan pendidikan menuntut kompetensi dan karakter; etika digital tidak boleh dikorbankan demi fitur.","section":"PCK"},{"id":37,"code":"PF.2","type":"PG","stem":"Saat mengajar keamanan aplikasi, murid membangun query dengan menggabungkan input pengguna ke string SQL. Penjelasan dan perbaikan yang tepat adalah ...","options":["Mengajarkan penggunaan prepared statement/parameter binding dan menunjukkan mengapa input tidak boleh diperlakukan sebagai bagian sintaks SQL.","Memakai kata sandi yang sama untuk semua akun agar mudah.","Menganggap input hanya angka sehingga selalu aman.","Menyembunyikan error tanpa memperbaiki query."],"key":"A","why":"Parameter binding memisahkan data input dari struktur perintah SQL, sehingga efektif menjadi contoh konsep keamanan aplikasi.","section":"PCK"},{"id":38,"code":"PF.2","type":"MCMA","stem":"Murid mendesain tabel siswa dan peminjaman dengan relasi 1:N. Manakah rancangan/aktivitas teknis yang benar? Pilih semua.","options":["Kolom id_siswa dapat menjadi PK di tabel siswa.","Memakai nama_siswa sebagai satu-satunya pengenal karena pasti unik.","Kolom id_siswa di peminjaman dapat menjadi FK menuju siswa.","Menguji apakah sistem menolak peminjaman dengan id_siswa yang tidak ada jika constraint FK aktif.","Satu baris siswa harus digandakan untuk setiap peminjaman."],"key":["A","C","D"],"why":"PK unik di tabel siswa, FK di sisi banyak, dan pengujian integritas merepresentasikan relasi 1:N yang benar.","section":"PCK"},{"id":39,"code":"PF.2","type":"PG","stem":"Murid mengirim form Laravel dengan method POST, tetapi route hanya didaftarkan untuk GET. Strategi pembelajaran tepat adalah ...","options":["Meminta murid me-restart komputer berulang kali.","Mengganti seluruh proyek dengan HTML statis.","Menelusuri alur request dari form ke route dan controller, membandingkan method, lalu memperbaiki definisi route.","Menghapus semua validasi agar request diproses."],"key":"C","why":"Kesalahan method menjadi kesempatan memeriksa hubungan form, HTTP method, route, dan controller.","section":"PCK"},{"id":40,"code":"PF.2","type":"Kategori","stem":"Guru memakai contoh tabel siswa (S1, S2) dan peminjaman (hanya milik S1). Nilai pernyataan konsep SQL sebagai Tepat atau Tidak tepat.","options":["INNER JOIN pada kunci siswa hanya mengembalikan pasangan yang cocok dalam contoh ini.","LEFT JOIN dari tabel siswa ke peminjaman dapat tetap memunculkan S2 dengan kolom peminjaman bernilai NULL.","Setiap LEFT JOIN selalu memiliki jumlah baris tepat sama dengan tabel kiri meski ada beberapa pasangan."],"key":["T","T","F"],"why":"INNER JOIN memerlukan pasangan; LEFT JOIN mempertahankan baris kiri, tetapi bisa menghasilkan lebih banyak baris jika satu baris kiri memiliki banyak pasangan.","section":"PCK"},{"id":41,"code":"PF.2","type":"PG","stem":"Murid membuat kondisi “nilai >= 75” untuk menentukan tuntas. Saat nilai tepat 75, program menyatakan tuntas. Untuk menguji pemahaman kondisi batas, guru sebaiknya meminta ...","options":["Hanya menjalankan input 90 berulang kali.","Menguji nilai 74, 75, 76, lalu menjelaskan fungsi operator >= terhadap ketiga hasil.","Mengganti semua operator menjadi ==.","Menilai warna tombol terlebih dahulu."],"key":"B","why":"Kasus batas 74, 75, 76 secara langsung menampakkan efek operator perbandingan.","section":"PCK"},{"id":42,"code":"PF.2","type":"MCMA","stem":"Untuk membimbing praktik Git yang dapat dipertanggungjawabkan, guru mengutamakan ... Pilih semua.","options":["Commit perubahan kecil dengan pesan bermakna.","Menyimpan kata sandi ke repositori publik supaya semua bisa uji.","Menggunakan pull request/review perubahan untuk proyek kolaboratif.","Menangani konflik penggabungan dengan membaca perubahan yang bertentangan.","Menghapus riwayat agar kontribusi tidak terlihat."],"key":["A","C","D"],"why":"Praktik version control mencakup jejak perubahan, review, dan resolusi konflik. Kredensial tidak boleh dipublikasikan.","section":"PCK"},{"id":43,"code":"PF.3","type":"PG","stem":"Sebagian siswa memahami logika program tetapi kesulitan membaca instruksi teks panjang. Guru ingin mengukur logika seleksi kondisi. Penyesuaian terbaik adalah ...","options":["Memberi diagram alir sederhana dan contoh input-output, lalu meminta siswa menjelaskan atau mengimplementasikan logika yang sama.","Mengganti semua kompetensi menjadi hafalan istilah.","Menganggap kesulitan membaca berarti tidak mampu pemrograman.","Menilai kualitas tulisan tangan sebagai kompetensi inti."],"key":"A","why":"Representasi visual dan contoh mengurangi hambatan bahasa tanpa menghilangkan tuntutan logika seleksi.","section":"PCK"},{"id":44,"code":"PF.3","type":"MCMA","stem":"Guru menggunakan kasus katalog produk UMKM setempat untuk basis data kelas. Praktik yang tepat adalah ... Pilih semua.","options":["Menyusun dataset tiruan yang menjaga struktur produk-kategori-transaksi.","Mengharuskan semua murid memiliki pengalaman usaha keluarga.","Memberikan penjelasan istilah yang belum dikenal murid.","Membuka alternatif kasus sepadan bagi murid yang lebih memahami perpustakaan atau inventaris.","Memakai informasi kontak pelanggan asli tanpa izin."],"key":["A","C","D"],"why":"Kasus lokal relevan dengan dukungan bahasa, pilihan konteks setara, dan perlindungan privasi.","section":"PCK"},{"id":45,"code":"PF.3","type":"Kategori","stem":"Untuk menetapkan kesiapan kelas sebelum materi API, nilai tindakan berikut sebagai Tepat atau Tidak tepat.","options":["Memeriksa apakah murid sudah memahami request, response, dan format data sederhana.","Menganggap semua murid otomatis memahami API karena sering memakai aplikasi.","Menyiapkan contoh konkret JSON dan alur pertukaran data bagi yang membutuhkan."],"key":["T","F","T"],"why":"Membaca kebutuhan berdasarkan prasyarat nyata, bukan asumsi kebiasaan memakai teknologi.","section":"PCK"},{"id":46,"code":"PF.4","type":"PG","stem":"Sekolah perlu mengontekstualkan pembelajaran RPL dengan kebutuhan inventaris. Guru sedang menyusun alur tujuan pembelajaran. Pilihan terbaik adalah ...","options":["Mengganti seluruh capaian menjadi dekorasi website karena paling disukai murid.","Memilih aktivitas populer tanpa menghubungkan ke tujuan.","Menetapkan tujuan kompetensi terkait analisis kebutuhan, model data, dan pengujian; kasus inventaris menjadi konteks pencapaiannya.","Menyamakan semua murid tanpa mempertimbangkan pengetahuan awal."],"key":"C","why":"Adaptasi kurikulum tetap menurunkan tujuan dari capaian dan memilih konteks untuk mencapainya.","section":"PCK"},{"id":47,"code":"PF.4","type":"MCMA","stem":"Framework web berubah versi. Guru ingin materi tetap relevan secara kurikuler. Mana yang tepat? Pilih semua.","options":["Mempertahankan prinsip request-response, validasi, dan pengelolaan data sebagai konsep lintas-versi.","Mewajibkan murid menghafal seluruh sintaks versi lama tanpa memahami konsep.","Memperbarui contoh sesuai dokumentasi tepercaya sambil menguji kompatibilitas.","Membandingkan perubahan sintaks dengan prinsip yang tetap berlaku.","Menghapus semua pelajaran dasar karena framework akan selalu berubah."],"key":["A","C","D"],"why":"Kurikulum adaptif memperbarui contoh tanpa mengorbankan konsep fundamental serta tujuan kompetensi.","section":"PCK"},{"id":48,"code":"PF.4","type":"Kategori","stem":"Guru menyelaraskan tujuan, kegiatan, dan asesmen untuk materi ERD. Nilai berikut sebagai Tepat atau Tidak tepat.","options":["Jika tujuan menentukan kardinalitas, siswa diberi kasus untuk menjelaskan arah relasi dan jumlah keterlibatan entitas.","Jika tujuan merancang ERD, tes satu-satunya harus menanyakan warna simbol pada aplikasi gambar tertentu.","Rubrik menyebut indikator kebenaran entitas, hubungan, dan alasan model."],"key":["T","F","T"],"why":"Keselarasan capaian–aktivitas–asesmen lebih penting daripada fitur alat tertentu.","section":"PCK"},{"id":49,"code":"PF.5","type":"PG","stem":"Guru mencatat bahwa murid berulang kali salah menentukan foreign key walau sudah diberi penjelasan. Tindakan pengembangan praktik paling ilmiah adalah ...","options":["Menganggap murid malas dan mempertahankan pendekatan yang sama.","Mencoba intervensi contoh data berelasi, membandingkan bukti kerja sebelum-sesudah, lalu merefleksikan hasilnya.","Memilih intervensi baru hanya karena sedang viral.","Mengurangi target asesmen agar tampak berhasil."],"key":"B","why":"Perbaikan profesional bertumpu pada identifikasi masalah, tindakan beralasan, bukti hasil, dan refleksi.","section":"PCK"},{"id":50,"code":"PF.5","type":"MCMA","stem":"Setelah proyek website, guru mengembangkan praktik melalui komunitas guru RPL. Tindakan yang etis dan bermanfaat adalah ... Pilih semua.","options":["Membagikan contoh rubrik dan data hasil belajar yang telah dianonimkan untuk mendapat masukan.","Menyebarkan nilai beserta nomor telepon siswa kepada publik.","Menguji masukan rekan pada kelas dan mengamati dampaknya.","Mendokumentasikan keterbatasan uji coba agar tidak mengklaim pasti berhasil.","Mengklaim satu percobaan kecil membuktikan semua metode lain salah."],"key":["A","C","D"],"why":"Pengembangan praktik harus reflektif, terbuka pada bukti, dan melindungi identitas murid.","section":"PCK"},{"id":51,"code":"P.1","type":"PG","stem":"Guru IPS ingin siswa memahami perubahan lingkungan, menerapkan konsep pada lingkungan sekitar, lalu merefleksikan pilihan tindakannya. Rancangan terbaik adalah ...","options":["Ceramah definisi lalu tes hafalan semata.","Kuis cepat tanpa kegiatan lanjutan.","Mengamati masalah sekitar, menganalisis dengan konsep yang dipelajari, mengusulkan langkah, dan menulis refleksi.","Meminta menyalin isi buku tanpa diskusi."],"key":"C","why":"Rancangan ini menyatukan pemahaman konsep, penerapan kontekstual, dan refleksi bermakna sebagaimana P.1.","section":"PU"},{"id":52,"code":"P.1","type":"Kategori","stem":"Nilai langkah pembelajaran bermakna berikut sebagai Tepat atau Tidak tepat.","options":["Membuka ruang bagi siswa menjelaskan apa yang berubah dari pemahaman awalnya.","Membatasi keberhasilan pada selesai menyalin jawaban guru.","Menautkan kegiatan dengan tujuan yang jelas dan tantangan di kehidupan nyata."],"key":["T","F","T"],"why":"Refleksi dan transfer menunjukkan pemahaman; reproduksi jawaban saja belum cukup.","section":"PU"},{"id":53,"code":"P.1","type":"MCMA","stem":"Guru menemukan miskonsepsi pada konsep yang menjadi prasyarat pelajaran berikutnya. Strategi yang tepat adalah ... Pilih semua.","options":["Mengumpulkan jawaban awal untuk mengetahui penalaran siswa.","Memberi contoh pembanding yang menguji gagasan keliru.","Menolak pertanyaan karena mengganggu jadwal.","Meminta siswa membandingkan gagasan awal dan hasil setelah eksplorasi.","Memberi nilai akhir hanya dari kecepatan menjawab."],"key":["A","B","D"],"why":"Perubahan konsep dibantu diagnosis, bukti pembanding, dan refleksi pemahaman.","section":"PU"},{"id":54,"code":"P.2","type":"PG","stem":"Dalam satu kelas ada siswa dengan kemampuan membaca berbeda. Guru ingin semua memahami gagasan utama bacaan. Pilihan terbaik adalah ...","options":["Memakai satu bahan sulit tanpa dukungan karena adil artinya sama persis.","Menyediakan teks inti, penjelasan visual/audio yang relevan, dan pertanyaan tujuan sama dengan dukungan berbeda.","Mengeluarkan siswa yang lambat dari kegiatan.","Menggantikan tujuan memahami bacaan menjadi sekadar kehadiran."],"key":"B","why":"Kesetaraan tujuan dapat disertai variasi dukungan agar hambatan akses tidak menghalangi pencapaian.","section":"PU"},{"id":55,"code":"P.2","type":"Kategori","stem":"Kelas terdiri atas siswa dari beragam latar bahasa. Nilai tindakan berikut sebagai Tepat atau Tidak tepat.","options":["Guru memastikan istilah penting dipahami melalui contoh tanpa merendahkan bahasa rumah siswa.","Guru menganggap aksen berbeda sebagai tanda kemampuan berpikir rendah.","Guru memberi kesempatan murid mengungkapkan ide secara bertahap dengan dukungan bahasa."],"key":["T","F","T"],"why":"Pembelajaran responsif menghargai identitas bahasa sekaligus menjaga target akademik.","section":"PU"},{"id":56,"code":"P.2","type":"MCMA","stem":"Guru mengatur kerja kelompok dengan siswa yang berbeda kesiapan dan kebutuhan. Pilih keputusan yang tepat.","options":["Membagikan peran jelas dan kesempatan rotasi peran.","Menyerahkan semua pekerjaan ke satu siswa yang dianggap pintar.","Mengecek secara berkala siapa yang belum mendapat kesempatan bicara.","Menyediakan kriteria tugas dan bantuan berjenjang.","Memberi label permanen kelompok pintar dan lemah."],"key":["A","C","D"],"why":"Peran, pemantauan partisipasi, dan scaffolding mendukung keterlibatan seluruh siswa.","section":"PU"},{"id":57,"code":"P.2","type":"PG","stem":"Siswa pindahan belum mengenal istilah teknis yang telah dipelajari kelas. Langkah awal paling tepat adalah ...","options":["Menganggap ia tertinggal permanen.","Memberi ujian dengan skor nol lalu mengumumkannya.","Mewajibkan menghafal semua istilah dalam satu malam.","Memeriksa prasyarat, memberi glosarium/contoh ringkas, dan memasangkan dukungan belajar tanpa mengurangi tujuan."],"key":"D","why":"Dukungan spesifik berdasarkan prasyarat lebih efektif daripada stigma atau tuntutan tanpa bantuan.","section":"PU"},{"id":58,"code":"P.3","type":"PG","stem":"Seorang siswa memberi jawaban salah dan beberapa teman tertawa. Guru sebaiknya ...","options":["Mengajak kelas menghargai proses mencoba, menanyakan alasan jawaban, dan menuntun peninjauan bukti tanpa mempermalukan.","Membiarkan ejekan demi kebebasan berekspresi.","Langsung menghapus nilai siswa yang salah.","Membuat daftar siswa yang tidak boleh menjawab lagi."],"key":"A","why":"Keamanan psikologis dan pembahasan alasan menciptakan ruang belajar yang berkesadaran dan menggembirakan.","section":"PU"},{"id":59,"code":"P.3","type":"Kategori","stem":"Nilai gagasan tentang pembelajaran berkesadaran, bermakna, dan menggembirakan berikut sebagai Tepat atau Tidak tepat.","options":["Siswa memahami tujuan belajar dan diberi ruang merefleksikan prosesnya.","Pembelajaran menggembirakan selalu berarti tanpa tantangan akademik.","Aktivitas boleh menantang apabila ada dukungan, relevansi, dan suasana aman."],"key":["T","F","T"],"why":"Kegembiraan belajar bukan hiburan semata; fokus, relevansi, tantangan yang terdukung, dan rasa aman bisa berjalan bersama.","section":"PU"},{"id":60,"code":"P.4","type":"PG","stem":"Guru ingin siswa memakai AI untuk membuat rangkuman materi. Risiko utamanya ialah jawaban AI bisa keliru dan data siswa dapat terbuka. Langkah tepat adalah ...","options":["Mewajibkan semua siswa mengunggah informasi keluarga.","Mengevaluasi keluaran dengan sumber tepercaya, melarang pengiriman data pribadi, dan meminta siswa menjelaskan hasil dengan bahasa sendiri.","Melarang semua diskusi literasi digital.","Menganggap keluaran AI otomatis bersumber resmi."],"key":"B","why":"Literasi digital meliputi verifikasi dan privasi, bukan hanya kemampuan menjalankan alat.","section":"PU"},{"id":61,"code":"P.4","type":"MCMA","stem":"Guru memilih media pembelajaran digital untuk kelas dengan akses beragam. Pertimbangan yang tepat adalah ... Pilih semua.","options":["Tersedia versi berukuran ringan atau alternatif luring.","Tampilan dan petunjuk mudah diakses dengan kebutuhan murid yang beragam.","Selalu mewajibkan gawai spesifikasi tinggi walau banyak murid tidak memiliki.","Data murid yang diperlukan dibatasi sesuai tujuan.","Memilih media hanya karena sedang populer."],"key":["A","B","D"],"why":"Akses, inklusi, dan keamanan data menjadi dasar pemilihan TIK yang kritis.","section":"PU"},{"id":62,"code":"P.5","type":"PG","stem":"Guru akan mengajar perbandingan dengan contoh kehidupan sekitar. Sebagian siswa belum familiar dengan konteks pasar tradisional. Pilihan terbaik adalah ...","options":["Memakai hanya satu contoh dan menyalahkan yang tidak paham.","Menghindari konteks nyata sama sekali.","Menyediakan beberapa konteks setara yang familier dan mengajak siswa menghubungkan ke konsep yang sama.","Menilai latar budaya sebagai faktor kemampuan permanen."],"key":"C","why":"Konteks beragam membantu transfer konsep tanpa mengasumsikan pengalaman semua siswa identik.","section":"PU"},{"id":63,"code":"P.5","type":"Kategori","stem":"Nilai pilihan sumber belajar berikut sebagai Tepat atau Tidak tepat.","options":["Sumber lokal dipilih karena membantu mencapai tujuan dan dapat diakses murid.","Contoh lokal harus selalu dipakai meskipun menimbulkan stereotip kelompok tertentu.","Guru memeriksa kesesuaian isi sumber dengan tingkat kesiapan murid."],"key":["T","F","T"],"why":"Kontekstual bukan otomatis baik; guru perlu menjaga relevansi, akurasi, dan penghargaan pada keragaman.","section":"PU"},{"id":64,"code":"P.6","type":"PG","stem":"Di awal topik pecahan, guru memberi dua soal singkat untuk melihat apakah siswa memahami bagian dari keseluruhan. Informasi ini paling tepat dipakai untuk ...","options":["Menentukan dukungan, contoh, dan kelompok fleksibel sebelum pembelajaran inti.","Menghukum murid yang jawabannya salah.","Menetapkan nilai rapor tanpa pembelajaran.","Mengabaikan hasil karena baru asesmen awal."],"key":"A","why":"Asesmen awal dipakai untuk mengidentifikasi kebutuhan belajar, bukan memberi label atau hukuman.","section":"PU"},{"id":65,"code":"P.6","type":"MCMA","stem":"Setelah exit ticket, guru mengetahui separuh kelas masih bingung menentukan alasan jawaban. Langkah tepat adalah ... Pilih semua.","options":["Mengelompokkan jawaban untuk mengidentifikasi pola kesalahan.","Memberi penjelasan/model tambahan yang menanggapi pola tersebut.","Mengajak siswa mengerjakan soal cek singkat untuk memastikan perbaikan.","Mengabaikan hasil karena materi sudah selesai diajarkan.","Mempermalukan siswa yang jawabannya belum tepat."],"key":["A","B","C"],"why":"Asesmen formatif bermakna jika hasilnya ditafsirkan dan digunakan untuk memperbaiki proses serta mengecek dampaknya.","section":"PU"},{"id":66,"code":"P.6","type":"Kategori","stem":"Nilai contoh umpan balik berikut sebagai Tepat atau Tidak tepat.","options":["“Alasanmu sudah menyebut dua bukti; cek lagi apakah bukti ketiga mendukung simpulanmu.”","“Kamu memang tidak berbakat; jangan mencoba soal ini lagi.”","“Bandingkan jawabanmu dengan rubrik, revisi satu bagian, lalu jelaskan mengapa diubah.”"],"key":["T","F","T"],"why":"Umpan balik yang baik spesifik, menjaga martabat, dan menyebut langkah perbaikan yang dapat dilakukan.","section":"PU"},{"id":67,"code":"P.6","type":"PG","stem":"Hasil penilaian akhir memperlihatkan banyak siswa belum mencapai satu indikator. Tindakan guru berikutnya yang paling bertanggung jawab adalah ...","options":["Menganggap tugas selesai karena nilai sudah terbit.","Membuat semua soal berikutnya lebih mudah tanpa pembelajaran.","Menyembunyikan hasil dari siswa.","Menganalisis indikator yang lemah, merancang tindak lanjut sesuai kebutuhan, serta mengomunikasikan kesempatan perbaikan."],"key":"D","why":"Hasil asesmen digunakan untuk keputusan pembelajaran dan tindak lanjut, bukan sekadar angka akhir.","section":"PU"},{"id":68,"code":"K.1","type":"PG","stem":"Seorang murid menceritakan sedang mengalami masalah keluarga dan meminta tidak diumumkan. Respons guru yang paling etis adalah ...","options":["Menjadikan cerita sebagai contoh di depan kelas dengan nama lengkap.","Mendengarkan secara empatik, menjaga kerahasiaan sesuai kewajiban perlindungan murid, dan merujuk ke pihak yang berwenang bila ada risiko keselamatan.","Menyebarkannya di grup guru tanpa pertimbangan.","Mengabaikan seluruh informasi meski ada tanda bahaya."],"key":"B","why":"Etika menuntut empati dan privasi; jika terdapat risiko keselamatan, guru mengikuti prosedur perlindungan dan rujukan yang tepat.","section":"PU"},{"id":69,"code":"K.1","type":"Kategori","stem":"Nilai perilaku guru berikut sebagai Tepat atau Tidak tepat.","options":["Guru menyampaikan kriteria penilaian sebelum tugas dan menerapkannya konsisten.","Guru menaikkan nilai murid tertentu karena kedekatan pribadi tanpa bukti belajar.","Guru mengakui kekeliruan penjelasannya lalu memperbaiki di depan kelas secara profesional."],"key":["T","F","T"],"why":"Keteladanan ditunjukkan oleh keadilan, integritas, dan tanggung jawab memperbaiki kesalahan.","section":"PU"},{"id":70,"code":"K.2","type":"PG","stem":"Setelah proyek kelompok gagal mencapai target, guru merasa metode yang dipilih tidak efektif. Refleksi profesional paling tepat adalah ...","options":["Menyalahkan sepenuhnya karakter murid.","Mengulangi tugas sama tanpa perubahan.","Meninjau bukti aktivitas dan hasil, meminta umpan balik murid, lalu menetapkan perbaikan yang bisa diuji.","Berhenti mencoba pembelajaran kolaboratif selamanya."],"key":"C","why":"Refleksi diri berbasis bukti mendukung pola pikir bertumbuh dan peningkatan praktik.","section":"PU"},{"id":71,"code":"K.2","type":"MCMA","stem":"Guru ingin mengembangkan kompetensi secara berkelanjutan. Mana yang mencerminkan growth mindset profesional? Pilih semua.","options":["Mencatat satu aspek pembelajaran yang perlu diperbaiki dari umpan balik.","Mencoba strategi baru secara terukur dan membandingkan buktinya.","Menganggap kritik berarti dirinya bukan guru yang baik sehingga menolak masukan.","Berdiskusi dengan rekan dan menyesuaikan praktik dari temuan.","Mengklaim dirinya sudah tidak perlu belajar karena telah lulus pendidikan guru."],"key":["A","B","D"],"why":"Pola pikir bertumbuh tampak dalam penerimaan masukan, eksperimen terukur, dan tindak lanjut hasil refleksi.","section":"PU"},{"id":72,"code":"K.3","type":"PG","stem":"Dalam diskusi kelas, hanya beberapa siswa berani berbicara. Guru ingin membangun budaya belajar saling mendukung. Langkah terbaik adalah ...","options":["Memberi label murid pendiam sebagai tidak aktif.","Memanggil siswa acak lalu mempermalukannya jika belum siap.","Mengizinkan siswa dominan berbicara sepanjang waktu.","Menyepakati aturan diskusi, memberi waktu berpikir, dan memakai giliran berbagi yang aman serta adil."],"key":"D","why":"Keputusan guru perlu konsisten membangun partisipasi dan rasa aman untuk mengembangkan potensi semua murid.","section":"PU"},{"id":73,"code":"K.3","type":"Kategori","stem":"Nilai keputusan pembentukan budaya belajar berikut sebagai Tepat atau Tidak tepat.","options":["Guru menegaskan bahwa semua siswa dapat berkembang melalui latihan dan umpan balik.","Guru menjadikan ranking publik sebagai identitas kemampuan yang tidak dapat berubah.","Guru memberi kesempatan revisi tugas berdasarkan kriteria yang jelas."],"key":["T","F","T"],"why":"Budaya belajar positif menekankan perkembangan, standar yang jelas, dan peluang belajar dari kesalahan.","section":"PU"},{"id":74,"code":"S.1","type":"PG","stem":"Orang tua menghubungi guru karena anaknya merasa tidak dipahami di kelas. Respons komunikasi paling tepat adalah ...","options":["Menjawab defensif bahwa guru selalu benar.","Mendengarkan kekhawatiran, menggali contoh konkret, menjelaskan temuan tanpa menyalahkan, lalu menyepakati tindak lanjut.","Mengunggah percakapan ke media sosial.","Menilai anak hanya dari komentar orang tua tanpa observasi."],"key":"B","why":"Komunikasi inklusif dan empatik mencari pemahaman bersama dan tindakan yang berbasis informasi.","section":"PU"},{"id":75,"code":"S.1","type":"MCMA","stem":"Guru memberi umpan balik kepada siswa yang berbeda latar bahasa dan gaya komunikasi. Cara yang tepat adalah ... Pilih semua.","options":["Menggunakan kalimat jelas dan contoh spesifik.","Memastikan siswa memahami tindak lanjut dengan kesempatan bertanya.","Mengejek pengucapan bahasa siswa.","Menyediakan saluran tertulis/visual bila membantu komunikasi.","Memotong penjelasan siswa karena lambat menyampaikan ide."],"key":["A","B","D"],"why":"Umpan balik inklusif menyesuaikan cara komunikasi sambil menghargai martabat dan kebutuhan murid.","section":"PU"},{"id":76,"code":"S.2","type":"PG","stem":"Seorang siswa sering absen sehingga tertinggal tugas. Guru mata pelajaran belum memahami penyebabnya. Langkah kolaboratif paling tepat adalah ...","options":["Menyimpulkan bahwa orang tua tidak peduli.","Mengumumkan identitas dan masalah siswa pada publik.","Berkoordinasi dengan wali kelas/BK secara proporsional, mendengar siswa dan keluarga, serta menyusun dukungan belajar.","Memberi nilai nol permanen tanpa mencari informasi."],"key":"C","why":"Kolaborasi dengan pihak terkait memetakan hambatan dan merancang dukungan, tetap menjaga privasi.","section":"PU"},{"id":77,"code":"S.2","type":"Kategori","stem":"Nilai tindakan kolaborasi sekolah–orang tua berikut sebagai Tepat atau Tidak tepat.","options":["Guru berbagi perkembangan belajar yang relevan melalui jalur komunikasi yang tepat.","Guru menyebarkan data pribadi murid kepada semua orang tua agar transparan.","Guru melibatkan pihak sekolah sesuai kewenangan saat merancang tindak lanjut kebutuhan murid."],"key":["T","F","T"],"why":"Kolaborasi memerlukan komunikasi terarah dan perlindungan kerahasiaan data murid.","section":"PU"},{"id":78,"code":"S.3","type":"PG","stem":"Komunitas guru membahas cara meningkatkan keterlibatan siswa dalam diskusi. Kontribusi paling bermanfaat adalah ...","options":["Berbagi praktik beserta bukti, mendengarkan masukan rekan, dan mencoba perbaikan yang sesuai konteks kelas.","Mengirim materi orang lain tanpa atribusi dan mengklaim hasilnya.","Menganggap semua strategi pasti cocok di semua sekolah.","Hanya meminta sertifikat tanpa mengikuti diskusi."],"key":"A","why":"Komunitas pembelajaran berguna ketika praktik, bukti, dan refleksi dibagikan secara bertanggung jawab.","section":"PU"},{"id":79,"code":"PF.1","type":"PG","stem":"Guru menilai proyek lintas mata pelajaran. Hasil belajar paling menggambarkan tujuan pendidikan yang luas adalah ...","options":["Siswa hanya meniru jawaban tanpa memahami alasannya.","Siswa hanya memperoleh angka ujian yang tinggi.","Siswa menyelesaikan tugas cepat tetapi menolak berdiskusi.","Siswa mampu menjelaskan penalaran, bekerja sama secara etis, dan menerapkan pengetahuan untuk masalah bermakna."],"key":"D","why":"Tujuan pendidikan mencakup penguasaan pengetahuan, karakter, kolaborasi, dan penerapan yang bertanggung jawab.","section":"PU"},{"id":80,"code":"PF.3","type":"MCMA","stem":"Dalam proyek sains lingkungan, sekolah memiliki keterbatasan alat dan kondisi lingkungan yang berbeda. Adaptasi yang tetap menjaga kompetensi adalah ... Pilih semua.","options":["Menggunakan pengamatan lingkungan setempat dengan prosedur aman dan data yang dapat dicatat.","Menyediakan format pencatatan sederhana dan contoh analisis data.","Menghapus kompetensi analisis karena alat laboratorium terbatas.","Membandingkan hasil dengan konsep ilmiah dan membahas keterbatasan pengamatan.","Memaksakan alat yang tidak aman demi meniru sekolah lain."],"key":["A","B","D"],"why":"Konteks lokal dapat menggantikan media mahal jika tujuan dan penalaran tetap dipertahankan secara aman.","section":"PU"}]};
